-- CoA world database: zhCN descriptions for the custom class spells that the client
-- only knows as English tooltips. Only the Description column is written; the numeric
-- Spell.dbc columns, the name, the rank line and the tooltip aura text keep coming from
-- the client record, so no mechanic can be overwritten here.

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (674, 92081, 92082, 92083, 92084, 92085, 92086, 92087, 92088, 92089, 92091, 92093, 92094, 92096, 92097, 92098, 92100, 92101, 92104, 92105, 92106, 92107, 92108, 92109, 92111, 92112, 92113, 92114, 92115, 92116, 92117, 92118, 92119, 92120, 92121, 92122, 92123, 92124, 92126, 92128, 92129, 92130, 92131, 92132, 92133, 92134, 92135, 92136, 92137, 92138, 92140, 92141, 92142, 92143, 92144, 92145, 92146, 92147, 92148, 92149, 92150, 92152, 92153, 92154, 102208, 139778, 255275, 300226, 300233, 300234, 300235, 300236, 300237, 300240, 300241, 300249, 300250, 300251, 300252, 300255, 300256, 300258, 300259, 300260, 300262, 300264, 300265, 300268, 300270, 300272, 300275, 300277, 300278, 300280, 300284, 300286, 300287, 300290, 300291, 300296, 300298, 300300, 300302, 300304, 300305, 300306, 300307, 300308, 300309, 300313, 300314, 300315, 300318, 300321, 300322, 300323, 300324, 300325, 300331, 300334, 300336, 300339, 300341, 300343, 300344, 300347, 300348, 300349, 300351, 300353, 300355, 300357, 300360, 300361, 300363, 300365, 300367, 300369, 300371, 300374, 300375, 300376, 300382, 300384, 300385, 300386, 300387, 300388, 300390, 300391, 300393, 300395, 300398, 300460, 300465, 300466, 300467, 300468, 300470, 300474, 300475, 300476, 300477, 300478, 300480, 300483, 300484, 300485, 300489, 300490, 300497, 300499, 300501, 300502, 300504, 300505, 300512, 300513, 300514, 300515, 300520, 300522, 300524, 300529, 300530, 300534, 300536, 300538, 300540, 300541, 300542, 300543, 300545, 300553, 300560, 300565, 300569, 300571, 300572, 300575);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(674, '允许单手武器和副手武器装备在副手。'),
(92081, '10级被动使你的能量上限提高100%。'),
(92082, '10级被动使投掷武器、致残标枪和旋进的能量消耗降低15点。'),
(92083, '10级被动使你获得满溢，并能够操控一个酒杯。'),
(92084, '10级被动伤害技能现在会在敌人身上留下傀儡师的丝线，持续 10 秒。'),
(92085, '10级被动你现在可以将材料放入大锅中，酿造一锅药酒。\n\n附近盟友会根据当前激活的药酒获得增益效果。\n\n每种材料同时只能激活一种。［拥有调酒师: 最多可同时激活2种材料。］'),
(92086, '10级被动允许你使用远程武器进行自动射击。\n\n此外，所有法术和技能的法力值消耗降低25%。'),
(92087, '10级被动近战技能造成暴击时，现在会触发舞刃，对最多5个附近敌人造成副手武器伤害。'),
(92088, '10级被动当心魔激活时，你的邪能火球现在会对目标释放一次邪能打击。'),
(92089, '10级被动使你可以双持双手斧、锤、长柄武器或剑，并根据你的攻击强度获得额外的护甲和魔法抗性。'),
(92091, '10级被动你现在可以在移动时施放暗影斩杀。\n\n远程攻击和技能现在有 25% 的几率额外射出一箭，造成（20% 远程攻击强度）点物理伤害，并产生 5 点怒气。'),
(92093, '10级被动你的远程自动攻击现在产生怒气，且暗影射击的暴击几率提高 20%。'),
(92094, '10级被动使用黎明之刃现在会赋予你罪孽之火，持续 3 秒，使你的自动攻击额外造成 40% 的伤害作为火焰伤害。\n\n在罪孽之火已激活时以这种方式赋予自身该效果，将使其当前持续时间延长 3 秒。'),
(92096, '10级被动造成法术伤害现在有5%的几率使你获得电刑者。\n\n几率基于静电等级提升。'),
(92097, '10级被动教你召唤：气元素。'),
(92098, '10级被动\n\n［拥有风暴君主: 盐水；否则： 电击］现在使你获得导电，持续30 秒，可叠加10次。\n\n湍流之怒在敌人身上存在传导时会触发导电。'),
(92100, '10级被动使地狱火打击造成的武器基础伤害翻倍，并使所有暴击伤害提高25%。'),
(92101, '10级被动教你召唤：大恶魔，并使你的专精提高10点。'),
(92104, '10级被动成功格挡现在有30%的几率召唤1只地狱火小鬼协助你战斗，持续12 秒。每3秒只能发生一次。\n\n此外，每层恶魔之血都会使你的总生命值提高1%。'),
(92105, '等级10 被动在堡垒阵型或战线阵型激活期间，你受到的伤害降低10%。\n\n此外，在堡垒阵型或战线阵型激活期间，你通过物理伤害产生的威胁值大幅提高。'),
(92106, '10级被动你的冲撞现在会为你提供一层荣耀，持续30 秒。\n\n达到3层时，你的下一次冲撞在30 秒内造成的伤害提高150%。'),
(92107, '等级10 被动施放叙事诗现在会获得节奏，可叠加 3 层。\n\n当节奏达到3层时，你将消耗所有层数释放一次战争之声，对 8 码内的所有敌人造成（12.7449% 攻击强度 + 71 × 等级系数）点魔法伤害。'),
(92108, '10级被动你的副手自动攻击现在会触发狂热。'),
(92109, '10级被动你现在会延迟承受40%的直接伤害，改为在8 秒内分摊承受。\n\n此外，你不再因誓言消耗你的誓言。'),
(92111, '等级 10 被动你造成的直接伤害有20%的几率以天灾克星打击敌人，额外造成50%武器伤害再加上（25% 攻击强度 + 262 × 等级系数 + 25% 法术强度）点圣焰伤害。\n\n对亡灵敌人必定造成暴击。'),
(92112, '10级被动消耗生命值的法术现在会赋予你饥渴。\n\n达到10层时，你将进入贪噬无厌状态，每3秒使你的伤害输出降低30%，直至饥渴效果结束。'),
(92113, '10级被动你的伤害性凡人形态法术现在可以在移动时施放。'),
(92114, '10级被动教你不灭诅咒并允许你双持武器。'),
(92115, '10级被动使毒性飞镖的伤害和持续伤害频率提高30%。\n\n你的远程技能对中毒目标攻击时，现在无视敌人25%的护甲。'),
(92116, '10级被动你的野性打击现在额外产生1层优势。\n\n移除你的远程技能的最小射程。'),
(92117, '10级被动你的伤害性暴击现在会在你周围15码范围内的随机位置生成一朵绿色梦境花。每1秒只能触发一次。'),
(92118, '10级被动施放伤害性法术现在会使你的伤害性法术冷却时间缩短，减少量为剩余冷却时间的10%。'),
(92119, '10级被动教你永世韧性。'),
(92120, '10级被动时光魔杖现在会生成一个回响碎片，可用于释放扭曲和连续体法术。\n\n分解现在是一个扭曲法术，根据你拥有的回响碎片数量造成额外伤害。'),
(92121, '10级被动技能地穴虫群造成的伤害现在会施加1层墓穴瘟疫，而巫妖寒霜则施加2层。'),
(92122, '10级被动施放任意法术现在有25%的几率使你获得冻原战士。'),
(92123, '10级被动使你的最大生命之力提高1点。'),
(92124, '熔岩碎片造成的伤害现在会施加地狱烈焰，使敌人燃烧，在18 秒内额外造成（1122 × 等级系数 + 120% 法术强度）点火焰伤害。'),
(92126, '10级被动当你受到本应致命的伤害时，你会转化为凤凰之魂，持续 15 秒。\n\n在转化状态下，你的法术不消耗法力值，且你的精神提高 100%。效果结束时，你将重生。每10分钟只能触发一次。'),
(92128, '30级被动技能教你巨龙化身。'),
(92129, '10级被动你的克苏恩凝视现在额外获得15点基础伤害和治疗效果。'),
(92130, '造成的伤害有 15% 的几率使你获得腐化低语。'),
(92131, '10级被动达到100点狂乱不再导致完全疯狂。\n\n教你深渊先驱。'),
(92132, '等级 10 被动你现在获得等同于你的力量值的智力，并且你的最大生命值额外按最大法力值的10%提高。'),
(92133, '10级被动使你的急速等级提高，相当于智力值的8%。'),
(92134, '10级被动技能你的女猎手射击现在拥有月蚀效果。\n\n女猎手射击：额外施加2层散落星辰。'),
(92135, '等级 10 被动：激活黎明后，施放神圣法术获得日出，施放火焰法术获得日落。进入一种状态后，在下一次激活黎明前无法进入另一种状态。'),
(92136, '等级 10 被动：履行誓言时释放日光，治疗 40 码内最多 5 名盟友（25 + 15% 治疗强度）点生命值，优先治疗生命值最低的盟友。'),
(92137, '等级 10 被动：避免受到一次攻击时，有 20% 几率获得天使降临。'),
(92138, '10级被动造成直接火焰伤害现在会对你的目标施加凝固汽油弹效果。'),
(92140, '10级被动教你建造：ZIGGI-6K.'),
(92141, '10级被动教你建造：机甲。\n\n你现在可以生成废料来建造你的机甲，并且废料射击和黏性炸弹现在也会生成废料。'),
(92142, '10级被动。造成直接伤害时，有20%的几率重置毒蛇之牙的冷却时间，使你获得腐化巫妖效果，并使盟友获得回能。'),
(92143, '10级被动。毒牙现在会施加孵化印记，最多叠加5层。某些技能会消耗这些印记以获得额外效果。'),
(92144, '10级被动敌对攻击现在有50%的几率使你获得一层暴露血肉。'),
(92145, '等级 10 被动：你现在造成的全部伤害的 15% 会治疗自身。'),
(92146, '等级 10 被动：你的灵魂撕裂现在还会施加衰弱灵魂，使你造成的暗影与冰霜伤害对该目标提高 10%。'),
(92147, '等级 10 被动：消耗灵魂灌注现在使受难灵魂的冷却时间缩短 3 秒。'),
(92148, '10级被动你现在可以在艾泽拉斯驯服野兽，让它们作为同伴协助你。'),
(92149, '10级被动施放晶石弹幕和你的地震技能现在会生成大地塑形。'),
(92150, '10级被动技能所有近战伤害或治疗现在有10%的几率使你获得余震，持续15 秒。'),
(92152, '10级被动使用元素迸发和原初轰击现在会为你提供冰霜符印。\n\n 符文可通过符印崩解或奥术秘法释放。'),
(92153, '10级被动符文剑现在会额外攻击你的目标一次，造成副手武器伤害的50%。'),
(92154, '等级10 被动你的原初轰击和燃刃斩现在会刷新一层符文剑。\n\n此外，每第3层符文剑现在会恢复（36.95 + 30% 攻击强度）点法力值，在符文纹饰：流水激活期间提高20%。'),
(102208, '无法被圣约指定为目标。'),
(139778, '远程直接攻击和技能现在有5%几率重置驯犬者之令的冷却时间。'),
(255275, '引导6 秒，为附近所有敌人宣告世界末日，立即移除他们身上所有有益的魔法效果，并在引导期间使你所受伤害以及他们的急速和移动速度降低25%。\n\n引导期间，附近敌人还会受到末日天穹的打击。\n\n引导结束后，你发出一声恐怖的尖啸，使附近敌人获得腐化心智。'),
(300226, '当生命值高于50%时，消耗怒气的技能会消耗你2%的最大生命值，对目标造成或治疗相当于10%的额外效果。'),
(300233, '使你受到的定身和减速效果持续时间缩短25%。'),
(300234, '提高你对人形生物和不死生物造成的暗影与冰霜伤害4%。'),
(300235, '你造成的周期性伤害现在有10%的几率使你和你亡灵仆从的急速提高20%，持续8 秒。'),
(300236, '每层抹除现在使目标从你的亡灵瘟疫中受到的伤害额外提高5%。'),
(300237, '艾露恩之手和月光之触现在额外在10 秒内恢复其数值的50%。'),
(300240, '提高你霜寒法术的射程6码，并使你和你的召唤物的冰霜暴击几率提高3%。'),
(300241, '当你的生命值低于50%时，你的亡灵仆从现在会为你恢复相当于其造成伤害10%的生命值。'),
(300249, '月相每层使你的远程急速提高4%。'),
(300250, '使你的招架几率提高2%，格挡值提高25%。'),
(300251, '使你的最大法力值提高10%。'),
(300252, '每消耗第10颗散落星辰，就会向一名敌人发射一颗彗星，对5码范围内的5个敌人造成（502 + 30% 奥术法术强度）点奥术伤害。'),
(300255, '用艾露恩的祝福强化一名盟友，使其智力提高3点，持续30 分钟。'),
(300256, '在夜晚时使你的移动速度提高20%。'),
(300258, '你的护甲值提高相当于智力300%的数值，并使你受到的昏迷和缴械效果持续时间缩短25%。'),
(300259, '使所有魔法伤害降低5%。'),
(300260, '你的效果触发暗翼召唤时，现在会额外触发一次暗翼召唤。\n\n每秒只能触发一次。'),
(300262, '你的宇宙之相现在可叠加1次。'),
(300264, '当黑血在盟友身上激活时，你的克苏恩凝视对该目标造成的治疗效果有15%的额外几率造成暴击。'),
(300265, '你的吞噬魔法现在会影响附近 2 名盟友。'),
(300268, '你的招架几率提高3%，躲闪几率提高2%。'),
(300270, '当疯狂值高于60点时，你受到的伤害降低5%。'),
(300272, '使触发灵气的几率提高10%。'),
(300275, '帝国之刃造成的伤害使你的近战急速提高3%，持续8 秒，可叠加3层。'),
(300277, '恢复5%的最大法力值，并使你造成的暗影伤害提高10%，持续8 秒。'),
(300278, '闪避攻击现在有40%的几率刷新一层帝国之刃。'),
(300280, '你的近战暴击会减少裂隙和克苏恩凝视的冷却时间3秒。'),
(300284, '使邪异愈合和邪异震击的治疗强度加成提高25%。'),
(300286, '30级被动技能直接治疗现在会施加虚空侵蚀。'),
(300287, '当深渊先驱激活时，你受到的伤害降低15%，并有25%的额外几率抵抗驱散效果。'),
(300290, '当深渊先驱激活时，你的移动速度不会被降低至正常值的100%以下。'),
(300291, '施放深渊先驱后，你下一次在10 秒内施放的虚空护盾的吸收量提高100%。'),
(300296, '施放克苏恩之凝视现在会在其激活时始终触发你的克苏恩意志。'),
(300298, '施放克苏恩凝视现在会使心灵镇压的冷却时间缩短4秒，并使泽克沃兹之握的冷却时间缩短1秒。'),
(300300, '你造成的周期性或引导伤害现在有25%的几率诅咒目标，施加心灵腐烂。'),
(300302, '提高你腐蚀法术的射程3码，并使它们的暴击几率提高2%。'),
(300304, '使恐怖魔箭和邪异震击的法术伤害加成提高10%，使帝国之怒的法术伤害加成提高20%。'),
(300305, '黑暗帝国之怒的暴击几率提高10%。'),
(300306, '增加暗影凋零的持续时间9秒。'),
(300307, '达到60点狂乱时，你的伤害提高10%，持续10 秒。'),
(300308, '造成持续伤害或引导伤害现在会获得2 狂乱，使你的湮灭光束的冷却时间缩短1秒，并获得1层深渊毁灭。'),
(300309, '减少恐怖魔箭和黑暗帝国之怒的施法时间0.3秒。'),
(300313, '40级被动技能使所有周期性伤害和造成的伤害有6%的几率重置克苏恩凝视的冷却时间，并产生5点狂乱。'),
(300314, '生命值高于 80% 时，造成的伤害和治疗提高 10%。'),
(300315, '审判日的冷却时间缩短 15 秒。'),
(300318, '施放太阳猛击时，太阳坠饰的冷却时间缩短 10 秒。'),
(300321, '黎明激活期间，黎明灼击的施法时间缩短 20%。'),
(300322, '急速提高 3%。'),
(300323, '日出和日落的效果提高 20%。'),
(300324, '黎明增加 3 次施法次数。'),
(300325, '辉耀圣焰对生命值低于 35% 的目标造成的伤害提高 10%。'),
(300331, '圣光誓言额外治疗，治疗量相当于你受到的伤害或你造成的直接治疗的 5%。'),
(300334, '每 125 点护甲使你的法术强度提高 3 点。'),
(300336, '光耀或圣光照耀的治疗使目标移动速度提高 20%，持续 3 秒。'),
(300339, '等级 50 被动：对目标的治疗暴击后，目标下一次受到伤害时，会获得相当于原治疗量 30% 的治疗。持续 15 秒。'),
(300341, '圣洁净化额外驱散 1 个效果。'),
(300343, '对生命值低于 20% 的目标，暴击几率提高 30%。'),
(300344, '治疗受赐福影响的目标时，返还该法术 25% 的法力消耗。'),
(300347, '圣光典范的冷却时间变为 1 分钟，并强化圣槌，使其无冷却时间、效果提高 50%，射程变为 40 码。'),
(300348, '被法术命中的几率降低 3%。'),
(300349, '治疗暴击使太阳祈愿的冷却时间缩短 1 秒，每秒最多触发一次。'),
(300351, '法力值提高，数值相当于智力的 150%；每 15 秒恢复 2% 最大法力值。'),
(300353, '等级 40 被动：圣槌不会未命中，也无法被躲闪或招架；神圣形态期间还获得强化效果。圣光之槌：附加一个等同治疗量的吸收护盾。恩典之槌：恢复 10% 最大法力值。愤怒之槌：额外攻击附近 5 名敌人。'),
(300355, '受到近战暴击后，在 4 秒内不会再次受到暴击。'),
(300357, '赐福的治疗量和法力恢复量翻倍。'),
(300360, '进入日落或日出时，法术急速提高 20%，持续 10 秒或直至完成 3 次施法。'),
(300361, '等级 50 被动：日出期间，每 1 秒使霍鲁萨斯冲击的剩余冷却时间缩短 10%；日落期间，以同样方式缩短圣光迸发的剩余冷却时间。'),
(300363, '法术急速提高 3%，白天额外提高 1%。'),
(300365, '圣光迸发的施法时间缩短 0.5 秒。'),
(300367, '霍鲁萨斯冲击和圣光迸发有 20% 几率不触发冷却时间。'),
(300369, '等级 20 被动：辉耀圣焰造成伤害时，有 10% 几率触发太阳烈焰。'),
(300371, '对受圣光锁链影响的目标造成直接伤害时，光链会蔓延至另一名敌人，每秒最多触发一次。'),
(300374, '对生命值高于80%的敌人造成的所有火焰伤害提高10%。'),
(300375, '使［拥有硫磺重击: 硫磺重击；否则： 斩断］对燃烧目标造成的伤害提高30%，并且现在会使目标被暴击的几率提高3%，持续12 秒。'),
(300376, '你的暴击现在使你激怒，近战攻击速度提高15%。'),
(300382, '力量提高5%。'),
(300384, '最大怒气值提高10，并使你受到的缴械效果持续时间缩短15%。'),
(300385, '你的招架几率提高5%。'),
(300386, '锻魔壁垒现在也使你的暴击几率提高10%。'),
(300387, '获得恶魔之血效果的几率提高25%。'),
(300388, '盾刺猛击和肉锯造成的伤害现在会施加撕裂血肉，使目标在15 秒内流血，造成（100 + 37.5% 攻击强度）点伤害。'),
(300390, '减少［拥有盾刺猛击: 盾刺猛击；否则： 地狱火打击］、肉锯和熔化的怒气消耗10点。'),
(300391, '获得一层恶魔之血现在有15%的几率对最多5个附近敌人触发一次火焰爆炸，造成8点火焰伤害。'),
(300393, '天灾瘟疫的天启瘟疫效果伤害提高25%，持续时间延长5秒。'),
(300395, '施放灌注现在使你在其持续的前6 秒内受到的治疗效果提高25%。'),
(300398, '40级被动技能使用瘟疫现在会为你的宠物施加一个次级瘟疫效果。\n\n你每10秒只能为你的宠物施加一次次级瘟疫效果。'),
(300460, '40级被动技能使锯齿射击造成的周期性伤害可以造成暴击。'),
(300465, '使你受到的移动限制效果持续时间缩短20%。'),
(300466, '切割造成的伤害和产生的威胁值提高15%。'),
(300467, '使你的憎恨壁垒的冷却时间减少 10 秒。'),
(300468, '施放憎恨壁垒现在还会在 15 码范围内的所有附近盟友身上制造一个伤害吸收护盾，吸收（208 + 8% 攻击强度 + 20% 法术强度 + 100% 耐力）点伤害，持续 5 秒。\n\n吸收护盾随耐力提高而提升。'),
(300470, '生命值高于75%时，受到的伤害降低5%，造成的伤害提高5%。'),
(300474, '造成的直接火焰和暗影法术伤害现在会对敌人施加暴露效果。'),
(300475, '来自魔裔的伤害提高10%，所有盟友对该目标的暴击几率提高3%，持续8 秒。'),
(300476, '躲闪攻击会对攻击者造成40%的副手武器伤害，并使20码内的队伍和团队成员激怒，暴击几率提高2%，持续10 秒。'),
(300477, '使你的法术暴击等级提高，相当于精神属性的20%。'),
(300478, '你的邪能火球造成暴击后，会使你在10 秒内施放的下一次邪能火球的暴击几率提高20%。\n\n此效果每5秒只能触发一次。'),
(300480, '直接伤害现在有5%几率重置地狱火的冷却时间。'),
(300483, '恶魔打击造成的伤害现在延长目标身上的残废术持续时间1秒，并使你的法术暴击伤害提高1%，持续6 秒，可叠加10次。'),
(300484, '埃辛诺斯的猛攻造成的伤害现在降低敌人4%的护甲，持续10 秒，可叠加5次。'),
(300485, '献祭光环的跳动频率提高25%。'),
(300489, '你的邪能之怒终结技的暴击几率提高1%，每拥有10点能量时生效。'),
(300490, '周期性伤害现在有15%的几率使你获得邪能铸造，持续8 秒。'),
(300497, '你的狂怒效果提高100%。'),
(300499, '斩首造成暴击时，使目标流血，在5 秒内额外造成相当于伤害值30%的伤害。'),
(300501, '减少信仰圣约的冷却时间60秒，并减少神圣束缚的持续时间30秒。'),
(300502, '当你的誓言锁链叠加至10层时施放誓言锁链，现在会刷新附近所有敌人身上的信仰之刃持续时间。'),
(300504, '当正义风暴激活时，你的移动速度提高20%。\n\n以此方式获得的移动速度与勇气叠加。'),
(300505, '20级被动技能先祖打击和野蛮挥砍的暴击现在会返还10点能量。'),
(300512, '使正义风暴和定罪造成的伤害提高30%。\n\n此外，正义风暴激活时使所有受到的伤害降低20%。'),
(300513, '给一名敌人打上烙印，持续20 秒，阻止其骑乘、逃跑或移动速度超过正常移动速度，并且当其造成直接伤害时，会受到（18.5% 攻击强度 + 243 × 等级系数 + 27.5% 神圣法术强度）点神圣伤害。\n\n被标记的敌人即使处于潜行或隐形状态，也始终能被十字军看到。'),
(300514, '你的下3次泰坦猛击冷却时间降低50%，无视目标生命值百分比即可使用，且伤害提高25%，持续1 分钟。\n\n施加神圣束缚，持续1 分钟。'),
(300515, '40码范围内的盟友受到的治疗效果提高6%。不与类似效果叠加。\n\n此外，你的最大生命值提高6%。'),
(300520, '天灾克星、猩红之锤和泰坦打击对生命值低于20%的敌人造成的伤害提高25%。'),
(300522, '增加你的誓言锁链的持续时间5秒。'),
(300524, '信仰之刃和正义风暴的伤害提高25%。'),
(300529, '50级被动使你的所有魔法抗性提高，相当于闪躲等级的10%，并降低你受到持续性伤害效果的伤害，降低15%。'),
(300530, '狂热赐福的效果提高20%。'),
(300534, '减少反击姿态和偏转剑刃的冷却时间 25%。'),
(300536, '施放战斗冲锋时，你的格挡等级提高相当于力量值25%的数值，持续6 秒。'),
(300538, '你的攻击强度提高5%。'),
(300540, '现在每当你格挡一次攻击，你将恢复3%的基础生命值。'),
(300541, '装备单手武器时，你造成的伤害提高10%。'),
(300542, '当战线阵型激活时，你的移动速度不会被降低至115%以下，但其能量消耗提高30点。'),
(300543, '勇气战旗和［拥有节奏: 屠龙者之歌；否则： 横扫千军］的持续时间延长50%。'),
(300545, '你的力量和耐力提高4%。'),
(300553, '装备提供的护甲贡献提高 25%，并使你的魔法抗性提高 21 点。'),
(300560, '使锁甲与板甲提供的护甲贡献提高 20%，并使敌人法术命中你的几率降低 2%。'),
(300565, '使小队与团队全体成员的暴击几率提高 3%。无法与其他同类效果叠加。此外，造成直接伤害现在有 15% 几率生成 1 个灵魂碎片。'),
(300569, '受难灵魂作用于你时，你的近战攻击速度提高 30%，且恐惧之潮的符文能量消耗降低 5 点。'),
(300571, '造成物理伤害会使木桩和黎明之刃的伤害提高2%，持续5 秒，可叠加10层。'),
(300572, '增加陷阱在地面上的持续时间7秒，减少钻地弩箭的冷却时间7秒，并减少黎明之刃的能量消耗7点。'),
(300575, '黎明之刃和黄昏之刃的伤害提高15%。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (300576, 300578, 300580, 300581, 300582, 300584, 300585, 300590, 300593, 300595, 300596, 300597, 300605, 300606, 300607, 300609, 300610, 300611, 300612, 300616, 300618, 300619, 300636, 300653, 300660, 300662, 300663, 300664, 300678, 300680, 300682, 300685, 300688, 300690, 300691, 300693, 300695, 300697, 300698, 300700, 300706, 300723, 300728, 300729, 300730, 300731, 300733, 300738, 300740, 300742, 300744, 300748, 300751, 300753, 300755, 300757, 300759, 300772, 300789, 300791, 300792, 300795, 300827, 300834, 300839, 300855, 300856, 300857, 300860, 300867, 300871, 300872, 300873, 300876, 300877, 300879, 300889, 300897, 300921, 300929, 300932, 300940, 300941, 300943, 300944, 300945, 300956, 300957, 300958, 300959, 300960, 300961, 300963, 300965, 300968, 300969, 300970, 300972, 300974, 300975, 300978, 300982, 300983, 300986, 300989, 300992, 300994, 300995, 301008, 301010, 301011, 301057, 301059, 301064, 301065, 301066, 301068, 301086, 301087, 301146, 301149, 301175, 301180, 301181, 301182, 301183, 301193, 301198, 301200, 301207, 301209, 301213, 301219, 301220, 301236, 301239, 301241, 301249, 301250, 301251, 301252, 301253, 301254, 301255, 301256, 301258, 301260, 301262, 301266, 301267, 301280, 301286, 301287, 301295, 301297, 301298, 301299, 301302, 301303, 301304, 301306, 301309, 301310, 301311, 301313, 301315, 301317, 301318, 301322, 301333, 301338, 301339, 301358, 301365, 301366, 301974, 301982, 301984, 301986, 301988, 302015, 302072, 302518, 302519, 302548, 302581, 302590, 302888, 302914, 302923, 303014, 500002, 500003, 500004, 500011, 500012, 500015, 500020, 500028, 500038);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(300576, '当符印过载激活时，你的符印崩解必定造成暴击。'),
(300578, '用符文铭刻一个区域，持续 2 秒，每 0.499 秒对区域内最多 5 个敌人造成（23 + 30% 法术强度）点元素伤害。'),
(300580, '你的每个召唤物现在会使你受到的伤害降低1%，最多可叠加10%。'),
(300581, '你的近战自动攻击现在有15%几率恢复（75 × 等级系数）点法力值。\n\n当符文纹饰：流水激活时，恢复的法力值提高250%。'),
(300582, '用原初轰击造成伤害现在降低受影响目标的护甲 4%，持续 12 秒，可叠加 5 层。'),
(300584, '每把被武器铭刻：大地附魔的武器现在减少原初脉冲的冷却时间 4 秒，并提高其伤害 15%。'),
(300585, '提高血箭的伤害 25%，并且在生命值低于 35% 时额外提高 25%。'),
(300590, '你的鲜血愈合现在会治疗1个额外附近目标。\n\n利爪扫击和鲜血爆裂的暴击伤害提高10%。'),
(300593, '当你的直接伤害法术未能造成暴击时，你的暴击几率提高2%，持续10 秒，最多可叠加5层。\n\n造成暴击会移除该效果。'),
(300595, '你的［拥有风暴召唤: 上升气流；否则： 召唤风暴］现在返还10点静电。'),
(300596, '你的闪电之体现在每跳额外恢复 1% 的最大法力值。'),
(300597, '你的分叉闪电现在影响 1 个额外敌人。'),
(300605, '你的下一次湮灭光束造成的伤害提高5%，持续15 秒，可叠加10层。'),
(300606, '提高你的暴击几率 2%，并减少你受到的打断和沉默效果持续时间 20%。'),
(300607, '你的泰坦打击现在会为你恢复相当于造成伤害两倍的生命值。'),
(300609, '分叉闪电造成的伤害现在有15%的几率将目标身上的活跃伏特效果扩散到每个受影响的敌人。\n\n几率根据静电等级提升。'),
(300610, '当被风暴之眼定身时，受影响的敌人现在受到你的伤害提高 30%。'),
(300611, '减少风暴之眼的冷却时间和法力消耗 15%。'),
(300612, '造成直接法术伤害现在有 33% 的几率使你的下一个 ［拥有风暴召唤 or 风暴君主: ；否则： 召唤闪电］［拥有风暴召唤: 气爆］［拥有风暴君主: 湍流之怒］ 的施法时间减少 15%，持续 10 秒，可叠加 2 层。'),
(300616, '提高你的法术暴击伤害 35%。'),
(300618, '你的智力和精神提高5%。'),
(300619, '50级被动技能你的电刑现在受导电影响，每层使其伤害提高10%。'),
(300636, '蜘蛛炸弹工厂现在还会召唤一个重型蜘蛛炸弹。\n\n重型蜘蛛炸弹移动缓慢，抵达目标时造成（1179.5 + 55% 远程攻击强度）点火焰伤害，并使其移动速度降低70%，持续2 秒。'),
(300653, '减少电击！的冷却时间5秒。'),
(300660, '使洛阿之酿和瓶中精魂的额外治疗加成提高 15%。\n\n此外，你的破咒现在会影响额外一名附近的盟友，并使其公共冷却时间缩短0.5秒。'),
(300662, '提高你的厄运诅咒的持续时间和效果 25%。'),
(300663, '你的迟缓诅咒现在提高你对目标的暴击几率 10%。'),
(300664, '使你的智力和敏捷提高5%。'),
(300678, '融面者现在每跳速度提高20%，持续时间延长6秒。'),
(300680, '施放硬化现在会清除暴露血肉。'),
(300682, '枯萎毒素的伤害提高20%。'),
(300685, '提高毒蛇之牙、愈合之雾和沙德拉香膏的治疗加成系数，提高20%。'),
(300688, '地震冲击现在额外产生 10 点怒气，地震尖刺现在额外产生 3 点怒气。'),
(300690, '施放图腾猛击现在会刷新一层双头飞龙之咬。'),
(300691, '对流血敌人造成的野性之爪和双头飞龙之咬伤害提高15%。'),
(300693, '以熔岩之怒在你面前掀起一道土浪，造成（94 + 22% 攻击强度 + 50% 耐力）点物理伤害，并赋予你领主之怒和余震。\n\n与其他地震法术共享冷却时间。'),
(300695, '原初奔袭和震击造成的伤害现在会赋予大地之怒。'),
(300697, '40级被动现在你获得相当于护甲穿透等级50%的法术强度。'),
(300698, '提高地震技能造成的伤害10%，并使其周期性伤害可以造成暴击。'),
(300700, '使你的远程技能和自动射击的射程提高5码。'),
(300706, '快速射击造成的远程武器伤害提高10%。'),
(300723, '等级 30 被动：神圣与火焰法术强度提高 30%，法术命中等级提高，数值相当于智力的 6%。'),
(300728, '当大地化身、熊皮或岩石屏障被移除或消失时，你获得10%近战急速和招架几率，持续15 秒。'),
(300729, '使你的法术和技能消耗降低5%。'),
(300730, '你周身散发出光环，使小队和团队成员获得390点护甲加成。\n\n与同类效果不叠加。'),
(300731, '对盟友造成暴击治疗现在使你的攻击强度提高15%，持续你的下3次攻击。持续12 秒。'),
(300733, '有效治疗现在使你的近战急速和伤害提高2%，持续5 秒，可叠加3层。'),
(300738, '大地母亲之手现在使目标的躲闪几率提高15%，持续5 秒。'),
(300740, '使你的力量提高5%，命中几率提高3%。'),
(300742, '自动攻击现在有20%的几率造成武器伤害，并恢复5%的最大法力值。'),
(300744, '使用原初奔袭穿过盟友现在最多治疗5名盟友，治疗量为（54 + 25% 攻击强度 + 35% 法术强度），并使其获得一层本能奔跑。'),
(300748, '使你的最大生命值以及你的召唤物的最大生命值提高5%。'),
(300751, '每个激活的余烬使爆炸的施法时间降低8%。'),
(300753, '当深渊先驱激活时，你的禁忌仪式冷却速度加快。'),
(300755, '等级 10 被动直接暴击现在额外产生 20 点热量。\n\n你获得相当于暴击等级 100% 的智力。'),
(300757, '使你的暴击几率提高3%，并且火焰法术的暴击现在会使敌人被法术暴击的几率提高3%，持续12 秒。'),
(300759, '地狱火屏障的吸收量提高10%，造成的伤害提高15%。'),
(300772, '宇宙之相不再降低敌人的移动速度。取而代之的是，你的近战和远程攻击使你获得5%移动速度提高，持续4 秒，最多可叠加3层。'),
(300789, '快速拔枪的暴击伤害提高100%。'),
(300791, '使怨灵之刃的符文能量消耗降低 50%。'),
