(300855, '为附近所有盟友的武器涂毒，持续30 分钟，使他们在造成伤害时有5%几率向目标喷射毒液，造成（3.1 + 10% 攻击强度 + 10% 自然法术强度）点自然伤害。'),
(300856, '宣告一名盟友为荣誉目标，使其力量提高4点，持续30 分钟。'),
(300857, '发出野蛮咆哮，使附近小队和团队成员的敏捷提高4点，持续30 分钟。'),
(300860, '在20码范围内的每名盟友使你的近战急速提高1%，最多提高20%。'),
(300867, '地震波现在使受影响的盟友移动速度提高30%，持续4 秒。'),
(300871, '使小队和团队成员的攻击强度提高5%。\n\n与同类效果不叠加。\n\n此外，你的精魂提供的生命值和法力值恢复效果现在触发频率提高50%。'),
