(300873, '使所有小队和团队成员暴击几率提高3%。不与同类效果叠加。\n\n此外，你的暴击几率额外提高3%。'),
(300876, '使小队和团队成员的近战及远程急速提高10%。\n\n不与类似效果叠加。'),
