(300879, '使所有小队和团队成员暴击几率提高3%。不与类似效果叠加。\n\n此外，使你对人型生物造成的伤害提高10%。'),
(300889, '使小队与团队全体成员的暴击几率提高 3%。无法与其他同类效果叠加。'),
(300897, '穿颅者对中毒目标造成的伤害提高 30%。'),
