(300958, '使所有小队和团队成员暴击几率提高3%。不与类似效果叠加。\n\n此外，使寒冰弹幕对冻结目标的暴击几率额外提高20%。'),
(300959, '小队和团队成员的法术急速提高3%，不与同类效果叠加。你的腐毒专精法术射程提高20%，产生的威胁值降低20%。'),
(300960, '对生命值低于35%的敌人施放血肉化虫时，暴击几率提高25%。'),
(300961, '使小队和团队成员造成的所有伤害提高3%，并使你造成的冰霜伤害提高5%。\n\n不与类似效果叠加。'),
(300963, '使小队和团队成员造成的所有伤害提高3%。\n\n不与类似效果叠加。'),
(300965, '施加墓穴瘟疫现在会使目标身上的血肉化虫持续时间延长 1 秒。'),
(300968, '使所有小队和团队成员暴击几率提高3%。不与同类效果叠加。\n\n此外，你的暴击几率额外提高3%。'),
(300969, '使小队与团队全体成员受到的伤害降低 3%。无法与其他同类效果叠加。此外，使你的近战急速提高 10%。'),
(300970, '使你的火焰伤害和治疗效果提高2%，并降低10%的威胁值。'),
