(301974, '使所有小队和团队成员暴击几率提高3%。\n\n不与类似效果叠加。'),
(301982, '标记盟友，持续30 秒，可叠加10层。\n\n当你施放克苏恩凝视时，所有层数将被消耗，为所有受到虚空侵蚀影响的盟友恢复（104.75 + 35% 治疗强度）点生命值，治疗量基于目标身上的层数提高。'),
