(302519, '你的冰川汲取现在额外产生20点符文能量，但消耗提高25%。'),
(302548, '周期性伤害现在有 15% 的几率使克索诺斯诅咒的冷却时间减少 3 秒。\n\n每层恶魔之火会使触发几率提高 2%。'),
(302581, '每层恶魔之血也使你的护甲提高1%。'),
(302590, '对5码内最多5名敌人造成（399.8 + 100% 自然法术强度）点物理伤害，并使他们在5 秒内受到你的地震的伤害提高20%。'),
