(302914, '圣光誓言激活期间，圣光之槌额外恢复相当于伤害 100% 的生命值。'),
(302923, '提高食尸鬼化和万人坑的持续时间，提高25%。'),
(303014, '你从造成的伤害中获得的怒气值提高10%，装备双手武器时额外提高15%。'),
(500002, '以野蛮之怒旋转，用双持武器攻击最多5个附近敌人，造成135%武器伤害外加3点伤害。'),
