(500015, '召唤一个暗影傀儡，它会收集一个精魂并冲向你的目标，造成（25 + 22% 暗影法术强度）点暗影伤害，每0.75秒重复一次，持续3 秒。'),
(500020, '钩住一个敌人，将其拉向你，造成（8 + 37.125% 攻击强度）点物理伤害，并产生10点怒气。'),
(500028, '3层充能，10秒充能时间将自身包裹于邪能能量之中，并向奔跑方向冲刺。\n\n可在定身状态下使用，并移除你身上的定身效果。'),
(500038, '消耗25点静电电击一名盟友的身体，使其恢复活力，立即治疗（76 + 24.5% 法术强度）点生命值。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (500039, 500040, 500041, 500042, 500053, 500055, 500056, 500060, 500067, 500069, 500071, 500073, 500074, 500075, 500085, 500086, 500093, 500094, 500101, 500103, 500110, 500115, 500116, 500118, 500121, 500123, 500124, 500125, 500126, 500135, 500141, 500142, 500143, 500144, 500146, 500147, 500149, 500151, 500152, 500154, 500161, 500166, 500167, 500169, 500205, 500206, 500217, 500219, 500230, 500232, 500235, 500236, 500239, 500241, 500242, 500249, 500250, 500258, 500259, 500261, 500269, 500270, 500286, 500287, 500288, 500294, 500296, 500302, 500329, 500331, 500335, 500338, 500341, 500342, 500343, 500344, 500357, 500359, 500373, 500376, 500402, 500445, 500464, 500472, 500476, 500477, 500478, 500483, 500484, 500501, 500508, 500509, 500511, 500517, 500534, 500535, 500542, 500549, 500551, 500567, 500572, 500578, 500580, 500582, 500584, 500594, 500600, 500608, 500610, 500612, 500615, 500617, 500631, 500671, 500678, 500688, 500689, 500692, 500694, 500696, 500704, 500711, 500712, 500714, 500715, 500719, 500720, 500721, 500723, 500751, 500764, 500904, 500913, 500915, 500918, 500923, 500928, 500932, 500933, 500935, 500937, 500939, 500940, 500943, 500947, 500950, 500952, 500957, 500960, 500961, 500962, 500965, 500967, 500968, 500969, 500970, 500971, 500981, 500982, 500983, 500984, 500985, 500989, 500991, 500995, 501132, 501134, 501136, 501380, 501562, 502429, 502537, 503532, 503534, 503550, 503552, 503568, 503569, 503583, 503584, 503596, 503608, 503630, 503631, 503636, 503637, 503639, 503651, 503655, 503659, 503662, 503664, 503669, 503679, 503680, 503681, 503682, 503690, 503696, 503698);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(500039, '消耗40点静电能量为所有小队和团队成员施加一个护盾，可吸收（101 + 100% 智力）点伤害（随智力提高），持续10 秒。\n\n护盾激活期间，目标受到伤害时不会因施法被打断而退条。'),
(500040, '消耗50点静电召唤一道巨型闪电，造成（51 + 100% 自然法术强度）点自然伤害。'),
(500041, '消耗25点静电为一名盟友注入闪电，持续12 秒，每1秒恢复其最大法力值的15%加上1%。\n\n在效果持续期间，造成的伤害会对附近敌人额外造成（75 × 等级系数 + 15% 自然法术强度）点自然伤害'),
(500042, '命令你的空气元素乘风滑翔到你身边，为你拦截下一次近战或远程攻击，并允许你在移动时施放电击和［拥有风暴召唤: 气爆；否则： 召唤闪电］，持续15 秒。'),
(500053, '当基地激活时，瓶中精魂现在会转化为提基溅射。'),
(500055, '施放觅心弩箭现在使你的物理伤害提高10%，持续8 秒。'),
(500056, '使用暗鸦群命中至少5名敌人，或施放驯犬者之令，会使你在每个被击中的敌人周围释放一群乌鸦，在9 秒秒内造成（1243.5 + 60% 远程攻击强度 + 105% 法术强度）点暮光伤害。'),
(500060, '使［拥有森金的指引: 森金的指引；否则： 投掷武器］的施法时间缩短20%，并移除你因受到伤害而遭受的法术退条效果。'),
(500067, '50级被动使你的耐力提高20%，敏捷提高10%，体型增大10%。'),
(500069, '使你与小队和团队成员的所有法术和攻击命中几率提高1%。\n\n不与类似效果叠加。'),
(500071, '用淬毒箭矢射击敌人的咽喉，造成（25 + 36.0687% 远程攻击强度）点自然伤害，并使其沉默 1 秒。\n\n每层优势使持续时间增加 1 秒。'),
(500073, '向一名敌人发射锯齿箭，使其流血，在4 秒内每3秒造成（36 + 25% 远程攻击强度）点物理伤害。\n\n每层优势使持续时间增加4秒。'),
(500074, '产生1点优势射击一名敌人，造成90%远程武器伤害外加2点伤害。'),
(500075, '精准射击远距离的敌人，造成（76 + 48.5% 远程攻击强度）点物理伤害。\n每层优势效果都会提高伤害。\n可在隐匿状态下使用。'),
(500085, '朝你移动的方向冲刺［拥有战略家: , 恢复5%最大法力值］。距离随移动速度提升。\n\n定身状态下无法使用。'),
(500086, '向后跳跃，使所有远程攻击在2 秒内无法命中你。［拥有保持距离: \n\n你的下一次闪电箭在3 秒内将击退你的敌人。］［拥有逃脱大师: \n\n重置翻越的冷却时间，并产生10点怒气。］'),
(500093, '向一名敌人投掷流星锤，造成（10 + 30% 攻击强度）点物理伤害，并降低其移动速度50%，持续8 秒。'),
(500094, '拥抱内心的黑暗，立即产生20%的最大法力值和50%的最大怒气值。'),
(500101, '你的击退现在会重置翻越的冷却时间，并使你在6 秒内的下一次翻越不消耗资源。'),
(500103, '远程技能对目标造成15%的额外直接火焰伤害，并对最多3个附近敌人造成同样效果。该伤害可受益于你的燃烧毒素及其他提升火焰伤害的效果，并能够造成暴击。\n\n同一时间只能激活1个箭袋。\n\n与其他箭袋共享冷却时间。'),
(500110, '将克苏恩的凝视施加于一名敌人或盟友，跳向1个额外附近目标，对敌人造成（21 + 20% 攻击强度 + 50% 暗影法术强度）点暗影伤害，或为盟友恢复（21 + 10% 攻击强度 + 66.5% 治疗强度）［拥有永恒之眼: 点生命值，并暴露8 秒码内的潜行敌人］。'),
(500115, '使永恒分身的冷却时间减少60秒。'),
(500116, '施放工艺师的魔杖和时光魔杖现在会获得发现，持续30 秒，可叠加4层。'),
(500118, '用冰冷的符文魔法冲击敌人，造成［拥有极寒元素: （冰霜法术强度高于奥术法术强度时：（40 + 165% 冰霜法术强度）；否则：（40 + 165% 奥术法术强度））；否则： （冰霜法术强度高于奥术法术强度时：（40 + 65% 冰霜法术强度）；否则：（40 + 65% 奥术法术强度））］点冰霜伤害，并施加极寒融合。'),
(500121, '使你的法术暴击几率提高25%，持续15 秒。\n\n激活时，你的符印崩解和原初轰击的伤害提高25%。'),
(500123, '攻击一个敌人，造成（19 + 20% 攻击强度 + 20% 法术强度）点物理伤害，并产生怒气。'),
(500124, '向附近敌人的灵魂嚎叫，造成（71 + 28.5% 攻击强度）点暗影伤害，并使其移动速度降低60%，持续6 秒。'),
(500125, '需要凡人形态对一名敌人造成（24 + 46.6229% 暗影法术强度）点暗影伤害并产生怒气［拥有饥渴: ，并获得1层饥渴。；否则： 。］［拥有吸血宝典: \n\n可在移动时使用。］'),
(500126, '跃至敌人身后，造成（8.6 + 20% 攻击强度）点物理伤害，使其眩晕3秒，并产生15点怒气。'),
(500135, '产生50点热量在8码范围内召唤一颗陨石，对8个敌人造成（122 + 125% 火焰法术强度）点火焰伤害，并使其迷惑4 秒。直接伤害会打破该效果。'),
(500141, '折射圣光束，治疗目标（209.88 + 14.1131% 治疗强度）点生命值，并跳转至 4 名额外盟友，每次跳转治疗递减。'),
(500142, '在 18 秒内治疗一名盟友，总治疗量为（96 + 75.6% 治疗强度）点。'),
(500143, '治疗一名盟友（39 + 105% 治疗强度）点生命值。'),
(500144, '造成（95 + 75% 神圣法术强度）点神圣伤害，产生 1 点太阳能量。'),
(500146, '以灼热的圣光轰击敌人，造成（88 + 76.5222% 火焰法术强度）点火焰伤害。'),
(500147, '2 次充能，充能恢复时间 10 秒。以祷言治疗一名盟友（186 + 59.5% 治疗强度）点生命值。'),
(500149, '达到 20 层时可以释放黎明。'),
(500151, '治疗目标周围 15 码内的所有小队和团队成员 48 点生命值。可对敌人或盟友使用。'),
(500152, '治疗 40 码内所有盟友（219.24 + 310% 法术强度）点生命值。与其他太阳祈愿共用冷却时间。'),
(500154, '造成（73 + 100% 神圣法术强度）点神圣伤害，并使目标的攻击强度降低 19.6，持续 15 秒。'),
(500161, '你的下一次诅咒无视目标当前生命值即可使用。持续20 秒。'),
(500166, '使余烬消耗技能造成暴击的几率提高5%。'),
(500167, '你的吸收效果提高20%。'),
(500169, '横扫附近敌人，造成（19 + 20% 攻击强度 + 20% 法术强度）点物理伤害。'),
(500205, '你的星火射击现在具有月蚀效果。\n\n星火射击：对目标施放灼烧，在6 秒秒内造成720点法术火焰伤害。受你的星火术影响的敌人无法潜行。'),
(500206, '每10 秒，你会在满月和新月之间循环。'),
(500217, '目标感染枯萎，使附近敌人每秒受到（110 + 84.5875% 法术强度）点暗影伤害，持续20 秒秒。\n\n20 秒秒后，枯萎从目标身上爆发，造成93点自然伤害。'),
(500219, '50级被动当你施放任意法术时，现在有20%的几率获得衰亡循环。\n\n此外，孢子和枯萎造成的周期性伤害现在可以造成爆击。'),
(500230, '触发毒素现在有25%的几率为你产生5点能量。'),
(500232, '［拥有建造：机甲: 产生10个废料］\n投掷一枚炸弹粘附在敌人身上，持续5 秒。\n\n持续时间结束时炸弹会爆炸，对目标及目标8码范围内的4个敌人造成（17 + 21.3% 攻击强度 + 40.7381% 火焰法术强度）点火焰伤害。\n\n可对尸体使用。'),
(500235, '向一名敌人发射强力火箭，造成（126 + 35% 远程攻击强度 + 35% 火焰法术强度）点火焰伤害。'),
(500236, '呈直线发射3枚死亡之球，飞行距离越远速度越快。\n\n它们与敌人接触时爆炸，对附近敌人造成（1028.1 + 35% 远程攻击强度）点火焰伤害，伤害随飞行距离提高。\n\n积攒技能会使此技能的冷却时间缩短2秒。'),
(500239, '建造一座哨兵炮台，持续5 分钟，向敌人发射子弹，造成（7% 攻击强度 + 100 × 等级系数）点物理伤害。再次激活可拆除你的哨兵炮台。\n\n同一时间只能拥有1座哨兵炮台。'),
(500241, '3层充能，30秒充能时间激活你的火箭靴，移除定身效果并向前冲刺。'),
(500242, '建造一个碎片吞噬者来陪伴地精工程师，直到被解散。'),
(500249, '释放一连串弹片，对直线上的敌人造成（831 + 36% 远程攻击强度 + 55% 火焰法术强度）点火焰伤害，并对每个被击中的目标施加一个次级黏性炸弹，在3秒后造成（283.881 + 50% 攻击强度 + 10% 火焰法术强度）点火焰伤害。\n\n3 秒后，你激活的哨兵炮台也将发射一发高爆弹幕。'),
(500250, '施放或重新激活跃迁匕首现在会移除你身上的所有定身和减速效果。'),
(500258, '对目标下达最终审判，造成（1195 + 100% 攻击强度）点物理伤害，并为你恢复15%的最大生命值。\n\n仅可在生命值低于35%的敌人身上使用。击杀目标会重置此技能的冷却时间。'),
(500259, '在你的背部装备一面迅捷旗帜，使40码范围内的队伍和团队成员急速提高5%。\n\n不与类似效果叠加。'),
(500261, '在你的背上装备一面征服旗帜，使40码范围内的队伍和团队成员暴击几率提高5%。\n\n该效果无法与同类效果叠加。'),
(500269, '坚守阵地，嘲讽周围的敌人，持续5 秒，并使他们从你的尖刺强化受到的伤害提高100%。'),
(500270, '使用回响符文标记当前位置，持续20 秒。\n\n持续时间结束或再次激活时，传送回标记位置并恢复（265 + 150% 攻击强度）点生命值。'),
(500286, '等级 30 被动：成功闪避攻击现在有 50% 几率从攻击者身上收割 1 个灵魂碎片。'),
(500287, '向前方直线投掷一把附魔匕首。再次激活时，你立即传送至匕首所在位置，并对附近敌人造成（32.85 + 20% 攻击强度 + 44% 法术强度）点元素伤害。\n\n可在潜行状态下使用。'),
(500288, '使你的身形隐入迷雾，进入潜行状态，并使移动速度降低30%。\n\n战斗中无法使用。［拥有帷幕行者: \n\n激活期间，跃迁匕首没有冷却时间。］'),
(500294, '图腾猛击和双头飞龙之咬现在会使敌人流血，在12 秒内造成（4.5% 攻击强度 + 155 × 等级系数）点伤害，可叠加2层。'),
(500296, '在你脚下制造一个力量铭刻，持续20 秒，使区域内最多5名盟友获得20%魔法伤害加成和20%暴击几率提升。'),
(500302, '用安抚之触成功驱散一个中毒或疾病效果后，会治疗相当于最大生命值4%的生命值。'),
(500329, '召唤一只倒下的石像鬼协助你战斗，占用3点生命之力。\n\n命令：向一名敌人射出坏死胆汁，造成（473 + 65% 法术强度）点瘟疫伤害，目标身上每有一个你的疾病，伤害提高50%。'),
(500331, '召唤一名骷髅法师协助你战斗，占用 ［拥有墓穴法师: 1；否则： 2］ 点生命之力。\n\n命令：向目标及 6 码范围内的敌人释放冰霜，造成（51 + 80% 冰霜法术强度）点冰霜伤害。'),
(500335, '召唤一个憎恶协助你战斗，占用3点生命之力。\n\n它被疾病云雾环绕，当敌人造成伤害时，对其造成（9 + 25% 法术强度）点自然伤害，并使其攻击速度降低20%，持续15 秒。\n\n命令：立即在其周围释放强化疾病云雾。'),
(500338, '使一名敌人感染疾病，每3秒造成（15 + 11.055% 暗影法术强度）点瘟疫伤害，持续18 秒，并产生符文能量。\n\n此效果造成的周期性伤害可造成暴击。'),
(500341, '用死灵能量将敌人活埋，将其放逐，使其无法做出任何行动，并在4 秒内免疫物理伤害。'),
(500342, '在接下来的15 秒内，你的疾病发生变异，加速致命性，使你新施加的疾病每跳速度提高50%。'),
(500343, '使目标从你的死灵法师疾病中受到的伤害提高10%，持续10 秒，可叠加2层。'),
(500344, '摆出最优姿态，使你的史诗值提高100%，并让附近的卫兵因嫉妒而为你鼓掌。\n\n此效果为开关式，移动将中断该效果。'),
(500357, '生成 1 个灵魂碎片。攻击一名敌人，造成 90% 武器伤害外加 3 点伤害，并生成符文能量。受相应双持效果影响时，改为双手武器分别造成该伤害。'),
(500359, '冲向一名敌人并将其定身 1 秒，同时生成 15 点符文能量。同一目标每 20 秒只能生效一次。'),
(500373, '生成 1 层收割之魂。用你的镰刃清除一名敌人，造成 150% 武器伤害外加 17 点。仅可对生命值低于 35% 的敌人使用。'),
(500376, '命令灵魂群鸦攻击一名敌人，造成 13 点 + 18% 攻击强度的暗影伤害，并使其命中几率降低 3%，持续 10 秒。拥有灵魂收集者时，生成 1 层收割之魂。'),
(500402, '在1 秒内向一名敌人投掷三块石头，每块造成（13 + 9% 攻击强度 + 36% 自然法术强度）点物理伤害并产生怒气。'),
(500445, '20级被动使你的法术暴击等级提高敏捷值的30%，法术命中等级提高敏捷值的5%。\n\n此外，你获得的法术穿透等级等于你的护甲穿透等级。'),
(500464, '在你脚下铭刻一道半径为10码的防御符文，召唤一道屏障，使范围内的盟友受到的魔法伤害降低40%。持续15 秒。'),
(500472, '你的投掷药水和溅射药水的冷却时间被重置，且在5 秒内的下一次使用会对受影响盟友施加丛林蓟效果。\n\n立即将你的材料切换为丛林蘑菇和血蓟。'),
(500476, '当武器铭刻：火焰激活时，你的元素迸发额外造成10%火焰伤害，且触发武器铭刻：火焰的几率提高5%。'),
(500477, '神圣伤害提高 20%，持续 2 分钟。'),
(500478, '用治疗之水泼洒目标位置，每1.25秒治疗（34 + 25% 法术强度）点，持续5 秒。根据你当前激活的基础获得新效果。受瓶中精魂的修正效果影响。\n\n兽血：使你获得5%的暴击几率提高，持续15 秒，可叠加2层。\n\n水晶之水为你提供一个护盾，吸收（228.54 + 75% 法术强度）点魔法伤害，持续15 秒。'),
(500483, '每有 1 层活跃的收割之魂，便创造 1 个受难灵魂并生成符文能量；学会融魂体魄后改为创造 2 个。消耗收割之魂与灵魂灌注。'),
(500484, '每有 1 层活跃的收割之魂便召唤 1 把幽魂镰刀，攻击附近敌人，持续 20 秒。以灵魂突刺命中敌人会使幽魂镰刀转而攻击该敌人及周围 5 个敌人。消耗收割之魂与灵魂灌注。'),
(500501, '对一名敌人施加符文印记，持续8 秒，累积你造成伤害的50%，并在8 秒后释放为元素伤害。\n\n当此效果造成伤害时，会触发你的武器铭刻。'),
(500508, '使友方目标受到的范围攻击伤害降低30%，持续10 秒。'),
(500509, '最大生命值提高10%，体型增大15%，持续10 秒。'),
(500511, '火焰暴击几率提高 20%，火焰伤害提高 10%，持续 2 分钟。'),
(500517, '产生 1 层收割之魂。攻击一名敌人，造成 75% 武器伤害 + 3 点暗影伤害，并恢复相当于所造成伤害 80% 的生命值，再额外恢复已损失生命值的 10%。'),
(500534, '你的受敬先祖获得你受到的治疗量的30%。'),
(500535, '制造一个蜘蛛炸弹，它会立即跑向你的目标并爆炸，在8码半径内造成（33.5 + 18% 远程攻击强度 + 18% 法术强度）点火焰伤害。\n\n使用废料射击会将蜘蛛炸弹重新导向你的新目标。'),
(500542, '等级 40 被动：使你的暴击等级提高自身力量值的 20%；此外，对生命值低于 35% 的敌人时，护甲穿透提高 30%。'),
(500549, '［拥有建造：机甲: 产生3块废料\n］用废料碎片射击一名敌人，造成100%远程武器伤害外加3点伤害。'),
(500551, '夺颅者的暴击现在使你的强效小鬼的急速提高15%，持续8 秒。'),
(500567, '50级被动每第5次暗影斩杀或暗影射击现在会将你的快速拔枪转变为六连射击。'),
(500572, '对一名敌人施放命令法术现在会对主要目标附近的3个敌人施加墓穴瘟疫。'),
(500578, '你的强效小鬼造成的火焰伤害现在有25%的几率强化你，使你的伤害提高5%，持续10 秒。'),
(500580, '你的空气元素造成的伤害现在为你产生2点静电。'),
(500582, '女神之相的效果提高25%。'),
(500584, '等级 50 被动：通过「收割——等级 10 被动」获得的治疗量提高 10%；身处你的收割之地时，该效果额外提高 75%。'),
(500594, '为目标恢复最大生命值的10%，并驱散1个魔法效果。'),
(500600, '3层充能，10秒充能时间制造一架火罐无人机，飞向你的目标，沿途投下炸弹并在着陆时爆炸，对5码范围内的敌人造成（17.5% 远程攻击强度 + 182 × 等级系数 + 45% 火焰法术强度）点火焰伤害，并在地面留下油污，持续6 秒，使范围内的敌人移动速度降低30%。'),
(500608, '使你的架势的冷却时间缩短5秒。'),
(500610, '产生1层邪能狂怒朝你奔跑的方向向前冲刺，对路径上的敌人造成（79.6 + 35% 攻击强度）点暗影烈焰伤害。\n\n产生大量威胁值。受混沌突进的修正效果影响'),
(500612, '投掷一枚炸弹，粘附在敌人身上持续3秒。\n持续时间结束时炸弹会爆炸，对目标造成（17 + 2.5% 攻击强度 + 5% 火焰法术强度）点火焰伤害。'),
(500615, '击垮你的目标，打断施法并阻止该系法术在4 秒内被施放。\n成功打断目标可获得1层大地塑形。'),
(500617, '猛击敌人的喉咙，打断其施法，并阻止该系法术在2 秒内被施放。'),
(500631, '将收割之魂储存在武器中，并将其能量转化为灵魂箭。灵魂箭在 5 秒内向前射出，每发对直线上的敌人造成 650 × 等级系数 + 40% 攻击强度的暗影冰霜伤害。消耗收割之魂与灵魂灌注。冷却时间：20 秒。'),
(500671, '从视线中消失，进入强化潜行状态，持续6 秒，并施加符文帷幕。'),
(500678, '冥想15 秒，每1秒恢复最大生命值的5%，并降低受到的伤害50%。\n\n每秒还会从自身移除1个疾病效果。\n\n施加神圣束缚，持续1 分钟。'),
(500688, '召唤盟友的灵魂回到其身体，使其复活。\n\n可在战斗中施放。'),
(500689, '释放神圣狂怒，对附近所有敌人造成（391 + 25% 攻击强度 + 45% 神圣法术强度）点神圣伤害，触发每个敌人身上的狂热，并使其护甲降低5%，持续20 秒，可叠加5层。\n\n受到对辩护的加成影响，并赋予誓言：昭雪。'),
(500692, '从地面升起一块巨石并将自己包裹其中，使你无法攻击或施放法术。\n\n在10 秒内，你以70%的移动速度向前翻滚，对翻滚路径上的敌人造成（1 + 50% 攻击强度 + 100% 法术强度）点物理伤害，并且免疫群体控制效果。'),
(500694, '以神圣能量爆发，对附近敌人造成（62 + 25% 攻击强度 + 25% 神圣法术强度）点神圣伤害，并每 1 秒触发一次狂热，持续 5 秒。\n\n激活时，你的神殿守护者法术的能量消耗降低 50%。'),
(500696, '［拥有灵魂兽大师: 你和你的宠物；否则： 向］前猛冲20码，对直线上的敌人造成40点自然伤害。\n\n产生20点怒气。'),
(500704, '将一个敌人传送至你的位置，并使其移动速度降低60%，持续4 秒。'),
(500711, '用奥术魔法包裹一名盟友，为其恢复（41 + 12% 攻击强度 + 56% 治疗强度）点生命值。'),
(500712, '产生20点狂乱诅咒一个敌人，立即造成（976 + 150% 法术强度）点暗影伤害，并在5 秒后额外造成（1957.32 + 100% 暗影法术强度）点暗影伤害。'),
(500714, '产生10点狂乱以邪异之力猛击一个敌人，造成（40 + 10% 攻击强度 + 52% 法术强度）点暗影伤害，并对5名附近盟友施加黑血，为其恢复（25 + 10% 攻击强度）点生命值，每3秒重复一次，持续12 秒。\n\n可在移动时使用。'),
(500715, '为一名盟友施加护盾，在30 秒内吸收（195 + 200% 法术强度）点伤害，并施加心智撕裂。'),
(500719, '湮灭光束的冷却时间缩短20%，并且现在会对所有击中的目标施加疯狂效果。'),
(500720, '3 层充能，6秒充能时间产生20点狂乱值攻击一名敌人，造成［拥有克苏恩意志: （22 + 25% 攻击强度 + 30% 暗影法术强度）；否则： （22 + 25% 攻击强度 + 15% 暗影法术强度）］点暗影伤害。'),
(500721, '3层充能，30秒充能时间向一名盟友注入暗影能量，在其下次受到伤害时为其恢复66点生命值。当治疗触发时，暗影灌注会被消耗并扩散至附近生命值最低的两名小队或团队成员。每次次级灌注在触发时都会进行治疗，随后扩散至附近三名盟友。'),
(500723, '嘲讽8码范围内的敌人，持续5 秒，并在5 秒内显著提高威胁值产生。'),
(500751, '将你与一名盟友链接30 分钟，转移其承受伤害的10%至你身上，并使你造成的伤害中20%转化为对其的治疗。\n\n每次只能对一名盟友施加此效果。'),
(500764, '命令你的宠物向目标短距离冲锋，打断施法，并阻止该系法术在3 秒内被施放。'),
(500904, '以恶魔之力猛击敌人，造成100%武器伤害外加3点伤害，并产生20点怒气。'),
(500913, '你的下一次攻击将猛烈挥击一个敌人及其附近最多2个敌人，造成135%武器伤害外加10点伤害。'),
(500915, '碾压前方锥形区域内的敌人，造成275%武器伤害，外加30［拥有碾压者: ；否则： ，使敌人昏迷3 秒秒］。'),
(500918, '需要激怒以先祖之狂热咆哮，为你恢复（100 + 50% 攻击强度）［拥有满溢: 点生命值，并获得1层满溢］。'),
(500923, '用风之力庇护自己，使伤害你的敌人被阵风击中并被击退。持续45 秒或3次攻击。'),
(500928, '将闪电注入敌人体内，在18 秒内造成（168 + 114% 自然法术强度）点自然伤害，并使其移动速度降低40%。\n\n每跳产生2点静电。'),
(500932, '向前方锥形区域释放阵风，击退敌人并打断所有敌人的当前施法，使其在5 秒内无法施放该系法术。'),
(500933, '在你附近创建一个命匣，持续2 分钟。\n\n当受到会使你生命值低于10%的伤害时，你将变为一个暗影，免疫所有物理攻击和法术，但在此期间你无法攻击或施法。\n\n在此状态下抵达你的命匣，将恢复你最大生命值的40%。若未能及时抵达，你将死亡。'),
(500935, '使你受到的伤害降低10%，并对近战攻击者造成3点自然伤害。\n\n同一时间只能激活1个赐福。'),
(500937, '图腾猛击现在会对敌人施加图腾粉碎，持续2 秒。\n\n效果结束时，如果你在目标5码范围内，你将免费对其施放图腾猛击。'),
(500939, '提高你的近战攻击强度、近战急速以及自动攻击产生的怒气值，效果为10%。\n\n同一时间只能激活1个恩赐。'),
(500940, '命令你的宠物撕碎8码内最多5个敌人，使其流血，在21 秒内造成（49.875 + 35% 攻击强度）点物理伤害。'),
(500943, '使你的法术急速提高12%，法术和技能消耗降低10%，并每5秒恢复1%的最大生命值。\n\n同一时间只能激活1个恩赐。'),
(500947, '变形成一条蛇，移除所有移动限制效果，并使移动速度提高80%，持续5 秒。\n\n你无法攻击或施法，但在此期间被远程攻击和法术命中的几率降低100%。'),
(500950, '为一名盟友注入魔精，在8 秒内每0.5秒恢复（126 + 10.73% 法术强度）点生命值。\n\n每当魔精光束治疗一个目标时，它都会生长出一条新枝。每条新枝会立即进行治疗并持续治疗。每长出一条新枝，你消耗的法力值都会增加。\n\n引导期间，你可以消耗20%额外法力值立即施放投掷药水、溅射药水和瓶中精魂。\n\n该法术不受急速修正影响。'),
(500952, '将目标位置敌人变成青蛙，使其无法攻击或施法，并降低其移动速度25%，持续40 秒（对玩家为8秒）。变成青蛙期间，该敌人被视为野兽。\n\n造成伤害可能会中断该效果。'),
(500957, '在你附近放置一根治疗守卫，持续 1 分钟，每 2.5 秒为 30 码范围内的 8 名附近盟友恢复（5.85 + 8% 远程攻击强度 + 18.5% 法术强度）点生命值。\n\n同时只能激活 1 根守卫。'),
(500960, '在你附近放置一个毒蛇守卫，持续1 分钟。\n\n守卫会向附近的敌人喷吐火焰，并优先攻击你的主要目标。\n\n同时只能激活1个守卫。'),
(500961, '在你附近放置一个精魂神像，持续15 秒。\n\n30码范围内的盟友每3秒恢复4%的最大法力值。'),
(500962, '用大锅灌注你的水晶之水，持续10 秒，使40码范围内的队伍和团队成员的受到治疗量的20%转化为护盾，持续5 秒。\n\n同时只能激活1个基底。'),
(500965, '引导一群蝗虫攻击敌人，造成24点暗影伤害［拥有召唤熟习: 使其移动速度降低30%，］并在3 秒内产生符文能量。［拥有召唤熟习: \n\n强化附近活跃的不死仆从，赋予其地穴之怒。］'),
(500967, '冰刺从一名盟友和复生仆从的体内喷发，持续30 分钟，使攻击者在命中时受到4点冰霜伤害。'),
(500968, '使一个敌人感染疾病，每3秒吸取（29 + 15% 法术强度）点生命值，持续18 秒，为你恢复部分造成的伤害。\n\n瘟疫会加剧，并根据目标离死亡的距离吸取更多生命值。'),
(500969, '召唤一个骷髅盗贼协助你战斗，占用1点生命之力。\n\n攻击时有几率施加腐化毒药，使目标的施法速度降低10%，持续6 秒，可叠加3层。\n\n命令：跃向你的目标并攻击2次。对生命值低于35%的敌人总是攻击5次。'),
(500970, '召唤一个次级骷髅战士协助你战斗，占用1点生命之力。\n\n命令：攻击前方一名敌人，造成武器伤害外加（1 + 13.65% 法术强度）点伤害。'),
(500971, '召唤一只食尸鬼协助你战斗，占用1点生命之力。\n\n它的自动攻击为你恢复（5.35 + 3.528% 智力 + 3.528% 法术强度）点生命值。\n\n命令：释放腐蚀瘟疫，击中最多5个附近敌人，造成（30 + 15.68% 智力 + 15.68% 法术强度）点瘟疫伤害，并为每个食尸鬼为你恢复（15.5 + 50% 智力 + 22% 法术强度）点生命值。'),
(500981, '变身为巫妖，成为亡灵，使你的冰霜伤害提高10%。\n\n激活时，每5秒产生3符文能量。\n\n亡灵状态下，你免疫恐惧、睡眠和魅惑效果。'),
(500982, '你的亡灵仆从进入攻击姿态，移动速度提高30%。［拥有腐臭召唤者: 你对人型生物的暴击几率提高5%。］\n\n同时只能激活1个亡灵姿态。'),
(500983, '你的亡灵仆从进入被动姿态，不会攻击敌人或施放法术。［拥有腐臭召唤者: 使你受到的伤害降低10%。］\n\n同一时间只能激活1种亡灵姿态。'),
(500984, '向前方 30 码直线区域投掷一柄长矛，造成 131% 远程武器伤害外加 23 点伤害，每击中一个敌人伤害递减。\n\n长矛在落点处碎裂，对附近敌人造成（149 + 15% 远程攻击强度）点物理伤害。\n\n与其他长矛技能共享冷却时间。'),
(500985, '你的亡灵仆从进入防御姿态，提高威胁值和护甲。［拥有腐臭召唤者: 使你产生的威胁值降低75%。］\n\n同一时间只能激活1种亡灵姿态。'),
(500989, '召唤一个腐朽巨像协助你战斗，占用3点生命之力。\n\n激活时，施法者承受的所有伤害中有25%由腐朽巨像承担。\n\n命令：释放一次强力攻击，对前方所有敌人造成武器伤害外加100点伤害。'),
(500991, '命令你的亡灵集中攻击目标敌人。\n\n可在施法或引导时使用。'),
(500995, '发出令人胆寒的战吼，使25码范围内队伍和团队成员的近战和远程攻击速度提高20%，攻击强度提高150，持续20 秒。\n\n盟友在5 分钟内无法再次受到该法术的影响。'),
(501132, '使塔达拉姆的折磨的伤害频率和法力消耗提高30%。'),
(501134, '投掷一把战刃，诅咒一名敌人及其附近最多2名敌人，每1秒吸取（3 + 10% 远程攻击强度）点生命值，持续6 秒。刷新恶意妖咒的持续时间。\n\n随恶意妖咒的修正效果而缩放。'),
(501136, '进入隐形状态，持续20 秒，获得5个精魂，留下一个自己的幻影，并每秒降低威胁值。直接造成伤害或进行治疗将结束此效果。\n\n隐形状态下，你只能看到其他隐形目标和能够看到隐形的目标。'),
(501380, '揭露敌人最黑暗的缺陷，使其瘫痪40 秒秒（对玩家为8秒）。\n\n造成伤害将终止此效果。仅能对人型生物、恶魔和不死生物使用。\n\n你同时只能对一个敌人施加1个烙印。'),
(501562, '释放一个强大的破誓者，造成（72 + 45% 攻击强度 + 45% 法术强度）点物理伤害，在狂热期间每触发一次誓言锁链，伤害提高10%。\n\n消耗你的誓言，每消耗一层造成额外伤害。'),
(502429, '治疗一名盟友（1229 + 105% 治疗强度）点生命值。'),
(502537, '向一名盟友发送纳米机器人［拥有 X-420型强力净化器: ，使其受到的所有周期性伤害降低 0% 并］每 3 秒移除 1 个中毒和疾病效果［拥有 X-420型强力净化器: s］，持续最多 15 秒。\n\n纳米机器人净化器每次只能发送给1个目标，且无法被驱散。'),
(503532, '移除荣耀竞技场的能量消耗，并使其造成的伤害提高25%。'),
(503534, '你的召唤物造成的伤害现在有40%的几率使你的攻击强度和法术强度提高9点，持续30 秒，可叠加3层。'),
(503550, '粘性炸弹爆炸的伤害提高15%。'),
(503552, '直接治疗暴击现在使你的下一次修复射击或紧急治疗的治疗效果提高30%，持续10 秒。'),
(503568, '你的机甲现在激活时额外提高你 10% 的伤害。'),
(503569, '激活你的机甲后的 8 秒内，所有造成的伤害将产生 3 个废料。'),
(503583, '你的庇护法术的法力值消耗降低10%。'),
(503584, '由群星之相召唤的群星之相现在使你的急速提高3%，持续5 秒，可叠加3次。'),
(503596, '提高你的法术急速 2%，并降低受到伤害性攻击时的法术退条效果 25%。'),
(503608, '使你的敏捷和智力提高5%。'),
(503630, '2层充能，20秒充能时间从脚下升起岩石，使你的护甲提高（100 + 300% 耐力）点，数值随耐力提高。持续10次攻击或10 秒。\n\n消耗一层岩石屏障充能会向敌人发射一枚晶核。'),
(503631, '你的骑兵冲锋的冷却时间缩短30秒，并且现在可以防止盟友受到定身和减速效果。'),
(503636, '提高炽燃和点燃的伤害 20%。'),
(503637, '群星覆体的冷却时间缩短10秒。'),
(503639, '群星覆体的持续时间延长4秒。'),
(503651, '使敌人定身 4 秒；或治疗盟友，恢复 10% 最大生命值，并使其移动速度提高 50%，持续 4 秒。与其他太阳祈愿共用冷却时间。'),
(503655, '你的火焰伤害提高5%。'),
(503659, '招架敌人攻击现在恢复你 5% 的缺失生命值和怒气值。'),
(503662, '向一名敌人投掷火炬，造成（166 + 30% 攻击强度 + 45% 火焰法术强度）点火焰伤害，并且你对其发起的后续最多5次攻击将为你提供罪孽之火，并使其持续时间延长2秒。'),
(503664, '增加黎明和黄昏的层数，共10层。\n\n此外，当两种增益效果均达到20层时，会消耗它们，使你在6 秒内获得20%的伤害、近战急速、移动速度和暴击几率提升。'),
(503669, '你的快速拔枪现在还会使你在 15 秒内的下一次暗影斩杀变为瞬发。'),
(503679, '在5码范围内投掷铁蒺藜，持续12 秒。\n\n踩中铁蒺藜的敌人会受到（5 + 25% 远程攻击强度）点物理伤害，并在2 秒内移动速度降低50%。'),
(503680, '提高暮光狂暴的持续时间 5 秒，并使其造成的伤害有 15% 的几率再次触发。'),
(503681, '暗影斩杀的伤害提高50%，但施法时间增加0.5秒。\n\n你的觅心弩箭和暗影斩杀现在有25%的几率额外攻击一次。'),
(503682, '降低猎巫和暗影射击的怒气消耗 10%，并提高你的命中几率 2%。'),
(503690, '施放黎明之盾时，有 40% 几率重置圣槌的冷却时间，并使下一个圣槌不触发冷却时间。'),
(503696, '使你的精神和最大法力值提高5%。'),
(503698, '提高你的法令效果 20%。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (503707, 503712, 503714, 503717, 503718, 503719, 503721, 503727, 503736, 503738, 503740, 503742, 503748, 503750, 503757, 503774, 503779, 503799, 503803, 503804, 503806, 503812, 503825, 503826, 503831, 503836, 503837, 503850, 503851, 503852, 503854, 503856, 503863, 503875, 503907, 503913, 503915, 503918, 503919, 503923, 503930, 503960, 503970, 503976, 504001, 504003, 504004, 504006, 504008, 504011, 504012, 504037, 504046, 504050, 504060, 504070, 504071, 504088, 504098, 504100, 504103, 504107, 504116, 504139, 504140, 504144, 504148, 504149, 504159, 504184, 504193, 504196, 504197, 504198, 504214, 504217, 504219, 504220, 504222, 504223, 504226, 504229, 504241, 504248, 504252, 504254, 504260, 504263, 504269, 504272, 504275, 504282, 504284, 504285, 504290, 504292, 504296, 504309, 504316, 504322, 504326, 504329, 504335, 504339, 504341, 504342, 504344, 504347, 504348, 504352, 504355, 504356, 504357, 504361, 504375, 504380, 504383, 504385, 504393, 504394, 504397, 504400, 504401, 504402, 504404, 504406, 504407, 504424, 504426, 504431, 504439, 504446, 504459, 504462, 504465, 504470, 504489, 504503, 504519, 504521, 504523, 504525, 504527, 504530, 504531, 504543, 504551, 504560, 504561, 504581, 504582, 504586, 504594, 504602, 504603, 504627, 504628, 504642, 504645, 504677, 504694, 504704, 504705, 504706, 504707, 504710, 504720, 504728, 504730, 504732, 504733, 504734, 504736, 504750, 504754, 504758, 504759, 504764, 504774, 504782, 504784, 504786, 504798, 504799, 504807, 504808, 504837, 504840, 504846, 504848, 504849, 504855, 504856, 504859, 504861, 504866, 504867, 504868, 504874, 504897);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(503707, '散发强大的光环，使小队和团队成员获得10%的近战和远程急速加成。不与类似效果叠加。\n\n恶意妖咒造成的周期性伤害现在有20%的几率收集一个精魂。'),
(503712, '50级被动技能施放精魂回收和恶咒箭现在有30%的几率将你的下一次精魂回收转化为精魂齐射，持续6 秒。'),
(503714, '暴击现在对敌人施加金布尔的凝视，持续15 秒。'),
(503717, '地震尖刺现在使你的狂野之爪攻击最多 4 个额外附近目标，每额外击中一个目标伤害降低。持续 6 秒。'),
(503718, '使用生命之锤或大地母亲之手有效治疗盟友现在有 20% 的几率施加注入力量。'),
(503719, '使所有小队和团队成员暴击几率提高5%，持续10 秒。\n\n不与类似效果叠加。'),
(503721, '将某个位置标记为你的林苑，持续 20 秒。\n\n范围内的盟友获得 30% 移动速度加成，并每 5 秒恢复（404 + 25% 攻击强度）点生命值，同时移除 1 个中毒和疾病效果。\n\n范围内的敌人移动速度降低 30%，每 5 秒受到（504 + 45% 攻击强度）点自然伤害，并被定身 2 秒。'),
(503727, '收集一个精魂现在立即恢复3%的最大法力值。'),
(503736, '产生 10% 的最大法力值和 20 点怒气，并在 10 秒内每 2 秒额外产生 2 点怒气和 4.55 点法力值。'),
(503738, '使队伍和团队中所有成员造成的伤害提高3%。不与类似效果叠加。\n\n此外，使尸体爆炸的伤害提高25%。'),
(503740, '你的食尸鬼造成的伤害现在有 15% 的几率将其转化为狂乱食尸鬼。'),
(503742, '你的模仿守卫现在会召唤 1 个额外的守卫。'),
(503748, '提高你造成的治疗量 4%，并降低你的法术产生的威胁值 15%。'),
(503750, '向一名盟友投掷你的愤怒酿造，恢复其最大怒气、能量和集中值的50%。\n\n使其攻击强度和远程攻击强度提高15%，持续10 秒。'),
(503757, '降低你的复活和活化法术的法力消耗和施法时间 30%。'),
(503774, '召唤一个神像现在使你的精神提高 10%，持续 1 分钟。'),
(503779, '月之箭矢现在会使15 秒内施放的下一个艾露恩之手的施法时间缩短20%，可叠加5次。'),
(503799, '施放消耗孵化印记的法术现在有25%的几率返还其孵化印记消耗。'),
(503803, '使你的移动速度提高50%，持续2 秒。'),
(503804, '烈焰施法层数现在每层也使爆炸和奈萨里奥之焰的伤害提高4%。'),
(503806, '火焰之环的冷却时间缩短30秒，并使迷惑持续时间延长1秒。\n\n被火焰之环迷惑的敌人无法接受任何治疗。'),
(503812, '使用倒钩之刺造成伤害现在会使目标受到的自然伤害提高5%，持续12 秒。'),
(503825, '周期性伤害现在有 8% 的几率向目标发射一枚异常尖刺。'),
(503826, '造成（奥术法术强度高于暗影法术强度时：（161 × 等级系数 + 25% 奥术法术强度）；否则：（161 × 等级系数 + 25% 暗影法术强度））点多彩伤害。'),
(503831, '异常尖刺造成的伤害现在每层也使你的多彩碎片的伤害和暴击几率提高6%。'),
(503836, '在目标位置放置一个不稳定时光玻璃，持续30 秒，它会将接下来的3个敌方进攻性法术引导至自身。'),
(503837, '30码内的盟友现在从范围攻击中受到的魔法伤害降低10%。'),
(503850, '对生命值低于35%的目标造成的伤害和治疗效果提高15%。'),
(503851, '在15 秒内，所有周期性伤害现在有30%的几率爆发，对8码范围内的8个敌人造成（92 × 等级系数 + 20% 暗影法术强度）点暗影伤害。'),
(503852, '寡妇之吻对疾病目标的爆击几率提高30%。'),
(503854, '毒牙造成的伤害提高15%，并使其使目标被法术爆击的几率提高3%，持续15 秒。'),
(503856, '现在造成的伤害和治疗有 10% 的几率施加沙德拉诅咒，持续 10 秒。\n\n对受到诅咒的敌人使用毒蛇之牙、爪击或毒牙造成伤害或进行治疗时，将额外造成 25% 的伤害或治疗量，并为你恢复相当于 19.2 的生命值。'),
(503863, '提高熔岩碎片的法术加成系数30%。'),
(503875, '对一名敌人及最多3个附近敌人造成（40 + 25.0505% 法术强度）点虹彩伤害。［拥有时光之穴: \n\n产生1个回响碎片。］'),
(503907, '变形会解除你身上的定身和减速效果。'),
(503913, '等级40 被动使你的法术暴击等级提高，数值相当于精神属性的15%。'),
(503915, '消耗一个余烬现在使你的下一个烬火之心或引燃的施法时间缩短15%，持续12 秒，可叠加2次。'),
(503918, '施放草本万用膏现在也返还你20%的基础法力值。'),
(503919, '枯萎的伤害提高20%，并且现在使目标被法术命中的几率提高3%，持续20 秒。'),
(503923, '从毒蛇领主的指环汲取力量，立即恢复20%的最大法力值，并使你的霉菌病在15 秒内没有冷却时间且无需消耗。'),
(503930, '真菌增生的层数对霉菌病提供的伤害增幅提高5%。'),
(503960, '受到直接伤害时，有30%的几率获得2点怒气，并恢复3%的基础法力值。每秒最多触发一次。'),
(503970, '你的爆击几率提高3%。'),
(503976, '毒液箭、虫巢破击或毒牙造成暴击后，使你的移动速度提高20%，持续3 秒。'),
(504001, '使用艾露恩之手造成暴击治疗时，现在会使目标的护甲提高10%，持续15 秒。\n\n此外，月井喷涌现在在对盟友施放时总是会治疗你。'),
(504003, '提高艾露恩之手和月流的暴击治疗效果15%。'),
(504004, '月之箭矢的伤害提高20%，并使目标受到的法术伤害提高10%，持续12 秒。'),
(504006, '星火射击现在会使敌人从你的女猎手射击受到的伤害提高10%，持续8 秒，可叠加2层。'),
(504008, '减少致残射击和爆裂种子的冷却时间20%。'),
(504011, '对所有附近敌人造成 75% 武器伤害外加 8 点。造成的伤害会收割灵魂碎片，最多 3 个。'),
(504012, '生成收割之魂现在会触发灵魂收割。'),
(504037, '使群鸦收割的符文能量消耗降低 10 点。'),
(504046, '获得灵魂灌注后，你的灵魂撕裂与迷失者遗物匣造成的伤害提高 20%，持续 6 秒，可叠加 2 次。'),
(504050, '命令你的腐朽巨像在脚下10码范围内污染地面，使范围内的敌人受到的治疗效果降低60%，持续20 秒。\n\n处于亡灵：安抚状态时无法使用。'),
(504060, '在10 秒内，你的建造法术不消耗法力值，且施法时间被移除。'),
(504070, '黎明灼击的法术强度加成提高 20%，太阳耀斑的法术强度加成提高 10%。'),
(504071, '使吸血盛宴的吸血效果提高50%。\n\n使用饥渴消耗至少9层吸血鬼之牙时，使罪孽的持续时间延长5秒。'),
(504088, '当液化结束时，你从附近敌人身上吸取（102.4 + 100% 法术强度）点生命值。'),
(504098, '你的周期性伤害和治疗有15%的几率使下一次鲜血愈合的消耗降低100%，持续8 秒。'),
(504100, '你的治疗效果现在有10%的几率额外为目标恢复（4% 治疗强度 + 320 × 等级系数）点生命值，持续6 秒。'),
(504103, '安瑟拉恩的痛楚现在消耗的怒气减少 25 点。\n\n塔达拉姆的折磨现在每跳使你的下一次瓦拉纳的复仇或凯雷塞斯的灾厄的伤害提高 3%，持续 10 秒，最多可叠加 5 层。\n\n瓦拉纳的复仇和凯雷塞斯的灾厄现在使恶咒的冷却时间缩短 5 秒。'),
(504107, '40级被动触发狂热10次后，会将你的辩护转化为神圣狂怒。'),
(504116, '施放血牙撕咬现在有20%的几率重置劫掠斩的冷却时间。'),
(504139, '在战斗中，每2秒，使你的下一次投掷长矛的范围和能量消耗提高1，造成的伤害提高3%，最多叠加15层。'),
(504140, '施放百夫长打击现在会使你能够使用并刷新一次反击的充能。'),
(504144, '在受到你的迅捷旗帜或征服旗帜影响时，你的勇气战旗造成的初始伤害提高150%。'),
(504148, '你的攻击强度每拥有50点护甲便提高1点。'),
(504149, '拥抱你英勇无畏的天性，在15 秒内使你的力量提高30%，暴击几率和近战急速提高15%。'),
(504159, '使你与小队和团队成员的所有法术和攻击命中几率提高1%。\n\n不与类似效果叠加。'),
(504184, '提高你的命中几率5%和精准等级4。'),
(504193, '你现在每5秒被动产生4点怒气。'),
(504196, '野性之爪的暴击现在会释放元素倾泻。'),
(504197, '提高你的攻击强度5%和命中几率2%。'),
(504198, '造成直接伤害现在会使熊皮、原始汇聚和巨石冲刺的冷却时间减少1秒。'),
(504214, '所有有效治疗现在有 25% 的几率使小队和团队成员的急速提高 5%，持续 20 秒。\n\n不与类似效果叠加。'),
(504217, '瞄准并投掷标枪攻击一名敌人，造成160%远程武器伤害外加241点伤害。\n\n伤害加成受投掷武器和长矛影响。可在移动时使用。'),
(504219, '塞拉赞恩之怒现在额外产生5点怒气值和5%的法力值。'),
(504220, '提高灵魂冲锋的暴击几率25%。'),
(504222, '将自然的怒火灌注自身，化身为战争古树，持续20 秒。\n\n激活时，你的生命之锤效果提高30%，附近队友的暴击几率提高20%。\n\n变身期间，你的移动速度降低30%。'),
(504223, '提高你造成的伤害和治疗效果4%。'),
(504226, '你的直接暴击现在使你和你的宠物的护甲穿透提高5%，持续10 秒，可叠加3层。'),
(504229, '召唤一个原初图腾，使40码范围内的队伍和团队成员的主属性提高20%，持续15 秒。'),
(504241, '使你的法术伤害提高攻击强度的20%，并使劫掠斩造成的伤害提高10%。'),
(504248, '圣光典范、圣光眷者和审判日的法力消耗降低 50%。'),
(504252, '40级被动技能每层饥渴现在使你的暴击几率提高1%。'),
(504254, '提高你的护甲穿透和消耗生命值的法术伤害15%。'),
(504260, '需要凡人之躯轰击一名敌人，造成（123 + 25% 攻击强度 + 85% 暗影法术强度）点暗影伤害。\n\n对流血目标造成25%的额外伤害。'),
(504263, '在一位盟友周围制造一道魔法帷幕，吸收50%的受到的伤害，最多吸收（511 + 75% 攻击强度 + 150% 精神）点，持续15 秒。'),
(504269, '你的幽魂之爪变为怨灵之爪，并获得 2 层充能。'),
(504272, '在12 秒内，使你下一次血箭的消耗降低10%，并且每击中一个目标，就会额外击中1个附近的敌人，最多叠加5层。'),
(504275, '诅咒一个敌人，使其流血，在30 秒内受到168点暗影伤害［拥有暗黑之心: 并立即恢复你最大怒气的30%］。\n\n对受到吸血鬼之吻影响的敌人造成的所有周期性伤害，会以25%的数值复制到该敌人身上。'),
(504282, '需要凡人之躯在你周围10码内最多10个敌人脚下制造一滩血池，使其在15 秒内流血，造成（165 + 140% 法术强度）点暗影伤害。\n\n强化：半径提高5码，怒气消耗降低100%。'),
(504284, '在10 秒内每1秒产生10点怒气值和1层饥渴效果。吸血鬼之牙会移除该效果。'),
(504285, '使所有主要属性提高4%。'),
(504290, '施放嚎叫法术现在会使你的召唤物进入激怒状态，造成的伤害提高10%，持续8 秒。'),
(504292, '你的法术和技能造成的直接有害暴击现在会使目标流血，在6 秒内造成（6% 攻击强度 + 306 × 等级系数 + 30% 法术强度）点伤害。'),
(504296, '以血魔法保护施法者。你的生命值恢复现在可在战斗中继续生效，且提高50%。来自物品的护甲加成提高20%。持续30 分钟。\n\n 同一时间只能激活1个护盾。'),
(504309, '召唤幽魂镰刀时，你会在 10 秒内治疗相当于所造成伤害 5% 的生命值。'),
(504316, '命令你的憎恶将一名敌人钩至其所在位置，使其移动速度逐渐降低直至完全停止，持续2 秒。\n\n在亡灵：安抚状态下无法使用。'),
(504322, '50级被动当寡妇之吻激活时，你的毒牙能量消耗降低20%。\n使用潜行时，降低敌人发现你的几率。'),
(504326, '提高你的毒素的持续时间50%。'),
(504329, '你的生存药剂现在每次生效时还会为你恢复10%的最大生命值。'),
(504335, '将你的目标包裹在茧中，使其昏迷5 秒。'),
(504339, '40级被动技能施放草本万用膏或毒蛇之牙现在有 30% 的几率刷新一层万能溶剂的充能。'),
(504341, '下一个法术的消耗降低100%。'),
(504342, '2层充能，12秒充能时间以沙德拉的恩赐祝福一名盟友，为其恢复（85 + 31.4397% 治疗强度）点生命值，并使其身上的沙德拉的祷言持续时间延长9秒。'),
(504344, '召唤一个真菌人攻击敌人，造成（226 × 等级系数 + 65% 法术强度）点自然伤害，并立即对目标施加衰弱毒素效果。持续20 秒。\n\n可在任意形态下使用。'),
(504347, '拥抱沙德拉的祝福，使你免疫所有沉默和打断效果，并允许你在移动时施法，持续15 秒。'),
(504348, '100码范围内的盟友受到的治疗效果提高6%。不与类似效果叠加。\n\n此外，你的抗毒血清现在额外驱散1个效果。'),
(504352, '在15 秒内，用沙德拉的恩宠笼罩一位盟友，使其受到的所有伤害降低20%，并且受到直接伤害时恢复3%的最大生命值。'),
(504355, '孢子造成的伤害现在会使腐烂的冷却时间减少1秒。'),
(504356, '对友方施放沙德拉的救护现在也会对你自己施放。\n\n此外，每层菌丝治疗还会使目标身上的翡翠帷幕的吸收量提高 10%。'),
(504357, '提高触发复苏寒意的几率5%。'),
(504361, '有害爆击现在会使枯萎的持续时间增加2秒。'),
(504375, '毒牙和蛛魔钉刺的爆击现在会额外立即造成其直接伤害的25%作为自然伤害。\n\n以此方式造成的伤害有40%几率延长腐牙的持续时间1秒。'),
(504380, '产生30点热量用熔岩护盾保护一名盟友，吸收（84 + 55% 火焰法术强度）点伤害。在护盾持续期间，攻击者每次对其造成伤害时，会受到（4 + 10% 精神）点火焰伤害。持续30 秒。'),
(504383, '使冲撞的冷却时间减少4秒，并使其暴击几率降低25%。'),
(504385, '施放［拥有鼓舞领袖: 征服者之歌；否则： 粉碎］或冲撞现在有20%的几率重置冲撞的冷却时间。'),
(504393, '提高所有甲虫形态技能的爆击几率10%。'),
(504394, '消耗余烬现在会减少熔岩碎片和火柱的冷却时间10%。'),
(504397, '每层热量现在会使龙跃造成的伤害提高6%。'),
(504400, '提高你造成的伤害所产生的怒气15%。'),
(504401, '在目标位置放置一道风之门，持续1 分钟。\n\n你可以对一名盟友施放风之门：撤离，将其拉至你的风之门处。'),
(504402, '你的倒钩之刺和甲壳冲锋现在会施加邪恶毒素。'),
(504404, '在10 秒内恢复16点生命值。'),
(504406, '受到直接伤害时有20%的几率反击，造成所受伤害5%的伤害。'),
(504407, '提高毒刺毒素的伤害30%。'),
(504424, '为你的大锅注入香料：地花。\n\n所有大锅效果和材料的效果提高30%。'),
(504426, '幻象的冷却时间减少60秒。'),
(504431, '你的最大生命之力提高1点。'),
(504439, '50级被动技能所有通灵术、复活术和命令法术的法力值消耗降低20%。'),
(504446, '每次攻击时，大地母亲的坠饰都会恢复失去的力量，为你治疗相当于造成伤害的10%。\n每0.5秒只能触发一次。'),
(504459, '提高沃金的守夜和迅捷神像的持续时间和效果10%。'),
(504462, '暗影傀儡的生效速度提高10%，并且你身上每激活一个精魂，其持续时间延长10%。'),
(504465, '拥抱沃金的道路，使你受到的伤害降低25%，并每1秒为你恢复最大生命值2%的治疗量，持续10 秒。'),
(504470, '使木桩的伤害提高，并使其法力值消耗降低30%。\n\n此外，使用木桩造成暴击时，现在会返还其一半消耗。'),
(504489, '命令你的骷髅法师在目标位置冻结敌人，持续40 秒（对玩家为8秒）。受到伤害可能会提前结束该效果。\n\n在亡灵：安抚状态下无法使用。'),
(504503, '提高你的格挡值10%和格挡几率2%。'),
(504519, '制造最新的炮塔科技——X-13型战斗炮塔，为30 秒提供光环效果，使你的召唤物伤害提高10%。\n\n盟友可进入炮塔，在持续期间获得独特技能并共享炮塔的生命值池。'),
(504521, '每1.5秒造成32点火焰伤害，并使目标从你的机甲：燃烧受到的伤害提高10%，持续4.5 秒，可叠加5层。'),
(504523, '在你的机甲内时，你的废料射击和简易炸药造成的伤害现在会对目标施加活体烈焰。'),
(504525, '提高你的暴击几率2%，并且远程暴击有50%的几率产生3个废料。'),
(504527, '2 层充能，8 秒充能时间产生 10 份废料将炸药装入你的枪中并向敌人发射，造成 100% 远程武器伤害外加 12 点火焰伤害。\n\n可在移动时使用。'),
(504530, '使冲撞和横扫千军的伤害提高25%。'),
(504531, '你的近战伤害现在会使骑士精神的冷却时间缩短 2 秒。'),
(504543, '在目标附近放置一个蘑菇，2秒后爆炸，对所有附近敌人造成（303 × 等级系数 + 35% 法术强度）点瘟疫伤害。'),
(504551, '你的急速提高20%，持续5 秒。'),
(504560, '使你的暴击伤害提高 10%。'),
(504561, '触发狂热现在还会为你恢复（50 × 等级系数 + 6% 法术强度）点生命值。'),
(504581, '在正前方锥形区域内消灭最多10个敌人，造成150%武器伤害加上353点暗影烈焰伤害，并产生4点恶魔之火。\n\n若你的生命值高于75%或低于35%，则造成20%额外伤害。该效果受地狱火打击的修正值影响。'),
(504582, '向你的敌人发射一道灵魂箭雨，对其造成（321 + 28.5% 远程攻击强度）点暗影伤害，并对 8 码范围内最多 3 个敌人造成伤害，同时收集一个精魂。\n\n使精魂飞刃的冷却时间缩短 3 秒。\n\n随精魂回收的修正效果而提升。'),
(504586, '你的下一个重击在15 秒内不触发冷却时间，并允许你使用反击，如同你近期刚格挡了一次攻击。'),
(504594, '在 1.5 秒内向敌人投掷齿轮 4 次，每次造成（79 + 16% 远程攻击强度）点自然伤害，并产生 1 个废料。\n\n使你的召唤物造成的伤害提高 10%，持续 8 秒。\n\n可在移动时使用。受简易炸药的修正效果影响。'),
(504602, '30级被动技能施放时光之波现在会赋予你扭曲现实，持续10 秒。'),
(504603, '允许你在移动时施放瓦解和熔解现实，持续10 秒。'),
(504627, '与一名盟友建立联结，持续30 分钟，使该盟友受到直接伤害时，为你产生 1 点怒气并恢复 3% 基础生命值，并将其产生的10%威胁值转移给你。\n\n此外，在非战斗状态下，你和联结的盟友移动速度提高30%。'),
(504628, '造成伤害使你获得宇宙和谐，使你在6 秒内的下一个技能的治疗效果提高5%。\n\n有效治疗使你获得宇宙之怒，使你在6 秒内的下一个技能的伤害提高5%。\n\n这些效果每秒最多触发一次。'),
(504642, '近战暴击现在会刷新一层帝国之刃，并恢复5%的基础法力值。'),
(504645, '亵渎造成的伤害现在有 15% 的几率重置夜刃的冷却时间。'),
(504677, '使钻地弩箭的冷却时间减少5秒。'),
(504694, '使消耗的散落星辰的暴击几率和暴击伤害提高10%。'),
(504704, '对中毒目标，寡妇之吻、寡妇制造者和毒牙造成的爆击伤害提高50%。'),
(504705, '施加1层孵化印记撕咬一名敌人，造成（91 + 30% 攻击强度 + 50% 暗影法术强度）点暗影伤害，并使你的急速提高20%，持续4 秒。伤害受毒蛇之牙的修正效果影响。'),
(504706, '2层充能，25秒充能时间向身后所有敌人喷射蛛网，使其定身4 秒秒，并造成（159 + 65% 自然法术强度）点自然伤害。'),
(504707, '以迅疾之焰灌注你的皮肤，使你的法术急速等级提高相当于精神值10%的数值，并使你的移动速度和坐骑移动速度提高15%。持续30 分钟。\n\n同一时间只能激活1种皮肤效果。'),
(504710, '将你的鲜血诅咒转化为诅咒形态。'),
(504720, '用火山灰浸染你的皮肤，使你在战斗中保持40%的法力回复速度，并且周期性伤害可恢复1%的基础法力值。持续30 分钟。\n\n同时只能激活1种皮肤效果。'),
(504728, '将你的鲜血诅咒转化为罪孽。'),
(504730, '使百夫长打击和反击的暴击伤害提高15%。'),
(504732, '造成或受到的物理伤害现在有10%的几率对一名敌人释放荆棘。'),
(504733, '50级被动技能有效的治疗暴击现在产生10点热量。'),
(504734, '虔诚专精技能的射程提高 20%，产生的威胁值降低 20%。'),
(504736, '你的毒蛇之牙现在会使你接下来的2次万能溶剂的治疗效果提高25%。'),
(504750, '20级被动技能诺兹多姆的回响和奈萨里奥之焰造成的伤害现在有33%的几率额外触发一次，造成45%的伤害。\n以此方式造成的伤害最多可额外触发此效果3次。'),
(504754, '龙跃造成的伤害现在产生10点热量。'),
(504758, '你的血箭现在额外治疗相当于伤害值20%的生命值。'),
(504759, '在你附近放置一个宁静神像，持续1 分钟。\n\n30码范围内的盟友受到的伤害性攻击造成的法术退条效果降低30%。'),
(504764, '造成（773 + 100% 神圣法术强度）点神圣伤害，并使你获得灼烧印记。'),
(504774, '使幻象的持续时间翻倍。'),
(504782, '触发战争之声现在会使你的移动速度提高40%，并使20码范围内的盟友移动速度提高20%，持续2 秒。'),
(504784, '在敌人周围制造荆棘，将其定身并在6 秒内造成264点自然伤害。\n直接受到的伤害可能会终止此效果。'),
(504786, '40级被动你的暴击现在会产生一层月相。每秒钟只能触发一次。\n\n此外，获得法力值不再产生威胁值。'),
(504798, '30级被动技能教你维齐尔形态。'),
(504799, '使你的治疗法术产生的威胁值降低10%，并使你的周期性治疗效果提高3%。'),
(504807, '施放破誓者现在会对你的目标触发狂热，并使圣契、高戈奈斯之力、神圣之力和意志圣约的冷却时间缩短1秒。'),
(504808, '触发狂热现在有8%的几率使你的下一次攻击获得一次额外自动攻击。'),
(504837, '减少毒刺毒素的怒气消耗10。'),
(504840, '在你附近放置一个净化神像，持续1 分钟。\n\n30码范围内的盟友每3秒移除1个中毒和疾病效果。'),
(504846, '打断目标当前施法，并为其施加5 秒标记。\n\n若其在标记期间再次施法，将被沉默3 秒。'),
(504848, '赐予一名盟友及附近最多 5 名盟友怜悯，移除 2 个疾病效果，每 3 秒重复一次，持续 12 秒。'),
(504849, '以生命魔法保护施法者，使你受到暗影和自然治疗的效果提高15%，并每5秒恢复你最大生命值的2%。持续30 分钟。\n\n 同一时间只能激活1个护盾。'),
(504855, '当你杀死一个提供经验值或荣誉的敌人时，其脚下会生成一个蘑菇。此效果每1秒只能触发一次。'),
(504856, '使你的抵抗恐惧、魅惑和睡眠效果的几率提高40%，并每3秒驱散30码范围内队友身上的1个恐惧、魅惑和睡眠效果。\n同时只能激活1个恩赐。'),
(504859, '召唤一只地穴恶魔协助你战斗，占用2点生命之力。\n\n命令：向你的目标发射尖刺，造成（341 × 等级系数）点冰霜伤害，并弹射至附近一名敌人。'),
(504861, '召唤一只女妖协助你战斗，占用2点生命之力。\n\n它会持续引导你的目标，造成伤害并逐渐吸取其法力值。\n\n命令：吸取目标10%的法力值（最多不超过其自身法力上限的20%），并造成等同于吸取法力值的冰霜伤害。'),
(504866, '当你召唤一个复生仆从时，它会携带一面护盾升起，吸收相当于其最大生命值40%的魔法伤害。'),
(504867, '使目标敌人身上长出脓疱，脓疱膨胀后爆裂，使其迷惑6 秒。效果结束时，移除目标身上你的所有剧剧毒术士毒药效果，并立即造成这些效果在剩余持续时间内原本会造成的伤害。'),
(504868, '命令你的亡灵仆从对目标发动一次独特的攻击。\n请参考各个亡灵复生法术的命令效果。'),
(504874, '你的宠物造成的伤害现在使敌人受到的周期性治疗效果降低10%，持续15 秒，可叠加3层。'),
(504897, '用一块凝结的屏障保护施法者，使受到的伤害性攻击造成的施法推迟降低 100%，并使打断和沉默效果的持续时间缩短 30%。持续 30 分钟。\n\n 同时只能激活 1 个盾牌。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (504903, 504910, 504918, 505188, 505199, 505200, 505201, 505202, 505203, 505220, 505228, 505230, 505327, 505336, 505339, 505344, 506632, 506634, 506635, 506818, 506819, 507082, 507084, 510176, 510236, 511109, 520005, 520008, 520009, 520015, 520017, 520019, 520022, 520024, 520032, 520034, 520042, 520043, 520045, 520046, 520047, 520054, 520056, 520062, 520083, 520087, 520090, 520092, 520099, 520106, 520107, 520108, 520131, 520138, 520145, 520149, 520151, 520153, 520156, 520164, 520166, 520171, 520173, 520175, 520188, 520218, 520227, 520229, 520236, 520237, 520240, 520244, 520246, 520251, 520252, 520254, 520257, 520269, 520277, 520278, 520290, 520292, 520294, 520295, 520296, 520307, 520314, 520326, 520345, 520353, 520359, 520369, 520371, 520372, 520381, 520386, 520388, 520402, 520405, 520412, 520442, 520445, 520453, 520457, 520464, 520466, 520469, 520481, 520482, 520485, 520488, 520492, 520493, 520523, 520524, 520534, 520539, 520548, 520568, 520574, 520578, 520581, 520585, 520586, 520590, 520591, 520592, 520593, 520608, 520615, 520621, 520622, 520628, 520639, 520641, 520644, 520645, 520646, 520647, 520650, 520661, 520670, 520681, 520682, 520686, 520753, 520755, 520770, 520780, 520783, 520800, 520804, 520805, 520809, 520810, 520811, 520812, 520817, 520822, 520823, 520831, 520833, 520834, 520835, 520840, 520841, 520851, 520853, 520854, 520855, 520865, 520869, 520875, 520884, 520885, 520917, 520922, 520923, 520925, 520937, 521211, 521219, 521220, 523478, 523485, 523489, 523495, 523510, 523513, 523523, 523524, 523526, 523527, 523712, 523721, 523727, 524600, 524610, 524617, 524620);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(504903, '暗影狂怒现在同时使你的暗影猎犬获得10%急速提高。'),
(504910, '坚定你的决心，立即恢复50点能量，并使你对下一次攻击造成格挡暴击。持续5 秒。'),
(504918, '使紧急治疗的治疗量提高20%，法力消耗降低20%。'),
(505188, '将你的鲜血诅咒转化为鲜血精华。'),
(505199, '每有一个10码内的附近敌人，使你受到的伤害降低1%，最多降低10%。'),
(505200, '站在你的勇气战旗中时，盟友有20%的几率抵抗昏迷和抓取效果。'),
(505201, '使你的暴击伤害提高20%。'),
(505202, '战争之声造成的伤害现在有25%的几率降低敌人的抗性18.8542点，并使其受到的法术伤害提高2%，持续8 秒。'),
(505203, '你对这个目标的下5次周期性治疗将额外治疗相当于数值10%的生命值。'),
(505220, '为你的宠物恢复50点集中值。'),
(505228, '施放战歌现在会使盟友获得骑士之歌。'),
(505230, '使你的信标的持续时间延长6秒，医疗包的持续时间延长3秒。'),
(505327, '使医疗包的冷却时间提高30秒，但可影响盟友周围最多4个额外目标。'),
(505336, '使你的召唤物的最大生命值提高10%。'),
(505339, '在你附近放置一个暗影雕像，持续1 分钟。\n\n30码范围内的敌人施法速度降低20%，移动速度降低40%。\n\n同时只能激活1个雕像。'),
(505344, '你立誓在战斗中激励盟友，将你的粉碎和横扫千军转化为战歌。'),
(506632, '使你受到的流血伤害降低20%，并使你身上的流血效果持续时间缩短20%。'),
(506634, '在你附近放置一个妖术雕像，持续1 分钟。\n\n下一个对你施放法术的敌人将被变成一只青蛙，持续40 秒。\n\n变形期间，目标无法移动、攻击或施放法术。受到伤害可能会中断此效果。\n\n同时只能激活1个雕像。'),
(506635, '在你附近放置一个雕刻雕像，持续1 分钟。\n20码范围内的敌人受到的控制效果持续时间提高25%。\n同时只能激活1个雕像。'),
(506818, '使过载的消耗降低15%，冷却时间缩短10%。'),
(506819, '使医疗包的持续时间延长100%，治疗效果提高75%。'),
(507082, '在你附近放置一个黑暗神像，持续1 分钟。\n30码范围内的盟友获得60点暗影抗性提升。'),
(507084, '在你附近放置一个丛林神像，持续1 分钟。\n30码范围内的盟友获得60点自然抗性提升。'),
(510176, '对目标队友施放魔法增幅，使其受到的法术伤害提高最多75点，受到的治疗效果提高最多80点。持续10 分钟。'),
(510236, '停止敌人的时间线，打断其施法，持续4 秒。\n\n成功打断敌人还会使其沉默4 秒秒。'),
(511109, '向前方锥形区域喷吐超高温烈焰，融化受影响敌人的武器，使其近战和远程武器失效，持续6 秒。'),
(520005, '产生1点恶魔之火猛击一个敌人及其附近所有敌人，造成250%武器伤害。\n\n释放你激活的瘟疫同化以触发强力效果。\n\n受斩断的修正效果加成。'),
(520008, '消耗恶魔之火的技能在至少拥有4层时，会返还1点恶魔之火。'),
(520009, '使正义突刺和白银之刃的伤害提高20%，能量消耗降低20%。'),
(520015, '魔法卷轴现在还会使释放符印的暴击伤害和暴击几率提高 5%，持续 15 秒，可叠加 3 层。'),
(520017, '白银之刃现在有10%的几率额外攻击一次。'),
(520019, '消耗1层余烬立即引发一次炽焰爆发，消耗目标身上的焦灼效果，造成两倍总周期性伤害，并在10 秒内额外造成（3500% 角色等级）至（3700% 角色等级）点伤害，穿透吸收效果和抗性。'),
(520022, '废料射击和机甲技能现在会使你的哨兵炮台获得一层首席技师效果，最多可叠加10层。\n\n当叠加至10层时，你的哨兵炮台会释放一道光束，对25码直线范围内的敌人造成（722 + 40% 攻击强度 + 75% 火焰法术强度）点火焰伤害，该伤害无视免疫效果。'),
(520024, '选定一名敌人并跃向空中，免疫所有物理攻击与法术，持续 2 秒。效果结束时冲向地面，对 8 码内所有敌人造成（130.6 + 100% 攻击强度 + 22.5% 法术强度）点神圣伤害。'),
(520032, '你的誓言：定罪现在提供3%的额外暴击几率。'),
(520034, '对生命值高于75%或受惩戒影响的敌人，使宁静之环的伤害提高25%。'),
(520042, '你的加速恢复现在也会作用于附近的一个目标。'),
(520043, '揭露一个敌人的过往，持续8 秒，使其受到你的魔法伤害提高20%。'),
(520045, '施放强化时间线现在会为你提供汇聚无限。'),
(520046, '以幽魂之手触碰目标，偷取其口袋中的战利品。'),
(520047, '以微弱的低语扰乱目标区域，吸引附近敌人的注意力，持续 10 秒。'),
(520054, '离开符文帷幕后，你的暴击几率提高 10%，持续 5 秒。'),
(520056, '挽歌的暴击现在生成 10 点符文能量。群鸦杀戮的暴击现在额外生成 1 层收割之魂。'),
(520062, '消耗你的怒气，射出一支强力箭矢，造成 130% 武器伤害外加 6 点暗影伤害，并将每点怒气转化为额外伤害。\n\n仅对生命值低于35%的敌人可用。'),
(520083, '在你周围散发一道光环，持续15 秒，使100码范围内的盟友在造成直接伤害时，额外造成（70% 自然法术强度）点自然伤害。\n\n施加力竭效果，使你在1 分钟内无法从类似效果中获益。'),
(520087, '阅读你的古代典籍，使你的下一个召唤：气元素变为瞬发且不消耗法力值，持续15 秒。'),
(520090, '释放：造成（437 × 等级系数）点冰霜伤害，并使移动速度降低30%，持续4 秒。'),
(520092, '释放：对主要目标附近的敌人造成（276 × 等级系数 + 18% 奥术法术强度）点奥术伤害。'),
(520099, '立即在自己身上生成冰霜符印、火焰符印和奥术符印并使其超载，下次对敌人释放时，所有激活的符印将获得额外效果。持续 15 秒。\n\n可在潜行状态下使用。'),
(520106, '造成的伤害提高100%。'),
(520107, '火焰符印现在影响额外2个敌人，并在12 秒内额外造成（760 × 等级系数 + 320% 火焰法术强度）点火焰伤害。'),
(520108, '将敌人冻结在原地，持续3 秒。效果结束时，其移动速度降低50%，持续5 秒。不会因受到伤害而打破。'),
(520131, '40级被动使你的火焰法术强度提高，相当于敏捷的50%。'),
(520138, '使用元素迸发和原初轰击造成的伤害现在有20%的几率重置极寒冲击的冷却时间，并使其下一次使用变为瞬发，持续10 秒。'),
(520145, '你的直接伤害有10%几率恢复3%的最大法力值。'),
(520149, '驱散一名盟友和附近另一名盟友身上的 1 个有害魔法效果和 1 个疾病效果。'),
(520151, '吞噬一名友方目标身上的1个有害魔法效果，将其驱散并为你恢复（174 + 17.5% 法术强度）点生命值。'),
(520153, '为一名盟友注入强效魔法解毒剂，驱散其身上的2个诅咒效果。'),
(520156, '使符印过载的冷却时间减少15秒。'),
(520164, '使你的急速提高4%，并降低你因受到伤害攻击而造成的施法退条35%。'),
(520166, '你的时光不谐现在产生1个回响碎片。'),
(520171, '使用碎裂回响造成暴击后，使敌人从你处受到的伤害提高10%，持续8 秒。'),
(520173, '施放无尽之握现在会减少回溯的冷却时间 10 秒。'),
(520175, '对一名敌人发动魔杖攻击，并额外造成6点奥术伤害。\n\n此法术对亡灵和恶魔必定造成暴击。［拥有回响碎片: \n\n产生1个回响碎片。］'),
(520188, '将目标区域内 8 码半径内的所有敌人和盟友置于静止状态，放逐他们 6 秒，使其免疫所有效果但无法移动。\n\n对目标施放瓦解将移除该效果。'),
(520218, '跃入空中，造成11点火焰伤害，击退6码范围内的敌人并使其眩晕6秒。\n\n落地时，造成11点火焰伤害，击退6码范围内的敌人并使其眩晕6秒。'),
(520227, '产生2点优势向目标射出一支强力箭矢，造成250%远程武器伤害外加14点伤害。\n\n仅能对生命值低于20%的敌人使用。'),
(520229, '变得坚如磐石，使你受到的物理伤害降低30%，持续8 秒。\n\n可在昏迷时使用。'),
(520236, '消耗2层邪能之怒用邪能魔法轰击一名敌人及其附近所有敌人，造成（69 + 40% 法术强度）点暗影烈焰伤害。\n\n心魔：使用此法术击中至少5名敌人时，会额外造成（10 + 10% 法术强度）点暗影烈焰伤害，持续6 秒，可叠加3层。'),
(520237, '在潜行状态下，使用跃迁匕首会使你的魔法伤害提高10%，持续8 秒。'),
(520240, '施放邪能之怒消耗技能现在会使燃烧憎恨、憎恨壁垒和恶魔意志的冷却时间降低0.5秒。'),
(520244, '舞刃造成伤害时，使怒意释放的冷却时间减少1秒。'),
(520246, '邪能火球造成暴击时，现在产生1点邪能之怒。'),
(520251, '提高你的直觉效果20%。'),
(520252, '当心魔激活时，你从布甲和皮甲物品中获得的护甲值提高120%。'),
(520254, '切割现在引导速度加快1秒。'),
(520257, '在拥有至少6层心魔时施放邪能之怒，现在会恢复50点能量。'),
(520269, '汲取敌人身上的潜在魔法，从他们身上偷取2个有益魔法效果。\n\n可在移动时使用。'),
(520277, '剑柄猛击造成的伤害现在有 20% 的几率触发暗影风暴。\n\n施放亵渎必定触发暗影风暴。'),
(520278, '从8码范围内的敌人身上吸取（10% 攻击强度 + 350 × 等级系数 + 30% 法术强度）点生命值。'),
(520290, '消耗恶魔之火的技能基础伤害提高25%。'),
(520292, '向你和身后6码锥形范围内的所有敌人喷吐火焰，造成（27.625% 攻击强度 + 552 × 等级系数 + 40% 火焰法术强度）点火焰伤害，并每击中一名敌人使克索诺斯锁链的冷却时间减少4秒。\n\n每消耗一层恶魔之火，冷却时间额外减少3秒。'),
(520294, '消耗所有你的恶魔之血，化身为一名主宰，使受到的所有伤害降低30%，持续10 秒。\n\n在持续期间，你每2.5秒恢复（6 + 10% 攻击强度）点生命值，每层消耗的恶魔之血都会提高该数值。'),
(520295, '激怒，每1秒生成15点怒气，并使你免疫瘫痪、放逐和变形效果，持续6 秒。\n\n可在被瘫痪、放逐或变形时使用。'),
(520296, '50级被动技能释放瘟疫首次使用时不再触发冷却时间。\n\n释放瘟疫每30秒只能以此方式重置一次。'),
(520307, '变形为剧毒喷射者，使你的移动速度提高40%，允许你悬浮，并降低你的坠落速度。\n\n坠落时，你可以控制方向并缓慢下降。只能在户外使用。'),
(520314, '释放一股强大的鲜血能量，对一名敌人造成（172 + 100% 精神 + 50% 暗影法术强度）点暗影伤害，并为目标20码范围内的12个盟友恢复（161 + 30% 治疗强度 + 100% 精神）点生命值。\n\n强化：使你的小队和团队成员攻击或法术强度提高95点，持续20 秒，并且额外使你提高19点，效果随等级提升。'),
(520326, '变身为深渊先驱，持续20 秒，使造成的伤害和治疗效果提高15%，并使吸收效果和持续治疗效果的基础持续时间提高100%。\n\n持续时间结束时，你的狂乱将降至0。'),
(520345, '向一名盟友引导一道虚空能量护盾，使你和该盟友吸收（803 + 25% 攻击强度 + 100% 治疗强度）点伤害，每 1 秒叠加 5 层，持续 5 秒。\n\n持续时间结束时，若护盾未被击破，你将传送至该盟友身边。\n\n引导期间你免疫昏迷和沉默效果。无法对自己使用。'),
(520353, '你的本能现在额外使你的暴击等级提高，相当于敏捷的20%。'),
(520359, '旋转并使用双持武器攻击 5 码内最多 5 名敌人，造成 50% 武器伤害及（6 + 20% 火焰法术强度）点伤害。主手造成物理伤害，副手造成火焰伤害。'),
(520369, '使你的躲闪和招架几率提高4%，并降低你在潜行时被敌人发现的几率。'),
(520371, '使小队与团队全体成员造成的全部伤害提高 3%。无法与其他同类效果叠加。'),
(520372, '使所有小队和团队成员暴击几率提高3%。不与类似效果叠加。\n\n此外，物理暴击现在会使目标受到的物理伤害提高4%，持续20 秒。'),
(520381, '生成热量现在使巨龙祈唤和玛里苟斯的精华的冷却时间缩短 3%。\n\n每秒只能触发一次。'),
(520386, '你的魔杖攻击现在使敌人的攻击强度降低19.15，持续5 秒。'),
(520388, '目睹末日幻象，直接造成的伤害或治疗会对附近目标施加末日幻象，持续3 秒。每3秒只能触发一次。\n\n效果结束时，目标会受到或恢复相当于造成末日效果时伤害或治疗量100%的伤害或治疗。持续1 分钟或5次伤害或治疗。\n\n被末日诅咒的敌人无法被治疗，此效果造成的伤害或治疗可以造成暴击。'),
(520402, '定身一条直线上的敌人，持续3.5 秒，随后在荣耀烈焰中向前冲刺，每0.5秒对身下的敌人造成（541 + 100% 火焰法术强度）点火焰伤害，持续10 秒。'),
(520405, '你的触须造成的伤害使邪异方尖碑的冷却时间减少2秒。\n\n此外，使邪异方尖碑的效果提高25%。'),
(520412, '在目标位置制造一场地震，每3秒造成（63 + 15% 攻击强度 + 30% 自然法术强度）点自然伤害，并使移动速度降低30%，持续9 秒。［拥有大地塑形: \n\n每层大地塑形效果使伤害提高5%。］'),
(520442, '提高正义剧变的暴击伤害20%。'),
(520445, '为目标盟友安装一个复苏装置，持续20 秒。\n\n当目标即将死亡时，改为恢复其最大生命值的50%。'),
(520453, '你和你的召唤物造成的伤害提高4%。'),
(520457, '为一名盟友施加拥有10层充能的永恒护盾，持续30 秒。每次该盟友受到伤害时，将为其恢复（190 + 25% 法术强度）点生命值并消耗1层充能。\n\n每1秒只能触发一次，且同一时间只能影响1个目标。'),
(520464, '当生命值低于或等于35%时，你的法术和技能会使你受到的治疗效果提高10%，持续6 秒。'),
(520466, '激活时，造成直接伤害有 20% 几率在 2 秒内投掷 3 把战锤，每把造成（100 + 27.8% 攻击强度 + 32.5% 法术强度）点物理伤害。持续 15 秒。\n\n伤害受山岳之锤的伤害修正效果影响。'),
(520469, '由三锤审判触发的每个战锤造成的伤害现在使你的爆击几率和伤害提高1%，持续10 秒，最多叠加10层。'),
(520481, '你的女猎手射击现在会额外击中3个敌人，并爆发星界能量造成10 秒点奥术伤害，伤害值为（3% 远程攻击强度 + 30 × 等级系数 + 8.1429% 奥术法术强度）。\n\n唤星术造成的伤害会使此技能的冷却时间减少2秒。'),
(520482, '你的月神之枪现在会攻击额外一个附近敌人。'),
(520485, '提高耀焰箭的暴击几率5%。'),
(520488, '为所有小队成员施加耐萨里奥的意志，使其免受恐惧影响。下一次对目标使用的恐惧效果将失败，并消耗该护盾。持续1 分钟。'),
(520492, '激怒附近所有盟友，使其急速提高30%，持续20 秒。\n\n受到此法术影响后，盟友在5 分钟内无法从类似效果中获益。'),
(520493, '激怒40码范围内的盟友，使其急速提高30%，持续20 秒。\n\n受到该法术影响后，盟友在5 分钟内无法从类似效果中获益。'),
(520523, '野蛮地头槌一名敌人，造成（48 + 37.5% 攻击强度）点物理伤害，使其短暂倒地并昏迷4 秒。'),
(520524, '提高你的符文烙印爆炸效果的暴击几率10%。'),
(520534, '正义风暴造成的伤害额外造成（85 + 8.5% 攻击强度 + 50% 神圣法术强度）点神圣伤害，并且造成伤害时，将 15 码内的敌人拉向你。\n\n被拉拽的敌人在 15 秒内无法再次被此效果拉动。'),
(520539, '近战攻击现在有8%的几率为你恢复相当于伤害10%的生命值，并使你的下一次先祖打击造成50%的额外伤害。'),
(520548, '你的魔法伤害提高5%，护甲穿透提高10%。'),
(520568, '敲击敌人头部，使其瘫痪 40 秒（对玩家为 8 秒）。\n\n只能同时影响 1 个目标。造成伤害会中断此效果。只能对未参与战斗的人形生物和野兽使用。'),
(520574, '使你的暴击几率提高2%，集中值恢复速度提高15%。'),
(520578, '生命能量涌动，驱散自身所有有害效果，并使移动速度提高40%，持续10 秒。\n\n可在潜行状态下使用。'),
(520581, '使侧翼攻击的暴击伤害提高10%。'),
(520585, '立即驱散30码范围内所有盟友身上的移动减速效果，并将其变为一丛灌木，使其潜行，持续20 秒。'),
(520586, '猎鹰打击和战斗尖啸现在使你的移动速度提高30%，持续3 秒。'),
(520590, '吸取20%最大法力值\n2层充能，18秒充能时间消耗散落星辰向你的目标及其附近的敌人开火，造成远程武器伤害加上（40 + 3% 最大法力值 + 18.5% 奥术法术强度）点奥术伤害，伤害随最大法力值提高。'),
(520591, '减少坠落伤害。'),
(520592, '移除你的邪能灾祸和法力燃烧的能量消耗，并且你的法力燃烧现在会击中主目标附近的4个额外敌人。'),
(520593, '使猎巫的伤害提高 30%，并使其可以额外命中一名附近的敌人。'),
(520608, '黎明战士现在也使你的下一次白银之刃的伤害和暴击几率提高50%。'),
(520615, '使你的集中值恢复速度提高15%。'),
(520621, '你的战隼和龙鹰在造成伤害时，现在会为你提供一层协作。'),
(520622, '使你的暴击几率和暴击伤害提高1%，持续15 秒，最多叠加10层。'),
(520628, '解放10名位于你周围15码内的盟友，持续8 秒，使其免疫定身和减速效果，并且他们的暴击会使移动速度提高30%，持续5 秒。'),
(520639, '激活黎明时，根据当前专精获得额外效果：虔诚获得虔诚圣焰，祝福获得神圣祝福，炽天使获得炽天使之光，女武神获得女武神之力。'),
(520641, '获得护盾，吸收（1000 + 75% 智力 + 50% 耐力 + 25% 力量）点伤害，持续 15 秒。'),
(520644, '伤害提高 10%，持续 6 秒。'),
(520645, '暴击几率提高 10%，持续 8 秒。'),
(520646, '近战急速提高 10%，移动速度不会低于正常速度的 115%，持续 6 秒。'),
(520647, '在目标位置创造半径 10 码的光环，持续 15 秒。区域内盟友受到的伤害有 30% 转移给你，且每 1.5 秒恢复（50 + 12.5% 攻击强度 + 42.5% 法术强度）点生命值。若转移的伤害使你的生命值低于 10%，效果终止。'),
(520650, '施放冲撞后，你的下3次近战攻击将额外造成（30 + 10% 攻击强度）点魔法伤害，持续10 秒。'),
(520661, '召唤一个强效小鬼来协助你战斗。\n\n强效小鬼拥有多种战斗能力，可提供出色的单体伤害与控制效果。'),
(520670, '你的下一次觅心弩箭在10 秒内造成25%额外伤害，且无冷却时间。\n\n当该增益效果被消耗时，你在3 秒内获得50%的移动速度提升。'),
(520681, '向沙德拉祈祷并致敬毒素教派，使你能够复活一名死亡的盟友，恢复70点生命值和135点法力值。战斗中无法施放。'),
(520682, '你的暗影面纱现在以50%的速度执行其效果。'),
(520686, '你的机甲：燃烧现在暴击几率提高10%，暴击伤害提高15%。'),
(520753, '立即获得5层优势，并在0 秒内使你能够看到附近潜行的敌人。\n\n可在潜行状态下使用。'),
(520755, '每当使用上古之拳或符文剑时，原初轰击的冷却时间减少2秒。'),
(520770, '使炽燃的周期性伤害能够造成暴击。\n\n此外，诺兹多姆的回响或时光化身造成的伤害现在有20%的几率确保你在8 秒内的下一次炽燃必定暴击，并使其暴击伤害提高100%，持续时间延长25%。'),
(520780, '使疾病效果的持续时间缩短40%。'),
(520783, '击杀一个提供经验值或荣誉值的敌人后，召唤一只战隼协助你战斗，持续12 秒。每4秒只能触发一次。'),
(520800, '使工艺师的魔杖的施法时间减少0.2秒。'),
(520804, '使毒性飞镖的集中值消耗降低15点。'),
(520805, '使混沌冲刺的能量消耗降低5点，并且施放［拥有邪能突进: 邪能突进；否则： 混沌冲刺］现在会为你恢复（51 + 33% 攻击强度 + 20% 耐力）点生命值。'),
(520809, '使你的机甲：燃烧的施法时间缩短0.25秒，并且其伤害提高20%。'),
(520810, '使暗影面纱的冷却时间减少60秒。'),
(520811, '使你和你召唤物的火焰伤害提高5%。'),
(520812, '每第2次施放白银之刃，现在使你获得誓言：惩戒。'),
(520817, '你的双刃斩和邪能撕裂现在有60%的几率额外产生1层邪能之怒。'),
(520822, '吸收（324 + 10% 攻击强度 + 30% 法术强度）点伤害，持续 20 秒。'),
(520823, '在10 秒内，你的下一个毁灭者之喉或火雨变为瞬发且不消耗资源［拥有黑翼重生: ，并造成50%额外伤害］。'),
(520831, '完整引导切割现在会返还1点邪能之怒。'),
(520833, '萨格隆惩击的暴击现在会返还1点邪能之怒。\n\n此外，萨格隆惩击对生命值高于75%的敌人造成的伤害提高25%。'),
(520834, '使战斗尖啸的持续时间延长，并减少爆裂种子的冷却时间5秒。'),
(520835, '激怒附近所有盟友，使其急速提高30%，持续20 秒。\n\n受到该法术影响后，盟友在5 分钟内无法从类似效果中获益。'),
(520840, '你的下一次纠正错误施法时间增加1秒，但治疗效果提高30%，且必定造成暴击。\n\n以此方式成功治疗一名盟友将使强化时间线的冷却时间减少8%。'),
(520841, '向一位盟友施予大地母亲的恩典，移除其身上的1个中毒和疾病效果。'),
(520851, '30级被动技能使你的攻击强度提高，相当于智力值的100%。'),
(520853, '将你的混沌冲刺转化为邪能突进。'),
(520854, '减少时间守卫的冷却时间30秒。'),
(520855, '立即将所有敌人变成婴儿，使其无法行动，持续40 秒（对玩家为8秒），造成伤害会中断此效果。\n被变成婴儿期间，敌人将快速恢复生命值。\n效果受还童术相关加成影响。'),
(520865, '将盾牌猛击地面，形成一面巨盾，持续10秒。\n\n当你停留在其附近时，指向你的敌对法术将被偏转。'),
(520869, '召唤艾露恩的净化之水降临一名友方，移除其身上的1个中毒和疾病效果。'),
(520875, '周期性伤害和周期性治疗现在有 15% 几率使你的急速提高 15%，持续 6 秒，并为盟友提供回能。'),
(520884, '爆炸造成的伤害现在会因目标身上的每个你的烈焰法师周期性效果而提高15%。'),
(520885, '双刃斩和撕裂的能量消耗降低10点。'),
(520917, '当大地之拳激活时，武器铭刻：大地造成暴击现在会使你的下一次自动攻击造成两次打击。'),
(520922, '时空停滞现在额外使目标的移动速度降低10%。'),
(520923, '使你的智慧法术的效果提高20%。'),
(520925, '林地箭矢现在会在你附近随机位置生成一朵稀有的红色梦境花，持续30 秒。\n\n暴击会对红色花瓣施加一层梦境之花效果。'),
(520937, '将你的爆炸转化为诺兹多姆的回响。'),
(521211, '你的巅峰现在拥有2层充能。'),
(521219, '你的武器铭刻：火焰现在在2秒后引爆，并且其暴击伤害提高10%。'),
(521220, '达到10层时，你的下一次游侠号角会使花朵绽放，为20码内的盟友提供增益效果，使其造成的伤害会为其恢复10%的伤害量，并且移动速度不会低于正常速度的100%，持续8 秒。'),
(523478, '提高友方目标的护甲值65点，并使所有主属性提高2点，持续30 分钟。\n\n与其他同类效果不叠加。'),
(523485, '提高友方目标的护甲值150点，并使所有主要属性提高6点，持续30 分钟。\n\n不与其它同类效果叠加。'),
(523489, '提高友方目标的护甲值105点，并使所有主属性提高4点，持续30 分钟。\n\n与其他同类效果不叠加。'),
(523495, '使所有小队和团队成员的护甲提高285点，所有主属性提高12点，持续30 分钟。'),
(523510, '向所有小队和团队成员宣告骑士法令，使其护甲提高285点，所有主属性提高12点，持续30 分钟。'),
(523513, '使附近小队和团队成员的护甲提高285点，所有主属性提高12点，持续30 分钟。'),
(523523, '受到的伤害降低10%，持续8 秒。'),
(523524, '野性之爪和双头飞龙之咬的伤害提高10%，持续8 秒。'),
(523526, '恢复15%的缺失生命值和法力值。'),
(523527, '移除1个移动限制效果。'),
(523712, '使用狂热造成伤害现在会对目标施加钢铁苦修，使其受到你的物理伤害提高1%，持续3 秒，可叠加10层。'),
(523721, '激怒，使你的物理伤害提高 20%，受到的物理伤害降低 20%，持续 30 秒。\n\n激活时，血牙撕咬现在发射 1 枚鲜血碎片，对目标造成（18 + 15% 攻击强度 + 35% 法术强度）点暗影伤害。'),
(523727, '你的血箭、鲜血碎片和动脉突袭的暴击几率提高10%。'),
(524600, '散发一道持续15 秒的光环，使盟友在造成直接伤害时额外造成（35% 远程攻击强度）点风暴打击伤害。\n\n施加力竭效果，使你在1 分钟内无法从类似效果中获益。'),
(524610, '每层效果可被［拥有鼓舞领袖: 征服者之歌；否则： 粉碎］消耗，造成额外（10% 攻击强度）点物理伤害，并使荣耀竞技场的冷却时间缩短10%。\n\n当叠加至5层时，效果将立即被消耗，使敌人昏迷5 秒。'),
(524617, '你的下一次惩戒会消耗所有层数的血色冠军，使直接伤害提高100%，并必定造成暴击。'),
(524620, '定罪造成的伤害现在有15%的几率以神圣狂热祝圣你周围的地面，对附近敌人造成（10% 攻击强度 + 91 × 等级系数 + 22.5% 神圣法术强度）点神圣伤害。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (524638, 524642, 524643, 524654, 524677, 524687, 524694, 524697, 524735, 524739, 524747, 524765, 524767, 524804, 524812, 524818, 524822, 524831, 524834, 524835, 524840, 524853, 524854, 524856, 524864, 524865, 524867, 524870, 524873, 524875, 524876, 524877, 524879, 524885, 524887, 524897, 524907, 524913, 524920, 524922, 524930, 524932, 524939, 524945, 524947, 524950, 524952, 524954, 524968, 524970, 524971, 524979, 525001, 525018, 525019, 525024, 525039, 525048, 525049, 525051, 525059, 525060, 525065, 525377, 525600, 525609, 526362, 527023, 527268, 531126, 531128, 531130, 531135, 531512, 531515, 532125, 532229, 532261, 532751, 533236, 534267, 534480, 534605, 535595, 535596, 535597, 535601, 535603, 535604, 535605, 536213, 536216, 537208, 537212, 537247, 538441, 541493, 547214, 552210, 553267, 555277, 555723, 555729, 555737, 555738, 557325, 557333, 560001, 560002, 560012, 560020, 560023, 560030, 560036, 560037, 560039, 560040, 560045, 560050, 560053, 560055, 560057, 560072, 560073, 560074, 560080, 560091, 560093, 560094, 560095, 560096, 560109, 560111, 560113, 560116, 560123, 560129, 560130, 560135, 560140, 560142, 560145, 560146, 560147, 560150, 560154, 560156, 560157, 560158, 560167, 560169, 560170, 560182, 560188, 560194, 560195, 560200, 560205, 560207, 560208, 560219, 560226, 560247, 560248, 560249, 560250, 560254, 560256, 560257, 560259, 560261, 560264, 560266, 560276, 560278, 560280, 560282, 560284, 560286, 560294, 560295, 560298, 560301, 560305, 560310, 560315, 560316, 560319, 560320, 560321, 560339, 560340, 560341, 560344, 560364, 560382, 560383, 560386, 560393, 560395);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(524638, '月之箭矢额外恢复你最大法力值的4%。\n\n此外，月之箭矢和女猎手射击的施法时间缩短10%。'),
(524642, '散落星辰造成的伤害现在有25%的几率刷新一层强击。'),
(524643, '骑乘女猎手刃豹，消耗30 秒，使你的移动速度提高50%，并免疫移动减速效果。\n\n骑乘军刀时，施法不会使你下马，且你可以在移动中施放攻击性法术。'),
(524654, '当你的穿颅者和突击在拥有5层| cff8fff7a射箭点时使用，现在会使肮脏刀刃的持续时间延长6秒。'),
(524677, '将野性之爪的公共冷却时间缩短0.25秒。'),
(524687, '使寒冰弹幕的伤害提高 20%。'),
(524694, '冲撞的暴击现在有50%的几率再次造成100%的伤害。'),
(524697, '使回能触发恢复的几率提高10%，并使符文纹饰：流水恢复的法力值提高25%。'),
(524735, '使用收割后，收割会变为横扫（Thresh），持续 10 秒。'),
(524739, '选择一个敌人并跃入空中。短暂延迟后，你以强大的神圣力量轰击他们，对5码内最多10个敌人造成（1503 + 100% 攻击强度 + 100% 神圣法术强度）点神圣伤害，并使其造成的伤害和治疗效果降低10%，持续5 秒。\n\n造成的伤害穿透所有免疫、抗性和伤害吸收效果。\n\n受惩戒的修正效果影响。'),
(524747, '将神圣之力的冷却时间缩短30秒。'),
(524765, '使用祝福进行治疗时，你的下一次祝福的治疗效果提高25%，持续30 秒。'),
(524767, '泰坦打击的暴击几率提高50%。'),
(524804, '将帝国之握的冷却时间缩短5秒。'),
(524812, '每次使用翻越时，你会在脚下放置铁蒺藜，持续6 秒。'),
(524818, '当你被击晕时，受到的伤害降低20%，持续3 秒。'),
(524822, '誓言：正义突刺的效果提高25%。'),
(524831, '快速射击或猎鹰打击的暴击现在使你的下一个消耗优势的技能施法时间和消耗降低34%，持续15 秒，可叠加3层。'),
(524834, '30级被动技能教授过载技能，并使信标获得过载效果，可通过使用修复射击治疗它们或直接使用过载来激活。\n\n激活的信标只能被过载一次。'),
(524835, '对所有激活的信标进行过载，释放其独特效果。\n\n请参阅各个信标的过载效果。'),
(524840, '建造最新的再生科技ZIGGI-6K，协助你治疗盟友，直至被解散。'),
(524853, '扭曲法术在敌人周围制造一场时间风暴，使其和最多2个附近敌人每4秒受到（270 + 24% 法术强度）点奥术伤害，持续4 秒。\n\n每消耗一个回响碎片，持续时间增加2秒。'),
(524854, '黑暗魔法之纱时刻环绕着你，使100码范围内的队伍和团队成员攻击强度提高5%。不与同类效果叠加。\n\n此外，使你受到的暗影伤害降低15%。'),
(524856, '你的加速和减速法术的效果提高25%。'),
(524864, '隐匿不再降低你的移动速度，并且每3秒恢复你最大生命值的3%。'),
(524865, '需要凡人之躯饱饮血魔法，进入大幅强化的诅咒形态，持续 20 秒，将你的血牙撕咬转化为猩红巨颚，但会持续消耗你的生命值。\n\n激活时，每 1 秒诅咒 8 码内的敌人，施加血肿，持续 6 秒。'),
(524867, '你的狩猎射击每弹射到一个后续目标，造成的伤害提高25%。'),
(524870, '射出一支燃烧箭矢，对一名敌人造成（791 + 27% 远程攻击强度）点火焰伤害，并对6码范围内的最多5名敌人造成伤害，同时使你接下来3个直接伤害的| cff8fff7a射箭点消耗技能对附近敌人造成相当于其50%的伤害。\n\n直接伤害根据| cff8fff7a射箭点的层数提高20%。'),
(524873, '直接物理伤害现在有8%的几率让你无视目标生命值使用致命射击，持续8 秒。'),
(524875, '耀焰箭现在使后续的闪光箭的伤害提高4%，持续10 秒，可叠加5层。\n\n奈萨里奥之焰和爆炸现在使后续的爆炸或奈萨里奥之焰的伤害提高4%，持续5 秒，可叠加5层。'),
(524876, '投掷一面被诅咒的盾牌，对最多 3 个敌人造成（72 + 9% 攻击强度 + 23% 法术强度）点暗影伤害，每次弹跳伤害降低 20%。\n\n每层狂乱使伤害提高 1%。'),
(524877, '当尤格萨隆之手激活时，每 1 秒你将对目标触发一次恐怖启示，并产生 5 点狂乱。'),
(524879, '饱足现在每跳额外恢复1%的法力值，并且在引导期间不再增加受到的伤害。'),
(524885, '20级被动使你的格挡等级提高，相当于力量值的20%。'),
(524887, '帝国之刃造成的伤害现在为生命值最低的盟友恢复造成伤害的35%加上（78.105 + 5% 攻击强度 + 20% 治疗强度）点生命值。'),
(524897, '以地狱之火爆炸，对附近敌人造成（51 + 10% 攻击强度 + 50% 火焰法术强度 + 25% 力量）点火焰伤害，召唤地狱火小鬼在 12 秒内协助你战斗，并产生 30 点怒气。\n\n每消耗一层恶魔之火，伤害提高，且 1 召唤的小鬼数量增加。'),
(524907, '在你上方凝聚一颗强大的猩红宝珠，在20码范围内为最多12个盟友恢复生命值，持续15 秒，恢复量为（5410.5 + 112.5% 治疗强度 + 450% 精神 + 350% 耐力）。\n\n每1.5秒生成2层汇聚活力和150点怒气。\n\n治疗效果受耐力和精神加成'),
(524913, '你的下5次（对玩家为1次）夺颅者或战争使者必定造成暴击，伤害提高100%（对玩家为25%）。持续30 秒。'),
(524920, '点燃你的武器，使你的每次近战暴击都会释放灼热火焰，对一条直线上的敌人造成（115 + 32.5% 攻击强度）点火焰伤害，并在激活期间提高30%的护甲穿透。持续6次攻击。\n\n每消耗一层恶魔之火，持续时间额外增加1次攻击。'),
(524922, '生成恶魔之血层数现在额外产生1点怒气。'),
(524930, '需要冻结目标向敌人释放一枚冰霜符文，使其昏迷4 秒。\n\n受影响的目标被视为冻结状态。'),
(524932, '自动攻击现在有20%的几率额外攻击一次，并使目标的命中几率降低3%，持续15 秒。'),
(524939, '灵魂突刺造成的伤害提高，数值相当于力量值的 30%。'),
(524945, '正在施放碎裂回响现在会使你的通量发射器持续时间延长 4 秒。\n\n无法延长至超过最大持续时间。'),
(524947, '使用 ［拥有邪能突进: 邪能突进；否则： 混沌冲刺］ 会使 5 秒内的下一次直接法术或技能伤害提高 25%。'),
(524950, '你的混沌灾祸和毁灭的伤害提高10%。'),
(524952, '向目标及其周围敌人投送手稿，在5 秒内造成（1620 + 190% 法术强度）点奥术伤害。\n\n当你施放此技能时，你将获得转录中效果，持续5 秒。'),
(524954, '湍流之怒的暴击现在会召唤一个带电水元素，协助你战斗，持续 20 秒。\n\n当带电水元素消散时，你的溺水冷却时间减少 2 秒。'),
(524968, '驱散一名友方目标的 1 个魔法和中毒效果；学会驱魔后改为 1 个，并可驱散 1 个疾病效果。'),
(524970, '对诅咒造成暴击现在返还40点怒气。'),
(524971, '安抚之触现在额外驱散一个中毒和疾病效果。'),
(524979, '哨兵炮塔造成的伤害现在有 30% 的几率额外造成（20% 攻击强度 + 47 × 等级系数）点自然伤害，并使炮塔的暴击几率提高 1%，可叠加 5 次，持续 8 秒。'),
(525001, '诅咒一名敌人，使其在 4 秒内施放的下一个法术被反射到自身。'),
(525018, '使大灾变的冷却时间缩短30秒。'),
(525019, '移除你的腐化心智的施法时间。'),
(525024, '你的神圣之力现在额外攻击主目标附近的2个敌人。'),
(525039, '搜索并翻找附近的残骸，每0.5秒获得10 废料和25点法力值，持续5 秒。\n无法在战斗中使用。'),
(525048, '致命射击的伤害提高75%。'),
(525049, '你的腐化心智现在还会对附近的敌人施加心灵腐烂。'),
(525051, '让一名友方沐浴在圣光中，驱散其身上的1个魔法、中毒和疾病效果。'),
(525059, '使受到伤害性攻击时的施法退条效果降低 50%，并使索瑞森的升腾提供的退条抵抗提高 15%。'),
(525060, '使虚空护盾抵抗盟友身上驱散效果的几率提高50%，并且现在还能反射50%吸收的伤害。'),
(525065, '制造一个扭曲的印记，将敌对力量从你身上偏转开，偏转所有法术和技能，持续5 秒，但在此期间你无法攻击或施法。\n\n法术被偏转的施法者将沉默3 秒。'),
(525377, '使用暗影闪爆造成伤害时，如果击中至少3个敌人，则施加恶意妖咒。'),
(525600, '当只有1个憎恶激活时，你的食尸鬼的暴击几率提高10%，急速提高10%。'),
(525609, '激活时，你的下一次奥术秘法或符印崩解将根据你当前的调和学派为你提供一个章节，使你的接下来10次直接法术施放对附近敌人造成额外的学派伤害，每额外击中一个目标，伤害降低20%。'),
(526362, '在10码范围内召唤一个漩涡，将附近所有敌人拉向中心，并使其移动速度降低60%，持续5 秒。\n\n3秒后，区域内的敌方玩家将被击飞到空中。'),
(527023, '你和你的小队成员跃上神圣战马，移动速度提高100%，每0.5秒践踏附近敌人，造成（66.35 + 20% 攻击强度 + 40% 神圣法术强度）点神圣伤害，持续15 秒。\n\n激活时，施法不会使你或你的盟友下马。仅可在户外使用。'),
(527268, '当你的狂乱值高于60时，你的虚空打击、克苏恩凝视和邪异震击将获得10%的额外暴击几率。'),
(531126, '每个激活的骷髅弓箭手使你的急速提高5%。'),
(531128, '你的亡灵仆从造成的伤害现在有5%几率恢复2点符文能量和2%的最大法力值。'),
(531130, '召唤一个白骨构造体协助你战斗，持续20 秒。\n\n它移动速度缓慢，但抵达敌人后会造成（1520 + 50% 攻击强度 + 200% 法术强度）点暗影伤害，无视所有无敌、抗性和免疫效果。'),
(531135, '你的冰霜伤害现在使你的盟友对该敌人的暴击几率提高1%，持续10 秒，可叠加3层。'),
(531512, '使一名盟友获得漂浮能力，使其以较低速度坠落，并可在水面上行走，持续2 分钟。在操控气流时，你可以控制方向并缓慢下降。\n\n受到伤害将取消该效果。'),
(531515, '你的否决之盾现在会额外击中1名敌人。'),
(532125, '在3 分钟内无法受到血肉塑造的影响。'),
(532229, '召唤一只恶魔之眼并将你的视野与之绑定，随后潜入虚空。\n激活时，你和恶魔之眼保持潜行状态。恶魔之眼移动迅速，但非常脆弱。'),
(532261, '每激活一个战隼或龙鹰，使你造成的物理和自然伤害提高1%。'),
(532751, '消耗50点静电从天空召唤一阵狂风暴雨与闪电，持续20 秒。每2秒，施法者周围30码范围内的敌人将被闪电击中，造成（540.95 + 55% 自然法术强度）点自然伤害。'),
(533236, '引爆附近所有尸体，每一具尸体对10码范围内的所有敌人造成（145 + 55% 法术强度）点瘟疫伤害。不影响机械和元素尸体。'),
(534267, '圣光照耀、光耀、破晓和神圣形态的治疗，还会治疗目标附近生命值最低的最多 5 名盟友，治疗量相当于原治疗量的 75%。'),
(534480, '当前选中的小队或团队成员将承受你下一次伤害性攻击造成的威胁值，以及之后4 秒内所有行动产生的威胁值。'),
(534605, '当前选中的小队或团队成员将承受你下一次伤害性攻击造成的威胁值，以及之后4 秒内所有行动产生的威胁值。'),
(535595, '撕裂一道穿越虚空的裂隙，将使用它的团队成员传送至暴风城。'),
(535596, '撕裂一道穿越虚空的裂隙，将使用它的团队成员传送至铁炉堡。'),
(535597, '撕裂一道穿越虚空的裂隙，将使用它的团队成员传送至达纳苏斯。'),
(535601, '撕裂一道穿越虚空的裂隙，将使用它的团队成员传送至塞拉摩。'),
(535603, '撕裂虚空裂隙，使用它的团队成员将被传送至风暴祭坛。'),
(535604, '打开一道穿越虚空的裂隙，使用它的团队成员将被传送至玛诺洛斯集会所。'),
(535605, '打开一道穿越虚空的裂隙，使用它的团队成员将被传送至暗语峡谷。'),
(536213, '炼金术技能提高15点。'),
(536216, '使用碎星斩或星辰横扫造成暴击后，必定使你招架下一次对你的攻击。\n\n此外，使碎星斩的法力消耗降低30%。'),
(537208, '你的亡灵仆从造成的暴击现在会使邪恶狂热的冷却时间缩短 3 秒。每秒最多触发一次。'),
(537212, '你的地震之握现在使敌人定身3.5 秒。'),
(537247, '使你的下一次火箭发射器（在10 秒内）变为瞬发，并造成20%的额外伤害。'),
(538441, '你的周期性伤害现在有5%的几率使你获得爆发，持续5秒。'),
(541493, '为一名小队成员注入奥术精华，使其受到的魔法伤害降低最多3%，受到的治疗效果降低最多3%。持续5 分钟。'),
(547214, '恩典誓言恢复的法力值提高 100%，霍鲁萨斯冲击还会打断目标施法，持续 3 秒。'),
(552210, '吸取敌人的法力，每2秒燃烧33点法力，并为你恢复相当于燃烧法力值的生命值，持续5 秒。\n可在移动时使用。'),
(553267, '需要凡人之躯进入鲜血涌动状态，使你激怒，造成的暗影伤害和法术急速提高30%，持续20 秒。\n\n在持续时间结束时，或每当触发诅咒形态时，改为获得逐血者。'),
(555277, '你的下一次毁灭在8 秒内变为瞬发。'),
(555723, '地震冲击现在使盟友对该敌人的所有法术命中几率提高3%，持续15 秒。'),
(555729, '使你的神圣法术产生的威胁值降低 20%，并且逆转伤口造成的治疗现在使目标受到的所有治疗效果提高 6%，持续 10 秒。'),
(555737, '保证时间经纬造成的治疗效果必定暴击，并使其获得一次额外充能。'),
(555738, '旋转你的战刃5 秒，移动速度提高30%，每1秒用双刃对所有附近敌人造成200%武器伤害。\n\n你免疫移动限制和失控效果。'),
(557325, '传送至一名敌人，在其脚下召唤一个诱饵，并将其标记，持续 8 秒。对其造成近战伤害会为此效果叠加一层，最多 20 层。\n\n在 8 秒内再次激活此技能将对目标造成（851 + 55% 攻击强度）点物理伤害，每层效果使伤害提高 30%，然后传送回你的诱饵处。\n\n可在隐匿状态下使用。'),
(557333, '从阴影中出现在目标身后，使其昏迷4 秒。'),
(560001, '使队伍和团队成员的攻击强度提高5%。不与类似效果叠加。\n\n此外，你现在获得相当于承受伤害15%的攻击强度，持续10 秒。每10秒只能触发一次。'),
(560002, '使小队和团队成员受到的伤害降低3%。不与同类效果叠加。\n\n此外，你的所有抗性提高5点，随等级提升。'),
(560012, '当骷髅法师激活时，你的亡灵仆从的暴击几率现在提高10%。'),
(560020, '以漩涡之力强化你的部分法术，将你的电击转化为盐水，并将召唤闪电转化为湍流之怒。'),
(560023, '使你的风暴之流能够造成暴击。'),
(560030, '产生50点静电升入空中并以闪电囚禁自己30 秒，将自己锁定在原地。\n\n在囚笼内时，伤害法术产生20点静电，且其射程翻倍。'),
(560036, '激发符文纹饰的力量，重置上古之拳的冷却时间，允许你使用需要符文帷幕的技能，并且可以在移动中施放这些技能，持续8 秒。'),
(560037, '40级被动技能你的相位遁形现在可以在进入冷却前，于15 秒内额外使用1次。'),
(560039, '燃刃斩和原初轰击对冻结目标的暴击几率和暴击伤害提高25%。'),
(560040, '使武器铭刻：空气复制的伤害提高100%（对玩家为40%），并使攻击速度提高15%。'),
(560045, '20级被动技能使你的法术强度提高，相当于智力值的30%。'),
(560050, '原初轰击的法术强度加成提高30%。'),
(560053, '武器铭刻：空气和武器铭刻：大地造成的伤害现在有10%的几率使你的近战急速提高10%，持续10 秒秒，影响你的下10次攻击。'),
(560055, '你的大地母亲之手现在会弹射到主要目标附近的1名盟友身上。'),
(560057, '使埃辛诺斯的猛攻和萨格隆惩击的暴击几率提高5%。'),
(560072, '鲜血爆裂的半径提高5码，暴击几率提高10%。'),
(560073, '你的罪孽现在会在持续期间内提供相当于你精神值50%的法术伤害。'),
(560074, '使你的抵抗诅咒效果的几率提高15%。'),
(560080, '使每点智力提供的法力值和生命值提高200%。'),
(560091, '使你的盾牌提供的护甲值提高15%，并且你造成暗影伤害时有5%的几率重置暮光盾牌投掷的冷却时间。'),
(560093, '闪避攻击现在会使荣耀竞技场的剩余冷却时间缩短10%。每1秒只能触发一次。'),
(560094, '眩光的冷却时间缩短 30 秒。'),
(560095, '2 次充能，充能恢复时间 25 秒。举起祝福之盾，使格挡值提高 100%，持续 5 次格挡或 10 秒。'),
(560096, '使所有小队和团队成员近战及远程急速提高10%。不与同类效果叠加。\n\n自动攻击造成的伤害使圣契法术的冷却时间缩短0.5秒。'),
(560109, '产生10点狂乱值腐蚀一名敌人的心智并散播狂乱，使其在原地恐惧40 秒（对玩家为8秒），并弹射至最多2个附近敌人［拥有邪异尖啸: ，同时对其施加心灵腐烂效果］。\n\n造成的伤害可能会提前结束此效果。'),
(560111, '施放霍鲁萨斯冲击时重置荣耀处决的冷却时间。'),
(560113, '光辉的冷却时间缩短 30 秒，伤害与治疗提高 125%。'),
(560116, '禁止一个敌人作恶，使其沉默6 秒。如果目标是不死族或恶魔，则在持续期间内无法被治疗。'),
(560123, '化身太阳，持续 30 秒。每 3 秒驱散 40 码内盟友的恐惧、沉睡与魅惑效果。'),
(560129, '你的魔杖攻击现在有30%的几率使工艺师的魔杖对该目标的伤害提高3%，持续15 秒，可叠加10层。'),
(560130, '你的发现现在额外产生相当于你基础法力值和生命值3%的资源。'),
(560135, '将地震震颤产生的怒气值提高2点。'),
(560140, '施放地震法术现在会延长大地塑形的持续时间4秒。'),
(560142, '在此效果激活期间，每消耗一层| cffc6a36a大地塑形，都会使你的碎石和晶石弹幕造成的伤害额外提高5%的自然伤害。持续8 秒。\n\n激活期间无法产生| cffc6a36a大地塑形。'),
(560145, '用火山爆发击中至少5个敌人现在会使你获得碎裂大地，持续10 秒。'),
(560146, '你的地震尖刺会击中额外1个敌人。可叠加5层。'),
(560147, '使你的近战急速提高10%，并显著提高晶石弹幕和晶簇产生的威胁值。'),
(560150, '地震技能和震击造成的伤害现在使大地化身的冷却时间减少 1 秒。\n\n此外，地震技能的冷却时间减少 3 秒。'),
(560154, '碎石现在有15%的几率额外施放一次。该效果可以自行触发。'),
(560156, '50级被动技能使地震震颤、地震冲击和地震造成的周期性伤害能够造成暴击。'),
(560157, '原本会杀死你的攻击现在改为将你化为石像重塑，恢复30%最大生命值，并在3 秒内使你受到的物理伤害降低70%。\n\n每2分钟只能触发一次。'),
(560158, '使你的最大生命值提高4%。'),
(560167, '30级被动使你的护甲穿透等级提高，相当于智力值的50%。'),
(560169, '地震震颤造成的周期性伤害现在会使你获得地质塑造，持续30 秒。'),
(560170, '你的下一次大地涌动消耗额外3点怒气，并造成10%的额外伤害。可叠加10层。'),
(560182, '使你的暴击几率提高3%，并且晶石弹幕和晶簇造成的伤害现在会使敌人受到法术暴击的几率提高3%，持续12 秒。'),
(560188, '战斗中仍可保持50%的法力回复速度。'),
(560194, '使毒蛇之牙的伤害及其法术强度加成提高15%。'),
(560195, '使毒蛇之牙的治疗效果提高50%，并且毒蛇之牙现在不会未命中。'),
(560200, '使用沙德拉香膏造成有效的持续治疗现在有10%的几率使你接下来8 秒内的下一次万能溶剂变为瞬发且不消耗法力值。'),
(560205, '施放狂战冲锋现在使你获得血之诞生。'),
(560207, '你的惩击邪恶现在有25%的几率再次攻击。\n\n当你激活罪孽之火时，触发此效果的几率提高10%。'),
(560208, '亵渎现在会为每个受到暗影烙印影响的目标恢复（10 + 10% 攻击强度 + 20% 暗影法术强度）点生命值，外加相当于你最大生命值1%的额外治疗。'),
(560219, '追猎现在额外产生15点怒气，且法力值消耗降低15%。'),
(560226, '使用罪孽之火造成伤害现在提供 2% 攻击速度，可叠加 12 层，持续 6 秒。此效果的施加不会刷新持续时间。\n\n此外，烈焰补剂现在还会重置火炬之光的冷却时间。'),
(560247, '每2秒从附近的敌人身上吸取（67 + 3% 攻击强度 + 10% 法术强度）点生命值，持续10 秒。'),
(560248, '从地面射出尖刺，刺穿15码直线范围内的所有敌人，造成（83 + 51.0714% 暗影法术强度）点暗影伤害，并使其昏迷3.5 秒。'),
(560249, '需要凡躯形态在目标区域扭曲血液，对敌人造成（177 + 69% 暗影法术强度）点暗影伤害。\n\n每层饥渴效果可缩短此技能的施法时间并提高其伤害。'),
(560250, '瓦拉纳的复仇和塔达拉姆的折磨造成的伤害提高15%。'),
(560254, '周期性伤害现在有20%的几率使你获得鲜血奔涌。该效果每5秒只能触发一次。'),
(560256, '增加你的最大怒气值20点，并且你现在每5秒回复4点怒气。'),
(560257, '你的鲜血契约现在还会使你受到的治疗效果提高20%。'),
(560259, '你的活化之血造成的伤害提高35%。'),
(560261, '使你的法术急速提高3%，并使你的猩红法术和血箭的射程提高5码。'),
(560264, '造成周期性伤害现在有10%的几率使你的下一次虫巢破击在8 秒内不消耗资源，并造成50%的额外伤害。'),
(560266, '喷出造成的伤害提高20%。'),
(560276, '太阳烈焰造成伤害后产生 1 点太阳能量，并使目标被法术暴击的几率提高 3%，持续 8 秒。'),
(560278, '提高暗影闪爆的伤害，提高25%。'),
(560280, '20级被动使你的治疗强度提高精神值的40%，并使你的法力恢复速度提高精神值的100%。'),
(560282, '使你的抵抗毒药和疾病效果的几率提高30%。'),
(560284, '以扭曲的魔法从天空中降下一名地狱火，对半径内的敌人造成（102 + 105% 火焰法术强度）点火焰伤害，使其恐惧 3 秒，并召唤一个地狱火为你作战，持续 15 秒。\n\n心魔：持续时间额外延长 1 秒。'),
(560286, '近战暴击现在使目标身上的流血效果提高30%，持续15 秒。\n\n不与类似效果叠加。'),
(560294, '为一名盟友注入森金之灵，持续30 分钟，使其精神提高3点，魔法抗性提高5点。\n\n同一时间目标只能拥有1个巫祝效果。'),
(560295, '强化一名盟友，使其资源消耗降低5%。'),
(560298, '当你的岩石屏障激活时，大地母亲之手的怒气消耗降低50%。'),
(560301, '制造3个你的分身，向随机方向奔跑持续3 秒，可短暂诱骗敌人无视你。\n\n大幅降低你的威胁值，并移除你身上的所有移动限制效果。'),
(560305, '你的灵魂冲锋和原初奔袭现在冷却更快。'),
(560310, '激活永世现在会使你从精神属性获得的法力回复提高100%，持续8 秒。'),
(560315, '需要凡人之躯向一名敌人发射强力的血之箭矢，造成（188 + 127.75% 法术强度）点暗影伤害。\n\n每层饥渴效果都会缩短此技能的施法时间并提高其伤害。'),
(560316, '制造一块归乡符文石，持续 2 分钟，允许你将炉石设定为其目的地。无法在战斗中使用。'),
(560319, '你的躲闪几率提高5%。'),
(560320, '近战攻击现在有10%的几率重置你的虚空打击的冷却时间，使下一次使用无视目标生命值，持续8 秒。'),
(560321, '在你脚下召唤一根邪异方尖碑，持续20 秒，在其附近时，你的触须造成的伤害提高100%，盟友的移动速度提高40%。'),
(560339, '你的林地专家现在会根据施放时激活的优势层数，使冷却时间降低10%。'),
(560340, '离开隐匿后，使你造成的伤害提高10%，持续12 秒。'),
(560341, '近战和远程自动攻击现在有 25% 的几率额外攻击一次，造成 50% 的伤害。\n\n每秒只能触发一次。'),
(560344, '你的野性打击现在额外攻击附近2个敌人，但每个被击中的敌人受到的伤害降低。'),
(560364, '受到直接伤害时，你的躲闪几率提高2%，持续5 秒，可叠加10层。'),
(560382, '时光涟漪每0.5秒周期性地治疗40码范围内的盟友，为其恢复（36.7 + 12.5% 法术强度）点生命值。'),
(560383, '你的法术强度提高，数值相当于精神属性的25%。'),
(560386, '时光涟漪每0.5秒对40码范围内的敌人造成周期性伤害，伤害值为（40 + 38.5% 法术强度）。'),
(560393, '时光涟漪现在会在引导期间为15码范围内的盟友施加一个吸收护盾，吸收量为（154.5 + 75% 治疗强度）。'),
(560395, '时光涟漪现在会在其持续时间内，使 40 码范围内的盟友受到的直接物理伤害延迟30%，并在5秒内分摊承受。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (560397, 560410, 560412, 560419, 560422, 560434, 560440, 560441, 560444, 560446, 560450, 560452, 560456, 560478, 560479, 560481, 560486, 560487, 560490, 560492, 560495, 560501, 560502, 560503, 560505, 560508, 560510, 560514, 560517, 560518, 560521, 560525, 560526, 560527, 560528, 560531, 560532, 560533, 560534, 560535, 560537, 560539, 560540, 560541, 560542, 560543, 560544, 560545, 560546, 560547, 560548, 560549, 560550, 560561, 560563, 560564, 560567, 560568, 560573, 560576, 560578, 560586, 560593, 560595, 560596, 560613, 560615, 560620, 560622, 560633, 560637, 560639, 560641, 560645, 560648, 560649, 560650, 560653, 560655, 560662, 560688, 560698, 560701, 560714, 560715, 560721, 560727, 560729, 560730, 560734, 560735, 560742, 560744, 560748, 560749, 560750, 560754, 560774, 560782, 560785, 560787, 560789, 560791, 560798, 560800, 560802, 560805, 560810, 560812, 560814, 560822, 560828, 560833, 560835, 560836, 560838, 560840, 560848, 560851, 560852, 560857, 560859, 560861, 560880, 560881, 560883, 560886, 560892, 560896, 560906, 560909, 560910, 560917, 560919, 560924, 560927, 560934, 560938, 560939, 560948, 560949, 560951, 560956, 560959, 560963, 560966, 560977, 560992, 560995, 561005, 561022, 561023, 561035, 561037, 561062, 561069, 561072, 561099, 561100, 561102, 561106, 561108, 561110, 561127, 561136, 561138, 561159, 561160, 561164, 561170, 561190, 561191, 561193, 561195, 561196, 561201, 561204, 561206, 561208, 561210, 561215, 561216, 561222, 561227, 561228, 561236, 561237, 561241, 561242, 561243, 561260, 561265, 561278, 561284, 561310, 561314, 561315, 561320, 561321, 561322);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(560397, '你的纪元造成暴击时，会获得时光韵律效果，使时光涟漪的治疗效果提高10%，持续15 秒，可叠加5层。'),
(560410, '降低你的阵型的能量消耗，并使其效果提高25%。'),
(560412, '使用幽魂疾步现在会生成 1 层收割之魂。'),
(560419, '你每拥有 100 点护甲，近战攻击强度便提高 1 点。'),
(560422, '使你的仪式（坚毅仪式、力量仪式、坚韧仪式，含各等级与群体版）提供的增益效果提高 20%。'),
(560434, '使收割、逐死者与怨灵之刃的暴击几率与暴击伤害提高 10%。'),
(560440, '暴击现在使目标受到的法术伤害提高10%，持续15 秒。'),
(560441, '无羁之怒现在还会使你的暴击伤害提高10%。'),
(560444, '对生命值低于20%的目标使用斩首和猎首者之矛时，暴击几率提高30%。'),
(560446, '先祖打击和碾压造成的伤害现在随你的力量值提高。'),
(560450, '对敌人造成暴击现在将杀戮的冷却时间缩短4秒。'),
(560452, '使你的暴击几率提高2%。'),
(560456, '你的能量恢复速度提高25%。'),
(560478, '强化形态现在使周围敌人受到的你的伤害提高 15%，持续 15 秒。'),
(560479, '血牙撕咬和利爪扫击对人形生物和野兽造成的伤害提高20%。'),
(560481, '将大地拥抱的持续时间延长4秒。'),
(560486, '对生命值低于 20% 的敌人时，你造成暗影伤害的技能暴击几率提高 15%。'),
(560487, '你成功的招架与闪避会在 10 秒内使你要承受的全部治疗量提高 2%，并使你要承受的魔法伤害降低 2%，可叠加 5 次。'),
(560490, '使你的命中几率提高，并使你受到的魔法伤害降低 3%。'),
(560492, '避免受到一次攻击时，还会对攻击者造成（3% 攻击强度 + 54 × 等级系数 + 12% 火焰法术强度）点火焰伤害，每秒最多触发一次。'),
(560495, '移除缴械的集中值消耗。'),
(560501, '闪避近战攻击将召唤一道月焰攻击攻击者，造成（66 × 等级系数）点奥术伤害。\n\n每秒最多触发一次。'),
(560502, '当你的狂乱值高于60点时，暮光盾牌投掷和克苏恩之凝视的冷却时间缩短25%。'),
(560503, '当心魔激活时，切割和萨格隆惩击现在会从初始打击造成的伤害中吸取20%作为暗影烈焰伤害。'),
(560505, '乌索克之吼的效果提高40%。'),
(560508, '使山岳之怒的冷却时间缩短20秒，持续时间延长4秒。'),
(560510, '地震震颤造成的伤害现在有20%的几率在你的目标脚下形成岩柱，在3 秒后爆炸。'),
(560514, '暴击几率提高2%，最多叠加3层。'),
(560517, '对生命值高于80%的敌人时，你的暴击几率提高25%。'),
(560518, '向一名敌人冲锋，造成（31 + 35% 远程攻击强度）点物理伤害并使其定身2 秒，随后向后跳跃。'),
(560521, '战斗滋养你的活力，在 4 秒内恢复（20 + 20% 攻击强度）点生命值和 12 点能量。'),
(560525, '使所有小队和团队成员的法术急速提高 3%。不与类似效果叠加。\n\n点燃斗志！ 现在使你的爆炸或奈萨里奥之焰的暴击可以将你的周期性伤害效果从目标身上扩散。每次施放只能扩散到一个目标。'),
(560526, '使所有小队和团队成员的法术急速提高3%。不与类似效果叠加。\n\n此外，你的暗影伤害提高3%。'),
(560527, '使所有小队和团队成员的法术急速提高3%。不与类似效果叠加。\n\n此外，你的铭文法术的射程提高6码。'),
(560528, '使小队和团队成员造成的所有伤害提高3%。不与类似效果叠加。\n\n此外，你的瓦解和时光撕裂获得额外20%的法术强度加成。'),
(560531, '使队伍和团队成员的近战及远程攻击强度提高5%。不与同类效果叠加。\n\n此外，使你的伤害提高3%。'),
(560532, '捡起一块石头砸向敌人的头颅，使其迷失方向，持续40 秒（对玩家为8秒）。\n\n受到伤害会解除此效果。［拥有填补空缺: 移除目标身上的所有流血效果。］'),
(560533, '使 100 码内所有小队和团队成员的暴击几率提高 3%。不与其他类似效果叠加。\n\n此外，使你的暴击几率额外提高 3%。'),
(560534, '小队和团队成员造成的所有伤害提高 3%，不与同类效果叠加。你的招架几率提高 5%。'),
(560535, '使所有小队和团队成员暴击几率提高3%。不与类似效果叠加。\n\n此外，你现在可以从所有暴击伤害中恢复15%的生命值。'),
(560537, '使所有小队和团队成员的法术急速提高3%。不与类似效果叠加。\n\n此外，使你的魔法伤害提高3%。'),
(560539, '使所有队伍和团队成员的暴击几率提高3%。不与同类效果叠加。\n\n此外，月之箭矢造成暴击时，会使附近一名盟友的最大法力值、怒气、能量、集中值和符文能量提高10%，持续30 秒。'),
(560540, '使 100 码范围内的队伍和团队成员近战及远程急速提高 10%。\n\n不与类似效果叠加。\n\n此外，你受到的昏迷效果持续时间缩短 20%。'),
(560541, '使所有小队和团队成员的法术急速提高3%。\n\n不与类似效果叠加。\n\n此外，所有治疗效果现在有10%的几率使你获得无尽之沙。'),
(560542, '散发强大的光环，使100码范围内的队伍和团队成员近战与远程急速提高10%。不与类似效果叠加。\n\n此外，当心魔激活时，你造成的所有近战伤害的15%将转化为治疗。'),
(560543, '进入狂暴状态，使你的攻击强度提高5%，并使所有小队和团队成员的冰霜抗性提高60点。不与类似效果叠加。'),
(560544, '施放投掷药水和瓶中精魂现在使你接下来的2次洛阿之酿的施法时间缩短20%，持续10 秒。'),
(560545, '使小队和团队成员造成的所有伤害提高3%。不与类似效果叠加。\n\n此外，你的暗影傀儡现在造成伤害的速度提高20%。'),
(560546, '40级被动格挡一次攻击现在会使你的招架几率提高10%，直到你招架一次攻击为止。'),
(560547, '散发光环，使附近所有盟友受到的治疗提高 6%，不与同类效果叠加。圣光照耀的治疗提高 20%。'),
(560548, '使你的暴击几率提高4%，且你的暴击现在会为盟友提供回能。'),
(560549, '使100码范围内的队伍和团队成员近战及远程急速提高10%。不与类似效果叠加。\n\n此外，你的耐力和攻击强度提高4%。'),
(560550, '使所有小队和团队成员的攻击强度提高5%。不与同类效果叠加。\n\n此外，使你的攻击强度提高5%。'),
(560561, '你对生命值低于35%的盟友造成的治疗效果提高25%。'),
(560563, '用野蛮旋风击中至少3个目标会重置其冷却时间。\n\n该效果每6秒只能触发一次当野蛮旋转的冷却时间降低时，该内置冷却时间也会降低。。'),
(560564, '在激怒状态下，施放长矛现在会刷新 3 层狂战飞斧的充能，并且你的下 3 次施法消耗的能量减少 50%。持续 12 秒。'),
(560567, '将风与暴风之力赋予附近所有盟友，使急速提高30%，持续20 秒。\n\n受到该法术影响后，盟友在5 分钟内无法从类似效果中获益。'),
(560568, '使所有小队和团队成员暴击几率提高3%。\n\n不与类似效果叠加。'),
(560573, '降低残废术和吞噬魔法的能量消耗10点。'),
(560576, '使你的招架几率提高4%。'),
(560578, '提高怒意释放造成的伤害并降低其能量消耗 50%。'),
(560586, '你的碎脏者现在使你的技能忽略目标 10% 的护甲。'),
(560593, '使所有小队和团队成员的攻击强度提高5%。不与类似效果叠加。\n\n此外，使你的远程攻击强度提高3%。'),
(560595, '每个亡灵姿态现在提供额外加成：\n\n亡灵：突击：对人形生物暴击几率提高5%。\n\n亡灵：防护：产生的威胁值降低75%。\n\n亡灵：安抚：受到的伤害降低10%。'),
(560596, '你的地穴虫群现在会弹射到2个额外的附近敌人，每击中一个敌人效果降低30%。'),
(560613, '提高你的法令的效果20%。'),
(560615, '提高你的法术急速4%。'),
(560620, '提高巫妖寒霜和寒冰弹幕的法术强度加成，效果为20%。'),
(560622, '每级提高0.5点暗影和冰霜抗性。'),
(560633, '当你使用消耗6层恶魔之火的技能时，现在会以一半效果释放你激活的疫病。'),
(560637, '当心魔激活时，施放毁灭、撕裂或邪能狂怒现在会返还20点能量。'),
(560639, '你的周期性伤害现在有 20% 的几率产生 1 层邪能之怒。'),
(560641, '残废术现在会使敌方目标无法造成暴击，持续4 秒。'),
(560645, '提高埃辛诺斯的猛攻的伤害 20%，并使其提高你的近战急速 20%，持续 5 秒。'),
(560648, '造成的近战伤害现在有10%的几率重置冷却时间，并使你的下一次白银之刃的能量消耗降低50%。'),
(560649, '希望圣约现在会召唤一个额外的你的复制体。'),
(560650, '提高你的神圣暴击几率 3% 和精准等级 5。'),
(560653, '你向附近小队和团队成员散发和谐气场，减少坠落伤害，并获得水上行走能力。'),
(560655, '使你的格挡值提高 30%。此外，你格挡猛烈攻击的几率提高 60%。'),
(560662, '你的月神之矛现在会对目标施加灼烧效果，在20秒内造成额外的神焰伤害。'),
(560688, '使用5层优势的技能现在会刷新你激活的游击的持续时间5秒。'),
(560698, '在10 秒内，下一次燃烧射击的施法时间缩短10%，暴击几率提高10%，可叠加10层。'),
(560701, '你现在有 20% 的几率在施法时不消耗优势。'),
(560714, '使盟友对受影响的敌人施放的所有法术命中几率提高3%，持续10 秒。\n\n如果该效果被驱散，你的暴击几率提高30%，持续5 秒。'),
(560715, '当生命值低于35%时受到伤害，现在会召唤3个亚煞极的化身，持续10秒，它们会攻击敌人并为你恢复基础生命值的5%。\n\n每2分钟只能触发一次。'),
(560721, '通过消耗散落星辰造成的伤害提高15%。'),
(560727, '提高你的法术急速5%。'),
(560729, '你的亡灵仆从在命中时吞噬寄生虫，将造成伤害的15%转化为瘟疫伤害吸取到目标身上。'),
(560730, '造成的伤害现在有 5% 的几率施加寄生虫，持续 8 秒。'),
(560734, '纳米机器人现在有30%的几率抵抗移动限制效果，持续15 秒。'),
(560735, '降低受到伤害性攻击时的施法退条 35%，并提高你的暴击治疗 10%。'),
(560742, '你和你的宠物的智力提高10%，并且你们现在都不会未命中攻击。'),
(560744, '展示你的最伟大发明，每 1.5 秒治疗 30 码范围内的队伍和团队成员（752.2 + 65% 治疗强度）点生命值，持续 9 秒。'),
(560748, '消耗你的精魂，每消耗一层精魂，使你的远程暴击等级提高10，暴击伤害提高5%，并为你恢复相当于造成伤害2%的生命值。\n\n此外，在激活状态下，每1秒获得1层精魂。\n\n每消耗一层精魂，持续4秒。'),
(560749, '灼烧一名盟友的伤口，移除其1个流血效果。'),
(560750, '3层充能，15秒充能时间投下一个补给信标，持续15 秒，投射出一个力场，每2.5秒为盟友恢复5点怒气、能量、集中值、符文能量和5%基础法力值。［拥有信标充能: \n\n过载：为15码内的所有盟友恢复10%最大法力值。］\n\n与其他信标共享冷却时间'),
(560754, '3层充能，15秒充能时间投掷一个警报信标，持续10 秒，每1秒移除20码范围内最多［拥有机械复苏: 2；否则： 1］个所有［拥有机械复苏: 盟友；否则： 友方］身上的恐惧、魅惑和睡眠效果。［拥有信标充能: \n\n过载：驱散15码范围内所有盟友身上的1个有害魔法和诅咒效果。］［拥有建造：ZIGGI-6K: \n\n@ext：与其他信标共享冷却时间：ext@］'),
(560774, '移动速度提高10%，持续30 秒。跑向电池充电站并给你的电池充电！'),
(560782, '施放Beacon技能现在会使巅峰造物！的冷却时间减少20秒。'),
(560785, '40级被动有效的治疗现在有25%的几率使你的机械宠物获得植入弹。'),
(560787, '电击！ 现在使你的激活的建造技能电击附近生命值最低的盟友，为其治疗（984.205 + 90% 治疗强度）点生命值。'),
(560789, '提高你和你的召唤物的暴击几率 5%。'),
(560791, '你的电击！现在必定对受纳米机器人影响的盟友造成暴击。'),
(560798, '你的亡灵仆从造成的伤害现在将疫病蔓延的冷却时间缩短1秒。'),
(560800, '完全引导地穴虫群后，你召唤一个腐烂怪，它会跑向敌人并在5秒后爆炸，造成（202 + 33.5% 法术强度）点瘟疫伤害。'),
(560802, '林地箭矢和翡翠箭矢造成的伤害现在会使敌人中毒，持续 8 秒，每 2 秒造成（15% 远程攻击强度 + 150 × 等级系数）点自然伤害。'),
(560805, '标记一个敌人进行彻底摧毁，使你的盟友对该目标的远程攻击强度提高 300，并在 15 秒内造成 2115 点自然伤害。\n\n被标记的目标无论潜行还是隐身，游侠始终能看到它。\n\n一个被被烙印标记的目标在 90 秒内无法再次受到萨拉斯烙印的影响。'),
(560810, '自动射击现在有20%的几率延长你的锯齿射击持续时间2秒。'),
(560812, '箭袋的效果提高25%。'),
(560814, '使肾上腺素激增的冷却时间缩短30秒。'),
(560822, '当憎恨壁垒从你身上移除时，你在8 秒内受到的所有魔法伤害降低15%。'),
(560828, '当生命值低于35%时，黑盾的吸收量翻倍。'),
(560833, '你的能量恢复速度提高20%。'),
(560835, '定罪造成的周期性伤害现在有15%的几率使你的招架几率提高2%，持续8 秒，最多叠加3层。\n\n定罪造成的周期性伤害还有15%的几率爆发，对目标5码内最多5个敌人造成（22% 攻击强度 + 100 × 等级系数）点神圣伤害。'),
(560836, '萨格隆惩击的暴击几率提高10%。'),
(560838, '施放湮灭现在使你获得末日雕塑者。'),
(560840, '每第 3 次毁灭或邪能狂怒现在会召唤一个地狱火为你作战，持续 15 秒。'),
(560848, '灵魂冻结现在每跳使目标受到你的冰霜伤害提高5%，持续8秒，可叠加3层。'),
(560851, '使冰川冲击的伤害提高50%。'),
(560852, '你的冰川冲击现在必定对冻结目标造成暴击。'),
(560857, '对生命值低于 35% 的目标造成的伤害和治疗提高 10%。消耗灼烧印记后，魔法伤害提高 10%，持续 8 秒。'),
(560859, '黎明灼击和太阳耀斑的施法时间和法力消耗降低 10%。'),
(560861, '黎明激活期间，辉耀圣焰造成伤害会使黎明降临之光和日光协奏的冷却时间缩短 1 秒。'),
(560880, '使开膛破肚的暴击几率提高10%，并且现在会对目标施加破甲，暴击时还会额外叠加一层。'),
(560881, '精准地向一名敌人投掷一柄重型长矛，造成160%远程武器伤害外加37点伤害，并使其受到的治疗效果降低30%，持续10 秒。\n\n与其他长矛共享冷却时间。'),
(560883, '将附近所有盟友带入战团，持续 12 秒，使其获得血之诞生，每 3 秒重复一次。'),
(560886, '使你的敏捷提高5%。'),
(560892, '使你的近战急速提高 10%。'),
(560896, '通过女神之相进行的治疗现在会使目标从你处受到的治疗效果提高1%，持续10秒，最多叠加10层。'),
(560906, '对生命值高于 80% 的敌人造成的所有伤害提高 20%。'),
(560909, '立即移除所有移动限制效果，使你的移动速度提高25%，并免疫减速效果。\n\n可被斩首或碾压消耗，以确保它们必定造成暴击。'),
(560910, '使极致杀戮的持续时间延长1秒，并且现在会提供彻底毁灭，持续6 秒。'),
(560917, '使逐死者造成的伤害提高 15%，并使你的命中几率提高 3%。'),
(560919, '灵魂突刺现在会盜取目标的部分生命值与力量，持续 12 秒，并以更高的数值转化为你的收益。'),
(560924, '使屠戮的暴击伤害与暴击几率提高 10%。'),
(560927, '幽魂武器现在使你的近战技能可以额外攻击主目标附近的 2 个敌人。'),
(560934, '击破敌人的防御，使其护甲降低4%，持续30 秒，可叠加5次。'),
(560938, '你的蛮角之怒激怒效果的持续时间延长6秒，并在持续期间使你的移动速度提高40%。'),
(560939, '霍迪尔之怒造成的伤害现在会使敌人冻结在原地，持续0.004 秒。'),
(560948, '每第10次你造成的伤害或治疗现在会使你获得11点法术强度提高，持续10 秒。'),
(560949, '你的周期性伤害和治疗效果现在可以造成暴击。'),
(560951, '施放月井水之瓶现在额外为你恢复相当于当前法力值25%的生命值。'),
(560956, '散落星辰造成的伤害现在使你的治疗量提高1%，暴击几率提高1%，持续10 秒，可叠加10层。'),
(560959, '使荆棘面纱提供的躲闪几率提高25%。'),
(560963, '束缚一个亡灵或恶魔敌人，将其放逐30 秒（对玩家为6秒）。被束缚的单位免疫物理伤害，无法移动、攻击或施放法术。\n\n同一时间只能束缚一个目标。'),
(560966, '向最多5个附近的敌人发射飞镖，造成（15 + 30% 攻击强度）点远程物理伤害。\n每层优势效果使伤害提高，并额外击中1个目标。'),
(560977, '移除邪异震击的冷却时间，并在拥有至少60点狂乱时保证其必定暴击。\n\n邪异震击现在可以在引导时施放。'),
(560992, '使跃迁匕首的冷却时间缩短5秒。'),
(560995, '使你的精神提高5%，并减少受到伤害性攻击时的施法退条35%。'),
(561005, '当盟友经过花朵时，他们会消耗它，恢复5%的最大生命值，并获得40%的移动速度加成，持续5 秒。'),
(561022, '女猎手之相现在使你的命中几率提高3%。\n\n此外，你造成的奥术伤害现在有5%的几率使你的下一次女猎手射击不消耗法力值，且伤害提高25%。'),
(561023, '等级 20 被动：护甲提高，数值相当于力量与智力之和的 250%，并获得等同于盾牌基础护甲值的生命值。'),
(561035, '恩佐斯的意志和亚煞极的意志的持续时间延长25%。'),
(561037, '在大地拥抱效果结束时，你使附近所有敌人迷惑6 秒。造成伤害会中断该效果。'),
(561062, '你的月神之矛现在对着火了目标必定造成暴击，伤害提高25%。'),
(561069, '你现在可以向你的材料中添加额外的大锅，以增强你的酿造效果。\n\n教你材料：鱼油。'),
(561072, '使投掷药水和你投掷的材料的效果提高20%。'),
(561099, '退出冥行时，暴击几率提高 10%，持续 5 秒。'),
(561100, '受难灵魂现在每有 1 层活跃的收割之魂，就会额外创造 1 个灵魂。'),
(561102, '重置灵界、灵魂重击与阴魂的冷却时间。潜行状态下可使用。'),
(561106, '使缴械的射程增加15码。'),
(561108, '使群鸦杀戮与灵魂震击的射程提高 5 码。'),
(561110, '割喉的冷却时间缩短15秒，但割喉的射程降低10码。'),
(561127, '副手武器伤害提高 25%。双持时，你的自动攻击有 8% 几率使你的下一次群鸦杀戮免费施放。'),
(561136, '每秒恢复2.1点生命值和法力值，持续12 秒，可叠加5次［拥有恶毒: ，并使你的移动速度提高4%］。'),
(561138, '吟唱一个强大的仪式，在你附近召唤1 腐烂冰霜巨人协助你战斗，持续30 秒，并产生30符文能量，每3秒重复一次，持续15 秒。\n\n在此期间，你的亡灵仆从必定造成暴击。'),
(561159, '等级 30 被动：法术强度提高，数值相当于力量的 100%。'),
(561160, '40级被动使你的力量提高25%。'),
(561164, '每个骷髅战士或骷髅盗贼使你的寒冰弹幕伤害提高8%。'),
(561170, '等级 30 被动：使冥行的冷却时间缩短 10 秒。此外，凋零之触现在总会为目标施加幽魂之爪。'),
(561190, '地震震颤的持续时间延长6秒，其跳动频率提高10%。'),
(561191, '施放巨石冲刺现在立即产生50点怒气。'),
(561193, '用震击击中至少5个敌人或施放山岳之锤现在使你获得领主之怒。'),
(561195, '鲜血爆裂的施法时间延长2秒，但现在当你击中至少5个敌人时，会使他们流血，在2 秒内额外造成348点暗影伤害。'),
(561196, '每层活化之血使饥渴的持续时间增加1秒。'),
(561201, '毁灭造成的伤害现在会根据等级吸收目标接下来99点治疗量，7级时最多吸收226点，持续8秒。'),
(561204, '光辉的持续时间延长 6 秒。激活黎明时获得持续 6.001 秒的光辉；若已激活，则延长相同时间。'),
(561206, '使月神之矛和星火射击的暴击几率提高5%。'),
(561208, '大地母亲之手的怒气消耗减少5。'),
(561210, '追猎现在额外使移动速度降低2秒。'),
(561215, '施放命令法术现在使你的活化术冷却时间减少1秒。'),
(561216, '2层充能，1.5分钟充能时间快速在敌人之间移动，用两把武器每0.5秒攻击一次，共进行6次攻击，每次攻击产生1层邪能之怒。激活期间免疫控制效果。\n可多次命中同一目标。无法命中隐形或潜行目标。\n需要附近有敌人才能施放。'),
(561222, '使你的奥术伤害提高5%，命中几率提高2%。'),
(561227, '使你的护盾效果提高50%。'),
(561228, '风暴之流造成的伤害现在为你恢复等量的生命值。'),
(561236, '强化一名盟友，使其总属性提高10%。'),
(561237, '强化一名盟友，使其敏捷提高10点，持续30 分钟。'),
(561241, '强化所有小队和团队成员，使其敏捷提高77点，持续30 分钟。'),
(561242, '强化所有小队和团队成员，使其总属性提高10%。'),
(561243, '强化所有小队和团队成员，使其资源消耗降低5%。'),
(561260, '使一名盟友与魔网协调，使其受到的法术伤害最多提高15点，受到的治疗法术效果最多提高16点，持续30 分钟。'),
(561265, '调整你脚下的魔网，使其在30 秒内将你产生的威胁值转移至目标小队成员。'),
(561278, '鲜血愈合的施法时间缩短0.5秒。'),
(561284, '专注释放2次魔杖攻击，造成远程武器伤害外加5点伤害，持续1 秒。\n\n产生1个回响碎片。'),
(561310, '将敌人从当前时间线中震出，使其抓握失效，缴械其近战和远程武器，持续6 秒。\n\n移除时，敌人重新同步，阻止其恢复生命值，持续6 秒。'),
(561314, '你的碎颅现在移除目标身上的所有流血效果。'),
(561315, '用一把生锈的小刀刺击敌人，在接下来10 秒内积累对其造成伤害的10%，并在持续时间结束时造成累积总量的伤害。'),
(561320, '使肾上腺素激增提供的移动速度提高 20%。'),
(561321, '使旋进的暴击几率提高50%。'),
(561322, '使你的怒吼效果提高20%。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (561326, 561327, 561328, 561342, 561353, 561360, 561386, 561387, 561389, 561392, 561394, 561395, 561397, 562028, 562210, 562225, 562226, 562227, 562228, 562301, 562302, 562371, 562372, 562373, 562374, 562376, 562377, 562390, 562572, 562573, 562720, 562723, 563123, 563725, 563736, 567233, 567524, 567533, 567542, 567555, 567560, 570001, 570014, 570015, 570023, 570027, 570046, 570051, 570057, 570061, 570067, 570077, 570121, 570122, 570123, 570124, 570128, 570131, 570136, 570149, 570157, 570158, 570170, 570173, 570183, 570191, 570207, 570208, 570217, 570231, 570235, 570236, 570242, 570336, 570338, 570713, 570716, 570722, 570726, 570727, 570735, 570737, 570739, 570746, 570752, 570756, 570758, 572023, 572029, 572064, 572103, 572116, 572127, 572130, 572173, 572177, 572178, 572213, 572214, 572303, 572304, 572305, 572306, 572310, 572340, 572352, 572357, 572367, 572370, 572372, 572378, 572384, 572391, 572396, 572399, 572400, 572404, 572527, 572530, 572538, 572545, 572546, 572547, 572548, 572582, 572626, 572629, 572630, 572631, 572632, 572633, 572637, 572722, 572723, 572747, 572752, 572770, 572771, 572783, 572787, 572790, 572791, 572799, 572800, 572808, 572810, 572817, 572836, 572855, 572870, 572871, 572879, 572885, 572889, 572904, 573028, 573034, 573035, 573036, 573038, 573039, 573040, 573041, 573042, 573043, 573044, 573047, 573056, 573057, 573059, 573060, 573066, 573067, 573247, 573250, 573256, 573283, 573299, 573307, 573310, 573343, 573348, 573364, 573365, 573426, 573436, 573452, 574138, 574140, 574143, 574145, 574146, 574147, 574148, 574149, 574153, 574301, 574308, 574309, 574310);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(561326, '当你装备双手武器时，你的近战攻击无视敌人10%的护甲。'),
(561327, '暴击使列王之锤和太阳祷言的冷却时间缩短 1 秒。'),
(561328, '生命值高于 80% 时，眩光变为瞬发。'),
(561342, '使死亡追猎者、灵魂石诱引与灵魂割裂的冷却时间缩短 25%。'),
(561353, '使地穴虫群和枯萎的伤害提高15%，并且枯萎造成的伤害现在有5%的几率重置尸体爆炸的冷却时间。'),
(561360, '对生命值高于80%或低于20%的敌人造成暴击现在会向其发起决斗挑战挑战。每次只能挑战一个敌人。'),
(561386, '向一名盟友赐予恩佐斯的疯狂，使其总属性提高10%，持续30 分钟。'),
(561387, '向队伍和团队中的成员赐予恩佐斯的疯狂，使其总属性提高10%，持续30 分钟。'),
(561389, '向一名盟友赐予亚煞极的疯狂，每5秒恢复10点法力值，持续30 分钟。每个邪邪教徒在同一时间只能对一名玩家施加一种低语效果。'),
(561392, '向附近的盟友赐予亚煞极的疯狂，每5秒恢复33点法力值，持续30 分钟。每个邪邪教徒在同一时间只能对一名玩家施加一种低语效果。'),
(561394, '移除碎颅的能量消耗。'),
(561395, '召唤一只猎鹰，并通过它的眼睛观察1 分钟，在此期间可以看到潜行和隐形的敌人，并追踪人型生物。\n可在隐匿状态下使用。'),
(561397, '在激怒状态下，你的远程暴击现在会赋予你狂战士效果。该效果一旦施加便无法再次触发。'),
(562028, '激活时，在小地图上显示附近所有亡灵的位置，并对亡灵造成的伤害提高 5%。'),
(562210, '从你的复生仆从身上汲取精华，每1秒吸取20点法力值，转化为1点符文能量。持续10 秒秒。'),
(562225, '在小地图上显示附近所有人型生物、恶魔和亡灵的位置，并显著提高你的潜行侦测能力。\n\n仅限夜间生效。'),
(562226, '在小地图上显示附近所有亡灵和恶魔的位置。'),
(562227, '激活时，在小地图上显示附近所有元素生物的位置，并对元素生物造成的伤害提高 5%。'),
(562228, '在小地图上显示附近所有人型生物、巨人和野兽的位置。'),
(562301, '驯服一只野兽，控制它40 秒（对玩家为8秒）。同一时间只能驯服一只野兽。'),
(562302, '使40码范围内的所有小队和团队成员的坐骑移动速度提高50%，持续15 秒。\n\n只能在骑乘时使用。不与类似效果叠加。'),
(562371, '使40码范围内的队伍和团队成员获得魔法抗性提高20点，持续10 秒。'),
(562372, '使40码范围内的敌人护甲降低15%，持续10 秒。'),
(562373, '使40码范围内的队伍和团队成员移动速度提高15%，持续10 秒。'),
(562374, '使40码范围内的敌人近战和远程攻击速度降低15%，持续10 秒。'),
(562376, '使40码范围内的敌人受到暴击的几率提高3%，持续10 秒。'),
(562377, '使40码范围内的小队和团队成员受到的治疗效果提高5%，持续10 秒。'),
(562390, '给敌人施加印记，使其受到近战和远程攻击命中的几率提高2%，持续5 分钟。\n你可以在小地图上看到被标记的目标，并且能看穿潜行或隐形状态。\n你同时只能对一个敌人施加1个印记'),
(562572, '拥抱你的恶魔诅咒，持续30 秒，进入强化后的诅咒形态，使你的攻击强度提高相当于敏捷值50%的数值，并且你的近战攻击会使目标受到的所有治疗效果降低20%，持续10 秒，可叠加2层。\n\n处于诅咒形态时，你被视为恶魔，并免疫变形术效果。此能力在返回凡人形态后进入冷却。'),
(562573, '烙印一个敌人，诅咒他们并使其施法速度降低30%，持续10 秒。同时只能影响1个目标。\n\n你同时只能对一个敌人施加1个烙印。.'),
(562720, '进入诅咒形态，持续 30 秒，允许使用独特技能，并随时间产生生命值和怒气值。该技能在返回凡人形态后进入冷却。\n\n处于诅咒形态时，你将被视为恶魔。'),
(562723, '让你的血咒掌控你的内心，持续5 分钟，从而解锁你的诅咒形态技能栏。\n激活期间，你无法移动、攻击或施放法术与技能。\n无法在战斗中使用。'),
(563123, '20级被动技能使你的暴击伤害提高50%，并使你的法术强度提高相当于智力30%的数值。'),
(563725, '射出一支灌注星辰的箭矢，击中一条直线上的敌人，造成 400% 远程武器伤害外加（45% 最大法力值）点奥术伤害，伤害随最大法力值提高，并向他们施加散落星辰。'),
(563736, '每点怒气现在使血箭的伤害提高1%，但其怒气消耗提高10。'),
(567233, '使用上古之拳现在使你的武器铭刻触发几率提高 20%，持续 5 秒。'),
(567524, '吸收（150 + 300% 智力 + 300% 耐力）点伤害，受智力和耐力加成。防止移动速度低于正常速度的 80%。持续 20 秒。\n\n效果结束时消耗所有狂乱。'),
(567533, '使风暴预警的施法时间缩短0.5秒。'),
(567542, '使稳定气压提供的击退减免提高 15%。'),
(567555, '消耗20点静电引导一道风暴光束射向敌人，在8 秒内造成（128 + 160% 法术强度）点冰霜伤害，伤害随你的法术急速提升。\n\n［拥有风暴君主: 盐水；否则： 电击］可在引导时立即施放［拥有不羁之流: ，并造成0%的额外伤害］。'),
(567560, '造成（冰霜法术强度高于自然法术强度时：（335 × 等级系数 + 58.5% 冰霜法术强度）；否则：（335 × 等级系数 + 35% 自然法术强度））点冰霜伤害，每层导电使其伤害提高。'),
(570001, '余烬之触造成的治疗现在使你获得烈焰施法。'),
(570014, '发射一连串强力射击，穿透护甲，对40码直线上的所有目标造成450%远程武器伤害外加300点伤害。\n\n当游击激活时，此技能必定造成暴击。'),
(570015, '潜入暗影，进入强化潜行模式，使你的移动速度提高25%，持续10 秒，并获得隐匿效果。'),
(570023, '根据你的饥渴等级获得加成。当饥渴为 1-5 层时：法术急速提高 10%。当饥渴为 6-10 层时：法术暴击造成的额外伤害提高 100%。'),
(570027, '霍鲁萨斯冲击和圣光迸发的伤害提高 15%。'),
(570046, '使你的结界效果提高15%。'),
(570051, '为你周围12码范围内的盟友恢复（32 + 10% 攻击强度 + 10% 治疗强度）点生命值。'),
(570057, '30级被动技能当电刑者激活时，你的电刑现在获得20%的伤害提升。'),
(570061, '你的通量发射器现在会额外击中1个敌人。'),
(570067, '变身为混乱化身，立即重置多彩碎片的冷却时间，使你在移动时也能施放该技能，并使你的下一次施放不会进入冷却时间。\n\n此外，你造成的伤害提高15%，持续15 秒。'),
(570077, '当心魔激活时，你的近战攻击使目标受到的治疗效果降低20%，持续8 秒，可叠加2层。'),
(570121, '点燃一个特殊的营火，允许烹饪，持续30 秒。'),
(570122, '以锁住的箱子或物品为目标，将其砸开！'),
(570123, '为一名盟友赋予魔法之翼，使其坠落速度降低，持续30 秒。'),
(570124, '向附近盟友赐予月之祝福，使其可在水面上行走。持续30 分钟。\n\n受到伤害将取消此效果。'),
(570128, '你的振奋现在可额外叠加5层。'),
(570131, '每 2 秒造成（2 + 6% 法术强度）点瘟疫伤害，持续 10 秒，最多叠加 10 层。\n\n额外施加不会刷新持续时间。'),
(570136, '提高墓穴瘟疫的伤害50%，并且地穴虫群现在会根据你对目标施加的每个死灵法师疾病效果，额外造成4%的伤害。'),
(570149, '使加速恢复的治疗加成效果提高15%。\n\n你的加速恢复会立即治疗目标，恢复相当于周期性效果总量15%的生命值。'),
(570157, '使你的副手武器伤害提高30%，命中几率提高3%。'),
(570158, '施放埃辛诺斯的猛攻现在会灼伤敌人，使你的盟友对其造成的攻击强度提高（15% 敏捷），持续10 秒。'),
(570170, '用永恒凤凰的力量强化你和附近的盟友，使其智力提高31，持续30 分钟。'),
(570173, '你的托里姆之臂现在会在目标脚下留下不稳定的电流，每1秒对范围内的敌人造成相当于其伤害15%的伤害，持续3 秒。'),
(570183, '20级被动使你的招架等级、躲闪等级和急速等级提高，数值相当于你力量的15%;并使你的攻击强度提高，数值相当于你耐力的30%。'),
(570191, '托里姆之臂的昏迷效果持续时间延长1秒。'),
(570207, '烈焰施法现在可以额外叠加 2 层。'),
(570208, '在一个位置制造一片 8 码的毒云，持续 12 秒，每 2 秒对其中的 8 个敌人造成（57 × 等级系数 + 12.5% 自然法术强度）点自然伤害［拥有昏睡: ，并对其施加嗜睡］。'),
(570217, '吸取10%最大法力值以月影笼罩区域，使敌人的攻击强度降低35点，持续30 秒，其怒火在暗夜之下逐渐消退。'),
(570231, '在3 秒内反转下一个对你施放的法术，将其反弹回施法者。\n\n以这种方式反转法术会消耗施法者（165 + 20% 法术强度）点法力值。'),
(570235, '40级被动技能血之诞生现在可叠加1次额外层数。'),
(570236, '你的猛击现在恢复25%的最大能量值。'),
(570242, '50级被动投掷武器造成的伤害现在会随你的敏捷属性提高。'),
(570336, '20级被动技能使你的法术伤害提高，相当于智力值的25%，并使你的急速等级提高，相当于智力值的20%。'),
(570338, '等级 20 被动：使你的法术穿透提高 20 点，收益随你的等级提升。'),
(570713, '40级被动近战攻击现在使加固的冷却时间减少1秒。'),
(570716, '移动速度提高30%，持续12 秒。'),
(570722, '施放放电现在恢复 5% 更多法力值。'),
(570726, '你的暗影猎犬的近战攻击现在顺劈1个附近的额外敌人。'),
(570727, '将你的克索诺斯之焰转化为战争使者。'),
(570735, '移除你的鲜血护盾和生命护盾的生命值消耗。'),
(570737, '你的战鹰和龙鹰现在有 25% 的几率对 3 个附近敌人造成额外物理伤害。'),
(570739, '受到的物理伤害提高 4%，持续 1 分钟。'),
(570746, '使鲜血契约的持续时间延长4秒，并且你每次躲闪现在都会产生3点怒气。'),
(570752, '提高友方目标的护甲150点，所有属性6点，所有抗性5点，持续30 分钟。'),
(570756, '为所有小队和团队成员赋予大地坚韧，提高其护甲285点，所有属性12点，所有抗性20点，持续30 分钟。'),
(570758, '你的鲜血护盾现在会使你的生命恢复速度额外提高50%。'),
(572023, '你对冻结目标造成的所有冰霜伤害现在有25%的几率对其触发灵魂冻结。'),
(572029, '野性之爪和地震法术的伤害提高 5%，持续 20 秒，最多叠加 5 层。'),
(572064, '虚空护盾现在可作用于附近额外的一名盟友，但持续时间减少30%。\n击杀可提供经验值或荣誉的对手将移除你身上的心智撕裂。'),
(572103, '选择一个敌人，并在其附近的地面上召唤一个恩佐斯触须，该触须将沉默目标，并每2秒造成（63 + 75% 法术强度）点暗影伤害，持续8 秒。如果目标超出范围，触须将寻找新的目标。\n\n触须的生命值基于你的耐力。如果触须死亡，沉默效果将结束。\n\n你同时只能激活1个上古之神触须。'),
(572116, '血棘术从所有小队和团队成员身上长出，持续30 分钟，击中时对攻击者造成（22 + 3.5% 暗影法术强度）点暗影伤害。\n\n每半秒只能触发一次。'),
(572127, '标记为6 秒。来自时光魔杖的伤害提高30%。\n\n你可以使用时光魔杖消耗此减益效果，根据当前激活的连续体法术获得额外效果。\n\n奇点核心：触发3次奇点核心伤害。\n\n通量发射器：在敌人身上爆炸，对8码内所有敌人造成50%的伤害。\n\n悖论炮：使你在6秒内下一次碎裂回响的伤害提高25%。'),
(572130, '现在你可以在使用寄生后额外疫病蔓延一个目标。'),
(572173, '提高目标对冰霜法术的抗性15点，持续30 分钟。'),
(572177, '提高目标的小队和团队成员对冰霜法术的抗性，持续30 分钟，数值为60。'),
(572178, '向一名敌人发射重型钝头箭矢，使其护甲降低25%，持续5 秒。\n\n每层优势使持续时间增加5秒。'),
(572213, '施放终焉使者现在会将你脚下的地面标记为你的墓地，持续 15 秒。在墓地范围内对敌人造成的直接暴击，额外造成 530 点 + 36% 攻击强度的暗影伤害。'),
(572214, '冰刺从附近盟友和复活的仆从体内喷发，持续30 分钟，使攻击者在命中时受到21点冰霜伤害。'),
(572303, '消耗10点静电安抚一名敌人，移除其1个激怒效果。'),
(572304, '向敌人注入肌体毒素，移除1个激怒效果，每4秒重复一次，持续20 秒。'),
(572305, '将你的血液注入敌人体内以冲击其神经系统，使其攻击强度降低 60，持续 15 秒，并移除 1 个激怒效果。'),
(572306, '净化一名敌人身上的邪恶，移除其所有激怒效果。'),
(572310, '湍流之怒的暴击现在会触发导电。\n\n使风暴之流的伤害提高50%。'),
(572340, '使帷幕行者提供的移动速度提高 25%。'),
(572352, '复述30码范围内小队成员的命运，为他们恢复（90.636 + 41.832% 治疗强度）点生命值。'),
(572357, '使你的魔法伤害提高3%，并且多彩碎片造成的伤害现在会使目标受到的法术伤害提高10%，持续30 秒。'),
(572367, '受到的直接魔法伤害现在有 50% 的几率使你 8 码内所有盟友的所有魔法抗性提高 15，持续 6 秒。'),
(572370, '你的夺颅者现在无视目标 25% 的护甲。'),
(572372, '使你的自动射击造成伤害时，有5%几率额外射出一箭，造成100%远程武器伤害的自然伤害，对中毒目标翻倍。'),
(572378, '2 层充能，15 秒充能时间改变时间的结构，为一个盟友治疗（801.78 + 84.66% 治疗强度）。\n\n你在 8 秒内施放的下一次纪元将无冷却触发。'),
(572384, '祝福一名友方目标，使其攻击强度提高 35，持续 30 分钟。每名目标同一时间只能受到同一位太阳祭司的一种祝祷影响。'),
(572391, '与盟友分享诺兹多姆的智慧，使其智力提高2，持续30 分钟。\n每位时光法师只能激活一个智慧效果。'),
(572396, '向所有小队和团队成员分享诺兹多姆的智慧，使其智力提高31点，持续30 分钟。'),
(572399, '稳定你周围的空气，使所有团队和队伍成员在受到伤害时减少35%的施法或引导时间损失。\n\n同一时间只能激活1个气压法术。'),
(572400, '血魔法灌注目标盟友，使其精神提高17，持续30 分钟。'),
(572404, '血之魔法灌注所有小队和团队成员，使其精神提高40点，持续30 分钟。'),
(572527, '时光之波的冷却时间减少4秒。'),
(572530, '暗影狂怒现在可以额外叠加4次。'),
(572538, '使以太增强的效果提高50%。'),
(572545, '当以太增强激活时，每第4次废料射击现在使你获得天赋卓绝。'),
(572546, '使你的近战急速提高5%，专精提高5点。'),
(572547, '30级被动技能使正义剧变每次触发狂热时获得的效能提高100%。'),
(572548, '使狂热造成的武器伤害提高10%，并使其有5%的几率触发两次。'),
(572582, '50级被动直接火焰伤害现在会对目标施加灼伤效果，持续15 秒。'),
(572626, '使目标受到你的周期性效果伤害提高3%，可叠加5层。'),
(572629, '对友方目标施加赠礼，使其总属性提高10%，持续30 分钟。'),
(572630, '对所有团队和队伍成员施加誓言，使其总属性提高10%，持续30 分钟。'),
(572631, '使一名队伍或团队成员获得短暂喘息，每1秒降低其总威胁值2%，持续10 秒。'),
(572632, '减缓对目标小队成员施放的法术。使所有法术伤害降低5%，所有治疗效果降低5%。持续10 分钟。'),
(572633, '加速对目标队伍成员施放的魔法，使其受到的法术伤害提高最多30点，受到的治疗法术效果提高最多32点。持续10 分钟。'),
(572637, '扰乱对目标队伍成员施放的魔法，使其受到的所有法术伤害降低5%，受到的所有治疗效果降低5%。'),
(572722, '周期性暴击伤害现在有20%的几率在8 秒内获得虚空法球。'),
(572723, '多彩碎片和异常尖刺的暴击伤害根据你的法术暴击等级提高。'),
(572747, '配制一份微效复苏魔精，可立即恢复100点生命值。'),
(572752, '0 秒后，对目标造成（1780 + 130% 法术强度）点圣焰伤害，并灼烧地面，持续 9 秒。区域内的敌人每 3 秒受到太阳烈焰攻击，受到圣光迸发和霍鲁萨斯冲击的伤害提高 15%。'),
(572770, '使你的专精提高10点。'),
(572771, '熔解现实造成的伤害现在还会使目标的主属性降低3%，持续15秒，可叠加5层。'),
(572783, '使腐爪的周期性效果可额外叠加2层，持续时间延长50%，并且每层效果使你忽略目标3%的护甲。'),
(572787, '对友方目标施加法令，使其法术强度提高33点，持续30 分钟。'),
(572790, '以黑暗敕令强化团队和小队成员，使法术强度提高62点，持续30 分钟。'),
(572791, '以克苏恩的疯狂祝福一名盟友，使其法术强度提高37点，持续30 分钟。'),
(572799, '无羁之怒现在使你的受敬先祖的物理伤害提高15%，持续10 秒。'),
(572800, '你现在从伤害中获得的怒气提高20%，且自动攻击暴击会使活化之血、鲜血帷幕和鲜血契约的冷却时间缩短1秒。'),
(572808, '对小队或团队成员施加祝福，每1秒降低其总威胁值2%，持续30 分钟。\n\n同一时间只能对1个目标施放。'),
(572810, '对友方目标施放一种平静而原始的直觉，每5秒恢复5点法力值。\n\n每个仪祭师同时只能对一名玩家施加一种本能效果。'),
(572817, '在所有团队和小队成员中唤起一种本能，每5秒恢复33点法力值。'),
(572836, '从巫医处受到的伤害会储存其数值的15%。当效果结束时，储存的伤害会立即造成。'),
(572855, '需要凡人之躯向一名敌人释放强大的鲜血爆发，造成（1480 + 65% 攻击强度 + 50% 法术强度）点暗影伤害。该技能对处于流血状态的目标必定造成暴击。\n\n延长下一次诅咒形态的持续时间5秒，持续30 秒，最多叠加2层。'),
(572870, '你的破咒现在额外移除一个诅咒效果。'),
(572871, '你的暴击几率提高4%。'),
(572879, '你的技能对被减速的目标造成的伤害提高 10%。'),
(572885, '被赦罪祝福命中的敌人造成的伤害降低 20%，持续 5 秒。圣槌的暴击几率提高 20%。'),
(572889, '造成暴击现在会使你的伤害提高1%，持续8 秒，可叠加10层。'),
(572904, '立即将盟友目标50%的威胁值转移给你。'),
(573028, '用虚空锁链阻碍敌人的行动，使其移动速度降低 30%，持续 10 秒。'),
(573034, '使你受到攻击时有30%的几率获得一层恶魔之火。'),
(573035, '等级30被动使你的力量提高相当于格挡等级50%的数值，并使你的命中等级提高相当于力量8%的数值。'),
(573036, '使你的暴击和命中几率提高3%。'),
(573038, '化为阴魂，进入增强潜行状态 10 秒并踏入冥行。移除所有移动限制效果。'),
(573039, '等级 20 被动：造成直接物理伤害时，有 5% 几率获得灭绝，持续 10 秒。每有 1 个活跃的收割之魂，触发几率提高 10%。'),
(573040, '使鲜血狂乱、收割时刻与收割之地的持续时间翻倍。'),
(573041, '等级 20 被动：使你耐力提高 20%，并使护甲穿透提高自身力量值的 10%。'),
(573042, '号角法术的冷却时间缩短25%。'),
(573043, '使你的远程技能射程提高5码。\n\n此外，你对亡灵、野兽和龙类目标的暴击几率提高2%。'),
(573044, '40级被动技能使蹂躏造成的周期性伤害可以造成暴击。'),
(573047, '使用冲撞造成伤害时，现在会驱散目标身上的1个魔法效果。'),
(573056, '使用号角现在会召唤一只龙鹰协助你战斗，持续15 秒。'),
(573057, '使你的水袋效果提高25%。'),
(573059, '战鹰和龙鹰造成的伤害现在有15%的几率降低敌人18.8542点抗性，并使其受到的法术伤害提高2%，持续30 秒。'),
(573060, '每第5次快速射击会在15 秒内转化为猎鹰打击。\n使用号角会立即将快速射击转化为猎鹰打击。'),
(573066, '50级被动技能你的成功格挡现在有30%的几率造成双倍格挡量的暴击格挡。\n\n每激活一个地狱火小鬼，触发几率提高3%。'),
(573067, '向附近盟友灌注克苏恩的疯狂，使法术强度提高62点，持续30 分钟。'),
(573247, '直接伤害性技能的暴击现在在目标身上激活时额外施加一层追踪强化。'),
(573250, '受到的治疗效果降低40%［拥有狂躁: ,受到的伤害提高25%,］，并且造成伤害时会使你受到（71.25 + 10% 攻击强度 + 50% 暗影法术强度）点暗影伤害。持续5 秒。'),
(573256, '暴击现在为小队和团队成员提供5%的暴击几率，持续8 秒。\n\n不与类似效果叠加。'),
(573283, '激活巨龙祈唤后，在10 秒内，你的下一次诺兹多姆的回响或奈萨里奥之焰变为瞬发。'),
(573299, '召唤2只血虫协助你战斗。血虫会随时间持续流血，存活越久受到的伤害越高。［拥有汇聚活力: \n\n强化：持续时间延长5秒，并额外召唤1个融合体。］［拥有吸血鬼领主: \n\n每层饥渴使持续时间延长0秒。］'),
(573307, '你的枯萎造成的伤害现在对受影响的敌人施加昏睡。'),
(573310, '召唤一只兽栏中的动物之灵来替换你当前的动物之灵。持续10 秒。'),
(573343, '使目标对奥术法术的抗性提高30点，持续30 分钟。'),
(573348, '使目标所在小队及团队中的成员对奥术法术的抗性提高60点，持续30 分钟。'),
(573364, '你的下一次召回动物之灵在10 秒内变为瞬发，且法力值消耗降低50%。'),
(573365, '40级被动你学会兽王的召回和灵魂兽栏。'),
(573426, '你的邪恶狂热的冷却时间减少60秒。'),
(573436, '你对受溺水影响的敌人造成直接暴击时，会召唤一个带电水元素协助你战斗，持续20 秒。\n\n当带电水元素消散时，你的溺水冷却时间减少2秒。'),
(573452, '通过永恒祝福造成的伤害现在会减少圣契法术的冷却时间4秒。'),
(574138, '30级被动技能对敌人施加墓穴瘟疫时，还会额外为你的亡灵仆从添加腐烂血肉效果，每层使其造成的伤害提高2%，持续5秒。'),
(574140, '20级被动技能你的心魔现在在激活时提供10%的闪避几率和暴击伤害加成。'),
(574143, '40级被动当心魔激活时，近战直接技能暴击将返还2点能量。'),
(574145, '50级被动双刃斩和萨格隆惩击现在额外受到你的敏捷加成。\n\n此外，你的暴击自动攻击现在额外造成75%的混乱伤害。'),
(574146, '40级被动技能邪能火球、萨格隆惩击和双刃斩造成的伤害现在额外根据你的敏捷值进行缩放。'),
(574147, '你的治疗强度基于主手武器伤害提高。'),
(574148, '30级被动技能使你的暴击等级提高，相当于智力值的25%。'),
(574149, '暗影斩杀的伤害提高10%，对亡灵额外提高10%。'),
(574153, '30级被动使你的躲闪和暴击等级提高，数值相当于敏捷的15%;命中等级提高，数值相当于敏捷的6%。'),
(574301, '开始驾驭一个动物之魂，20秒后你成功驯服该动物之魂。'),
(574308, '20级被动使你的远程攻击强度相当于精神值的100%，命中等级相当于精神值的5%。'),
(574309, '［拥有工艺师的魔杖: 工艺师的魔杖；否则： 瓦解］的施法时间缩短15%，并使你的瞬发法术法力值消耗降低10%。'),
(574310, '使你永恒施加的效果持续时间延长4秒。');

