INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(574312, '40级被动技能使你的时光韧性、时间迅捷和时光恢复法术的效果提高100%，并使其法力值消耗降低50%。'),
(574313, '地震冲击的伤害提高30%。'),
(574314, '你的最大怒气值提高15点，并降低受到伤害性攻击时的施法退条效果50%。'),
(574318, '20级被动技能当高于40点狂乱时，近战攻击和技能会触发虚空之影。'),
(574321, '30级被动技能施放投掷武器现在有30%的几率重置你的长矛的冷却时间。'),
(574323, '30级被动技能周期性伤害现在有10%的几率重置你的地震技能的冷却时间，并使你在10 秒内的下一次施法不消耗资源。'),
(574326, '地震尖刺命中的目标数量增加4个。'),
(574339, '移除你放置的战旗。'),
(574348, '40级被动技能消耗散落星辰的效果提高40%。'),
(574349, '20级被动你现在获得小行星带。\n\n此外，你的命中等级提高，数值相当于智力的5%，你的精准提高8点。'),
(574350, '你的命中几率和暴击几率提高3%。'),
(574351, '50级被动你受到艾露恩之光的庇护。你吸收造成超过你最大生命值20%伤害的攻击，并将其15%的伤害转化为法力值。'),
(574353, '当敌人生命值高于75%时，你的融面者和腐牙造成的周期性伤害提高30%。'),
(574354, '40级被动技能当枯萎毒素激活时，你的自动攻击现在有10%的几率施加该效果。\n\n此外，你的攻击性暴击现在会使目标受到的法术伤害提高10%，持续15 秒。'),
(574356, '目标小队或团队成员将承受你下一次伤害性攻击造成的威胁值，以及之后4 秒内所有行动产生的威胁值。'),
(575025, '同时放置所有选中的守卫、雕像和神像。'),
(575030, '向附近所有队伍和团队成员释放月井之水，为其恢复（85 + 69.6% 治疗强度）点生命值。\n\n月蚀：无需冷却时间即可触发，并消耗40码内与你战斗中的敌人身上的散落星辰。'),
(575039, '向一名盟友释放一道月井之水，弹射至附近盟友，每次弹射治疗（185 + 87% 治疗强度）点生命值，治疗量随弹射递减10%。总共治疗5个目标。\n\n月蚀：治疗效果和法力值消耗翻倍，并变为瞬发。'),
(575040, '祝福一名友方目标，使其法术强度提高 28，持续 30 分钟。每名目标同一时间只能受到同一位太阳祭司的一种祝祷影响。'),
(575335, '对处于饥渴打击状态的目标，利爪扫击和饥饿打击的暴击几率和暴击伤害提高10%。'),
(575839, '使一名友方玩家的抗性提高 10 点，持续 30 分钟。'),
(575842, '使所有小队和团队成员的抗性提高 20 点，持续 30 分钟。'),
(575843, '召唤风暴之力强化一名盟友玩家，使其所有抗性提高10点，持续30 分钟。'),
(575846, '召唤闪电之力强化团队和小队成员，使其所有抗性提高20点，持续30 分钟。'),
(578120, '50级被动技能腐爪造成的周期性伤害现在有50%更高的几率命中，且你的血牙撕咬、利爪扫击和血箭额外随闪躲等级提高效果。'),
(578126, '使一名友方玩家的力量提高 20 点，持续 30 分钟。'),
(578130, '使所有小队和团队成员的力量提高 77 点，持续 30 分钟。'),
(578255, '你的地震技能和石矛的暴击几率提高10%，持续3 秒。'),
(578295, '瓶中精魂造成的伤害使敌人受到的伤害提高3%，造成的伤害降低3%，持续15 秒。'),
(578299, '30级被动技能引导盐水时，［拥有风暴君主: 电击；否则： 风暴之流］造成的伤害提高15%。'),
(578300, '40级被动你的电刑现在可以在引导风暴之流时使用，并使其施加导电。'),
(578302, '40级被动你的自然法术穿透提高20点，随等级提高。\n\n此外，风暴破击现在会额外驱散1个魔法效果。'),
(578311, '召唤风暴之力强化一名友方玩家，使其智力提高3点，持续30 分钟。\n不与风之召唤叠加。'),
(578316, '召唤风暴之力强化团队和小队成员，智力提高31点，持续30 分钟。'),
(578320, '你的能量和法力恢复速度提高20%。'),
(578344, '用巫毒之力强化一名盟友，使其资源消耗降低5%，持续30 分钟。'),
(578345, '邪能能量疾影你的轮廓，暂时降低所有威胁值，并使你受到的范围法术伤害降低20%，持续6 秒。'),
(581314, '使目标小队成员的自然抗性提高45点，持续10 分钟。'),
(582261, '使所有小队成员的自然抗性提高60点，持续10 分钟。'),
(582307, '每点狂乱现在使你的瞬发法术和技能的法力消耗降低1%。'),
(582308, '使你的伤害吸收效果提高20%。'),
(582310, '20级被动技能你的觅心弩箭现在对生命值低于20%的敌人必定造成暴击，并恢复你最大法力值的10%。'),
(582356, '你的不谐与时间秩序配合使用时，现在必定造成暴击。'),
(582533, '使目标的火焰抗性提高30点，持续30 分钟。'),
(582536, '使目标的小队和团队成员的火焰抗性提高60点，持续30 分钟。'),
(582589, '使幻觉的冷却时间缩短5秒，法力值消耗降低20%。'),
(582591, '与虚空融为一体，使你在6 秒内免于死亡，或直到你受到相当于最大生命值100%的伤害。\n\n效果结束时，你立即恢复相当于生效期间所受伤害50%的生命值。'),
(582832, '近战暴击使急速和治疗提高 5%，最多叠加 3 层，持续 10 秒。'),
(582836, '使帝国之刃的暴击几率提高2%，法力值消耗降低25%。'),
(582855, '50级被动使你每层优势提供的加成提高25%。'),
(582901, '成功格挡现在会对攻击者造成（5% 攻击强度 + 51 × 等级系数）点物理伤害，伤害随防御等级提高。每秒钟只能触发一次。'),
(582933, '你的最大能量值提高15点，并且粉碎和横扫千军的伤害提高10%。'),
(582937, '近战技能暴击后，使你的下一次粉碎在6 秒内无需消耗资源，并造成25%的额外伤害。'),
(583092, '摧毁你激活的结界、图腾和雕像，通过灵魂召回恢复每个被摧毁物品所需法力值的50%。'),
(583245, '当混沌化身激活时，你的熔解现实造成的伤害提高30%，并额外复制20%的伤害此外，周期性伤害现在会使混沌化身的冷却时间缩短1秒。'),
(583248, '你的多彩碎片现在有25%的几率再次触发，且不触发冷却时间。'),
(583403, '穿越时空飞回绑定的旅店。你可以与不同地点的旅店老板交谈，更改你的家所在位置。'),
(592008, '每20秒，你的下一个时光不谐在10 秒内变为瞬发。'),
(600327, '你的近战攻击速度提高25%，并且你的近战自动攻击会为生命值最低的盟友额外恢复相当于伤害100%的生命值。持续15 秒或10次攻击。'),
(602220, '饮用强力巫毒药剂，使你的身体陷入长达5 分钟的死亡般静止状态，让你假死，可能骗过敌人使其忽略你。'),
(620610, '使附近敌人陷入恐惧，降低10码范围内所有敌人的攻击强度35点，持续30 秒。'),
(630868, '激活回春毒素，持续120 分钟，使你的施法有20%的几率治疗目标30码范围内的随机盟友，在6 秒内恢复（9.2% 治疗强度 + 67 × 等级系数）点生命值。\n\n你最多同时拥有2种不同的毒液效果。'),
(630869, '治疗目标30码范围内的一个随机盟友，在6 秒内恢复（9.2% 治疗强度 + 67 × 等级系数）点生命值。'),
(630872, '清除当前激活的毒素。\n\n可在任意形态下使用。'),
(630900, '孵化印记的最大叠加层数增加2层。'),
(630932, '你的纺锤束缚现在拥有2层充能，冷却时间25秒，并造成更高的伤害。'),
(630934, '使用融面者后，你在15 秒内的下一次寡妇制造者造成20%额外伤害，并额外攻击2名附近敌人。'),
(632621, '附魔技能提高15点。'),
(638403, '使你的亡灵仆从的近战急速提高5%，并且它们的近战自动攻击暴击时有50%几率触发骨棒，造成相当于伤害40%的暗影伤害。'),
(645435, '打击敌人［拥有风之符文: 7；否则： 5］次，持续2 秒，每次打击造成（152 × 等级系数）%（对玩家为（121.6 × 等级系数）%）武器伤害的自然伤害，随等级提升。\n\n在打击目标期间，你的躲闪几率提高100%，但你无法使用任何法术或技能。'),
(653022, '将火焰符文铭刻到你的武器上，持续1小时，获得火焰铭刻效果。'),
(653130, '为你的枪械添加一个以太增强效果，持续1小时，使每次射击额外造成（40 × 等级系数 + 15.5% 法术强度）点奥术伤害。\n\n使你对机械类敌人的伤害和暴击几率提高25%，并降低你受到的魔法伤害10%。'),
(653131, '用尖刺强化你的盾牌，使你的格挡对攻击者造成（5.495 + 6% 攻击强度 + 3.75% 耐力）点高威胁物理伤害。持续1小时。'),
(653210, '当此效果结束时，会发生爆炸，每层造成（16 + 7.5% 攻击强度 + 20% 火焰法术强度）点火焰伤害。\n\n重复施加不会刷新其持续时间。'),
(653211, '你的直接伤害有30%的几率对目标施加火印，最多叠加100层。'),
(653213, '将水之符文铭刻到你的武器上，持续1小时，获得水之附魔效果。'),
(653214, '你的直接伤害有30%的几率吸取目标身上的法力值，最多为你最大法力值的2%，为你恢复所吸取的法力值，并根据吸取的法力值造成冰霜伤害。\n\n同时使附近队友获得回能效果。'),
(653218, '将大地符文铭刻到你的武器上，持续1小时，获得大地附魔效果。'),
(653219, '你的直接伤害有15%的几率对目标周围8码范围内的敌人造成（8.75% 攻击强度 + 13 × 等级系数 + 11.5% 自然法术强度）点自然伤害。'),
(653222, '将空气符文铭刻到你的武器上，持续1小时，获得空气附魔效果。'),
(653223, '使你的近战攻击、远程攻击和施法速度提高10%。\n\n你的直接伤害有15%的几率复制30%的伤害。复制的伤害无视护甲。'),
(653234, '为你的枪械添加穿刺强化效果，持续1小时，使每次射击额外造成（11% 远程攻击强度 + 63 × 等级系数）点物理伤害。\n\n使你的攻击无视目标25%的护甲，并为你提供19.75点法术穿透。'),
(653236, '为你的枪械添加一个爆炸强化，持续1小时，使你的远程攻击在目标身上爆炸，对其及附近敌人造成（10% 远程攻击强度 + 6 × 等级系数 + 25% 火焰法术强度）点火焰伤害。\n\n每秒只能触发一次。'),
(653239, '为你的枪添加作战药剂增幅，持续1小时，使你的直接治疗技能可额外治疗最多［拥有修复喷枪: 5；否则： 3］个附近盟友，治疗量为原治疗量的20%。\n\n此效果造成的治疗可以造成暴击。'),
(653242, '为你的枪添加一个魔法增幅，持续1小时，使每次射击额外造成（2 + 4.5% 远程攻击强度 + 10% 法术强度）点魔法伤害。\n\n使你的远程技能射程提高5码。'),
(653245, '为你的枪械添加追踪强化，持续1小时，使你的远程攻击标记敌人，持续5 秒，最多叠加5层。持续时间结束后，标记会爆炸造成（8% 远程攻击强度 + 80 × 等级系数 + 15% 火焰法术强度）点火焰伤害，伤害随叠加层数提高。\n\n被标记的敌人在20 秒内无法进入潜行或隐身状态。\n\n重复使用不会刷新持续时间。'),
(653254, '你的目标无法造成暴击，并且其总主属性降低5%，持续8 秒。'),
(653264, '将冰霜符文铭刻到你的武器上，持续1小时，获得冰霜铭刻效果。'),
(653265, '将一道奥术符文铭刻到你的武器上，持续1小时，获得奥术铭刻。'),
(653266, '你的直接伤害有40%的几率造成（16.8 + 24% 攻击强度 + 36% 法术强度）点冰霜伤害，并使目标的移动速度降低50%，持续8 秒。\n\n每次触发会叠加一层冰缚动能。'),
(653267, '你的直接伤害有40%的几率造成（54.3 + 5% 攻击强度 + 30% 法术强度）点奥术伤害，并标记目标，持续5 秒。\n\n该标记会储存受到的有效治疗量。当其自然消失时，会释放奥术伤害，数值相当于储存治疗量的30%。\n\n此效果每5秒最多触发一次。'),
(653273, '你的下一次废料射击射程提高5码，伤害提高15%，并吸取目标（8 + 10% 远程攻击强度）点法力值。持续10 秒。'),
(653277, '用重型合金强化你的盾牌，使你的攻击强度提高10%，但攻击速度降低10%。持续1小时。'),
(653278, '用魔法强化你的盾牌，使你在生命值低于75%时格挡攻击可获得25%额外格挡值，持续5 秒。'),
(653279, '用利刃边缘强化你的盾牌，使你的暴击伤害提高10%，并且你的格挡有30%几率确保你的下一次攻击必定暴击。持续1小时。每5秒只能触发一次。'),
(653280, '以奥术合金强化你的盾牌，使你受到的魔法伤害降低5%，范围攻击造成的额外魔法伤害降低5%，并使你被法术命中的几率降低3%。持续1小时。'),
(654545, '放逐目标敌对元素生物，最多持续40 秒（对玩家为8秒），使其免疫所有物理伤害。同一时间只能放逐一个目标。'),
(674303, '在你附近放置一个哨兵守卫，持续1 分钟，揭示附近所有潜行和隐形敌人。'),
(675204, '显示目标位置10码内所有潜行和隐形的敌人。持续15 秒。'),
(680196, '发射一道远程闪电，为一名盟友恢复（254 + 150% 治疗强度）点生命值。\n\n随修复射击的修正效果提升。'),
(680199, '刺穿现在会在3秒内为你恢复造成伤害的50%，并叠加一层饱餐，持续30 秒。\n\n达到3层时，你的下一个［拥有硫磺重击: 硫磺重击；否则： 斩断］将消耗这些层数，从5码内最多5个敌人身上额外吸取造成伤害的200%。\n\n此外，［拥有硫磺重击: 硫磺重击；否则： 斩断］现在会在1秒后额外造成一次打击，但冷却时间增加［拥有硫磺重击: 12秒；否则： 2］。'),
(680200, '粘性炸弹爆炸和机甲技能的伤害提高15%。'),
(680212, '你的守望者之刃现在会向目标额外发射2把飞刃，造成（47 + 24.5% 法术强度）点法术打击伤害。'),
(680215, '使用流星后，你的下一次星界打击、碎星斩或自动攻击将结束该效果，造成（5% 攻击强度 + 450 × 等级系数 + 28.75% 法术强度）点奥术伤害，伤害基于移动距离提高。'),
(680216, '施放释放瘟疫现在会移除你身上的所有移动限制效果。'),
(680223, '降低女猎手射击和强击的法力消耗，并使其造成的伤害提高15%。'),
(680233, '20级被动技能使你的暴击等级提高，相当于智力值的12%，并使你的精准等级提高，相当于智力值的10%。'),
(680236, '从你的火枪中爆发出一股暗影能量，击中你面前的敌人，造成57点暗影伤害，并将所有受影响的目标击退。'),
(680238, '在地上放置一个黑暗陷阱，持续30 秒。陷阱会诅咒第一个靠近的敌人及其3码范围内最多5个敌人，使其昏迷4 秒，并在8 秒内造成（44.5 + 136% 攻击强度）点暗影伤害。'),
(680247, '六连射击的伤害提高25%，并使其引导速度加快0.5秒。'),
(680253, '你的陷阱持续时间延长50%。'),
(680255, '你和你的暗影猎犬以暗影伤害造成的暴击伤害提高 50%，但你的法术和技能的消耗提高 10%。\\r\\n\\r\\n此外，你的快速拔枪现在必定暴击。'),
(680275, '远程自动攻击额外造成（57 + 15% 攻击强度）点暗影伤害。'),
(680276, '持续4 秒，你的近战自动攻击额外造成70%的自然伤害，并使目标受到的治疗效果降低20%，持续8 秒，最多叠加2层。\n\n持续时间因每层优势增加4秒。\n\n可在隐匿状态下使用。'),
(680280, '宣告附近所有盟友为荣耀之身，使其力量提高77点，持续30 分钟。'),
(680282, '使你的护甲提高60点，法术急速提高3%。持续30 分钟。\n\n 同一时间只能激活1个圣盾。'),
(680283, '你的生命之力提高1点。'),
(680286, '以黑暗敕令强化团队和队伍成员，使其耐力提高54点，持续30 分钟。'),
(680291, '以魔法之风强化队伍和团队成员，每5秒恢复33点法力值，持续30 分钟。'),
(680294, '强化队伍和团队成员的专注力，使其近战和远程攻击强度提高232点，持续30 分钟。'),
(680298, '使所有友方目标的耐力提高 54 点，持续 30 分钟。'),
(680299, '与附近所有盟友建立血契，使其耐力提高54点，持续30 分钟。'),
(680300, '以寇尔萨兹的力量标记附近的小队和团队成员，使其力量提高77点，火焰抗性提高60点，持续30 分钟。'),
(680301, '以银河活力强化你的盟友，使其智力提高31点，持续30 分钟。'),
(680302, '以持久之怒咆哮，使附近盟友的耐力提高20点，持续30 分钟。'),
(680303, '向所有队伍和团队成员宣告骑士法令，使其敏捷提高77点。'),
(680306, '对所有团队和队伍成员施加誓言，使其敏捷提高77点，持续30 分钟。'),
(680307, '强化附近的队伍和团队成员，使其精神提高40点，持续30 分钟。'),
(680308, '以恶魔能量强化队伍和团队成员，使其敏捷提高77点，持续30 分钟。'),
(680310, '在所有团队和队伍成员中唤起本能，使其攻击强度提高232点，持续30 分钟。'),
(680312, '给盟友注入蜘蛛信息素，使其敏捷提高77点，持续30 分钟。\n\n可在任意形态下使用。'),
(680315, '激活团队和队伍成员的能源模块，使攻击强度提高232，持续30 分钟。\n\n每个工匠只能激活一个模块。'),
(680316, '提高你的暴击几率，并降低你被暴击的几率，持续5%。持续30 分钟。\n\n 同一时间只能激活1个庇护。'),
(680322, '诅咒对亡灵和恶魔的暴击几率提高25%。'),
(680323, '你的猎巫现在会在缩短 1 秒的时间内造成全部伤害。'),
(680326, '你的远程物理暴击伤害提高25%。'),
(680331, '觅心弩箭的暴击几率提高20%。'),
(680334, '使你的法术强度提高，相当于智力值的10%，并使你的自然抗性和冰霜抗性提高23点。持续30 分钟。\n\n 同一时间只能激活1个庇护。'),
(680337, '进入强化形态，持续 15 秒，生成 30 点符文能量，并使你的护甲与招架几率提高 30%。'),
(680373, '受到物理伤害时，你会恢复相当于伤害值10%的生命值。每1秒只能触发一次。'),
(680377, '你的裂隙现在保证你的下一次暮光之锤必定造成暴击。'),
(680378, '立即获得5层烈焰施法，然后用魔法火焰强化附近所有盟友，使其移动速度提高30%，持续15 秒。\n\n在余烬之心效果影响下，盟友造成的直接伤害额外造成（119 × 等级系数 + 35% 火焰法术强度）点火焰伤害。'),
(680384, '暗影射击的伤害提高10%，猎巫的伤害提高5%。'),
(680387, '用岩浆灌注你的皮肤，使你的护甲值提高相当于智力200%的数值，并使受到的近战和远程伤害对攻击者造成（2 + 5% 法术强度）点火焰伤害，同时产生热量。持续30 分钟。\n\n同一时间只能激活1种皮肤。'),
(680388, '对自己和你的亡灵仆从激活一个腐臭结界，持续30 分钟。\n\n激活期间，你造成的伤害的30%会治疗你和你的仆从，均分给它们，且受到的治疗效果提高10%。\n\n同时只能激活1个守卫。'),
(680389, '以时空魔法环绕自身，持续30 分钟，使你的护甲值提高50。\n\n激活时，若敌人击中你，其攻击间隔将提高20%，持续5 秒。'),
(680390, '用青铜魔法环绕自身，持续30 分钟，使你的法术急速提高相当于精神10%的数值，并使作用于你的魔法法术的持续时间缩短25%。'),
(680395, '10级被动自动攻击现在有20%的几率使你获得余震。'),
(680399, '祝福的治疗效果提高15%，并使其额外驱散1个中毒和疾病效果。'),
(680404, '你的耐力提高5%，并使大地之怒可额外叠加1层。'),
(680405, '山岳之锤的伤害提高50%。'),
(680406, '40级被动技能当获得5层大地之怒时，现在会触发山岳呼唤。'),
(680408, '岩石屏障提供的护甲提高50%，并在持续期间使你的法术和技能消耗降低25%。'),
(680409, '猛击的触发几率提高3%，你的武器技能提高5点。'),
(680410, '自动攻击现在使山岳之锤和原初奔袭的冷却时间缩短1秒。'),
(680412, '晶石弹幕或晶核造成的伤害现在会产生更高的威胁值，并有15%的几率为一个激活的岩石屏障增加1层充能，并使其持续时间延长1秒。'),
(680413, '从地震冲击获得的怒气值提高 5，从地震尖刺获得的怒气值提高 2。'),
(680415, '龟之祝福和大地之怒的效果提高50%。'),
(680419, '施放野性之爪和地震技能时，现在有25%的几率刷新一层震击的充能。'),
(680421, '化身大地之灵，使你的伤害提高15%，受到的伤害降低15%，近战急速提高20%，持续20 秒。\n\n持续期间免疫昏迷、定身和减速效果。\n\n可在昏迷时使用。'),
(680424, '将大地化身的效果提高 100%。'),
(680439, '每层大地塑形现在使你的暴击伤害提高 5%。'),
(680441, '强化你的部分技能，并使你的法术急速提高1%，持续20 秒，最多可叠加15层。\n\n额外施加不会刷新持续时间。'),
(680442, '向敌人发出一道地震波，造成（70 + 60% 自然法术强度）点物理伤害，并在24 秒内额外造成568点伤害。伤害起初较慢，随后逐渐提高。\n\n造成的伤害产生1点怒气。\n\n产生2层大地塑形。\n\n与其它地震法术共用冷却时间。'),
(680444, '产生大地塑形或施放碎石现在有 10% 的几率重置你的地震技能的冷却时间。'),
(680446, '使巨石冲刺提供的移动速度提高 30%。'),
(680448, '向敌人投掷一块锋利的石头，造成（57 + 10% 攻击强度 + 100% 自然法术强度）点物理伤害。\n\n每层大地塑形额外造成 5% 点伤害。'),
(680451, '你的物理或自然伤害暴击现在额外造成相当于伤害20%的火焰伤害，作用于目标和附近敌人。'),
(680452, '在拥有10层或以上大地塑形时产生该效果，现在会获得梦境。'),
(680453, '使你的地质法术射程提高10%，并使地震法术射程提高8码。'),
(680456, '以恢复魔法环绕自身，持续30 分钟，使你在战斗中保持25%的法力恢复速度，并使你的法力恢复速度提高相当于精神25%的数值。'),
(680469, '在隐匿状态下，每 2 秒获得一层精湛箭术。'),
(680470, '消耗优势现在有20%的几率，每消耗一点优势返还20点集中值。'),
(680471, '你的下一次精准射击在10 秒内造成的伤害提高10%，最多叠加5层。'),
(680472, '使你的招架几率提高5%，受到的伤害降低5%，造成的伤害提高5%。'),
(680476, '使所有小队和团队成员的法术急速提高3%。不与类似效果叠加。\n\n此外，使你的法术急速提高5%。'),
(680487, '你的虚空化身的冷却时间减少 90 秒，持续时间延长 5 秒。'),
(680491, '饮下一瓶黑暗药剂，为你恢复（104 + 600% 耐力）点生命值，效果受你的耐力加成［拥有亡灵使者: ，使你的闪避几率提高0%］，并使你的最大生命值提高30%，持续10 秒。\n\n每次只能激活1种药剂。'),
(680492, '原本会杀死你的攻击现在会为你恢复50%的最大生命值，并使夜刃的伤害提高50%，持续6 秒。\n\n每2分钟只能触发一次。'),
(680494, '爆发黑暗能量，对最多10名附近敌人造成（51 + 20% 攻击强度 + 50% 暗影法术强度）点暗影伤害［拥有暗影教团: ，施加暗影烙印，］并为你恢复20%的最大生命值。\n\n每个被击中的目标在6 秒内必定会miss下一次伤害。'),
(680496, '黎明之刃造成的伤害根据目标身上的剑柄猛击层数每层提高10%。'),
(680497, '50级被动通过闪避伤害或自动攻击造成伤害现在有40%的几率使你获得黎明骑士。'),
(680498, '诅咒一个敌人，每（84 + 14.6% 攻击强度 + 19.2% 暗影法术强度）秒造成（84 + 14.6% 攻击强度 + 19.2% 暗影法术强度）点暗影伤害，并为你施加黑暗誓言，使你受到的所有伤害降低20%，持续8 秒。\n\n在8 秒内，你的下一次亵渎将恢复你最大生命值和法力值的15%。'),
(680500, '使你的暮光之锤和邪异震击的暴击伤害提高25%。'),
(680503, '使暗影烙印和黎明之刃的伤害提高 20%，并使你的命中等级提高相当于敏捷 3% 的数值。'),
(680504, '当生命值低于 75% 时，黎明之刃现在使夜刃的暴击几率提高 40%，持续 10 秒。'),
(680508, '使你造成的魔法伤害提高3%，且暮光之锤使目标受到的法术伤害在15 秒内提高10%。'),
(680513, '饮用滋补剂会将你的黎明之刃转化为强大的伤害法术，并根据最后消耗的滋补剂为 30 秒提供独特效果。\n\n与圣水补剂不兼容。'),
(680515, '用剑柄猛击一个敌人，造成高威胁武器伤害外加 11，并使其受到的法术伤害提高 2%，持续 30 秒，可叠加 5 层。'),
(680516, '直接技能伤害现在会对敌人施加暗影烙印。'),
(680517, '标记目标，持续 12 秒，在 12 秒内造成 28 点高威胁暗影伤害。'),
(680518, '亵渎你面前最多8个敌人，造成武器伤害外加29点暗影伤害，穿透抗性。\n\n仅在躲避攻击后可使用。'),
(680521, '将所有附近的敌人拉向你，造成（50 + 15% 攻击强度 + 55% 暗影法术强度）点暗影伤害并嘲讽它们，持续 3 秒。'),
(680523, '使防御打击不再消耗怒气，并使黑王进军造成的伤害提高25%。'),
(680525, '使你的锁甲护甲提供的护甲值提高100%。'),
(680528, '黎明之刃造成的伤害现在每 1 秒额外造成相当于该伤害 20% 的暮光伤害，持续 3 秒。'),
(680529, '使你的物理伤害和招架几率提高 3%。'),
(680530, '黎明之刃造成的伤害现在使你的生命值提高相当于该伤害 15% 的数值，持续 8 秒，可叠加 3 层。'),
(680535, '激活黑暗光环，使你的耐力提高5%，并使所有小队和团队成员的暗影抗性提高45点。不与类似效果叠加。'),
(680537, '将木桩刺入一名受伤敌人的胸口，造成（279 + 67.5% 攻击强度）点物理伤害，忽略敌人护甲。\n\n获得罪孽之火，并使其持续时间延长3秒。\n\n仅对生命值低于35%的敌人使用。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (680538, 680540, 680542, 680544, 680555, 680557, 680558, 680569, 680570, 680574, 680576, 680579, 680581, 680599, 680600, 680607, 680609, 680611, 680618, 680619, 680620, 680621, 680622, 680624, 680630, 680631, 680634, 680637, 680641, 680643, 680645, 680646, 680647, 680648, 680650, 680652, 680656, 680657, 680661, 680663, 680670, 680675, 680679, 680680, 680684, 680685, 680692, 680695, 680696, 680700, 680703, 680704, 680705, 680708, 680709, 680711, 680716, 680723, 680725, 680730, 680731, 680732, 680733, 680737, 680738, 680742, 680745, 680748, 680750, 680755, 680763, 680767, 680768, 680770, 680771, 680773, 680774, 680775, 680777, 680779, 680784, 680786, 680788, 680789, 680791, 680794, 680797, 680800, 680801, 680805, 680808, 680809, 680810, 680812, 680813, 680820, 680821, 680822, 680823, 680828, 680836, 680845, 680862, 680871, 680872, 680882, 680891, 680900, 680918, 680931, 680936, 680946, 680953, 680959, 680964, 680970, 680971, 680975, 680977, 680991, 680995, 680996, 681001, 681003, 681007, 681009, 681026, 681047, 681048, 681052, 681054, 681056, 681057, 681059, 681060, 681063, 681064, 681066, 681077, 681078, 681087, 681088, 681092, 681093, 681095, 681097, 681098, 681100, 681102, 681104, 681106, 681107, 681110, 681119, 681130, 681145, 681152, 681156, 681169, 681173, 681180, 681190, 681196, 681199, 681200, 681222, 681235, 681242, 681251, 681252, 681253, 681281, 681292, 681304, 681306, 681307, 681314, 681315, 681320, 681326, 681327, 681328, 681329, 681330, 681334, 681336, 681337, 681340, 681341, 681358, 681363, 681364, 681376, 681389, 681390, 681403, 681407, 681411, 681425, 681427);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(680538, '黄昏之刃造成的伤害现在有 15% 的几率使你的下一次净化者之刃的法力消耗降低 100%。此效果有 25% 的几率不会被净化者之刃消耗。'),
(680540, '40级被动施放净化者之刃或烈焰审判后，可以在 8 秒内使用木桩，无论目标的生命值百分比如何。'),
(680542, '使下一次通过罪孽之火获得火炬之光的攻击数量提高 5。'),
(680544, '主手自动攻击现在会对目标施加一层纯洁，使你对其造成的火焰和神圣伤害提高2%，最多叠加6层。\n\n副手自动攻击现在会对目标施加一层邪恶，使你对其造成的暗影和物理伤害提高2%，最多叠加6层。\n\n火炬之光现在可以消耗这些层数，对目标造成（1028 + 45% 攻击强度 + 25% 神圣法术强度）点圣焰或暗影打击伤害。'),
(680555, '使你的格挡值提高25%。\n\n当高于60点狂乱时，该效果数值翻倍。'),
(680557, '40级被动无畏现在褪去你的凡人之躯，将你转化为虚空怪物，使你受到的伤害降低10%'),
(680558, '使你的格挡几率提高 5%，当狂乱值高于 40 时额外提高 10%。'),
(680569, '每拥有 0 点护甲值，你的攻击强度提高 2 点。'),
(680570, '使你的格挡几率提高10%，并且施放深渊护盾现在会使你的暴击格挡几率提高100%，持续10 秒。'),
(680574, '你的成功格挡现在有 20% 的几率造成双倍格挡量的暴击格挡。\n\n在高于60点狂乱时，该效果翻倍。'),
(680576, '产生30点狂乱值释放一道力量波，对你前方敌人造成（631 + 12.5% 攻击强度 + 76.255% 法术强度）点暗影伤害，并使其移动速度降低30%，持续10 秒。'),
(680579, '根据你的招架和躲闪等级提高你的暴击等级。\n\n此外，暴击现在会使恐惧冲锋和无畏的冷却时间缩短2秒。'),
(680581, '使用暮光盾牌投掷造成伤害现在为你恢复相当于该伤害 10% 的生命值。'),
(680599, '你的直接物理暴击现在为盟友恢复回能。\n\n此外，黎明之刃现在对亡灵或恶魔必定暴击。'),
(680600, '使暮光之锤和熵能猛击的伤害提高25%，并使其产生大量威胁值。'),
(680607, '你的暮光盾牌投掷现在每拥有20点狂乱就会额外击中一个敌人。'),
(680609, '帝国之刃和熵能猛击造成的伤害现在会根据你的防御等级提高。'),
(680611, '使你的暗影暴击几率和暗影伤害提高 4%，并使你的武器技能提高 5。'),
(680618, '对生命值高于 80% 的敌人，神圣法术与技能的暴击几率提高 50%。'),
(680619, '太阳热忱的叠加上限额外提高 3 层。'),
(680620, '女武神的召唤的暴击几率提高 50%。'),
(680621, '向 8 码内释放强大圣光，对附近所有敌人造成（93 + 5.0575% 攻击强度 + 50% 神圣法术强度）点神圣伤害。每命中一名敌人，太阳祈愿的冷却时间缩短 1 秒。对亡灵与恶魔必定暴击。'),
(680622, '履行誓言时，太阳猛击的伤害提高 10%，持续 1 分钟，可叠加 5 层。'),
(680624, '积累你对目标造成伤害的 25%，在 8 秒后释放，对 10 码内的敌人造成神圣伤害。'),
(680630, '激活太阳坠饰，刷新黎明的持续时间与全部次数。'),
(680631, '暴击几率与招架几率提高 2%，法术命中几率提高 5%。'),
(680634, '圣槌的效果提高 25%。'),
(680637, '天选者的吸收护盾耗尽时爆炸，造成（25% 攻击强度 + 80 × 等级系数 + 45% 神圣法术强度）点神圣伤害，由 8 码内的敌人分摊。'),
(680641, '圣槌或黎明之盾暴击后，20 秒内下一次圣光照耀的治疗提高 15%，最多叠加 3 层。消耗层数后，精确格挡几率和移动速度提高 10%，持续 8 秒。'),
(680643, '近战攻击速度提高 15%，且对每个目标的第一次自动攻击会命中两次。'),
(680645, '圣槌的暴击伤害提高 15%，且对亡灵必定暴击。'),
(680646, '诵读希望卷轴，使 15 码内的小队和团队成员受到的魔法伤害降低 30%，持续 10 秒。期间，盟友的生命值低于 35% 时会立即恢复 15% 最大生命值，每名盟友仅触发一次。'),
(680647, '黎明之盾的暴击几率提高 10%，炽天使壁垒可额外格挡 2 次攻击。'),
(680648, '消耗天使降临时，暴击几率与治疗提高 1%，持续 20 秒，最多叠加 10 层。再次叠加不会刷新持续时间。'),
(680650, '躲闪几率提高 5%。'),
(680652, '板甲提供的护甲提高 10%，受到的暗影伤害降低 3%。'),
(680656, '等级 30 被动：霍鲁萨斯冲击额外造成随攻击强度提高的伤害，并使盟友获得回能。'),
(680657, '你的血色谵妄现在造成的伤害提高100%。'),
(680661, '移除诅咒形态的生命值消耗，并且进入该形态现在会立即恢复你最大生命值的15%。'),
(680663, '避免受到一次攻击时，有 25% 几率恢复 5% 基础法力值。'),
(680670, '格挡几率提高 5%，减速效果的持续时间缩短 20%。'),
(680675, '对生命值高于75%或低于35%的敌人，提升需要诅咒形态的技能暴击几率20%。\n\n此外，近战暴击现在有50%的几率使你的下一次黑暗祭礼或血月冲击变为瞬发。'),
(680679, '散发一道光环，持续 15 秒，使盟友在造成直接伤害时额外造成（60% 暗影法术强度）点暗影伤害。\n\n施加力竭，使你在 1 分钟内无法从类似效果中获益。'),
(680680, '在目标区域释放血疫，积累你对受影响敌人造成的30%伤害，持续10 秒，然后爆炸造成等量的暗影伤害。\n\n此技能造成的伤害无法造成暴击。'),
(680684, '你的暴击现在使所有小队和团队成员获得 5% 的暴击几率，持续 10 秒。\n\n不与类似效果叠加。'),
(680685, '使利爪扫击、鲜血爆裂、饥渴打击和血月冲击的伤害提高20%。'),
(680692, '进入一种独特的诅咒形态，该形态不会禁用凡人形态的技能，并凝聚出一颗血球漂浮在你身旁。\n\n激活时，每1秒，你将对目标复制鲜血愈合和血月冲击造成的20%治疗或伤害，持续3 秒。\n\n处于诅咒形态时，你将被视为恶魔。'),
(680695, '周期性伤害和治疗效果现在有50%几率使吸血鬼之吻的冷却时间缩短1秒。'),
(680696, '你造成的伤害根据每层汇聚活力提高1%。'),
(680700, '移动速度提高 150%，持续 2 秒，并移除减速和定身效果。'),
(680703, '［拥有刺穿黑夜: 每次命中施加2层散落星辰；否则： 每次命中施加1层散落星辰］\n向附近敌人释放暗藏利刃，造成（10 + 3% 最大法力值 + 30% 法术强度）点奥术伤害，伤害随最大法力值提高。\n\n消耗一层散落星辰可使刀扇的剩余冷却时间减少2秒。'),
(680704, '消耗散落星辰挥砍一名敌人，对其及附近敌人造成（97 + 20% 攻击强度 + 63.5% 奥术法术强度）点奥术伤害。每额外击中一个敌人，伤害降低20%。'),
(680705, '向一名敌人释放正义锁链，将其与你束缚8 秒。\n\n若锁链因持续时间结束或目标与你相距至少10码而断裂，目标将被拉回你身边，并受到（81.2 + 120% 奥术法术强度）点奥术伤害。'),
(680708, '你的刀扇现在会对每个命中的敌人额外施加一层散落星辰。'),
(680709, '使所有小队和团队成员暴击几率提高3%。\n\n不与类似效果叠加。'),
(680711, '刀扇现在会标记敌人，使其带有复仇效果，持续10 秒。成功标记敌人会使你的下一次星界之刃射程提高25码。\n\n对带有标记的敌人施放星界之刃时，其造成的伤害提高30%。'),
(680716, '你的吸血鬼之牙现在会为你额外恢复相当于造成伤害50%的生命值。'),
(680723, '使你的物理攻击暴击伤害提高10%，并使血肉之钩、恶意锁链和锁链鞭挞的范围提高5码。'),
(680725, '10级被动碎星斩造成暴击时，现在会额外叠加一层散落星辰。'),
(680730, '使血肉塑造的冷却时间和满足减益效果的持续时间缩短60秒。'),
(680731, '你的吸血鬼之吻现在恢复20%的最大怒气值。'),
(680732, '施放诅咒形态技能或血箭现在会每1.5秒为受到血祭仪式影响的盟友恢复（32 + 10% 治疗强度）点生命值，持续3 秒。'),
(680733, '你的萨莱茵挽歌造成的伤害现在会对受影响的敌人施加鲜血技艺，使其造成的伤害降低2%，持续5 秒，可叠加4层。'),
(680737, '使守望者之刃的范围提高20码。'),
(680738, '使守望者之刃的冷却时间缩短5秒。'),
(680742, '每当你累计消耗最大法力值的100%，你便恢复最大生命值的4%。'),
(680745, '你的安瑟拉恩的痛楚造成的伤害现在会使被击中的敌人流血，在10 秒内造成（1405 × 等级系数 + 100% 暗影法术强度）点暗影伤害。'),
(680748, '30级被动耐力提高10%，并使你的法术伤害提高攻击强度的25%。'),
(680750, '10级被动达到100点狂乱不再导致完全疯狂。\n\n教你无畏。'),
(680755, '成为月神选民，使所有受到的物理伤害降低60%，并嘲讽8码内的所有敌人，持续10 秒。'),
(680763, '施放毒蛇之牙现在会在目标下方生成一个蘑菇，2秒后爆炸，对附近敌人造成（303 × 等级系数 + 12.5% 法术强度）点自然伤害。'),
(680767, '延长沙德拉香膏和愈合之雾的持续时间，对30码内的所有盟友增加15秒。'),
(680768, '万能溶剂的直接治疗效果现在会将一个激活的沙德拉香膏从主要目标扩散到附近的一名盟友。'),
(680770, '使刀扇的冷却时间缩短5秒。'),
(680771, '使影歌的使命的冷却时间缩短25%，并使守望者之刃的触发几率提高60%。'),
(680773, '通过消耗散落星辰造成的伤害提高10%。'),
(680774, '获得一位女神的祝福，使40码内所有小队或团队成员获得20%的临时最大生命值，持续10 秒。'),
(680775, '使你的奥术暴击伤害提高20%。'),
(680777, '使守望者之相的伤害提高（1% 最大法力值），数值随最大法力值提高。'),
(680779, '使碎星斩和月焰的伤害提高20%。'),
(680784, '使你的攻击速度提高30%，并使近战攻击的暴击施加一层散落星辰。'),
(680786, '使你受到的伤害降低，降低量相当于你最大法力值的1.5%。'),
(680788, '群星之相造成的伤害现在额外击中2个附近的敌人。'),
(680789, '当生命值低于35%时，你受到的伤害降低10%。'),
(680791, '使你的月刃和星辰横扫的伤害提高50%，暴击几率提高20%。'),
(680794, '使所有毒素的触发几率提高10%。'),
(680797, '回春毒素现在会影响额外1名附近的盟友。'),
(680800, '10级被动毒蛇之牙造成的治疗现在会对盟友施加沙德拉的守护。'),
(680801, '使星火射击的施法时间缩短0.5秒。\n\n使你在施放远程技能时因受到伤害而造成的施法推迟降低75%。'),
(680805, '艾露恩祷言额外获得你治疗加成效果的20%。'),
(680808, '使你的还童术的施法时间缩短0.25秒，法力值消耗降低15%。'),
(680809, '30级被动技能月蚀效果现在使月井喷涌影响3个目标。'),
(680810, '使唤星术的冷却时间缩短50%。'),
(680812, '宇宙迁跃现在会驱散目标身上的所有有害效果，且冷却时间缩短 60 秒。'),
(680813, '使强击的伤害提高25%。'),
(680820, '使月井喷涌的施法时间缩短0.3秒。'),
(680821, '月井喷涌的施法时间降低25%，持续8 秒，最多可叠加4层。\n\n在此效果激活期间，月井喷涌可在移动时施放。\n\n月蚀激活期间不会移除层数。'),
(680822, '变身为复仇化身，传送至你的目标处，并使你的智力提高25%，持续30 秒。\n\n在持续期间，星界之刃的射程提高30码，并会将你传送至目标处。\n\n如果目标是敌人，你对其发动攻击，每1秒造成（54 + 22% 智力 + 6.5% 奥术法术强度）点奥术伤害，持续8 秒，伤害随智力提高。'),
(680823, '你的周期性伤害和治疗现在有10%的几率获得一层汇聚活力。'),
(680828, '吟唱邪恶仪式，在8 秒内为最多12名受血祭仪式影响的盟友恢复（1224 + 160% 治疗强度）点生命值，并在8 秒内从10码范围内的敌人身上吸取（1224 + 1600% 治疗强度）点生命值。\n\n激活时，你免疫沉默和打断效果，但无法移动。'),
(680836, '提高你的法术急速4%。'),
(680845, '使时间守卫获得2次额外充能。'),
(680862, '使晶石弹幕、碎石和地震冲击的法术伤害加成提高25%。'),
(680871, '每层蛛魔钉刺现在使你的寡妇制造者和毒牙对目标造成的伤害提高8%。'),
(680872, '以森金之灵灌注所有小队和团队成员，持续30 分钟，使其精神提高40点，魔法抗性提高20点。\n\n每个目标同时只能激活一种巫祝效果。'),
(680882, '使你的命中几率提高5%，并使精魂回收的伤害提高20%。'),
(680891, '你的惩戒现在总是对目标触发天灾克星。'),
(680900, '熔化现在使你目标从克索诺斯之焰和夺颅者受到的伤害提高10%。'),
(680918, '你的空气元素造成的伤害提高3%，持续15 秒，最多可叠加10层。\n\n重复施加不会刷新持续时间。'),
(680931, '锯齿射击和毒性飞镖造成的周期性伤害现在使你在8 秒内下一次精准射击的伤害提高10%，可叠加10层。'),
(680936, '使你的智力和耐力提高5%。'),
(680946, '施放熔解现实后，你在6 秒内的下一次瓦解或逆转伤口变为瞬发，且法力值消耗降低100%。'),
(680953, '获得启迪，使圣约的剩余冷却时间缩短50%。'),
(680959, '使耀焰箭的法术强度加成提高20%。'),
(680964, '你的自动攻击有30%的几率造成100%的武器伤害，并使敌人昏迷1 秒。'),
(680970, '受到陨石迷惑效果影响的目标，从下一次爆炸或熔岩碎片中受到的伤害提高40%。'),
(680971, '使敌方施法速度降低10%，持续20 秒，每次施法后额外降低10%。\n\n叠加层数不会延长法术的持续时间。'),
(680975, '50级被动技能废料射击造成的伤害现在有30%的几率使你的下一次简易炸药在8 秒内转化为无尽齿轮。'),
(680977, '使烈焰施法的层数额外增加1层，并使其持续时间延长5秒。'),
(680991, '使血肉之钩和锁链鞭挞的冷却时间缩短5秒。'),
(680995, '生成收割之魂现在有 10% 几率触发受虐之怒，持续 5 秒。若受虐之怒已生效，则改为将其持续时间延长 3 秒。'),
(680996, '怨灵之刃现在会创造你本人的幽魂分身，持续 12 秒，自动对敌人施放挽歌与群鸦杀戮。'),
(681001, '在机甲内时，受到的所有伤害降低10%，并且使用活体烈焰造成伤害时获得一层烈焰锻造泰坦。'),
(681003, '施放废料射击和机甲技能现在会使触发过载的几率提高 3%，持续 10 秒，最多叠加 10 层。\n\n当过载触发时，所有层数将被消耗。'),
(681007, '选定一名敌人，召唤一个持续20 秒的复制体攻击该敌人，并对其复制其法术。'),
(681009, '使你的最大生命值和能量提高5%。'),
(681026, '消耗汇聚活力现在可治疗30码内最多10个盟友，治疗量为（63.5 + 25% 法术强度 + 50% 精神），受精神和治疗强度加成。'),
(681047, '50级被动技能每8.999秒，你的沙德拉的祷言将恢复目标1%的最大法力值、8点能量或集中值、4点怒气以及4点符文能量。'),
(681048, '使回春毒素的触发几率提高10%。'),
(681052, '在甲虫形态下受到的所有伤害降低3%，并在蜘蛛形态下使你的移动速度提高5%。'),
(681054, '真菌突袭者现在额外召唤2个真菌人。'),
(681056, '在你脚下创造一个法阵，持续10 秒，每1秒对范围内的敌人造成25点自然伤害，并立即在你周围环形长出12个蘑菇。\n\n持续时间结束时，范围内最多15名盟友恢复（300 + 65% 自然法术强度）点生命值。\n\n可在任意形态下使用。'),
(681057, '使腐烂的施法时间降低50%，法力消耗提高50%。'),
(681059, '你的毒蛇之牙现在会击中额外2名附近的敌人。'),
(681060, '每层满溢现在使你受到的伤害降低2%。'),
(681063, '你的猛击现在有30%几率不触发冷却时间。'),
(681064, '神圣暴击几率提高 2%，受到伤害时的施法退条减少 50%。'),
(681066, '太阳祈愿的冷却时间缩短 5 秒。'),
(681077, '在地面上放置一滩血池，立即沉默所有敌人，持续4 秒，并每1秒为盟友恢复（103 + 33% 治疗强度）点生命值，持续4 秒。'),
(681078, '10级被动技能消耗生命值的法术现在会获得一层汇聚活力，最多叠加10层。\n\n凡人形态下消耗怒气的法术会消耗10层汇聚活力，从而获得强化效果。'),
(681087, '暮光盾牌投掷造成的伤害现在产生3点狂乱。'),
(681088, '使虚空护盾吸收的基础值提高100%，并使你的无畏技能忽略受到的所有伤害的25%。\n\n吸收伤害会使你获得相当于吸收值20%的攻击强度，持续8 秒。'),
(681092, '受到的直接魔法伤害现在会治疗你，并为你恢复相当于伤害值3%的法力值。'),
(681093, '你的黑王进军现在使你的护甲值提高15%。'),
(681095, '驱逐你内心的黑暗，在10 秒内对附近敌人造成50点暗影伤害。\n\n每2秒产生5点怒气。'),
(681097, '使剑柄猛击的伤害提高 25%，并且现在会额外攻击附近的一个敌人。'),
(681098, '对受到夜刃影响的敌人，不死之握和暗影烙印的伤害提高20%。'),
(681100, '施放夜刃现在会施加一个护盾，吸收（184 + 10% 攻击强度 + 200% 耐力）点伤害，持续4 秒。'),
(681102, '通过虚空之影提高的暗影伤害额外增加5%。'),
(681104, '释放你内心的虚空之怒，使你的伤害和暴击几率提高25%，并让你在15 秒内免疫昏迷效果。\n\n每0.5秒产生1点狂乱。'),
(681106, '每层狂乱使你的虚空打击的暴击伤害提高1%。'),
(681107, '50级被动使你的攻击强度提高，相当于智力值的100%。'),
(681110, '变身为风暴元素，持续15 秒，使你造成的魔法伤害提高20%，受到的魔法伤害降低50%。\n\n此外，你的伤害性法术现在额外产生10点静电。该效果每秒只能触发一次。'),
(681119, '向一名敌人释放巨大的土球，造成（154 + 130% 自然法术强度）点物理伤害，并使其护甲降低 50%，持续 10 秒。\n\n穿透吸收、偏转和反射效果。\n\n每层大地塑形效果额外造成 10% 的伤害。'),
(681130, '向一名敌人投掷一把锤子［拥有万物皆钉: 和最多0个附近的敌人，］造成（49 + 15.5% 攻击强度 + 35.5% 自然法术强度）点物理伤害，并使其昏迷5 秒。'),
(681145, '每跳产生 ［拥有炽热难当！: 15；否则： 10］ 点热量向前方 5 个友方和敌方目标播撒净化烈焰，在 3 秒内造成或治疗（92 + 59.2% 法术强度）点伤害或治疗量。'),
(681152, '当你受到暗影或奥术暴击时，使巫术护罩的冷却时间缩短10秒。'),
(681156, '你的［拥有追猎: 追猎；否则： 翻越］现在恢复5%的最大法力值。'),
(681169, '使你受到疾病效果持续时间缩短30%。'),
(681173, '40级被动技能当你受到伤害，生命值降至35%或以下时，召唤3只次级暗影猎犬，并重置翻越的冷却时间。\n\n每2分钟只能触发一次。'),
(681180, '你的陷阱技能的冷却时间缩短25%。'),
(681190, '受到的伤害降低30%，持续10 秒。\n\n激活时，若受到的伤害会使你的生命值低于10%，将立即为你恢复最大生命值的30%。该效果每场战斗只能触发一次。'),
(681196, '消耗或产生一个余烬现在有10%的几率使你过热，所有伤害和治疗效果提高10%，持续6秒。'),
(681199, '40级被动技能使你的远程攻击强度提高，相当于智力值的100%，并使你的远程攻击强度和法术强度提高，相当于敏捷值的25%。'),
(681200, '20级被动技能使你的招架等级提高，相当于敏捷的40%，并使你的躲闪等级提高，相当于智力的25%。'),
(681222, '在你附近召唤4个蛇守卫，持续15 秒。\n\n受毒蛇守卫的修正效果影响。'),
(681235, '偷袭一击敌人，造成（35% 攻击强度 + 591 × 等级系数）点物理伤害，并获得5层优势。受突击的加成影响。\n\n在8 秒内，突击的暴击几率提高10%。'),
(681242, '30级被动技能远程攻击现在有10%的几率将恶意妖咒转化为暗影飞刃，持续10 秒。\n\n几率受你的远程暴击等级加成。'),
(681251, '向敌人发射一道大地能量光束，造成（283.2 + 180% 自然法术强度）点物理伤害，产生20点怒气和2层大地塑形［拥有破裂者: ，并使大地涌动的冷却时间缩短4秒］。\n\n受晶石弹幕的加成影响。'),
(681252, '造成直接物理伤害时，太阳圣使的冷却时间缩短 1 秒。太阳圣使和圣光锁链的持续时间延长 5 秒。'),
(681253, '施放太阳祈愿后，圣光照耀额外治疗附近一名盟友，效果为 70%，持续 10 秒。圣光照耀还会使太阳祈愿的冷却时间缩短 1 秒。'),
(681281, '移除精灵之尘的材料消耗，并使其提高目标的潜行侦测能力。'),
(681292, '当与目标距离40码或更远时，精准射击的伤害提高20%。'),
(681304, '将一名敌人困在血球中，使其在原地恐惧，持续4 秒。\n\n在4 秒内重新激活此技能，会立即引爆止血，造成（137 + 43% 攻击强度 + 103% 暗影法术强度）点暗影伤害，并使其受到的治疗效果降低60%，持续10 秒。'),
(681306, '使你的法术穿透提高2点，持续15 秒，最多可叠加15层。\n\n当叠加至15层时，你的伤害技能将灌注火焰之力，立即额外造成相当于伤害值30%的火焰伤害，并击碎你的目标及附近另一名敌人。'),
(681307, '你对这个目标造成的火焰和自然伤害提高2%，持续4 秒，最多叠加5层。'),
(681314, '用龙鳞强化你的皮肤，使你受到的昏迷效果持续时间降低25%，所有抗性提高5点，火焰抗性额外提高10点。持续30 分钟。\n\n同时只能激活1种皮肤效果。'),
(681315, '回春毒素的持续时间延长2秒，其跳数频率提高30%。'),
(681320, '施放草本万用膏会重置毒蛇之牙的冷却时间，并使你在接下来的8 秒内施放的下一次毒蛇之牙不消耗资源。'),
(681326, '当虚空之影激活时，你受到的伤害降低15%。'),
(681327, '使你的近战急速提高15%。'),
(681328, '50级被动技能木桩现在对生命值高于75%的敌人必定造成暴击。'),
(681329, '你的副手自动攻击现在有10%的几率额外攻击2次，并为盟友提供回能。'),
(681330, '等级 20 被动使你的远程暴击等级提高，相当于你智力的10%。\n\n此外，获得法力值不再产生威胁值。'),
(681334, '巨龙之怒造成的伤害现在使你的智力提高3%，持续20 秒，可叠加10层。\n\n消耗一个余烬现在使你的暴击几率提高2%，暴击伤害提高4%，持续20 秒，可叠加5层。'),
(681336, '触发汇聚活力现在还会生成3点怒气。'),
(681337, '等级 50 被动：女武神誓言和圣光誓言的效果翻倍。'),
(681340, '等级 30 被动\\r\n\\r\n现在你每获得 2 点敏捷，便获得 2 点耐力。'),
(681341, '使你的敏捷提高6%。'),
(681358, '你和你的宠物每8秒恢复最大生命值的3%。'),
(681363, '增加岩石屏障的层数上限，提高5层。'),
(681364, '闪避攻击现在使你获得5点怒气，并减少地震技能的冷却时间1 秒。'),
(681376, '造成伤害现在有8%几率使你的伤害提高3%，持续8 秒，最多可叠加3层。'),
(681389, '使虚空之影的持续时间翻倍。'),
(681390, '你在15 秒内的下一次黎明之刃不消耗资源，并造成25%额外伤害。'),
(681403, '在10 秒内累积你、你的队伍或团队成员以及他们的仆从对目标造成的伤害，然后释放累积的伤害作为暗影伤害。'),
(681407, '50级被动技能你的艾露恩之手现在额外获得相当于你治疗加成30%的效果。'),
(681411, '提高火炬之光的伤害100%。'),
(681425, '技能暴击现在召唤一个亚煞极的化身，持续10 秒，它会攻击敌人并为你恢复基础生命值的5%。'),
(681427, '猩红浪潮的每跳现在有10%几率治疗附近一名盟友，治疗量为造成伤害的25%。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (681435, 681436, 681442, 681443, 681444, 681445, 681448, 681449, 681450, 681453, 681455, 681460, 681465, 681473, 681474, 681478, 681494, 681521, 681527, 681529, 681788, 681792, 684330, 684331, 685020, 685028, 685321, 686020, 704096, 704098, 704099, 704101, 704107, 704111, 704115, 704116, 704139, 704149, 704150, 704159, 704163, 704166, 704171, 704175, 704180, 704182, 704185, 704186, 704193, 704197, 704201, 704209, 704211, 704212, 704222, 704235, 704240, 704264, 704273, 704275, 704311, 704312, 704317, 704320, 704322, 704343, 704347, 704355, 704356, 704357, 704360, 704361, 704368, 704370, 704371, 704374, 704378, 704389, 704402, 704413, 704418, 704420, 704421, 704423, 704434, 704449, 704452, 704473, 704475, 704476, 704487, 704488, 704489, 704490, 704495, 704497, 704500, 704503, 704505, 704511, 704512, 704513, 704514, 704515, 704516, 704524, 704525, 704526, 704527, 704528, 704533, 704535, 704539, 704540, 704552, 704556, 704558, 704562, 704563, 704565, 704568, 704579, 704581, 704582, 704585, 704586, 704602, 704603, 704604, 704606, 704607, 704610, 704611, 704612, 704613, 704621, 704623, 704624, 704625, 704626, 704627, 704632, 704633, 704634, 704635, 704636, 704641, 704642, 704644, 704646, 704649, 704652, 704653, 704654, 704659, 704660, 704661, 704662, 704669, 704670, 704676, 704680, 704681, 704682, 704690, 704692, 704701, 704713, 704715, 704717, 704718, 704721, 704723, 704724, 704725, 704729, 704732, 704739, 704740, 704741, 704745, 704755, 704756, 704759, 704764, 704765, 704769, 704771, 704774, 704775, 704776, 704777, 704778, 704783, 704784, 704785, 704786, 704787, 704788, 704789);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(681435, '你的山岳之锤现在最多击中5个敌人。'),
(681436, '太阳祈愿不再消耗法力，施放时还恢复 5% 缺失法力值。'),
(681442, '向所有小队和团队成员宣告一道巫术法令，使其法术强度提高62点。'),
(681443, '使所有小队和团队成员的自然抗性提高0点。\n与同类效果不叠加。'),
(681444, '将血色谵妄的施法时间缩短1秒，但生命值消耗提高100%。'),
(681445, '在地面放置一个持续1 分钟的残酷陷阱，诅咒第一个靠近的敌人，使其沉默，并令其周围5码范围内的所有敌人沉默6 秒。'),
(681448, '女武神的召唤的持续时间延长 1 秒。'),
(681449, '受到暴击伤害现在使你获得1层恶魔之火和5 点怒气。每3秒只能触发一次。'),
(681450, '在地面放置一个持续1 分钟的死亡陷阱，诅咒第一个靠近的敌人，为其标记死亡，使其在1 分钟后受到（600 + 100% 攻击强度）点暗影伤害。'),
(681453, '教你如何使用盾牌，并教你巨盾。'),
(681455, '在地面放置一个持续1 分钟的天灾陷阱，当第一个亡灵或恶魔敌人靠近时爆炸，立即对5码范围内的敌人造成（1600 + 100% 攻击强度 + 200% 法术强度）点神圣伤害。'),
(681460, '对自己和你的亡灵仆从激活一个冰川结界，持续30 分钟。\n\n激活时，最大符文能量和智力提高10%，并且你受到的昏迷效果持续时间减少20%。\n\n同一时间只能激活1个守卫。'),
(681465, '你的迟缓诅咒现在还会使目标受到的治疗效果降低30%。'),
(681473, '使破甲的能量消耗降低15点，并使先祖打击和猛击的伤害提高25%。'),
(681474, '每第5次技能暴击现在会使你的下一次克苏恩凝视变为邪异之力。'),
(681478, '提高原初奔袭的射程3码。'),
(681494, '减少晶石弹幕和碎石的施法时间0.3秒。'),
(681521, '月之箭矢、月流和银溪的暴击几率提高 10%。'),
(681527, '使所有小队和团队成员的自然抗性提高45点，持续30 分钟。\n与同类效果不叠加。'),
(681529, '为你和你的亡灵仆从激活一道白骨护盾，持续 30 分钟。\n\n激活时，护甲提高 50%，耐力提高 10%，并且受到近战和远程伤害会降低攻击者的攻击强度，降低值为 19。\n\n同时只能激活 1 种护盾。'),
(681788, '劈斩一名敌人，造成280%的武器伤害，并使你的急速提高15%，持续10 秒。'),
(681792, '使血箭、血月冲击和猩红浪潮造成的伤害和法术强度加成提高20%。\n\n此外，血箭造成的伤害现在会降低所有抗性18.8542点，并使目标受到的魔法伤害提高2%，持续10 秒。'),
(684330, '诅咒附近所有敌人，每1秒造成（104 + 12% 攻击强度）点暗影伤害，持续8 秒，并使其从你处受到的魔法伤害提高3%。\n\n受巫毒血热影响的敌人在潜行状态下也可被看见。'),
(684331, '施放猩红浪潮现在还会使所有小队和团队成员获得5%的急速，持续15 秒。\n不与类似效果叠加。'),
(685020, '碾压附近敌人，造成（241 + 24% 攻击强度）点暗影伤害并使其昏迷3 秒。'),
(685028, '你周身散发出光环，使小队和团队成员获得390点护甲值。\n不与同类效果叠加。'),
(685321, '双刃斩现在额外造成（30% 攻击强度）点物理伤害，并撕裂敌人，持续12 秒，使你的盟友对其攻击强度提高（19 + 15% 敏捷）。'),
(686020, '吸取8码内10个敌人的生命，造成（279 + 28% 攻击强度）点暗影伤害，并恢复造成伤害90%的生命值。'),
(704096, '你的力量提高5%，专精提高4点。'),
(704098, '当装备双手武器时，你的攻击强度提高10%，每5秒产生3点怒气，并且野性之爪造成的伤害提高25%。'),
(704099, '当熊之祝福激活时，野性之爪将额外攻击一次，造成双持武器伤害的40%。'),
(704101, '以乌索克之力咆哮，使10码内敌人的攻击强度降低32，持续30 秒。'),
(704107, '你的扳手重击现在会对目标施加震荡。'),
(704111, '使你的远程攻击强度提高，相当于智力值的50%。'),
(704115, '在动脉突袭效果结束时，前方10码锥形区域内的所有敌人受到（50% 攻击强度 + 600 × 等级系数）点物理伤害。\n\n此效果对流血目标造成的伤害提高25%。'),
(704116, '用辩护或正义突刺造成暴击时，额外造成50%的物理伤害。'),
(704139, '你现在每1秒获得一层驾驭魔网，持续永久。持续时间结束后，层数重置。'),
(704149, '站立不动每秒使你获得电荷，急速提高1%。达到20层时，你的技能不会消耗静电，持续10 秒，之后层数清零。'),
(704150, '使你的投网射程提高15码。'),
(704159, '向一名敌人投掷盾牌，弹射至最多2名附近敌人，造成（55 + 33% 攻击强度）点物理伤害并打断其施法，阻止该系魔法被施放，持续3 秒。'),
(704163, '20级被动技能你的疾病和地穴虫群现在对生命值低于20%的敌人造成125%的额外伤害。'),
(704166, '在不灭诅咒状态下，你的耐力额外提高10%。'),
(704171, '接下来20 秒内的5次星陨造成递增伤害，每次使用基于10%智力提高，可叠加5次。'),
(704175, '通过定罪获得的暴击几率提高3%，并允许其周期性伤害造成暴击。'),
(704180, '使你的破誓者的能量消耗降低10。'),
(704182, '使你的瘟疫效果提高50%。'),
(704185, '使恶意锁链［拥有硫磺盾卫: 和克索诺斯锁链，］的冷却时间缩短30秒，并允许血肉之钩和锁链鞭挞额外击中主目标附近最多2个敌人。'),
(704186, '使［拥有硫磺重击: 硫磺重击；否则： 斩断］造成的武器伤害提高10%，并且每激活一层恶魔之火，伤害额外提高10%。'),
(704193, '等级 50 被动：每第 6 次施放收割，会使下一次收割变为毁灭横扫，持续 15 秒。'),
(704197, '达到3层时，你的下一次时光魔杖或工艺师的魔杖额外造成（1 + 10% 远程攻击强度 + 21.2% 奥术法术强度 + 25% 精神）点奥术伤害，伤害受精神加成。'),
(704201, '3层充能，35秒充能时间在目标位置召唤一个狂怒之风，持续12 秒。\n\n每4秒，它会将10码范围内的所有敌人拉向自身。'),
(704209, '你的伤害现在会使你的空气元素的急速提高2%，持续10 秒，可叠加5层。\n\n你的空气元素造成的伤害现在会使你的急速提高2%，持续10 秒，可叠加5层。'),
(704211, '使烈风的暴击几率提高15%。'),
(704212, '立即重置你的撤离、乘风和解脱法术的冷却时间。'),
(704222, '将你的漩涡转化为狂怒之风。'),
(704235, '用利爪缴械一名敌人的近战武器，持续5 秒，并对其施加虚弱毒素，持续10秒。'),
(704240, '钢铁风暴造成伤害时，其后续打击的伤害提高4%，可叠加10层。\n\n此外，钢铁风暴的持续时间延长2.5秒。'),
(704264, '将甲虫形态强化为蜘蛛领主，受到的伤害降低5%，并且当虫群风暴激活时，你的召唤物获得30%的急速和伤害加成。\n\n施放虫巢破击和坚甲冲撞现在有40%的几率，近战自动攻击现在有15%的几率，召唤1只圣甲虫协助你作战，持续12 秒。'),
(704273, '余烬之触的有效治疗现在会治疗目标附近最多3名生命值最低的盟友，额外治疗量为治疗量的15%。'),
(704275, '治疗暴击现在会为盟友施加一个吸收护盾，数值相当于治疗量的30%，持续8 秒。'),
(704311, '闪避攻击现在会使你迅速用箭袋中的一支箭刺击敌人，造成（1 + 100% 攻击强度）点物理伤害，并使其攻击速度降低20%，持续8 秒。'),
(704312, '穿颅者和精准射击的伤害提高20%。'),
(704317, '你的敏捷提高5%，并使移动减速效果对你的持续时间缩短20%。'),
(704320, '进入隐匿状态时，每5秒产生1层优势和10点集中值，持续30 秒。'),
(704322, '50级被动技能暴击和击杀现在会为你提供恩惠，持续1 分钟，最多叠加20层。\n\n达到20层时，你的下一次自动攻击造成额外500%武器伤害，并消耗所有层数。'),
(704343, '艾露恩之手获得以下满月和新月效果。\n\n满月：治疗效果提高10%。\n\n新月：消耗降低10%。'),
(704347, '在8 秒内，每2秒对10码内最多10个敌人造成49点自然伤害。'),
(704355, '需要冻结目标向一个冻结的敌人召唤冰霜巨石，造成（142 + 140.5% 冰霜法术强度）点冰霜伤害。［拥有冰川领主: \n\n此法术必定造成暴击。］\n\n伤害随你的暴击等级提高。'),
(704356, '恐惧之潮造成的伤害现在使受难灵魂的冷却时间缩短 1 秒。'),
(704357, '使用幽魂疾步、镰刃冲锋或帷幕行者之后，获得一层护盾，吸收 114 点 + 33% 攻击强度的伤害，持续 6 秒。'),
(704360, '你的［拥有邪能突进: 邪能突进；否则： 混沌冲刺］现在会使你受到的所有伤害降低3%，持续5 秒，可叠加2层。'),
(704361, '你的副手武器伤害提高25%，并且双刃斩的能量消耗降低5点。'),
(704368, '生成 1 点邪怒向敌人释放邪能魔法，在 21 秒内造成 196 点混沌伤害。\n\n心魔：目标每 6 秒受到额外（551 × 等级系数 + 48% 法术强度）点混沌伤害。\n\n同一目标上只能同时存在 1 个灾尸。\n\n此效果造成的周期性伤害可以造成暴击。'),
(704370, '每次混沌灾祸造成伤害时，其对目标的伤害提高1%，持续6 秒，可叠加20层。'),
(704371, '瘫痪一个敌人，使其移动速度和施法速度降低40%，效果在12 秒内逐渐衰减。'),
(704374, '在15 秒内，每第3次双刃斩或邪能火球会额外产生1层邪能之怒。'),
(704378, '使邪能火球的能量消耗和施法时间降低15%。'),
(704389, '使你的灵思的效果提高10%，触发几率提高5%。'),
(704402, '使碎石和晶石弹幕的伤害提高25%，且碎石现在会恢复4%的最大法力值。'),
(704413, '使你的格挡值提高15%，武器技能提高4点。'),
(704418, '猛击一个敌人及其身后直线范围内的敌人，造成（140 + 100% 攻击强度）点高威胁物理伤害，并使其沉默3.5 秒。'),
(704420, '吟唱一首优美的歌曲，立即重置解放、悲恸旋律和英雄行军的冷却时间。'),
(704421, '使粉碎、冲撞和横扫千军的能量消耗降低15%。'),
(704423, '使你的攻击强度和总护甲值提高4%。'),
(704434, '使所有小队和团队成员受到的伤害降低3%。\n\n此外，你受到的神圣伤害降低10%。'),
(704449, '简易炸药现在标记敌人，持续6 秒。\n\n你的宠物对该目标使用的下一个伤害技能会消耗标记，造成（71.33 + 20% 远程攻击强度 + 20% 火焰法术强度）点火焰伤害。'),
(704452, '在拥有6层克索诺斯之焰时施放恶魔之火现在会召唤一场混沌之雨。'),
(704473, '治疗一名友方目标（144 + 67.8496% 法术强度）点生命值，数值随狂乱提高，并使其暴击几率提高1%，可叠加15次，持续15 秒。'),
(704475, '建造技能的施法时间缩短50%。'),
(704476, '将你与一名盟友连接，持续15 秒，使其造成的所有伤害提高15%，受到的所有伤害降低15%。［拥有邪异启示: \n\n激活期间每15秒，你会对目标触发一次恐怖启示，并产生5点狂乱。］'),
(704487, '施放熔解现实现在会使你的时光撕裂和瓦解的周期性伤害从急速中获得收益，持续10 秒。'),
(704488, '强化时间线造成的治疗效果现在会施加秩序印记。'),
(704489, '触发异常尖刺的几率提高5%，且其伤害提高20%。'),
(704490, '50级被动心灵熔融现在每层还会使你对该目标造成的周期性伤害提高6%。'),
(704495, '你的攻击暴击现在使你的急速提高20%，持续6 秒。'),
(704497, '使你定身8秒，并制造5个你的幻象对你引导，施加一层灵魂木偶。'),
(704500, '50级被动技能施放咒火将使你在8 秒内的下一次恶咒之怒转化为咒火之怒。'),
(704503, '厄运巫咒和咒火造成的伤害现在会将恶意妖咒传播给最多1个附近的敌人。'),
(704505, '你的恶意妖咒持续时间延长6秒，你的攻击性巫毒法术射程提高6码。'),
(704511, '咒火现在会切断你对目标施加的傀儡师的丝线，立即对其造成伤害并收集一个精魂。'),
(704512, '减少洛阿之酿的施法时间0.25秒。'),
(704513, '将战斗冲锋的冷却时间减少5秒，推进的冷却时间减少30秒。'),
(704514, '移除你的战旗的公共冷却时间，并将守护的冷却时间减少10秒。'),
(704515, '装备斧类武器时，你的暴击几率提高2%，暴击伤害提高5%。'),
(704516, '横扫千军、投掷长矛和百夫长打击的能量消耗降低5。'),
(704524, '使战争回响的价值提高5%。\n\n此外，施放战争之声现在有40%的几率产生回响，在0.5秒后额外造成一次打击。每秒最多触发一次。'),
(704525, '触发战争之声后，你的下一次攻击将额外进行一次自动攻击。'),
(704526, '减少英雄行军的冷却时间60秒。'),
(704527, '周期性或引导伤害现在会使敌人从你处受到的伤害提高2%，持续10 秒，可叠加10次。'),
(704528, '地穴虫群每跳产生的符文能量增加2点。'),
(704533, '施放叙事诗现在使你的急速提高3%，可叠加3层，持续8 秒。'),
(704535, '悲恸旋律的伤害加成现在额外影响2次叙事诗施放，并使其必定暴击且造成100%额外伤害。'),
(704539, '触发战争之声现在为附近盟友提供战争回响，持续8 秒。'),
(704540, '提升队伍和团队成员的士气，使其攻击强度或法术强度提高95点，持续15 秒。\n\n不与同类效果叠加。'),
(704552, '末日撕裂的暴击现在返还 1 层收割之魂。'),
(704556, '使末日撕裂与屠戮的伤害提高 30%。'),
(704558, '以暗影伤害造成直接暴击，可使灵界的冷却时间缩短 2 秒。'),
(704562, '履行誓言时，格挡几率提高 2%，持续 15 秒，可叠加 5 层。'),
(704563, '直接治疗使目标的最大生命值提高 295，持续 15 秒。'),
(704565, '辉耀连锁额外跳转至 2 名盟友。'),
(704568, '圣光照耀和破晓的治疗提高 20%。'),
(704579, '日蚀誓言使目标目盲，其下一次攻击的未命中几率提高 10%，持续 6 秒，可叠加 5 层。对首领无效。履行誓言的效果提高 100%。'),
(704581, '昏迷效果的持续时间缩短 20%。'),
(704582, '圣光照耀的施法时间缩短 0.25 秒。'),
(704585, '受到的物理伤害降低 5%，生命值高于 80% 时额外降低 5%。'),
(704586, '激活黎明时获得闪耀之盾，持续 1 分钟。'),
(704602, '减少怒意释放的冷却时间 60 秒。\n\n当怒意释放结束时，你打击附近所有敌人，造成（751.65 + 56.1429% 攻击强度）点暗影烈焰伤害，并使其受到的撕裂伤害提高100%，持续15 秒。'),
(704603, '使星界之刃、碎星斩和守望者之刃的伤害提高15%。'),
(704604, '使你的智力和力量提高5%。'),
(704606, '直接法术暴击现在产生5点能量。'),
(704607, '使你的暴击伤害提高10%，并在与元素生物作战时，额外提高你的暴击几率15%。'),
(704610, '埃辛诺斯的猛攻现在有30%的几率用你的主手武器额外攻击一次。'),
(704611, '引导切割时，你的躲闪几率根据引导时间提高1%，最多提高10%。'),
(704612, '使你的契约效果提高50%。'),
(704613, '使你的吞噬魔法偷取的增益魔法效果数量提高1点。'),
(704621, '将止血的持续时间增加1秒。'),
(704623, '附近队伍和团队中的成员受到的治疗效果提高6%。此效果不与同类效果叠加。\n\n此外，血箭的生命偷取效果提高50%。'),
(704624, '自动攻击流血目标现在会感染伤口，使目标受到你的暴击几率提高1%，持续6 秒，可叠加10层。'),
(704625, '施放血箭或血牙撕咬现在会减少你的鲜血契约的冷却时间0.5秒。'),
(704626, '承受的物理伤害现在使下一次攻击在10 秒内受到的物理伤害降低（15 + 20% 攻击强度）点。'),
(704627, '使你的躲闪几率提高4%，武器技能提高5点。'),
(704632, '使你与小队和团队成员的所有法术和攻击命中几率提高1%。\n\n不与类似效果叠加。'),
(704633, '你的暴击现在使血肉塑造的冷却时间和目标身上的满足持续时间减少4秒。\n\n此外，你的暴击等级提高，数值相当于精神属性的15%。'),
(704634, '你的直接有害暴击会使目标受到你的暗影伤害提高2%，可叠加5层，持续12 秒。'),
(704635, '使祭品的效果提高20%。'),
(704636, '使你的血疮有15%的几率在不被消耗的情况下提供其效果。'),
(704641, '你的血箭现在对受到塔达拉姆的折磨影响的敌人必定暴击。'),
(704642, '使你的暗影伤害提高4%，并使你的命中几率提高3%。'),
(704644, '使所有小队和团队成员的法术急速提高3%。不与类似效果叠加。\n\n此外，当诅咒形态激活时，你的公共冷却时间缩短25%。'),
(704646, '你的血箭现在会刷新塔达拉姆的折磨的持续时间。'),
(704649, '暴击几率提高3%。'),
(704652, '40级被动技能物理暴击现在使动脉突袭的冷却时间减少1秒，并赋予你无情。'),
(704653, '当你突刺向一名敌人时，现在会用自动攻击打击他们3次。'),
(704654, '直接技能暴击现在会使你的法术和技能暴击几率及暴击伤害提高3%，持续10秒，最多可叠加10层。\n\n每次额外暴击会使该效果再提高3%，但持续时间减少1秒。'),
(704659, '你的静脉爆裂现在有40%的几率在施放时不触发冷却。\n\n你的血箭现在有40%的几率在施放时返还一半的怒气消耗。'),
(704660, '允许你的厚皮额外承受一次攻击。'),
(704661, '30级被动技能在不灭诅咒状态下，你从敏捷和力量中获得的攻击力提高50%。'),
(704662, '当生命值高于75%时，你受到的伤害降低5%。'),
(704669, '30级被动技能对冻结目标造成的暴击伤害提高100%。'),
(704670, '使你的冰霜伤害提高5%，并使你的最大符文能量提高15。'),
(704676, '当你的巫妖形态激活时，你的冠军法术冷却速度加快。'),
(704680, '你的冰川冲击现在产生20点符文能量。'),
(704681, '50级被动使你的法术有15%的几率获得永冻效果，使你的下2个法术视目标为冻结状态。持续12 秒。'),
(704682, '将骷髅弓箭手的持续时间增加3秒。'),
(704690, '每点怒气现在使静脉爆裂和劫掠斩的暴击几率增加0.5%，最高50%。'),
(704692, '当你对人型生物或野兽使用塔达拉姆的折磨时，会污染其血液，使你对它们造成的伤害提高10%。'),
(704701, '施放命令法术现在会使你获得一层地底之王，持续20 秒。\n\n达到10层时，［拥有活化：白骨怨灵: ；否则： 活化：墓王,］［拥有活化：墓王: ；否则： 活化：白骨怨灵］或活化：瘟疫之父的冷却时间随机减少15秒，并且你会召唤一只巨型僵尸，持续15 秒。'),
(704713, '使你的命令法术的符文能量消耗降低5。'),
(704715, '减少献祭亡灵的施法时间0.5秒。'),
(704717, '移除亡者行军的冷却时间，但使其拥有 1 秒施法时间。'),
(704718, '缩短你的暗影虫群引导时间25%。'),
(704721, '当你施放邪恶狂热时，你现在会唤起 5 只大型僵尸协助你作战，持续 15 秒。\n\n你的亡灵仆从造成的冰霜和物理伤害现在会使邪恶狂热的冷却时间缩短 0.5 秒。\n\n每个激活的憎恶或腐烂巨像都会使你的亡灵仆从造成的伤害额外缩短1秒冷却时间。'),
(704723, '40级被动技能施放法术现在会为你提供1层邪恶谋略，最多可叠加15层，持续20 秒。\n\n你的地穴虫群造成的伤害会消耗一层，每层使伤害提高10%。'),
(704724, '20级被动技能施放命令法术现在有30%的几率使其在6 秒内的下一次使用不消耗资源。'),
(704725, '月流和艾露恩祷言的暴击现在会对目标施加蚀影箭矢，持续20 秒。\n\n施放女猎手射击会治疗被标记的盟友，治疗量为（59 + 30% 法术强度）。'),
(704729, '你的最大符文能量提高20%。'),
(704732, '减少星辰汇聚的冷却时间 30 秒。'),
(704739, '每第3次星火射击将你的下一次星火射击转变为星火弹幕。'),
(704740, '星火射击现在有50%几率向目标免费射出一发女猎手射击。'),
(704741, '你的远程伤害现在有 15% 的几率触发散落星辰。\n\n此外，施放银溪现在会对每个被治疗目标周围至多 5 个敌人施加散落星辰。'),
(704745, '你的艾露恩祷言现在额外驱散1个效果。'),
(704755, '月光之触的治疗效果提高10%，并减少因受到伤害性攻击而造成的施法退条35%。'),
(704756, '你的治疗效果提高3%，对中毒或疾病目标额外提高3%。'),
(704759, '艾露恩之手、月流和银溪的治疗效果提高 10%。'),
(704764, '施放月之箭矢现在会使艾露恩祷言的冷却时间缩短 3 秒，并使月流和星界形态的冷却时间缩短 2 秒。'),
(704765, '每消耗第8颗散落星辰，你的下一次唤星术伤害提高50%。'),
(704769, '对30码以外的敌人造成的伤害提高5%。'),
(704771, '星辰碎裂的射程提高10码。'),
(704774, '受到的奥术伤害降低15%。'),
(704775, '流星提供的移动速度提高20%。'),
(704776, '星界心智的效果提高20%。'),
(704777, '吸取 30% 最大法力值立即反击任何从正面近战攻击你的敌人，造成奥术伤害，持续 10 秒。每个敌人每秒只能触发一次。\n\n与其他庇护法术共享冷却时间。'),
(704778, '急速提高4%。'),
(704783, '你的暴击几率提高5%。'),
(704784, '哨兵战刃现在恢复20%的最大法力值，并对敌人施加散落星辰。'),
(704785, '使所有小队和团队成员受到的伤害降低 3%。\n\n此外，你延迟承受 30% 的直接魔法伤害，改为在 10 秒内承受。\n\n不与同类效果叠加。'),
(704786, '减少哨兵战刃的冷却时间 5 秒。'),
(704787, '你造成的和受到的治疗效果提高 10%，生命值低于 50% 时效果翻倍。'),
(704788, '星辰爆裂的暴击几率提高10%。'),
(704789, '提高星界之刃的持续时间7秒。');

