INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(704790, '降低守望者之刃的冷却时间25%。'),
(704792, '能量恢复速度提高15%。'),
(704793, '狂怒之蚀的效果提高40%。'),
(704794, '星界顺劈的伤害提高10%，并额外影响1个敌人。'),
(704795, '你的成功格挡现在有50%的几率造成双倍格挡量的暴击格挡。'),
(704798, '使你的近战急速提高5%，移动速度提高10%。\n\n该天赋提供的移动速度可与月影步叠加。'),
(704800, '造成周期性伤害或治疗现在有15%的几率使你获得灼热之速。'),
(704801, '20级被动技能使用余烬消耗技能造成直接暴击时，现在会焦灼目标，使其额外受到相当于造成伤害30%的燃烧效果，持续6 秒。'),
(704804, '智力和暴击几率提高3%。'),
(704807, '施放火柱后，你造成的所有周期性伤害有10%的几率免费对目标施放火柱，持续5 秒。'),
(704809, '你的巨龙祈唤现在提供5层烈焰施法。\n\n此外，允许烈焰施法额外叠加5层，并使其持续时间延长5秒。'),
(704812, '使你的法术急速提高 4%，并使耀焰箭的伤害提高 10%。'),
(704813, '你的熔岩碎片现在会将炽燃扩散到主目标8码范围内的最多1个额外敌人。'),
(704814, '你的诺兹多姆的回响现在额外缩短守护巨龙的祝福的冷却时间5%。'),
(704815, '熔岩碎片对受炽燃影响的敌人造成的伤害现在会波及附近敌人，造成相当于该伤害50%的火焰伤害。'),
