(705216, '北地之息的暴击几率提高10%。\n\n此外，你的攻击现在对冻结目标无视护甲。'),
(705218, '你的神王麦酒不再清空你的酒杯。'),
(705221, '使可触发你的神王麦酒的攻击次数提高 10。\\r\n\\r\n此外，施放神王麦酒时，现在还会对 8 码内附近的一名额外友方玩家施放。'),
(705222, '用斩首造成击杀后，现在会回复100%的最大能量值。'),
(705227, '使投掷武器、碎脏者和开膛破肚的伤害提高10%。'),
(705232, '使你的肠穿肚烂造成的伤害提高75%。'),
(705234, '使长矛和狂战飞斧对流血目标的暴击几率提高8%。'),
(705235, '使血之诞生的跳数频率提高25%，其治疗效果现在受你的敏捷加成，并且可以造成暴击治疗。'),
(705238, '流血效果造成的伤害现在使你的敏捷提高1%，持续8 秒，可叠加10层。'),
(705240, '造成的直接物理伤害现在会减少无羁之怒的冷却时间 1 秒。'),
(705242, '20级被动技能血之诞生现在还会使你的伤害提高5%，并且持续时间延长3秒。'),
(705250, '使你的敏捷提高5%，命中几率提高3%。'),
(705253, '使触发天灾克星的几率提高5%，命中几率提高2%。'),
(705255, '天灾克星造成的伤害现在使白银之刃的伤害提高5%，持续6 秒，可叠加10层。'),
(705256, '你的神殿守护者现在使你5 秒内的下一个技能不消耗资源。'),
(705259, '当圣契激活时，你的惩戒现在会释放一道神圣能量，造成（25% 攻击强度 + 112 × 等级系数）点高威胁值的神圣伤害。'),
(705263, '使你的圣契和圣典的持续时间增加10秒。'),
(705266, '使你的圣契法术的冷却时间减少30秒。'),
(705268, '使你从坚韧圣约和信仰圣约获得的治疗效果翻倍。'),
(705271, '你的暴击几率提高2%，并使你受到的缴械效果持续时间缩短15%。'),
(705272, '提高你的神圣法术和技能造成的暴击伤害15%。'),
(705274, '你的圣契法术现在使你获得10%的近战急速提高，持续20 秒。'),
(705276, '你的副手武器伤害提高25%。'),
(705278, '提高你造成和受到的神圣治疗效果8%。'),
(705281, '20级被动你的神圣法术伤害提高，相当于攻击强度的50%，护甲穿透提高，相当于智力的50%。'),
(705283, '使誓言锁链的持续时间延长 20%。'),
(705284, '使破誓者、定罪和泰坦打击的伤害提高20%。'),
(705285, '定罪现在可额外叠加1层。'),
(705286, '施放获得誓言的技能现在使你的伤害和移动速度提高2%，持续15 秒，可叠加5层。'),
(705287, '祝福现在基于你的敏捷和耐力为友方目标提供护甲，持续 15 秒。'),
(705290, '使用圣契法术［拥有天灾克星: 或白银之手咏唱］现在使你的伤害和治疗效果提高10%，持续15 秒。'),
(705291, '对受你正义突刺影响的敌人，由惩戒、信仰之刃、天灾克星和定罪造成的伤害现在每层提高6%。'),
(705293, '挥击前方敌人，造成140%高威胁武器伤害外加13点伤害，并使其攻击和移动速度降低20%，持续10 秒。\n仅可在躲避攻击后使用。'),
(705295, '施放神圣挥击现在使你获得法杖守卫，吸收（125 + 30% 耐力）点伤害，效果随耐力、招架和躲闪等级提高，持续8 秒。'),
(705300, '使你的神圣伤害和治疗效果提高15%，持续30 秒。\n\n激活时，破誓者对附近敌人额外造成（141 + 12% 攻击强度）点神圣伤害。［拥有永恒奉献: \n\n以此方式造成伤害会使你的圣契冷却时间缩短4秒。］'),
(705303, '20级被动技能你的招架等级提高，相当于敏捷的20%，你的躲闪等级提高，相当于智力的20%。'),
(705306, '当你受到物理伤害时，现在会以15%的伤害值对敌人进行神圣伤害反击。每秒只能触发一次。\n\n对首领无效。'),
(705307, '提高清算的伤害20%。'),
(705315, '你的偏转剑刃现在保证你招架额外1次攻击，并且其招架窗口的持续时间增加 1 秒。'),
(705316, '每3秒恢复5点能量。'),
(705318, '使战争之声造成的伤害提高15%。'),
(705320, '放置战旗现在会额外触发一项独特效果。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (705323, 705324, 705329, 705330, 705331, 705332, 705333, 705336, 705338, 705341, 705343, 705345, 705346, 705350, 705351, 705352, 705356, 705359, 705361, 705364, 705368, 705369, 705370, 705376, 705377, 705378, 705379, 705386, 705389, 705392, 705397, 705401, 705403, 705404, 705406, 705409, 705410, 705413, 705414, 705416, 705418, 705424, 705426, 705428, 705432, 705436, 705437, 705441, 705442, 705450, 705453, 705455, 705456, 705463, 705465, 705467, 705477, 705478, 705480, 705484, 705490, 705496, 705497, 705498, 705499, 705500, 705506, 705512, 705514, 705515, 705519, 705520, 705524, 705526, 705528, 705531, 705533, 705534, 705540, 705541, 705543, 705546, 705550, 705551, 705554, 705556, 705559, 705560, 705562, 705563, 705564, 705565, 705568, 705570, 705572, 705575, 705577, 705579, 705580, 705581, 705583, 705586, 705592, 705594, 705600, 705605, 705609, 705613, 705615, 705618, 705619, 705621, 705625, 705627, 705632, 705634, 705636, 705639, 705643, 705645, 705646, 705650, 705652, 705653, 705655, 705657, 705659, 705661, 705662, 705663, 705666, 705667, 705668, 705669, 705672, 705675, 705677, 705686, 705689, 705690, 705692, 705693, 705700, 705702, 705704, 705708, 705709, 705715, 705717, 705719, 705720, 705721, 705723, 705725, 705727, 705731, 705732, 705733, 705734, 705742, 705745, 705746, 705747, 705750, 705752, 705754, 705780, 705781, 705786, 705788, 705789, 705792, 705796, 705802, 705803, 705805, 705806, 705810, 705811, 705815, 705817, 705820, 705825, 705827, 705831, 705840, 705843, 705844, 705846, 705848, 705850, 705851, 705856, 705859, 705864, 705870, 705871, 705876, 705877, 705880);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(705323, '每当你获得3层荣耀或20层恩惠时，你在10 秒内的下2次粉碎或横扫不消耗资源。'),
(705324, '反击现在额外恢复20能量。'),
(705329, '你的百夫长打击和反击的伤害提高20%。'),
(705330, '勇气战旗的能量消耗降低20点。'),
(705331, '30级被动你的成功格挡现在有 50% 的几率造成精确格挡，效果为正常格挡的两倍。此外，你的盾牌提供的护甲值提高 50%。'),
(705332, '你的推进和战斗冲锋的冷却时间缩短30%。'),
(705333, '对冲撞造成暴击现在会减少坚守阵地的剩余冷却时间0秒。'),
(705336, '装备单手锤时，你的护甲穿透提高8%。'),
(705338, '你的最大能量提高25点。'),
(705341, '你的反击、横扫千军和投掷长矛现在会根据施放时拥有的每点能量值，额外造成2%的武器伤害。'),
(705343, '你的［拥有节奏: ；否则： 粉碎或 ］冲撞现在无视目标15%的护甲。'),
(705345, '你的重击现在使你散发一道光环，持续5 秒，使小队成员受到的所有伤害降低5%。'),
(705346, '施放举盾和重击现在会使你的加固持续时间延长 1 秒。\n\n加固无法延长超过其最大持续时间。'),
(705350, '触发战争之声后，你的下一次冲撞伤害提高20%，持续15 秒。'),
(705351, '暴击现在会减少英雄行军的冷却时间 1 秒。'),
(705352, '散发一道环绕你的光环，持续 15 秒，使 100 码范围内的盟友在造成直接伤害时额外造成（28% 攻击强度）点神圣伤害。\n\n施加力竭，使你在 1 分钟内无法从类似效果中获益。'),
(705356, '提高你的战歌的暴击几率10%。'),
(705359, '你的急速提高5%，且战线阵型提供的移动速度提高8%。'),
(705361, '你的能量恢复速度提高10%。'),
(705364, '使你的耐力提高5%，暴击几率提高2%。'),
(705368, '你的力量提高4%，专精提高2点。'),
(705369, '举盾提供的格挡值提高25%，你的格挡几率提高1%。'),
(705370, '你的盾牌提供的护甲加成提高20%。'),
(705376, '粉碎造成的伤害提高15，并额外根据你的格挡值提高。'),
(705377, '每当你格挡一次攻击，你的力量和耐力提高2%，持续10 秒，最多叠加3层。'),
(705378, '对人型生物造成的伤害提高6%。'),
(705379, '重击造成的伤害现在每1秒额外造成20%的伤害，持续3 秒。'),
(705386, '使死亡之风、群鸦杀戮与灵魂突刺的伤害提高 15%。'),
(705389, '使幽魂疾步的伤害提高 30%，并降低潜行时敌人发现你的几率。'),
(705392, '使迷失者遗物匣的冷却时间缩短 5 秒。'),
(705397, '幽魂武器造成的伤害现在治疗你相当于所造成伤害 50% 的生命值。'),
(705401, '使幽魂武器与灵魂撕裂的持续时间延长 5 秒。'),
(705403, '安魂曲与灵魂撕裂现在有 40% 几率返还 1 层收割之魂。'),
(705404, '你的死亡之风如今还会在你立于其半径之内时，使你的受到的的治疗量与招架几率提高 10%。'),
(705406, '受难灵魂现在有 25% 几率在承受伤害时不消耗 1 层。'),
(705409, '使鬼魅尖啸与灵魂突刺的符文能量消耗降低 10 点。'),
(705410, '使灵魂撕裂的持续时间延长 10 秒。'),
(705413, '在指定位置创造一片收割之地，持续 15 秒；身处其中的敌人近战与远程急速、移动速度降低 20%。在此期间试图离开收割之地的敌人会被拉回其中心。'),
(705414, '你的屠戮现在有 20% 几率免费再施放一次。'),
(705416, '末日撕裂吸收的治疗量提高 30%。'),
(705418, '使灵魂撕裂让你无视的护甲量额外提高 10%。'),
(705424, '幽魂疾步在 5 秒内已造成的伤害，现在额外提高 125%。'),
(705426, '邪恶祷文现在使你在 10 秒内的下一个法术或技能伤害提高 50%，且施放它会让你获得幽魂效果，持续 3 秒。'),
(705428, '屠戮的暴击现在使你的自动攻击在 5 秒内额外造成 85% 暗影伤害。'),
(705432, '对生命值低于 35% 的敌人时，你的技能伤害与暴击几率提高 20%。'),
(705436, '最大生命值低于 35% 时，你闪避攻击的几率提高 25%；成功闪避会使灵魂收割作用于目标。'),
(705437, '等级 30 被动：灭绝可额外叠加 1 次，并使怨灵之刃也能让你获得灭绝。'),
(705441, '你的怨灵之刃对受到灵魂撕裂影响的敌人造成的伤害翻倍。'),
(705442, '生成收割之魂现在使你在 15 秒内受到的伤害降低 2%，可叠加 3 次。'),
(705450, '使用驯犬者之令会召唤1只次级暗影猎犬，持续15 秒，它们会扑向目标并造成（225 + 200% 角色等级）点暗影伤害。'),
(705453, '减少暗影射击、翻越和释放猎犬的怒气消耗 10。'),
(705455, '施放暗影射击现在会为你的暗影狂怒提供暗影猎犬。'),
(705456, '20级被动技能施放暗影射击现在恢复你最大法力值的3%。'),
(705463, '施放释放猎犬现在会使你获得暗影狂怒，持续15 秒。'),
(705465, '你的暗影猎犬造成的暗影伤害提高5%。'),
(705467, '暗影射击的伤害提高15%，命中几率提高2%。'),
(705477, '你和你的暗影猎犬的暴击几率提高4%。'),
(705478, '对生命值低于20%的敌人，你的暴击几率提高25%。'),
(705480, '净化者之刃现在使你获得灼热剑柄，持续10 秒。'),
(705484, '造成火焰伤害现在会使火炬之光和黄昏之刃的伤害提高2%，持续5 秒，可叠加10层。'),
(705490, '你的大胆逃脱现在会重置翻越的冷却时间，并产生 10 点怒气。'),
(705496, '你的暴击现在产生 10 点怒气和 5% 最大法力值。该效果每 3 秒只能触发一次。'),
(705497, '使用滋补剂现在使所有其他滋补剂的冷却时间减少10秒。'),
(705498, '你的药剂的效果提高25%。'),
(705499, '当暮光狂暴激活时，你的移动速度提高40%。'),
(705500, '暗影射击的暴击几率提高25%。'),
(705506, '对生命值高于75%和低于35%的敌人造成的伤害提高15%。'),
(705512, '使你的远程急速提高8%。'),
(705514, '使你的远程攻击强度提高10%，并使你的远程技能射程提高5码。'),
(705515, '远程技能的暴击现在会将折磨者扩散到附近一个敌人身上。'),
(705519, '使坚忍的冷却时间缩短30秒，钻地弩箭的冷却时间缩短10秒。'),
(705520, '使坚忍的持续时间延长 5 秒，并使其效果提高 25%。'),
(705524, '你的弩箭与冲刺现在额外影响一次觅心弩箭的使用。\n\n你的巨盾现在持续时间延长2秒，冷却时间减少30秒。'),
(705526, '使烟雾弹的冷却时间缩短30秒，持续时间延长1秒。'),
(705528, '饮用药剂现在还会恢复30点怒气。'),
(705531, '远程自动攻击暴击现在会使你的暗影猎犬的近战急速提高15%，持续5 秒。'),
(705533, '饮用药剂现在还会恢复你最大生命值和法力值的5%。'),
(705534, '每当你受到直接伤害或回避攻击时，你有 10% 的几率进行反击，造成 75% 武器伤害。'),
(705540, '使你的敏捷和智力提高5%。'),
(705541, '20级被动技能使你的法术伤害提高，相当于敏捷的20%;法术暴击几率提高，相当于敏捷的10%;命中等级提高，相当于敏捷的5%。'),
(705543, '使你的武器铭刻效果提高20%。'),
(705546, '你的魔网汲取现在会从目标身上额外偷取1个魔法效果。'),
(705550, '直接伤害有5%的几率使你的法术急速提高20%，持续5 秒。'),
(705551, '触发武器铭刻：大地的几率提高4%。'),
(705554, '使你的移动速度提高8%，并使你的符文纹饰的法力值消耗降低25%。'),
(705556, '使极寒融合的持续时间增加2秒。'),
(705559, '巨龙之怒造成的伤害现在有50%的几率变得不稳定，额外造成（50 + 16.5% 智力）%的魔法伤害，但会燃烧（85 + 40% 智力）点法力值。\n\n造成的伤害和燃烧的法力值均会随你的智力属性提高。'),
(705560, '50级被动技能使用元素迸发现在有20%的几率使你的下一次原初轰击转化为符文湮灭，持续10 秒。'),
(705562, '来自物品的护甲加成提高30%。'),
(705563, '你的跃迁匕首如果在符文帷幕激活期间使用，则不再有冷却时间。'),
(705564, '使你造成的魔法伤害提高3%，并允许30%的法力值恢复在战斗中持续生效。'),
(705565, '飓风结束后，你现在可以在4 秒内使用需要符文帷幕的技能。'),
(705568, '30级被动技能燃刃斩现在以旋风环绕你，使你接下来的3次符文之刃额外造成一次相当于75%伤害的自然伤害。'),
(705570, '使你的暴击几率提高3%，并使你的精准等级提高4。'),
(705572, '你的原初轰击造成的暴击现在有40%的几率额外攻击一次。'),
(705575, '从你的武器中释放出一阵狂风，打击6码范围内的附近敌人，每0.5秒造成200%武器伤害的自然伤害，持续3 秒。\n\n激活时，你每0.5秒会留下一个湍流螺旋，持续6 秒。'),
(705577, '使冰霜符文的冷却时间缩短20秒，法力值消耗提高50%，但射程降低10码。'),
(705579, '50级被动技能每第3次施放符文剑，将使你在15 秒内的下一次符文剑转化为激涌斩。'),
(705580, '每第3次施放符文剑现在会造成30%的额外伤害。'),
(705581, '施放相位遁形现在会使你在其持续的前2 秒内移动速度提高40%。'),
(705583, '需要符文帷幕的技能现在可在符文帷幕破碎后使用3秒，且无施法时间。'),
(705586, '使用掌印符印后，你的控制效果持续时间提高20%。\n\n所有掌印符印的施法时间减少0.5秒，并使你的掌印符印增益效果持续时间提高50%。'),
(705592, '使冰霜符文和掌印：大地的昏迷效果的持续时间延长1秒。'),
(705594, '移除冰川符文和永冻符文的施法时间。'),
(705600, '飓风结束后，你的近战攻击速度提高15%，暴击几率提高10%，持续10 秒。'),
(705605, '触发你的武器铭刻的几率提高5%。'),
(705609, '你的标记：符文烙印现在可叠加3层。'),
(705613, '当上古之拳激活时，武器铭刻：火焰的伤害提高15%。'),
(705615, '触发武器铭刻：火焰和武器铭刻：大地的几率提高5%。'),
(705618, '30级被动技能上古之拳现在会随机释放一道元素刻痕。\n\n火焰雕刻：使你的护甲穿透提高15%，持续6 秒。\n\n水刻：在6 秒内恢复300点法力值。\n\n大地雕刻：每1秒恢复3%的缺失生命值，持续6 秒。\n\n空气雕刻：使你的近战急速提高10%，持续6 秒。'),
(705619, '你的符文纹饰效果提高25%。'),
(705621, '使巅峰的持续时间延长6秒。'),
(705625, '在元素迸发激活期间使用原初轰击或冰霜符印将为你提供一层火焰符印。\n\n 雕文可通过符印崩解或奥术秘法触发释放。'),
(705627, '原初轰击和奥术秘法的伤害提高20%。'),
(705632, '你的智力提高10%，且每点智力提供的法力值提高10%。'),
(705634, '施放旁观者之眼现在会在持续期间内快速减少你的符文法术和相位遁形的冷却时间。'),
(705636, '花岗岩决心额外降低受到的伤害10%。'),
(705639, '电击的周期性伤害提高50%。'),
(705643, '你的分叉闪电和托里姆之臂现在会标记敌人，持续10秒。\n\n你对被标记敌人施放的召唤闪电会额外造成15%的伤害，并波及附近敌人。'),
(705645, '电刑的暴击伤害提高30%。'),
(705646, '每消耗一层托里姆之臂，使你的静电伤害额外提高1%。'),
(705650, '你的自然伤害提高5%。'),
(705652, '你的风暴斗篷、召唤风暴和闪电之体的持续时间延长30%。'),
(705653, '电击、召唤风暴和风暴之眼的暴击几率提高4%。'),
(705655, '召唤风暴的跳动频率提高25%。'),
(705657, '［拥有导电: 盐水；否则： 电击］的施法时间缩短15%。'),
(705659, '你的护盾法术效果提高15%。'),
(705661, '用振奋之风包裹一名盟友，使其免疫沉默和打断效果，并在20 秒内不会因受到伤害而施法退条。'),
(705662, '使电击的法术伤害加成提高10%，气爆提高20%。'),
(705663, '对生命值低于20%的敌人，电刑的暴击几率提高30%。'),
(705666, '使溺水的暴击几率提高25%。'),
(705667, '使电击、召唤闪电和托里姆之臂的法术强度加成提高15%。'),
(705668, '使你的风暴破击驱散的有益魔法效果数量提高1个，范围提高10码。'),
(705669, '3层充能，12秒充能时间召唤一道狂暴的雷霆冲击，粉碎魔法，移除1个有益魔法效果。'),
(705672, '消耗20点静电释放附近盟友的压力，驱散1移动减速效果，每3秒重复一次，持续9 秒。'),
(705675, '使昏迷和迷惑效果的持续时间缩短20%。'),
(705677, '使烈风防护和云爆的冷却时间缩短5秒。'),
(705686, '使闪电之体的伤害翻倍，并且当你对盟友施放时，它会自动对你施放。'),
(705689, '使风之召唤和风暴之唤的效果提高20%。'),
(705690, '使你的振奋涌动的暴击几率提高20%。'),
(705692, '分叉闪电造成伤害时有5%的几率转化为雷霆之波。'),
(705693, '使你的闪电之体冷却时间缩短30秒。'),
(705700, '你的气爆现在使你的空气元素获得一层振奋。'),
(705702, '使你的解脱的效果提高20%。'),
(705704, '使你的上升气流的持续时间延长3秒，脉冲频率提高15%。'),
(705708, '施放上升气流现在会使你的空气元素在你脚下施放它自己的上升气流。\n此外，上升气流的伤害提高 25%。'),
(705709, '在你上升气流范围内的盟友移动速度额外提高25%。'),
(705715, '正在施放云之吻现在使你的空气元素获得空气之礼，持续 30 秒。\n\n此外，你的暴击现在会使顺风的持续时间延长 1.5 秒。'),
(705717, '施放［拥有风暴召唤: 气爆；否则： 召唤闪电］现在会刷新一层烈风。'),
(705719, '施放烈风现在使消耗静电的技能冷却时间减少 1 秒。\n\n 此效果不影响上升气流或振奋涌动。'),
(705720, '使你的总威胁值降低30%，阵风的范围提高3码。'),
(705721, '使你的空气元素的法术造成的伤害提高10%，你的自然伤害提高2%。'),
(705723, '你的直接伤害暴击会使你的风暴之流的脉冲频率提高20%，持续3 秒。'),
(705725, '20级被动使你的法术急速提高，相当于智力属性的20%。'),
(705727, '使你的湍流之怒的施法时间缩短0.2秒，命中几率提高2%。'),
(705731, '使你周围5码范围内的敌人命中几率降低3%。'),
(705732, '嚎叫技能的冷却时间缩短25%。'),
(705733, '对流血目标造成的暗影伤害提高10%。\n\n你的精准提高10。'),
(705734, '与一名盟友交换生命值百分比。\n\n将两者中较低的生命值百分比提升至40%，若低于该数值。［拥有汇聚活力: \n\n强化：冷却时间缩短60秒。］'),
(705742, '使你受到的治疗效果提高15%。'),
(705745, '冰川冲击造成的伤害现在会对主目标周围6码范围内的敌人额外造成50%的冰霜伤害。'),
(705746, '你吸收20%的治疗效果，并获得相当于吸收量的护盾，持续10 秒。'),
(705747, '收割瘟疫造成的伤害现在有20%的几率召唤一只次级僵尸协助你战斗，持续15 秒。'),
(705750, '造成魔法伤害现在有15%的几率使你的急速提高10%，持续12 秒。'),
(705752, '直接暴击恢复3%的最大法力值和9%的最大符文能量。周期性暴击恢复1%的最大法力值。'),
(705754, '对一名敌人施放命令法术现在会在其处于抹除状态时施加抹除效果。'),
(705780, '来自作战药剂增幅的治疗现在影响主要目标附近的2个额外盟友。'),
(705781, '你的急速和对机械类生物造成的伤害提高3%。'),
(705786, '施放扳手重击和废料射击现在使你的宠物攻击强度提高5%，持续15 秒，可叠加2层。'),
(705788, '你的机甲技能的暴击伤害提高15%。'),
(705789, '使黏性炸弹的引爆速度提高1秒，冷却时间减少2秒。'),
(705792, '你和你的召唤物的暴击和命中几率提高4%。'),
(705796, '你的穿刺强化现在额外忽略目标10%的护甲，并为你提供10点法术穿透。'),
(705802, '20级被动技能使你的治疗强度提高，相当于智力值的20%，并使你的暴击等级提高，相当于智力值的15%。'),
(705803, '施放修复射击或紧急治疗现在有 15% 的几率刷新一层信标。'),
(705805, '废料射击和修复射击的施法时间缩短15%。'),
(705806, '所有法术和技能的法力消耗降低 10%。'),
(705810, '生命值低于35%时，现在会刷新所有火箭靴的充能次数。\n\n每3分钟只能触发一次。'),
(705811, '所有附近盟友受到的治疗效果提高6%，不与同类效果叠加。\n\n此外，你的警报信标现在可驱散额外1名盟友的恐惧、魅惑和睡眠效果。'),
(705815, '20级被动技能火焰伤害有5%的几率使你获得蓄势待发！.'),
(705817, '你的宠物或召唤物造成的伤害或治疗现在会使你恢复相当于其数值15%的生命值。\n\n此外，你造成的直接伤害或治疗现在会使你的宠物恢复相当于其数值15%的生命值和法力值。\n\n这些效果每秒只能触发一次。'),
(705820, '火焰暴击现在使火箭专家的剩余冷却时间缩短3秒。'),
(705825, '敏捷和智力提高 4%。'),
(705827, '动能护盾降低的伤害提高10%，持续时间延长2秒。'),
(705831, '每当你的召唤物暴击时，你和你的宠物受到的伤害降低2%，持续15 秒，可叠加4层。'),
(705840, '对受到厄运巫咒影响的目标，恶咒之怒、咒火和恶意妖咒的伤害提高 10%。'),
(705843, '20级被动你身上的每个激活的精魂使你的精魂回收有 5% 的几率额外施放一次。'),
(705844, '30级被动技能你的暗影傀儡和傀儡师的丝线造成的伤害现在有15%的几率重置厄运巫咒的冷却时间，并使你的下一次施法获得10秒的冷却缩减。'),
(705846, '纳米机器人重构造成的周期性治疗效果现在为受影响目标 10 码范围内的 5 个盟友恢复（3.5 + 4.0286% 治疗强度）点生命值。'),
(705848, '30级被动技能洛阿之酿造成的治疗效果现在会为目标盟友随机施加一种强化效果。'),
(705850, '你的投掷药水和溅射药水的冷却时间被重置，且在5 秒内的下一次使用会对受影响盟友施加鱼骨效果。\n\n立即将你的材料切换为鱼油和鱼骨。'),
(705851, '你的投掷药水和溅射药水冷却时间重置，且在5 秒内的下一次使用会对受影响盟友施加蛙菇。\n\n立即将你的材料切换为丛林蘑菇和鱼骨。'),
(705856, '使你的丛林蘑菇产生的大锅的治疗效果提高15%。'),
(705859, '从你的丛林蘑菇中使用的大锅现在治疗效果提高100%，但治疗目标减少3个。'),
(705864, '在 10 秒内，所有大锅效果和材料的效果提高 100%，并且你可以在移动时施放瓶中精魂。'),
(705870, '用大锅灌注你的大锅，持续10 秒，使40码范围内小队和团队成员受到的15%直接物理伤害改为随时间生效。\n\n同时只能激活1个基座。'),
(705871, '造成的伤害和产生的治疗现在有5%的几率使你的下一个法术或技能消耗降低100%，持续10 秒。'),
(705876, '允许邪恶毒素额外叠加一层。'),
(705877, '你的暴击几率提高 4%，伏都法术产生的威胁值降低 20%。'),
(705880, '你的结界、神像和图腾的法力消耗降低 20%。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (705894, 705899, 705901, 705902, 705903, 705906, 705907, 705909, 705910, 705911, 705912, 705916, 705917, 705921, 705922, 705925, 705928, 705936, 705939, 705942, 705943, 705948, 705949, 705957, 705959, 705961, 705962, 705966, 705967, 705969, 705970, 705973, 705975, 705980, 705982, 705985, 705991, 705993, 705996, 705998, 705999, 706000, 706001, 706002, 706006, 706007, 706009, 706012, 706014, 706015, 706016, 706018, 706021, 706023, 706025, 706026, 706027, 706030, 706032, 706033, 706035, 706036, 706038, 706040, 706046, 706053, 706055, 706059, 706063, 706071, 706076, 706077, 706079, 706083, 706084, 706085, 706096, 706098, 706099, 706100, 706102, 706107, 706114, 706121, 706122, 706128, 706130, 706131, 706133, 706134, 706137, 706138, 706148, 706150, 706153, 706159, 706160, 706161, 706162, 706165, 706167, 706171, 706174, 706176, 706177, 706179, 706181, 706182, 706187, 706188, 706189, 706190, 706201, 706203, 706208, 706209, 706211, 706216, 706220, 706230, 706232, 706238, 706239, 706240, 706245, 706247, 706256, 706258, 706260, 706266, 706267, 706270, 706271, 706277, 706281, 706282, 706284, 706295, 706297, 706309, 706312, 706318, 706320, 706323, 706325, 706331, 706333, 706336, 706338, 706340, 706342, 706344, 706352, 706353, 706354, 706357, 706359, 706365, 706368, 706369, 706370, 706375, 706379, 706385, 706425, 706431, 706434, 706449, 706455, 706458, 706464, 706468, 706472, 706477, 706481, 706482, 706483, 706488, 706501, 706502, 706514, 706515, 706518, 706523, 706531, 706538, 706542, 706543, 706544, 706545, 706551, 706555, 706557, 706558, 706563, 706564, 706565, 706566, 706569, 706572);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(705894, '你身上每激活一个恶咒箭，使精魂之蚀和精魂造成的伤害提高5%。'),
(705899, '使所有结界、神像和雕像的冷却时间减少25%。'),
(705901, '你的模仿结界现在也会施放厄运巫咒，并且施放厄运巫咒现在会使暗影傀儡的冷却时间缩短3秒。'),
(705902, '使恶意妖咒的伤害提高15%，并使厄运的持续时间延长2秒。'),
(705903, '使你的最大法力值提高5%，并使法术和技能的法力消耗降低3%。'),
(705906, '将万灵药转化为群体万能解药药剂。'),
(705907, '使黑暗帷幕造成的伤害提高100%。'),
(705909, '强大巫毒现在仅减少25%的伤害输出，并额外减少5%的伤害承受。'),
(705910, '当厄运巫咒作用于受傀儡师的丝线影响的敌人时，每1秒额外触发一次攻击，造成3 秒内30%的伤害作为自然伤害。'),
(705911, '使你在施法时仍保持40%的法力回复，并降低因受到伤害性攻击而造成的施法退条70%。'),
(705912, '现在召唤你的战争魔像会使你的法术急速提高30%，持续20 秒。\n\n此外，恶意妖咒造成的周期性伤害和暗影傀儡造成的伤害将使战争魔像的冷却时间缩短0.5秒。'),
(705916, '邦桑迪之音现在使你的精神提高100%。'),
(705917, '暗影闪爆和咒火造成的伤害现在使敌人被暴击的几率提高3%，持续12 秒。'),
(705921, '急速提高5%。'),
(705922, '使恶咒之怒和厄运巫咒的施法时间缩短0.5秒。'),
(705925, '周期性伤害现在有25%的几率使你的毒蛇结界急速提高3%，持续15 秒，最多可叠加3层。'),
(705928, '你的恶咒箭现在每1秒额外造成4 秒内15%的伤害作为自然伤害。'),
(705936, '使你的敏捷以及造成的自然和暗影伤害提高3%。'),
(705939, '使瑟拉图斯的召唤的冷却时间延长5秒，但使其召唤的毒蛇结界数量增加2。'),
(705942, '当暗影追踪者或幻象激活时，每0.5秒你获得一层巫毒渴望。'),
(705943, '被暗影魔法强化15 秒，使你的急速提高，受到的暗影伤害降低20%［拥有沃金的祝福: ，并且每1秒使精魂飞刃的冷却时间减少20%］。'),
(705948, '施放精魂之蚀时若拥有5个精魂，将重置精魂飞刃的冷却时间，并使你在 8 秒内的下一次施法必定造成暴击。\n\n以此方式使用的灵魂战刃将使暗影追踪者的冷却时间减少 15 秒。'),
(705949, '变形法术的资源消耗降低4%。'),
(705957, '将草本万用膏的持续时间、冷却时间和治疗效果加倍。\n\n此外，现在每6秒会寻找附近另一名盟友进行治疗，而非在持续时间结束时才触发。'),
(705959, '虫巢破击现在消耗2秒的毒刺毒素持续时间，喷出有毒粘液，对5码内的5个敌人造成20点自然伤害。'),
(705961, '每当你受到魔法伤害时，使该魔法系别的伤害降低10%，持续10 秒。\n\n每个魔法系别每30秒只能触发一次。'),
(705962, '提高你的急速4%。'),
(705966, '使你的总护甲值提高20%。\n\n此外，在蜘蛛或甲虫形态下，你的攻击将无法被招架或躲闪。'),
(705967, '当一层暴露血肉被施加时，你现在恢复最大生命值的1%。'),
(705969, '闪避一次攻击现在产生3点怒气。'),
(705970, '20级被动技能在甲虫形态下，所有主属性提高15%。\n\n此外，你的命中等级提高，数值相当于所有主属性的3%。'),
(705973, '减少甲壳冲锋的冷却时间3秒，并提高其伤害15%。'),
(705975, '提高你的毒素效果30%。'),
(705980, '甲壳冲锋造成的伤害现在提高你的躲闪几率1%，持续5 秒，可叠加8层。'),
(705982, '甲壳冲锋、坚甲冲撞和虫巢破击的爆击现在会施加邪恶毒素。'),
(705985, '每1.5秒造成（3.2% 攻击强度 + 60 × 等级系数 + 5.6667% 暗影法术强度）点暗影伤害，持续6 秒。'),
(705991, '暴露血肉的最大叠加层数增加5层，每层造成的物理易伤降低1个百分点。'),
(705993, '伤害和有效治疗现在有8%的几率获得安卡赫特典籍，持续15 秒。'),
(705996, '提高你的信息素效果20%和持续时间50%。'),
(705998, '直接伤害现在有 20% 的几率在敌人脚下生成一滩甲虫黏液。\n\n每3秒只能触发一次。'),
(705999, '使甲壳再生消耗的怒气减少3。'),
(706000, '造成（18.85 + 12.5% 法术强度）点暗影伤害，并降低攻击强度23。'),
(706001, '坚甲冲撞现在会在每个被击中的敌人脚下留下一滩甲虫黏液。'),
(706002, '提高你的最大生命值和躲闪几率3%。'),
(706006, '减少虫巢破击和坚甲冲撞的怒气消耗3，并提高你的命中几率2%。'),
(706007, '毒蛇之牙现在使后续的蛇之牙伤害提高15%，持续8 秒，最多可叠加3层。'),
