(706016, '所有爆击治疗使目标从你处受到的周期性治疗效果提高10%，持续5 秒。'),
(706018, '直接治疗现在有5%的几率使你获得5秒的毒蛇领主的护符效果。 如果毒蛇领主的护符已激活，触发此效果将改为延长其持续时间5秒。此效果无法使其超过最大持续时间。'),
(706021, '使你的爆击几率和爆击治疗效果提高20%，持续20 秒，并立即恢复你最大法力值的30%，但会消耗附近所有盟友身上的所有层数菌丝治疗。\n\n在激活期间，所有周期性爆击治疗额外造成相当于治疗量20%的治疗效果。'),
(706023, '等级40 被动霉菌病现在根据你当前激活的毒素获得强化。\n\n衰弱毒素：施法时间缩短20%。\n\n枯萎毒素：目标身上的孢子持续时间延长4秒。\n\n肾上腺毒素：额外攻击1个附近目标。'),
(706025, '提高毒液箭的伤害10%，并提高其爆击几率2%。'),
(706026, '在潜行状态下以及脱离潜行后的4秒内，你造成的伤害提高30%。'),
(706027, '所有法术和技能的消耗降低5%。'),
(706030, '周期性伤害现在有10%的几率使毒蛇之牙和真菌突袭者的剩余冷却时间缩短20%。'),
(706032, '你在15 秒内的下一次蛇牙将不消耗资源。'),
(706033, '提高毒牙和蛛魔钉刺的爆击几率10%。'),
(706035, '暴击现在有 15% 的几率使你的下一次沙德拉的祷言的治疗效果提高 20%，并使其变为瞬发，持续 10 秒。\n\n每5秒只能触发一次。'),
(706036, '周期性伤害现在有10%的几率生成一个孵化印记。'),
(706038, '提高凋零毒素的法术强度加成15%。'),
(706040, '使时光不谐和多彩碎片的暴击伤害提高50%。'),
