(706084, '使你抵抗移动减速效果的几率提高20%。'),
(706085, '使你在战斗中仍能保持40%的法力回复速度。'),
(706096, '你的伤害和治疗暴击现在使时光涟漪的剩余冷却时间减少1秒。'),
