(706099, '当加速激活时，维度分歧、时光异常和时光专注的冷却时间每2秒缩短10%。'),
(706100, '使重力炸弹造成的伤害提高50%。'),
(706102, '每层时光之沙现在也使你的纪元的治疗效果提高10%。'),
