(706121, '奇点核心现在会在激活期间使碎裂回响的伤害提高30%，并允许碎裂回响触发其伤害。'),
(706122, '使你的回响碎片的效果提高20%。'),
(706128, '移除永恒护盾的冷却时间。'),
(706130, '你的水晶炮现在会额外攻击2个附近的敌人。'),
(706131, '当无尽之沙激活时，你的法术和技能的每层法力消耗降低3%。'),
(706133, '缩短不稳定时光玻璃的冷却时间 30 秒。'),
(706134, '每次施放强化时间线现在会使加速恢复额外延长 5 秒，且强化时间线可延长加速恢复的最大时长提高 15 秒。'),
(706137, '使荆棘丛的冷却时间减少30秒。'),
(706138, '地震法术造成的伤害和治疗效果现在有20%几率使所有地震法术的冷却时间缩短1秒。'),
(706148, '在你的荆棘丛内时，你的地震技能冷却时间降低80%。\n\n此外，荆棘丛的持续时间翻倍。'),
