(706161, '使你的招架和躲闪几率提高3%，并使你从锁甲和板甲获得的护甲值提高25%。'),
(706162, '使你的护甲值提高，相当于你智力的200%，并使你受到的伤害降低3%。'),
(706165, '你的原初奔袭现在额外产生 10 点怒气。'),
