(706189, '使你造成的暗影伤害提高4%，治疗量提高4%。'),
(706190, '使你的最大法力值、移动速度和坐骑移动速度提高15%。'),
(706201, '施放地震技能现在也会获得 2 层大地之怒。'),
(706203, '使恩赐和本能的效果提高10%。'),
