(706209, '使你的法术暴击伤害提高100%。'),
(706211, '20级被动技能使你的法术暴击等级和治疗效果提高，数值相当于智力值的20%。'),
(706216, '施放地震波后，你在8 秒内的下一次大地母亲之手的怒气消耗降低50%。'),
(706220, '你的副手武器造成的伤害现在有30%的几率向敌人发射一枚晶核。'),
(706230, '用散落星辰造成伤害时，有30%的几率向目标发射一枚灵体，对附近敌人造成（280 × 等级系数 + 13.5% 奥术法术强度）点奥术伤害。'),
