(706258, '你的鲜血护盾现在每5秒还会从你身上移除1个流血效果。'),
(706260, '暴击现在施加魔法气息，持续15 秒，使你的暗影猎犬的下一次暗影跃击冷却时间减少10秒。'),
(706266, '使你的被法术命中几率降低2%，并使憎恨壁垒的吸收量提高10%。'),
