(706312, '天灾克星和猩红之锤造成的伤害现在会额外击中1个附近敌人。'),
(706318, '使辩护的能量消耗降低5。'),
(706320, '誓言的效果提高20%。'),
(706323, '使你对亡灵造成的伤害提高5（随等级提升），并使你抵抗疾病效果的几率提高30%。'),
(706325, '使用定罪、神圣顺劈或信仰之刃造成伤害时，若你在目标近战范围内，则有15%几率触发狂热。'),
(706331, '20级被动技能消耗恶魔之火的伤害技能现在会刷新一层刺穿的充能。'),
(706333, '使你的敏捷提高10%。'),
(706336, '你的举盾冷却时间缩短5秒，能量消耗降低10%。'),
(706338, '使图腾猛击的范围伤害提高30%，但现在额外消耗5点怒气。'),
