(706353, '延长无羁之怒的持续时间 2 秒。'),
(706354, '你的技能暴击现在使战斗活力和厚颅的冷却时间减少1秒。'),
(706357, '使你的耐力提高10点，另外再提高相当于你的敏捷10%的耐力。'),
(706359, '提高你的招架和躲闪几率3%。'),
(706365, '施放释放猎犬现在有25%的几率额外召唤一只次级暗影猎犬，持续15 秒。'),
(706368, '减少你的巫毒消耗50%，并提高力量巫祝的效果20%。'),
(706369, '放置一个灵魂链接神像，持续14 秒。图腾每2秒重新分配所有小队和团队成员的生命值，使每个玩家最终拥有相同百分比的最大生命值。\n\n同时只能激活一个神像。'),
(706370, '你的枯萎造成伤害时，有15%几率额外造成一次暗影伤害。'),
(706375, '减少黏性炸弹和部署爆破地雷的冷却时间2秒。'),
(706379, '你或你的召唤物造成的直接有害技能暴击现在恢复你最大法力值的4%。'),
(706385, '你的定罪现在为你恢复相当于造成伤害75%的生命值。'),
