(706449, '你的祝福现在施法时间为1.5秒，但治疗效果提高100%。'),
(706455, '对受昏睡影响的敌人施加真菌感染，在3 秒内额外造成相当于毒液箭或毒蛇之牙伤害20%的自然伤害，最多叠加2层。'),
(706458, '飓风和燃刃斩对生命值低于20%的敌人造成的伤害提高50%。'),
(706464, '你现在向附近盟友散发温暖，为附近生命值最低的盟友恢复相当于你周期性伤害25%的生命值。'),
(706468, '30级被动技能使用圣契现在可以移除守誓者的70%延迟伤害。'),
(706472, '你的耐力提高5%。\n\n你的法术强度提高，数值相当于你的复活的仆从耐力总值的15%。'),
(706477, '毒蛇之牙现在最多额外治疗5名附近盟友；万能溶剂也会额外治疗一名附近目标。'),
(706481, '等级50被动使你的体型增大7%，并使你的近战攻击强度提高相当于力量75%的数值。'),
(706482, '20级被动技能使你的法术伤害提高，相当于精神属性的50%，并使你的法术命中等级提高，相当于精神属性的5%。'),
(706483, '50级被动技能对生命值高于80%或低于20%的敌人，你的暴击伤害提高15%。'),
(706488, '你的模仿守卫现在额外召唤1个模仿守卫，且其持续时间增加3秒。'),
(706501, '肉锯造成的伤害现在忽略目标10%的护甲。'),
(706502, '造成的伤害现在有 15% 的几率获得一层恐惧。\n在 10 层时，你的下一次肉锯将转化为湮灭，持续 8 秒。'),
(706514, '格挡一次攻击会使你获得一层典范，持续10 秒。每0.5秒只能触发一次。\n\n当叠加至10层时，你的重击将转化为典范猛击，持续10 秒。\n\n施放重击会立即获得3层该效果。'),
(706515, '你的盾牌挑衅不再有冷却时间，但现在消耗10点额外能量。'),
(706518, '减少相位遁形的冷却时间30秒，并移除其法力消耗。'),
(706523, '你的元素迸发和符文剑现在有20%的几率立即触发你的武器铭刻。'),
(706531, '用符文爆炸击中至少5个敌人现在会释放狂野蒸汽。'),
(706538, '增加停滞守卫昏迷效果的持续时间1秒。'),
(706542, '在你附近放置一个诅咒雕像，持续15 秒。\n\n15码范围内的敌人无法造成暴击。\n\n同时只能激活1个雕像。'),
(706543, '在暗影化身持续时间结束时，你变成一个次级暗影化身。'),
(706544, '每1秒提高10%的魔法伤害，并减少精魂飞刃的冷却时间20%，持续8 秒。'),
(706545, '从你的丛林蘑菇中使用的大锅现在跳动速度快2秒。'),
(706551, '恶意妖咒的每跳伤害使对敌人的下一跳伤害提高3%，可叠加10层。'),
(706555, '移除30码范围内小队和团队成员的所有中毒、疾病和诅咒效果，并在3 秒内免疫此类效果。'),
(706557, '恶咒箭造成的伤害现在使目标受到的治疗效果降低20%，持续10 秒，可叠加2层。'),
(706558, '当无羁之怒激活时，你的攻击现在忽略目标20%的护甲。'),
(706563, '盾刺猛击造成暴击时，会释放地狱火爆发，造成（20% 攻击强度 + 111 × 等级系数）点火焰伤害，并额外生成1层恶魔之火。'),
(706564, '使你从物品获得的护甲值提高 10%，并强化你的盾牌，使格挡攻击时受到的伤害额外降低 20%。'),
(706565, '你的地狱火小鬼现在有20%的几率在命中时发射一枚火弹，造成（40% 力量）点火焰伤害，并降低敌人攻击强度11.5点，持续10 秒。'),
(706566, '每消耗一层灌注，恶魔之火的持续时间延长 2 秒。'),
(706569, '每个激活的地狱火小鬼现在使你的格挡几率提高 1%。\n\n此外，你的格挡几率始终提高 5%。'),
(706572, '使星火射击和月神之矛造成的暴击伤害提高15%。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (706574, 706575, 706576, 706577, 706589, 706590, 706598, 706599, 706603, 706605, 706613, 706617, 706619, 706622, 706624, 706625, 706628, 706629, 706630, 706632, 706633, 706634, 706636, 706637, 706639, 706647, 706650, 706653, 706656, 706660, 706661, 706670, 706671, 706672, 706674, 706680, 706683, 706692, 706695, 706722, 706725, 706731, 706735, 706741, 706742, 706748, 706754, 706755, 706756, 706758, 706777, 706779, 706784, 706785, 706788, 706790, 706792, 706793, 706795, 706804, 706806, 706807, 706821, 706823, 706858, 706859, 706860, 706862, 706867, 706872, 706875, 706877, 706878, 706886, 706889, 706893, 706894, 706896, 706904, 706909, 706911, 706915, 706917, 706921, 706926, 706928, 706937, 706938, 706940, 706942, 706945, 706948, 706953, 706955, 706956, 706962, 706969, 706973, 707001, 707006, 707007, 707014, 707028, 707044, 707053, 707054, 707055, 707064, 707067, 707072, 707077, 707078, 707079, 707081, 707104, 707113, 707115, 707116, 707126, 707137, 707141, 707149, 707150, 707153, 707157, 707162, 707168, 707173, 707175, 707204, 707207, 707209, 707212, 707217, 707220, 707224, 707230, 707232, 707233, 707234, 707237, 707239, 707240, 707244, 707246, 707249, 707252, 707253, 707254, 707256, 707257, 707258, 707259, 707260, 707262, 707265, 707269, 707271, 707273, 707277, 707278, 707283, 707305, 707310, 707317, 707319, 707320, 707325, 707329, 707331, 707364, 707365, 707367, 707371, 707372, 707380, 707382, 707385, 707388, 707389, 707390, 707391, 707395, 707398, 707403, 707405, 707407, 707410, 707413, 707414, 707416, 707417, 707418, 707421, 707423, 707429, 707430, 707432, 707433, 707434);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(706574, '月神之矛和幽暗之刃使敌人从散落星辰受到的伤害提高10%，持续10 秒。'),
(706575, '你的伤害性暴击现在使你获得一层星辰门徒。'),
(706576, '使收割与群鸦杀戮的伤害提高 25%。'),
(706577, '当暗影化身激活时，精魂飞刃的冷却时间现在每1秒减少20%。'),
(706589, '以寇尔萨兹的力量标记一名盟友，使其力量提高3点，火焰抗性提高5点，持续30 分钟。'),
(706590, '周期性伤害和治疗有10%的几率获得一层恶魔之火。'),
(706598, '获得拉娜瑟尔的祝福，使你的法术强度提高相当于精神25%的数值，命中等级提高相当于精神4%的数值。'),
(706599, '20级被动技能使你的法术伤害提高，相当于你的耐力和精神总和的25%。'),
(706603, '急速提高5%。'),
(706605, '需要凡人之躯在5 秒内吸取最多3具附近敌方尸体的精华，每0.5秒快速恢复5%最大生命值和怒气［拥有动脉束缚: ，随后爆发，为15码范围内的队伍和团队成员恢复（82.275 + 75.25% 法术强度）点生命值］。\n\n无法在战斗中使用。'),
(706613, '产生5点怒气，然后使你的法术的生命值消耗提高5%［拥有肆意狂乱: ，你的暴击几率提高1%］，并使它们的伤害提高3%。可叠加10层。'),
(706617, '显著提高你的潜行侦测能力。'),
(706619, '提高瓦拉纳的复仇和凯雷塞斯的灾厄的暴击几率 10%。'),
(706622, '你的震击现在会在脚下制造一道裂隙，每2秒额外造成（8% 攻击强度 + 173 × 等级系数）点自然伤害，持续6 秒。'),
(706624, '使血月冲击为标记的盟友恢复（7.7 + 7% 治疗强度 + 8.5% 耐力）点生命值。'),
(706625, '消耗50点静电将你的空气元素转化为更强大的形态，持续15 秒，造成的伤害提高25%，法术急速提高30%。'),
(706628, '增加振奋的持续时间5秒。'),
(706629, '施放［拥有风暴召唤: 气爆；否则： 召唤闪电］现在会使小队和团队成员获得5%的暴击几率加成，持续10 秒。\n\n不与类似效果叠加。'),
(706630, '与一名盟友进行鲜血仪式，使其耐力提高 8 点，持续 30 分钟。'),
(706632, '使所有小队和团队成员近战及远程急速提高10%。不与同类效果叠加。\n\n此外，你的远程攻击技能和自动射击的射程提高10码。'),
(706633, '使队伍和团队成员的攻击强度提高5%。不与类似效果叠加。\n\n此外，你的暴击几率提高3%。'),
(706634, '对一名友方目标施加礼物，使其敏捷提高3点，持续30 分钟。'),
(706636, '你周围 20 码范围内的盟友获得 20% 几率抵抗诅咒。'),
(706637, '你的自动攻击现在有 25% 几率使你能够使用反击，如同你最近格挡了一次攻击。'),
(706639, '使你的最大生命值提高6%。'),
(706647, '当你使用远程引爆时，对10码范围内最多5个敌人造成（187.5 + 25% 攻击强度 + 38.5% 法术强度）点物理伤害。地雷持续1 分钟。'),
(706650, '使你的有益法术被驱散的几率降低30%。'),
(706653, '提高你的精神法术效果 25%。'),
(706656, '你的直接伤害暴击会使目标受到的流血伤害提高30%，持续15 秒。'),
(706660, '使你的湍流之怒和电刑的暴击伤害提高30%。'),
(706661, '洪水造成的伤害每层导电提高5%。'),
(706670, '使燃刃斩、飓风和霜寒斩的暴击伤害提高15%。'),
(706671, '所有火焰、冰霜和自然伤害提高5%，并为符文剑的攻击强度加成提高25%。'),
(706672, '飓风的持续时间延长 1 秒，使其能额外攻击 2 次。'),
(706674, '移除魔网封锁的施法时间，但将其持续时间减少0.5秒。'),
(706680, '当你使用机甲：激光束或机甲：燃烧造成伤害时，现在会对每个被击中的目标发射一枚小型黏性炸弹。'),
(706683, '用撕咬伤口进行治疗现在使突刺的冷却时间减少1秒。'),
(706692, '将哨兵炮台升级为发射榴弹，大幅提高其攻击速度，并在 8 码半径范围内造成 28.55 点火焰伤害，外加在 1.5 秒内额外造成（13 + 8.5% 攻击强度 + 15% 火焰法术强度）点火焰伤害。'),
(706695, '施放黏性炸弹现在会使你的哨兵炮台在下次攻击时发射火箭弹群，对目标 5 码范围内的敌人造成 22.69 点火焰伤害。'),
(706722, '黑暗帝国之怒的伤害提高25%。'),
(706725, '你的魔法伤害提高20%，法力值消耗降低30%，持续8 秒。'),
(706731, '收割生成 1 个灵魂碎片。生成 3 个灵魂碎片可获得 1 层收割之魂；生成 3 层收割之魂可获得灵魂灌注，允许使用强力技能。'),
(706735, '造成的神圣伤害、物理伤害和治疗提高 4%。'),
(706741, '说服你的盟友与黑暗做交易，敏捷提高3点。'),
(706742, '激活盟友玩家身上的能量模块，使其攻击强度提高19，持续30 分钟。\n\n每个地精工程师只能激活一个模块。'),
(706748, '击倒和伏击现在使你对该目标造成的伤害提高15%，持续8 秒。'),
(706754, '你的召唤：地狱火小鬼现在额外召唤2个小鬼。'),
(706755, '将你的召唤：地狱火小鬼转变为小鬼召唤者。'),
(706756, '在目标位置制造恶魔锁链，使其中的敌人减速 80%，持续 5 秒。持续时间结束时，将所有受影响的敌人拉向锁链。'),
(706758, '献祭之环现在会为你提供一个伤害吸收护盾，数值相当于每个被摧毁小鬼总生命值的 15%，持续 10 秒。'),
(706777, '你的加速恢复持续时间延长 6 秒，分解持续时间延长 3 秒。'),
(706779, '使你的逆转伤口、纪元和纠正错误的暴击几率提高8%。'),
(706784, '等级 40 被动：使你的耐力等同于你的护甲穿透等级。'),
(706785, '你的迷失者遗物匣对生命值低于 20% 的敌人必定暴击，伤害提高 25%。'),
(706788, '使幽魂守望者的冷却时间缩短 60 秒，且其治疗量相当于其造成伤害的 200%。'),
(706790, '使收割生成的符文能量额外提高 5 点。'),
(706792, '灵魂突刺与群鸦杀戮造成的伤害现在使幽魂镰刀的冷却时间缩短 1 秒。'),
(706793, '你的幽魂镰刀持续时间延长 10 秒。'),
(706795, '使你的招架几率提高 5%；成功招架攻击现在生成 5 点符文能量。'),
(706804, '你的长矛造成的伤害现在有25%几率使你快速投掷一支额外长矛，造成相当于伤害值40%的伤害。'),
(706806, '你的举盾持续时间延长 1 秒。'),
(706807, '你的百夫长打击和横扫千军现在会额外造成40%的伤害，作为流血效果在2 秒内生效。'),
(706821, '你的近战攻击现在有 15% 的几率获得一层满溢。\n\n此外，你的命中几率提高 5%。'),
(706823, '施放原初轰击现在使原初脉冲的冷却时间缩短 5 秒。'),
(706858, '20级被动技能当你对除自己以外的盟友使用地狱火屏障时，其冷却时间减少15秒。'),
(706859, '烈焰施法现在每层额外提供3%精神。'),
(706860, '地狱烈焰的持续时间延长 5 秒，改为每 5 秒触发一次其持续时间结束时的治疗爆炸。'),
(706862, '使余烬之握的施法时间缩短 0.25 秒，并且使其射程提高 10 码。'),
(706867, '复活一名已死亡的盟友，恢复其70点生命值和135点法力值。\n\n无法在战斗中施放。'),
(706872, '使你的皮肤法术效果提高50%。'),
(706875, '使火雨产生的所有威胁值降低25%，并使其暴击几率提高10%。'),
(706877, '对熔岩碎片目标，烬火之心和烬心的暴击几率提高 6%。'),
(706878, '你的圣印法术效果提高 20%。'),
(706886, '炽燃的持续时间延长 4 秒。'),
(706889, '你的奈萨里奥之焰和爆炸现在对燃烧目标造成的伤害提高 15%。'),
(706893, '终极烈焰现在必定造成暴击，暴击伤害提高 20%，且引导速度加快 0.5 秒。'),
(706894, '爆发现在还会使法术急速和移动速度提高20%，持续10 秒。'),
(706896, '毁灭者之喉的伤害提高 20%。'),
(706904, '建造一个排斥装置，每 5 秒击退附近敌人，持续 20 秒。'),
(706909, '每第3次施放恐怖魔箭会使你的下一次成功施放的恐怖魔箭在3 秒内对目标额外造成初始伤害50%的伤害。'),
(706911, '克苏恩凝视造成的伤害现在有 15% 几率生成一个虚空传送门，在消失前施放克苏恩之凝视、恐怖魔箭或湮灭光束。'),
(706915, '你的命中几率提高 3%，暗影伤害法术产生的威胁值降低 15%。'),
(706917, '使你的法术急速提高4%，并且每10秒回复相当于你缺失法力值10%的法力值。'),
(706921, '你的腐化低语提供的伤害加成提高 5%。'),
(706926, '你现在为受黑血影响的生命值最低的盟友恢复相当于你自动攻击伤害 50% 的生命值。'),
(706928, '你的低语效果提高 25%。'),
(706937, '使沙德拉的祷言和翡翠帷幕的施法时间缩短 10%，并使你在受到伤害攻击时的施法退条缩短 35%。'),
(706938, '你的万能溶剂造成的治疗效果现在会使你的下一次翡翠帷幕变为瞬发法术。'),
(706940, '30级被动技能教你学会织者形态。'),
(706942, '你的剧毒术士周期性伤害效果持续时间延长 3 秒。'),
(706945, '你的毒蛇之牙现在会刷新一层万能溶剂。'),
(706948, '造成暗影伤害现在会使目标从你的骷髅战士处受到的伤害提高 1%，持续 10 秒，可叠加 10 层。'),
(706953, '献祭亡灵的法力消耗和冷却时间降低 20%。'),
(706955, '你的锁甲提供的护甲值提高 25%。'),
(706956, '每当你生成一个蘑菇，腐烂的冷却时间就缩短 1 秒。\n\n此外，使腐烂影响的目标数量提高 5 个。'),
(706962, '施加1层孵化印记。向敌人注入致命毒液，每 3 秒造成（16 + 20% 自然法术强度）点自然伤害，持续 21 秒。造成的伤害会随时间逐渐提高。'),
(706969, '3层充能，15秒充能时间使敌人的移动速度降低60%，持续8 秒。'),
(706973, '标记一个敌人的位置，在 3.5 秒后将其拉回标记处。'),
(707001, '亡灵仆从造成的伤害有 10% 几率对最多 3 个附近敌人造成（71 × 等级系数 + 30% 法术强度）点瘟疫伤害。'),
(707006, '巫妖寒霜的伤害提高 10%，其产生的符文能量提高 25%。'),
(707007, '召唤不安的亡者起身并向前行进。\n\n当它们抵达敌人时会发生爆炸，对附近敌人造成（700 × 等级系数 + 75% 法术强度）点瘟疫伤害，并使其移动速度降低 70%，持续 3 秒。'),
(707014, '变形为狂暴食尸鬼，急速提高40%，持续10 秒。免疫移动减速效果。'),
(707028, '使内爆的冷却时间缩短 10 秒。'),
(707044, '用即将到来的风暴幻象惊扰敌人，使其恐惧10 秒。每次只能影响1个敌人。\n\n造成的伤害可能会中断该效果。'),
(707053, '施放放电现在会使你的移动速度提高20%，持续6 秒，可叠加2层。'),
(707054, '电刑的伤害和暴击几率提高15%。'),
(707055, '对受到你的召唤闪电影响的目标，托里姆之臂和伏特的暴击几率提高15%。'),
(707064, '等级 10 被动手持双手武器时的自动攻击现在有 25% 的几率触发不死之握，从目标身上吸取（10.2 + 10% 攻击强度 + 15% 法术强度）点生命值。'),
(707067, '夜刃现在会消耗暗影烙印，造成50%的额外伤害。'),
(707072, '等级 10 被动：允许双持，并可在每只手上装备双手锤、双手剑或长柄武器，命中几率提高 6%。'),
(707077, '直接治疗使目标的护甲提高 10%，持续 20 秒。'),
(707078, '白天造成的神圣伤害提高 10%，受到的周期性伤害降低 10%。'),
(707079, '施放列王之锤时，暴击几率提高 10%，持续 10 秒。'),
(707081, '履行誓言时，对目标释放光链，造成（86 + 10% 攻击强度 + 23% 神圣法术强度）点神圣伤害，并跳转至最多 5 名额外敌人，每次跳转伤害递减。'),
(707104, '在目标位置创建一个宏重力区域，持续8 秒。\n\n区域内的敌人移动速度降低50%，并且每0.5秒获得1层宏观重力效果。'),
(707113, '使抹除可额外叠加一层，并提升你的死亡法术射程20%。'),
(707115, '40级被动技能使你的机甲效果提高100%。'),
(707116, '幽魂镰刀与幽魂守望者造成的伤害现在使幽魂守望者的冷却时间缩短 0.5 秒。'),
(707126, '使法术燃烧的冷却时间缩短4秒，持续时间延长1秒。'),
(707137, '在举盾激活时格挡一次攻击会使你的最大生命值提高（299.15 + 11% 攻击强度 + 10% 耐力），持续15 秒。'),
(707141, '3层充能，6秒充能时间用刻有符文的刀刃斩击敌人，造成（21 + 30% 攻击强度 + 30% 法术强度）点元素伤害。'),
(707149, '迅捷符文的冷却时间延长 30 秒，但现在会在持续时间内为路径上的盟友施加潜行效果。'),
(707150, '飓风的每次攻击现在必定在激活时对目标施加武器铭刻：流水或武器铭刻：寒冰。'),
(707153, '区域内的敌人每 1 秒额外受到（97 + 13.5% 攻击强度）点自然伤害。'),
(707157, '在符文纹饰：大地状态下，你每 4 秒恢复最大生命值的 3%，并免疫击退效果。'),
(707162, '召唤一个仿生守卫，持续12 秒。在持续时间内，当你施放［拥有暗影猎手: 恶咒箭；否则： 恶咒之怒］［拥有暗影猎手: , 精魂回收,］和洛阿之酿时，该守卫也会对目标施放这些技能。\n\n仿生守卫可以与其他守卫同时激活。'),
(707168, '使模仿守卫和精魂的持续时间延长4秒。'),
(707173, '使地震对敌人的减速效果提高 30%。'),
(707175, '施放命令法术现在有15%的几率使你的下一个巫妖寒霜或枯萎免费且变为瞬发。'),
(707204, '当闪电牢笼激活时，你受到的魔法伤害降低 25%，并且无法被远程攻击命中。'),
(707207, '使你的旋进范围提高 3 码。'),
(707209, '变身为一个恶毒之灵，持续 30 秒，使你可以在移动时施放恶咒之怒和厄运巫咒，并每 2 秒定期获得一个精魂。'),
(707212, '当你用洛阿之酿进行治疗时，你的图腾现在会额外治疗 20 码内的一个盟友，治疗量为治疗量的 35%，优先治疗生命值较低的盟友。'),
(707217, '40级被动技能消耗余烬现在有30%的几率重置毁灭者之喉和火雨的冷却时间，并为你提供死亡之翼的遗产。'),
(707220, '召唤闪电打击一名敌人及其附近的敌人，造成（406 + 65% 奥术法术强度）点法术风暴伤害，并刷新被击中敌人身上的伏特持续时间。\n\n对受到伏特影响的敌人造成的伤害提高 50%。'),
(707224, '霉菌病会使你的真菌人进入狂怒，持续6 秒，使其伤害和攻击速度提高30%。'),
(707230, '你的流星索投掷现在有2层充能，造成额外伤害，持续时间延长2秒，但消耗10点怒气而非法力值。'),
(707232, '你的灌注现在使你的移动速度提高 20%。'),
(707233, '周期性伤害现在有 8% 的几率向你的目标射出蛛网，将其缠绕在窒息之环中。'),
(707234, '向一名敌人发射蛛网束，每1秒造成（91 × 等级系数 + 12% 自然法术强度）点自然伤害，持续4 秒。\n\n4 秒后，如果目标身上存在孢子，则在其脚下生成一个蘑菇，2秒后爆炸，对5码范围内的所有敌人造成（303 + 12.5% 自然法术强度）点自然伤害。'),
(707237, '当你炸弹投掷时，你的哨兵炮塔会向目标喷射火焰，对 30 码直线上的敌人造成（89.75 + 12% 远程攻击强度 + 40% 火焰法术强度）点火焰伤害。'),
(707239, '爆炸强化和追踪强化造成的伤害现在有 50% 的几率对敌人额外施加一层凝固汽油弹。'),
(707240, '当你在一个目标身上叠加 5 层凝固汽油弹时，会刷新 1 层建造：烈焰无人机。'),
(707244, '当火箭发射器对受黏性炸弹影响的敌人使用时，现在必定暴击。'),
(707246, '充能待发现在也使火箭发射器的暴击几率提高 20%。'),
(707249, '每第4次废料射击现在会使你在 15 秒内的下一次废料射击的伤害提高 25%。'),
(707252, '使火箭发射器的射程提高10码。'),
(707253, '使火箭发射器的暴击伤害提高10%。'),
(707254, '你的废料射击现在对燃烧目标造成伤害时，忽略目标 25% 的护甲。'),
(707256, '火罐无人机和废料射击现在对敌人每层凝固汽油弹效果造成 2% 的额外伤害。'),
(707257, '在目标位置建造一个溢油塔，持续10 秒，在8码范围内溢出石油，使敌人的移动速度降低60%，并使他们受到的你的火焰伤害提高15%。\n\n粘性炸弹爆炸和火罐无人机对内部的敌人造成20%额外伤害。'),
(707258, '建造：蜘蛛炸弹现在会额外制造一个蜘蛛炸弹冲向你的目标。'),
(707259, '使机械协同可额外叠加2层，且使用火箭发射器现在会使你的哨兵炮台也施放火箭发射器。'),
(707260, '施放黏性炸弹现在会使你在 10 秒内的下2次废铁射击的施法速度提高 50%，伤害提高 25%。'),
(707262, '你的粘性炸弹爆炸和蜘蛛炸弹现在在只击中一个目标时造成 30% 的额外伤害。'),
(707265, '你的哨兵炮台造成的伤害现在会使敌人移动速度降低10%，持续8 秒，可叠加3层。'),
(707269, '使废料射击的伤害提高 15%，并使你的命中几率提高 2%。'),
(707271, '30级被动技能施放建造：蜘蛛炸弹现在会重置炸弹投掷的冷却时间，并使你在15 秒内的下一次炸弹投掷不触发冷却时间、公共冷却时间或消耗。'),
(707273, '50级被动当狂轰滥炸激活时，你的投掷炸弹还会使黏性炸弹的冷却时间减少5秒。'),
(707277, '施放废料射击现在会为你的激活宠物和机械协同叠加一层哨兵炮台。'),
(707278, '伤害提高 5%，急速提高 3%，可叠加 3 层，持续 6 秒。'),
(707283, '你的憎恶和腐朽巨像造成的暴击现在会啃咬你的目标，对其造成（150 + 112.5% 法术强度）点伤害。'),
(707305, '怨灵之刃现在额外造成 100% 武器伤害，且其符文能量消耗降低 20 点。'),
(707310, '百夫长打击现在对受投网影响的敌人必定暴击。'),
(707317, '提高净化者之刃和烈焰审判的法术强度加成，提高 25%。'),
(707319, '施放本能现在还会额外恢复 40 点集中值，并确保你在 20 秒内的下3次穿颅者或突击必定造成暴击。\n\n此外，本能现在还会使你获得相当于敏捷值 10% 的近战攻击强度。'),
(707320, '40级被动使你的法术伤害提高攻击强度的30%，并允许喷出造成的周期性伤害造成爆击。'),
(707325, '你的守护巨龙的祝福现在会影响额外 2 次诺兹多姆的回响的施放，但其冷却时间翻倍，且法力值消耗提高 50%。'),
(707329, '将瑟拉图斯的召唤转化为蝰蛇守卫。'),
(707331, '你的厄运巫咒和咒火现在会额外击中2个附近的敌人。\n\n暗影闪爆对受到傀儡师的丝线影响的敌人造成的伤害提高50%。'),
(707364, '施放祝福现在会使你的下一次神殿守护者的消耗降低 50%，持续 6 秒。'),
(707365, '使目标区域内的所有机械敌人过载，使其迷惑，持续 40 秒（对玩家为8秒）。'),
(707367, '施放原初撕碎现在强化你的宠物，使其自动攻击最多击中 4 个附近敌人，造成 21 秒点伤害。'),
(707371, '将鲜血护盾提供的护甲加成提高 40%。'),
(707372, '击杀一个提供经验值或荣誉值的敌人现在恢复你20点能量。\n\n每5秒只能触发一次。'),
(707380, '减少致残射击的冷却时间4秒。'),
(707382, '寡妇之吻的爆击现在会施加1层额外的孵化印记。'),
(707385, '施放坚韧圣契现在还会为你恢复20%的最大生命值。'),
(707388, '提高刺穿的暴击几率 30%，并提高你的武器技能 5 点。'),
(707389, '倒刺标枪的暴击现在会触发血之诞生。'),
(707390, '30级被动技能使用刺穿造成暴击时，现在额外产生1层恶魔之火。'),
(707391, '近战伤害现在有 20% 的几率额外攻击 2 次，造成 30% 的伤害作为神圣伤害。'),
(707395, '施放机甲技能现在会使你的宠物进入失控状态，持续 6 秒。'),
(707398, '使纳米机器人重构的生效频率和治疗效果提高20%。'),
(707403, '机甲：燃烧和机甲：激光束造成的伤害现在有 40% 的几率额外攻击 2 次，造成 30% 的伤害。'),
(707405, '提高恶咒之怒、暗影闪爆和厄运巫咒的法术强度加成 20%。'),
(707407, '40级被动\\r\n\\r\n受到伤害会使你的攻击强度提高，最高相当于最大生命值的 20%。\\r\n\\r\n对恶魔和不死生物时进一步提高。\\r\n\\r\n该效果会随时间缓慢衰减，并且在脱离战斗时也会衰减。'),
(707410, '施放无羁之怒现在为你恢复 30 点能量，并在激活期间移除你的灵魂技能的能量消耗。'),
(707413, '你的掌印现在额外影响 1 次伤害。'),
(707414, '激活黎明时，光辉、女武神的召唤和太阳猛击的冷却时间缩短 10%。'),
(707416, '在邪能锻造激活时使用的邪能铸造现在造成 30% 的额外伤害。'),
(707417, '提高你的近战和远程急速 5%。'),
(707418, '减少生存药剂的冷却时间 25%。'),
(707421, '在10 秒内，你的亡灵仆从的暴击几率提高4%，可叠加3层。'),
(707423, '施放符文帷幕现在使你的移动速度提高 75%，持续 3 秒。'),
(707429, '你的群体梦魇在 80 点狂乱或以上使用时，现在会触发 60 秒的冷却缩减。'),
(707430, '将你的时光魔杖转变为时光撕裂。'),
(707432, '30级被动你的治疗暴击现在为盟友恢复回能。\n\n此外，战斗中有20%的法力回复速度保持生效。'),
(707433, '怜悯的生效频率提高 50%，但法力消耗提高 100%。'),
(707434, '当你经过时，恢复你缺失生命值的3%以及5点怒气，并获得一层黑暗施法效果，持续1 分钟，最多叠加10层。');

