INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(707435, '塔达拉姆的折磨造成的伤害现在有20%的几率引发内部破裂，使其对目标附近所有敌人额外造成一次伤害。'),
(707444, '30级被动技能施放切割后，你的下一个邪能火球变为瞬发，并根据引导时间对主目标附近的额外1个敌人造成伤害，最多可影响10个敌人，每击中一个目标造成的伤害递减。'),
(707445, '减少活化：骷髅弓箭手和命令：钩子的冷却时间 20%。'),
(707451, '降低地狱烈焰的治疗效果20%，但提高其触发几率50%。'),
(707455, '对生命值低于 20% 的目标使用逐死者时，效果结束时它会重新施加，直至目标死亡或 5 秒过去。'),
(707460, '当你激活一个掌印时，你接下来的3次攻击或持续10 秒内必定暴击，且暴击伤害提高20%。'),
(707463, '施放相位遁形现在会召唤10个你的分身，它们会向随机方向奔跑5 秒。\n裂隙分身会周期性爆炸，对周围5码内的所有敌人造成（19.5% 攻击强度）点奥术伤害。'),
(707479, '时光化身造成的伤害现在会为你恢复相当于伤害值200%的生命值。'),
(707482, '提高热血沸腾的触发几率30%。'),
(707493, '施放毁灭者之喉现在获得2层烈焰施法。'),
(707494, '减少喷发的冷却时间 30 秒。'),
(707503, '炽燃的持续时间现在根据施放时拥有的余烬数量延长 1 秒。'),
(707504, '每个激活的精魂使你在施放恶咒箭时有15%几率额外产生一个精魂。'),
(707505, '提高咒火的暴击几率和暴击伤害，数值为25%。'),
(707513, '你的［拥有邪能突进: 邪能突进；否则： 混沌冲刺］现在使你的能量恢复速度提高10%，持续5 秒，可叠加2层。'),
(707514, '减少你的地震技能的冷却时间 2 秒。'),
(707515, '在地狱火形态激活期间，你的追踪烈焰现在没有冷却时间，且造成的伤害提高 25%。'),
(707517, '辉耀连锁对受赐福影响的盟友必定暴击。'),
(707528, '履行恩典誓言时，还会使被触发技能的冷却时间缩短 10%。'),
(707534, '每次你生成一朵绿色梦花时，获得1层高地人。'),
(707535, '30级被动使你的火焰法术伤害提高，相当于敏捷的50%，并使你的攻击强度提高，相当于智力的100%。'),
(707541, '你周身散发出光环，使小队和团队成员获得390点护甲值。\n与同类效果不叠加。'),
(707542, '由传导造成的伤害现在有 60% 的几率召唤一颗雷霆宝珠。'),
(707543, '消耗10点静电命令你的空气元素，使其下一次伤害对目标释放一阵狂风，在21 秒内造成（430.5 + 140% 自然法术强度）点自然伤害，并降低其抗性18.8542点，同时使其受到的魔法伤害提高2%。'),
(707546, '施放烈风现在会使你的空气元素施放烈风。\n\n此外，你周围会散发一道光环，使小队和团队成员的护甲值提高390点。\n\n不与类似效果叠加。'),
(707548, '减少气爆的施法时间 0.3 秒。'),
(707551, '提高时光魔杖和工艺师的魔杖的伤害，数值为10%。'),
(707553, '减少时光撕裂的冷却时间 2 秒，并延长分解的持续时间 3 秒。'),
(707555, '选定一个敌人并将其放逐到次元口袋中，持续5 秒，使其被放逐并免疫所有伤害。\n\n在持续时间结束前再次激活此技能，可在20码范围内为该敌人选择一个新的位置。'),
(707556, '使你的法术消耗降低5%，并使你的法术被驱散的几率降低15%。'),
(707557, '对减速敌人造成的伤害提高，数值为15%，影响多彩碎片、熔解现实和瓦解。'),
(707560, '你的晶石弹幕现在会为20码内的所有盟友恢复相当于造成伤害10%的生命值。'),
(707562, '当你杀死一个提供经验值或荣誉的敌人，或使用冰霜伤害造成暴击时，现在获得一层冰封之躯。'),
(707563, '你的自然伤害提高5%，治疗效果提高3%。'),
(707574, '使草本万用膏的冷却时间缩短2秒，并在持续时间结束时提高50%的治疗效果。'),
(707583, '提高猛攻的持续时间，持续6秒。'),
(707584, '快速向目标投掷3次狂暴投掷，然后向后飞跃一大段距离，造成125%的远程武器伤害，伤害受狂战飞斧的修正效果影响。'),
(707588, '冰霜法术的暴击现在返还3%的最大法力值。'),
(707604, '你的克苏恩凝视现在会额外打击1个附近的敌人。'),
(707606, '施放正义剧变或信仰之刃现在会赋予你誓言：惩戒并开始你的誓言锁链。'),
(707613, '每层逐日之行使光耀的暴击几率提高 15%。'),
(707614, '使你从造成的伤害中获得的怒气值提高20%。'),
(707615, '用风的力量强化你的部分法术，将你的召唤风暴转化为上升气流，并将召唤闪电转化为气爆。'),
(707616, '等级50 被动晶石弹幕或晶洞造成的伤害现在有5%的几率使你获得大地化身，持续5秒。\n如果大地化身已激活，触发此效果将改为延长其持续时间5秒。'),
(707617, '40级被动使用魔精光束进行治疗时，现在会为最多2名附近生命值最低的盟友恢复相当于治疗量50%的生命值，并且施放该技能会使盟友获得回能。'),
(707618, '风暴升腾现在额外使你获得闪电之主，持续20 秒。'),
(707619, '用风暴破击驱散一个魔法效果时，现在为你恢复最大生命值的3%。'),
(707620, '50级被动直接伤害造成的爆击现在会为你施加原始起源，可叠加10层。\n\n达到10层时，消耗所有层数，并使喷出的冷却时间缩短3秒。'),
(707621, '50级被动使用举盾、推进或战斗冲锋后，你将获得高位防御。'),
(707622, '当你突刺向一名敌人时，现在为你恢复最大生命值的5%。'),
(707623, '当生命值低于75%时，你造成的所有伤害现在为你恢复3%的生命值。'),
(707624, '使你周围5码内的敌人受到的物理伤害提高3%。'),
(707626, '鲜血契约的效果提高50%。'),
(707627, '对感染巫妖寒霜的目标，你的巫妖冰霜造成的伤害和暴击伤害提高 30%。'),
(707629, '格挡攻击时，有 30% 几率获得持续 4 秒的列王之锤。若已激活，则延长 4 秒。'),
(707631, '获得一层恶魔之血时，有5%的几率以一半效果释放你激活的瘟疫。'),
(707632, '你的燃烧之刃现在额外影响4次攻击。'),
(707633, '30级被动技能使你的攻击强度提高，数值相当于力量值的40%。'),
(707634, '你的幽魂守望者现在会让你额外召唤 2 名幽魂守望者，但其持续时间缩短 8 秒；此外，幽魂守望者提供的护盾吸收量提高 100%。'),
(707635, '星界之刃的暴击现在额外造成2次打击，第一次造成40%的伤害，第二次造成20%的伤害。'),
(707636, '减少星界之刃的冷却时间，减少4秒。'),
(707637, '施放星辰汇聚现在会重置艾露恩祷言的冷却时间。'),
(707638, '20级被动技能你现在被动获得月相的速度加快1秒。'),
(707639, '施放星火射击时，有20%的几率使你获得艾露恩之弦，持续5秒。'),
(707640, '帝国之刃现在有30%的几率使你的下一次自动攻击造成两次伤害。'),
(707648, '折磨者和诅咒的怒气消耗降低20%。'),
(707650, '在模仿守卫激活期间，你获得 15% 远程急速提高，并且你的精魂回收会转化为精魂齐射。\n\n每个精魂现在使精魂齐射的伤害提高 2%。'),
(707652, '使40码内盟友的最大法力值、怒气、能量、集中值和符文能量提高3%。'),
(707653, '切换到符文纹饰：空气时，现在立即移除你身上的1个移动减速效果。'),
(707654, '使极寒冲击的法术强度加成提高50%，但施法时间增加1秒。\n\n此外，极寒融合现在对目标累积的伤害提高10%。'),
(707656, '施放加速时，现在总是额外使你的治疗法术的施法时间缩短20%。'),
(707657, '纠正错误造成的过量治疗现在对盟友施加一个持续治疗效果，在5 秒内恢复相当于治疗量30%的生命值。'),
(707661, '将你的投掷武器转化为投掷标枪，并使投掷标枪的暴击几率提高5%。'),
(707663, '移除祝福的冷却时间，但使其能量消耗提高10。'),
(707666, '你的［拥有盾刺猛击: 盾刺猛击；否则： 地狱火打击］现在会召唤一只地狱火小鬼协助你战斗，持续10 秒，但其怒气消耗提高10。\n\n此外，你的小鬼最大生命值提高30%。'),
(707668, '强化蜘蛛形态为育巢领主，使你的孵化印记消耗技能向目标发射蛛网，附着目标持续10 秒。\n\n每个被蛛网缠住的目标移动速度降低25%。\n\n对缠网目标造成爆击时，召唤1只小蜘蛛协助你战斗，持续8 秒。'),
(707670, '你的复活法术的施法时间缩短15%。'),
(707671, '为一名友方目标注入巫毒之力，使其近战和远程攻击强度提高30点，持续30 分钟。\n同一目标同时只能受到一种巫祝效果的影响。'),
(707684, '与盟友缔结魔法契约，使其法术强度提高25点。'),
(707689, '与盟友缔结魔法契约，使其法术强度提高28点。'),
(707693, '以布劳缪克斯之力标记一名盟友，使其法术强度提高25点，暗影抗性提高15点，持续30 分钟。'),
(707707, '直接伤害暴击现在额外生成 1 个灵魂碎片。'),
(707716, '律法之锤造成的伤害现在使受影响的敌人造成的伤害降低10%，持续8 秒。'),
(707719, '顺风常伴，推动你移动更快，使你的移动速度和坐骑移动速度提高15%。'),
(707721, '使你抵抗中毒效果的几率提高，并使你身上的中毒效果持续时间缩短 30%。'),
(707726, '使沙德拉的祷言和翡翠帷幕的暴击治疗提高 25%。'),
(707738, '召唤亡者，移除所有复活法术和活化的法力消耗和施法时间，持续10 秒。'),
(707739, '减少尸体爆炸的符文能量消耗，减少20。'),
(707744, '在目标背后造成直接暴击时，使你的急速提高15%，持续5 秒，或持续你的下2次攻击。'),
(707747, '移除泽克沃兹之握的冷却时间，但使其法力消耗提高25%。'),
(707751, '50级被动对星火射击的目标，你的强击和强击的暴击几率与暴击伤害提高 25%。'),
(707753, '当你的狂乱值高于40点时，触发黑暗启示的几率提高10%。'),
(707754, '使你的移动速度提高，并使你受到的移动减速效果持续时间缩短10%。'),
(707762, '减少碾压的冷却时间，减少5秒。'),
(707763, '你的狩猎本能令附近的敌人感到不安，使其移动速度降低20%，并使其在潜行或隐形状态下也能被看见。\n\n 你每次只能激活1个灵魂法术。'),
(707764, '你的灵魂以战斗的碰撞为食，使附近敌人的资源消耗提高15%，并使直接受到的伤害有几率恢复10点能量。\n\n 你同时只能激活1个灵魂法术。'),
(707767, '祝祷的效果提高 20%。'),
(707775, '你凶猛的战斗意志削弱了附近的敌人，使其攻击力降低32。\n\n 你每次只能激活1个灵魂法术。'),
(707810, '地震的持续时间延长3秒，且其造成的伤害提高25%。'),
(707832, '你的模块效果提高20%。'),
(707835, '所有骑乘战斗技能的冷却时间缩短20%。'),
(707854, '将你的恶咒之怒转化为恶咒箭。'),
(707855, '恶咒箭的冷却时间缩短2秒。'),
(707876, '40级被动技能你的符文剑和原初轰击现在有35%的几率使你获得压倒性能量，重置符文烙印的冷却时间。'),
(707885, '装备长柄武器时，触发武器技艺的几率及其造成的伤害提高25%。'),
(707888, '提高锯齿射击的伤害30%。'),
(707899, '在 20 码内有目标时施放收割时刻，会释放鲜血狂乱。'),
(707900, '立即恢复最大怒气的50%，消耗生命值作为代价。'),
(707901, '产生1层邪能之怒对一名敌人释放火焰，使其受到的火系伤害提高，并且你对其施放火焰法术造成暴击的几率提高20%，持续18 秒。\n同一时间只能对目标施加1个灾厄效果。'),
(707902, '产生1层邪能之怒对一名敌人释放暗影魔法，使你对他们的暴击几率提高50%，但他们的伤害输出提高25%。持续3次暴击或15 秒。\n同一时间只能对一个目标施加1个灾厄。'),
(707903, '产生1层邪能之怒对一名敌人释放残酷魔法，使你忽略其15%的护甲，并在1 分钟内可看到潜行或隐形的该敌人。\n同一目标只能同时拥有1个灾厄效果。'),
(707907, '提高撕裂和献祭光环的伤害20%，并降低其消耗20%。'),
(707908, '幽魂武器额外造成的冰霜伤害提高 10%。'),
(707909, '使灵魂重击的持续时间延长 1 秒。'),
(712289, '在6层时，受影响的敌人将被眩晕，持续6 秒。'),
(712299, '给敌人烙下印记，用每把武器造成（10 + 28% 攻击强度 + 15% 法术强度）点火焰伤害，并将敌人标记 8 秒。'),
(712308, '霜寒斩的暴击现在使你接下来的15 秒内的下一个法术施放时视为目标处于冻结状态。'),
(712312, '使用精魂之蚀后，你在15 秒内的下一次暗影闪爆的伤害提高50%。'),
(712323, '你的下一次［拥有魔网之子: 3］ 符文剑［拥有魔网之子: s］对敌人造成符文爆炸，对附近敌人额外造成（165 + 18.5% 攻击强度）点魔焰伤害。'),
(712325, '持续6 秒，你的符文纹饰迸发，使你触发武器铭刻的几率提高100%。'),
(712326, '用你刻有符文的拳头猛击一名敌人和附近的1名敌人，造成（40 + 55% 攻击强度 + 20% 法术强度）点元素伤害，并触发你的武器铭刻。［拥有显露铭刻: \n\n施放时，你的武器铭刻触发几率提高 20%，持续 5 秒。］'),
(712346, '暴击现在会使守誓者的持续时间减少 1 秒。'),
(712367, '使所有小队和团队成员的攻击强度提高5%。不与类似效果叠加。\n\n此外，使你的敏捷提高10%。'),
(712373, '在目标位置召唤一个强大且攻击迅速的蝰蛇守卫，持续20 秒。\n\n毒蛇守卫有50%的几率释放妖火爆破，对一名敌人造成（216 + 15% 远程攻击强度）点火焰伤害。\n\n几率基于你的远程暴击等级提高。'),
(712383, '获得一层会使活化之血的冷却时间减少1秒，并使你的下一次活化之血生成1条血虫攻击你的敌人。'),
(712389, '2层充能，45秒充能时间在6 秒内，你的符文纹饰会迸发能量，使你触发武器铭刻的几率提高100%［拥有魔法汲取者: ，并使你受到的所有魔法伤害降低1%］。'),
(712396, '提高抵抗魔法和诅咒效果的几率20%。'),
(712429, '战团的持续时间延长 3 秒。\n\n此外，你的第一次使用战团将不会触发冷却时间。每1.5分钟只能触发一次。'),
(712431, '每层活力获得的伤害提高 2%。\n你的宠物伤害有几率强化你的下一次烈风，使其伤害提高 200%。\n\n客户端校对：触发几率引用的法术500032不存在于当前客户端，具体几率待游戏内核对。'),
(712434, '使你下一次冰川冲击的伤害提高3%，持续20 秒，可叠加10层。\n达到10层时，你的下一次冰川冲击将造成暴击，伤害提高50%。'),
(712435, '你的精魂之蚀在撞击时爆炸造成的伤害提高 40%。'),
(712437, '你的禁绝现在会额外攻击附近一个目标。'),
(712458, '为所有小队和团队成员施加巫毒，使其近战和远程攻击强度提高232点，持续30 分钟。\n同一目标只能同时受到一种巫祝效果影响。'),
(712459, '与一名盟友缔结魔法法令，使其法术强度提高 62。'),
(712460, '以布劳缪克斯的力量标记附近的小队和团队成员，使其法术强度提高62点。'),
(712467, '你的战斗气场动摇了附近敌人的意志，使其法术暴击几率降低10%，并使其施法时受到的法术反冲效果提高20%。\n\n 你同时只能激活1个灵魂法术。'),
(712468, '血腥气息令附近敌人胆寒，使其在生命值低于35%时受到物理伤害提高10%，并且你的击杀将赋予你血之诞生效果。\n 你同时只能激活1个灵魂法术。'),
(712471, '减少禁忌仪式的施法时间1秒，并允许黑血最多叠加2层。'),
(712483, '产生1层邪能之怒对一名敌人释放混乱魔法，使其每施放一个法术或技能都会为这个效果叠加1层，持续30 秒。\n效果结束时，根据累积的层数对其造成伤害。\n同一时间只能对一个目标施加1个灾厄效果。'),
(712484, '灵魂重击至少命中 1 个敌人后，会返还其消耗的收割之魂。'),
(712490, '符文大师每层额外造成1%的冰霜伤害。最多叠加8层，持续12 秒。'),
(712673, '北地吐息造成的伤害现在会使敌人的抗性降低 18.8542，并使其受到的魔法伤害提高 2%，持续 8 秒。'),
(712677, '施放神圣挥击现在会使你的近战急速提高 5%，持续 15 秒，可叠加 4 层。'),
(712678, '增加禁绝的持续时间2秒，并增加其冷却时间5秒。'),
(712683, '使灵魂重击的冷却时间缩短 15 秒。'),
(760379, '立即施放正义旋击，接下来 6 秒内每 1 秒施放一次正义旋击。期间可以移动，但无法使用其他技能；不会受到怜悯、悔恨或恐惧的影响，只有被缴械或死亡才能中止。'),
(789256, '使翻越的基础范围提高3码。'),
(800014, '法术急速提高3%，可叠加10层。'),
(800029, '散发光环，使附近盟友的暗影抗性提高5点，并使他们攻击者时造成4点暗影伤害。'),
(800031, '散发一道光环，使附近盟友的暴击几率提高 3%，并对恶魔造成的伤害提高 5%。不与类似效果叠加。\n\n每个玩家同时只能激活一个契约。'),
(800038, '每 2 秒治疗附近盟友（17 + 10% 攻击强度 + 20% 法术强度）点生命值，并对附近敌人造成（18 + 15% 攻击强度 + 40% 法术强度）点伤害。'),
(800039, '圣槌和黎明之盾的暴击几率提高 5%。'),
(800054, '每 2 秒治疗附近的盟友（17 + 10% 攻击强度 + 20% 法术强度）点生命值，并对附近的敌人造成（18 + 15% 攻击强度 + 40% 法术强度）点伤害，持续 10 秒。'),
(800077, '野性打击和毒刺造成的伤害现在会撕裂敌人，使其在9 秒内流血，造成69点物理伤害，可叠加4层。\n\n毒刺造成的伤害现在会将你的周期性效果扩散至10码内的5个敌人，并使其持续时间延长2秒。'),
(800081, '挥动锁链攻击一名敌人，造成（8 + 45% 攻击强度 + 25% 法术强度）点物理伤害，并使其沉默 2 秒，产生大量威胁值。\n\n若成功打断敌人，将返还 20% 的冷却时间。'),
(800083, '产生［拥有蹂躏者: 2；否则： 1］点优势狂野打击一名敌人，造成100%武器伤害外加3点伤害。\n\n若双持武器，则额外用副手武器造成武器伤害。'),
(800084, '荆棘和树叶在你周围旋转，掩盖你的行动，持续10 秒，使你的躲闪几率提高50%，并且躲闪攻击会恢复2%最大生命值和5点集中值。'),
(800086, '产生1点优势散发一道持续30 秒的光环，使小队和团队成员获得5%的暴击几率提升。不与类似效果叠加。\n\n激活时，每1秒产生3点集中值。\n\n所有游侠号角法术共享冷却时间。'),
(800088, '产生 1 点优势散发一道光环，持续 30 秒，使 100 码范围内小队和团队成员的技能资源消耗降低 10%。\n\n激活时，你每 1 秒产生 3 点集中值。\n\n所有游侠号角技能共享冷却时间。'),
(800093, '产生1点优势挥动你的长矛攻击面前的所有敌人，造成 200% 武器伤害，并标记他们，持续 10 秒。\n\n你可以再次激活该技能，将所有被标记的敌人拉到你所在的位置。每拉到一个敌人，就会使你的钩锁射击冷却时间缩短 3 秒。'),
(800094, '使受到的所有伤害降低60%，并使你受到的定身、昏迷和瘫痪效果的持续时间缩短30%，持续10 秒。'),
(800098, '消耗所有静电将自身包裹在电能护盾中，移除并使你免疫所有物理攻击和法术，持续10 秒。\n\n在此期间无法产生静电。'),
(800099, '消耗40点静电灌注闪电之力并向前长距离闪烁，对路径上的所有敌人造成（540 + 50% 法术强度）点自然伤害。\n\n随放电的修正效果而缩放'),
(800103, '使你的伤害和治疗效果提高20%，并每0.5秒产生5点热量，持续15 秒。'),
(800105, '吟唱一道禁忌仪式，为附近所有小队和团队成员施加一个护盾，持续 10 秒，可吸收（225 + 50% 治疗强度）点伤害。'),
(800131, '杀死一名提供经验值或荣誉的敌人，现在会使你获得 5% 护甲穿透和 10% 移动速度加成，持续 5 秒，可叠加 10 层。'),
(800132, '获得盾牌熟练度，装备盾牌时，攻击速度提高40%，盾牌提供的护甲值提高100%。'),
(800133, '以野兽般的狂热咆哮，产生20点怒气，并使你攻击速度提高20%，持续15 秒。'),
(800135, '恢复一名盟友，为其恢复（59 + 20% 攻击强度 + 30% 治疗强度）点生命值。'),
(800137, '移动速度提高25%，闪避几率提高8%。\n\n同一时间只能激活1个祝福。'),
(800140, '双持武器攻击，造成武器伤害外加4点伤害。'),
(800141, '你的原始法术或宠物造成的周期性伤害现在为你产生2点怒气，为你的宠物产生5点集中值。'),
(800144, '冲向一名盟友提供援助，为其恢复（53 + 20% 攻击强度 + 20% 治疗强度）点生命值，并对5码范围内的敌人造成（67 + 20% 攻击强度 + 20% 治疗强度）点自然伤害。'),
(800145, '召唤一只石手抓住目标，使其瘫痪，持续40 秒（对玩家为8秒）。造成伤害会打破该效果。'),
(800146, '唤起内心的侵略本性，使最多3名攻击盟友目标的敌人转而攻击原初者，持续3 秒。'),
(800150, '施放毒性飞镖以及消耗优势层数的技能现在有 20% 的几率在你周围15码内的随机位置生成一朵绿色梦花。\n\n你只能在战斗中生成梦花。'),
(800152, '爆发霍迪尔之力，对附近敌人造成（1361 + 120% 攻击强度）点冰霜伤害，并恢复100%的最大能量值。'),
(800154, '饥渴打击或血牙撕咬的暴击，或使用嚎叫法术，现在会触发暗翼召唤。'),
(800156, '撕咬一名敌人，造成（37 + 26.5% 攻击强度 + 26.5% 法术强度）点物理伤害，并制造一个撕咬伤口。'),
(800157, '拥抱你的永恒诅咒，进入诅咒形态，使你造成的伤害降低 10%，产生的威胁值提高 95%，并且从消耗生命值的法术造成的伤害中额外获得 50% 的威胁值。\n\n激活时，你的装备提供的护甲值提高 400%，总耐力提高 25%。\n\n处于诅咒形态时，你被视为恶魔。'),
(800162, '发射一支致命箭矢，造成（暗影法术强度高于神圣法术强度时：（8 + 17.5% 暗影法术强度）；否则：（8 + 17.5% 神圣法术强度））点暮光伤害，并在 14 秒内额外造成（105 + 206.5% 远程攻击强度）点伤害。'),
(800165, '释放一系列毁灭性的射击，在3 秒内造成（80 + 60% 远程攻击强度）点物理伤害。'),
(800168, '凶残地斩击一名敌人，造成70%武器伤害外加5点伤害。\n\n每消耗一层恶魔之火可造成额外伤害。'),
(800169, '嘲讽一个敌人目标攻击你。'),
(800175, '使你的移动速度提高60%。作用类似于坐骑。'),
(800178, '对一名敌人造成140%武器伤害外加20点伤害。\n\n对8码范围内的最多5个敌人额外造成（10 + 35% 攻击强度）点伤害。'),
(800180, '在你周围 15 码范围内制造一片圣林，持续 16 秒，立即治疗附近所有小队和团队成员（100% 攻击强度 + 2002 × 等级系数）点生命值。\n\n在激活期间，圣林中最多 12 名盟友受到的治疗效果提高 25%，并且每 2 秒恢复已损失生命值、怒气和法力的 3%。'),
(800181, '升华为原始汇聚，使你恩赐的效果提高100%，持续30 秒。'),
(800184, '原初撕碎的暴击为你和你的宠物提供米莎之怒，持续12 秒，使自动攻击额外造成（85 + 12.5% 攻击强度）点物理伤害。\n\n双头飞龙之咬的暴击为你和你的宠物提供雷欧克的愤怒，使近战急速提高2%，持续12 秒，可叠加3层。\n\n野性之爪的暴击为你和你的宠物提供哈弗的速度，使移动速度提高8%，持续12 秒，可叠加3层。'),
(800185, '造成的直接伤害有10%几率向敌人发射一枚晶核。'),
(800188, '使你的敏捷提高8%，躲闪几率提高3%。'),
(800193, '技能暴击现在产生5点能量。'),
(800195, '为附近的小队和团队成员注入巫毒之力，使其资源消耗降低5%。持续30 分钟。\n\n同一目标同时只能激活1个巫祝效果。'),
(800196, '以永恒凤凰之力强化一名盟友，使其智力提高2点，持续30 分钟。'),
(800197, '对友方目标施放野蛮本能，使其攻击强度提高30，持续30 分钟。\n\n每个仪祭师同时只能对一名玩家施加一种本能效果。'),
(800198, '对一名盟友施行坚毅仪式，使其耐力提高 4 点，持续 30 分钟。'),
(800199, '以黑暗敕令强化一名盟友，使其耐力提高8点，持续30 分钟。'),
(800203, '打断施法，阻止目标施放该系法术，持续3 秒，并根据你的精神值吸取目标法力值。\n\n可在移动时使用。'),
(800204, '产生1层邪能之怒向一名敌人冲锋，造成（60 + 28.5% 攻击强度）点物理伤害。'),
(800206, '消耗2层邪能之怒在2.5 秒内蓄力一次强力攻击。\n\n引导结束后，向前方挥砍，根据引导时长用两把武器造成更高的武器伤害，每击中一个目标伤害递减。\n\n心魔：使受影响敌人的近战和远程急速降低20%，持续8 秒。\n\n引导时可闪避和招架，且可在移动时引导。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (800207, 800209, 800210, 800212, 800214, 800220, 800225, 800227, 800231, 800234, 800239, 800260, 800261, 800262, 800266, 800267, 800292, 800311, 800316, 800317, 800319, 800330, 800340, 800341, 800347, 800349, 800352, 800353, 800355, 800357, 800358, 800359, 800360, 800368, 800370, 800386, 800393, 800394, 800401, 800402, 800413, 800416, 800424, 800430, 800432, 800446, 800463, 800474, 800490, 800496, 800497, 800501, 800504, 800505, 800506, 800508, 800600, 800601, 800602, 800611, 800612, 800614, 800617, 800622, 800626, 800637, 800654, 800669, 800685, 800699, 800702, 800703, 800706, 800710, 800722, 800732, 800736, 800752, 800756, 800757, 800758, 800764, 800766, 800772, 800774, 800776, 800780, 800781, 800782, 800785, 800790, 800791, 800796, 800797, 800806, 800807, 800808, 800811, 800816, 800818, 800838, 800841, 800843, 800845, 800848, 800852, 800856, 800857, 800861, 800869, 800870, 800871, 800878, 800880, 800882, 800887, 800892, 800894, 800895, 800899, 800901, 800902, 800905, 800910, 800912, 800914, 800921, 800922, 800926, 800943, 800946, 800995, 800997, 800999, 801002, 801005, 801006, 801016, 801042, 801053, 801054, 801059, 801061, 801063, 801065, 801067, 801069, 801074, 801076, 801086, 801087, 801094, 801096, 801103, 801104, 801106, 801107, 801121, 801123, 801125, 801126, 801127, 801128, 801132, 801134, 801135, 801143, 801145, 801146, 801148, 801153, 801155, 801157, 801165, 801179, 801181, 801191, 801202, 801204, 801205, 801219, 801226, 801231, 801234, 801235, 801242, 801270, 801271, 801277, 801281, 801291, 801292, 801303, 801304, 801312, 801325, 801328, 801335, 801343, 801345);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(800207, '用火焰包裹自己，持续最多1 分钟，每3秒对附近敌人造成（25 + 23% 攻击强度 + 30% 火焰法术强度）点火焰伤害。'),
(800209, '产生1点魔怒强化你的意志，使受到的物理伤害降低30%，持续10 秒。'),
(800210, '产生1层邪能之怒爆发出一阵邪能之怒的旋风，用双武器攻击6码内的所有敌人，造成武器伤害外加10点伤害。'),
(800212, '以恶魔能量强化一名盟友，使其敏捷提高20点，持续30 分钟。'),
(800214, '直接暴击现在有 60% 的几率触发一次邪能打击，并生成一个恶意碎片。'),
(800220, '使地狱鞭挞的冷却时间缩短30秒，现在该技能会影响所有盟友，且作用半径提高15码。'),
(800225, '吞噬古尔丹之颅的精粹，使你的最大生命值和能量提高25%，持续10 秒。'),
(800227, '消耗50点静电在目标区域召唤风暴，立即对敌人造成（25 + 20% 自然法术强度）点初始自然伤害。\n\n在12 秒内额外对区域内的敌人造成（102 + 90% 自然法术强度）点自然伤害。'),
(800231, '以日光轰击一名敌人，造成 27 至 31 点神圣伤害。'),
(800234, '治疗目标 11 点生命值，并使其受到的治疗提高 20%，持续 10 秒。日落期间，治疗提高 25%。'),
(800239, '恢复5点能量，并使你的暴击几率提高10%，持续5 秒。'),
(800260, '远程技能发射一支淬毒箭矢，在15 秒内造成30点自然伤害，可叠加3层。\n\n同一时间只能激活1个箭袋。\n\n与其他箭袋共享冷却时间。'),
(800261, '近战和远程急速提高10%，并使技能集中值消耗降低15%。\n\n同时只能激活1个箭袋。\n\n与其他箭袋共享冷却时间。'),
(800262, '使你对野兽和龙类的伤害提高20%，并且对它们的暴击几率提高10%。\n\n同时只能激活1个箭袋。\n\n与其他箭袋共享冷却时间。'),
(800266, '增强一名盟友的专注力，使其近战和远程攻击强度提高30点。持续30 分钟。'),
(800267, '获得使用剥皮获取的皮革制作粗糙皮革的能力，剥皮时有一定几率获得它，并提高你的剥皮速度。\n\n允许你制作需要粗糙皮革的物品。'),
(800292, '使你的游泳速度提高50%，并让你永久获得水下呼吸能力。'),
(800311, '用盾牌猛击一名敌人，造成（4 + 35.5% 攻击强度）点物理伤害。'),
(800316, '2层充能，6秒充能时间反击一名敌人，造成135%武器伤害外加16点伤害，并恢复20点能量。\n\n仅可在格挡一次攻击后使用。'),
(800317, '提高你的格挡几率10%，并使你的盾牌提供的护甲值提高50%，但你造成的伤害降低10%。'),
(800319, '投下一面勇气战旗，持续20 秒，范围内的附近敌人每2秒受到（8.12 + 4% 攻击强度）点物理伤害，并且移动速度降低40%。\n\n同一时间只能激活1面战旗。'),
(800330, '召唤一个战争魔像，持续10 秒，基于你的智力吸收对你造成的伤害，并将附近盟友受到的有害法术转移至自身。'),
(800340, '产生2层恶魔之火快速挥舞巨刃攻击最多5个附近的敌人，造成50%武器伤害加上8［拥有绞肉机: 并施加撕裂血肉］。'),
(800341, '每3秒造成（18.8 + 9% 攻击强度 + 20% 角色等级）点流血伤害，持续15 秒。'),
(800347, '向盟友投掷一个医疗包，在6 秒内为其恢复（204 + 120% 法术强度）点生命值，并移除所有流血、中毒和疾病效果。'),
(800349, '将附近的哨兵炮塔升级为熔岩手雷炮塔，持续1 分钟。'),
(800352, '使灾祸的持续时间延长，能量消耗降低20%。'),
(800353, '从敌人身上偷取1个有益魔法［拥有魔法恶魔: 效果；否则： 效果］。\n\n若成功偷取一个效果，则对敌人造成（8 + 22% 攻击强度 + 34.3% 暗影法术强度）点暗影伤害。'),
(800355, '引导一道邪能魔法光束射向敌人，使目标的移动速度降低60%，持续5.5 秒，并在持续时间结束时造成（火焰法术强度高于暗影法术强度时：（695 + 85% 火焰法术强度）；否则：（695 + 85% 暗影法术强度））点暗影烈焰伤害。\n\n在引导期间，你可以瞬发施放邪能火球和毁灭，并且它们会返还消耗。'),
(800357, '治疗目标（136 + 29.4699% 法术强度）点生命值。'),
(800358, '你现在每 3 秒向 30 码内受你的狩猎射击影响的敌人射出一支箭矢，造成 75% 远程武器伤害。\n\n受狩猎射击修正效果影响。'),
(800359, '射出一支强力箭矢，造成武器伤害外加40点伤害，并使目标昏迷1 秒。\n\n每层优势效果使持续时间增加1秒。'),
(800360, '向目标掷出钩爪，试图将其嵌入开放性伤口中，造成（99 + 47.85% 攻击强度）点物理伤害。\n\n如果目标正在流血，你可以再次激活此技能将自己拉向目标，造成300%点武器伤害并获得2点优势'),
(800368, '隔离自己或一名盟友，使所有威胁值降低100%，持续10 秒。'),
(800370, '用月井之水包围一名盟友，为其治疗（76 + 90% 法术强度）。\n\n月蚀：此法术变为瞬发，并额外治疗盟友其最大生命值的5%。'),
(800386, '激活此效果可使你的下一个月相法术触发其月能效果。\n\n可在施放或引导另一个法术时使用。'),
(800393, '你的暴击几率提高10%。'),
(800394, '造成伤害时有25%的几率施加散落星辰。'),
(800401, '精通投掷武器，使［拥有森金的指引: 投掷标枪；否则： 投掷武器］、碎脏者和狂战飞斧额外击中2个附近敌人，但你造成的所有伤害降低15%。'),
(800402, '吞噬一名盟友身上的暗影魔法，驱散其身上的2个诅咒效果，并为你恢复（90 + 65% 法术强度）点生命值。'),
(800413, '以压倒性的虚空能量冲击一名敌人，造成（27 + 100% 法术强度）点暗影伤害，并消耗20点狂乱。'),
(800416, '产生10点狂乱值对一名敌人造成（22 + 71% 暗影法术强度）点暗影伤害。'),
(800424, '嘲讽8码范围内的所有敌人，持续4 秒，并使你的移动速度提高50%，持续4 秒。'),
(800430, '在目标位置为5 秒创造一个虚空区域，进入其中的敌人移动速度降低。\n\n减速效果根据敌人距离区域中心的远近而增强。'),
(800432, '击晕一个敌人，每0.5秒造成（30 + 10% 攻击强度 + 55% 暗影法术强度）点暗影伤害，持续5 秒。\n\n在你引导此法术期间，目标受到的所有来源的法术伤害提高15%。'),
(800446, '产生10点狂乱值枯萎一个敌人，在15 秒内造成125点暗影伤害。每次伤害会使其受到周期性治疗效果降低5%，最多可叠加［拥有克苏恩呼唤: 8；否则： 4］层。'),
(800463, '闪避或吸收一次攻击现在有20%的几率使你的下一次帝国之刃造成20%额外伤害，额外击中一个附近敌人，且不消耗法力值。'),
(800474, '30级被动技能使你的远程攻击强度提高，相当于智力值的30%，并使你的命中等级提高，相当于智力值的3%。'),
(800490, '撕裂一名敌人，造成125%武器伤害外加26点伤害。\n\n如果敌人正在流血、生命值低于35%，或你位于其背后，每满足一个条件则额外造成100%暗影伤害。'),
(800496, '攻击一名敌人，造成65%的武器伤害外加9.2308点伤害，并恢复10%的最大法力值外加20点法力值。'),
(800497, '以月火术轰击目标敌人及其附近所有敌人，造成（127 + 33% 奥术法术强度）点奥术伤害，并施加散落星辰效果。\n\n消耗一层散落星辰可使剩余冷却时间减少1.5秒。'),
(800501, '抓住宇宙的潮汐，使附近所有敌人的移动速度降低50%，持续3 秒。\n\n3 秒后，你将附近所有敌人击退一大段距离。'),
(800504, '艾露恩之手或月光之触的治疗效果现在会标记盟友，持续20 秒。\n\n施放女猎手射击现在会治疗被标记的盟友，治疗量为（59 + 30% 法术强度）。'),
(800505, '以星界魔法在脚下冲刺前进，使你的移动速度提高60%，持续4 秒。\n\n激活时，你无法被减速，也无法停止移动。'),
(800506, '向一名敌人投掷哨兵战刃，造成武器伤害外加105点奥术伤害（基于你的法力值上限进一步提高），并使其资源消耗提高15%，持续8 秒。'),
(800508, '你的散落星辰现在可以额外叠加2层。'),
(800600, '重置圣光典范、圣光眷者和审判日的冷却时间。'),
(800601, '下一次光耀的施法时间和法力消耗降低 20%，持续 30 秒，可叠加 5 层。'),
(800602, '神圣形态的效果翻倍，远古仪式的生效间隔缩短 5 秒。'),
(800611, '攻击敌人，造成 100% 武器伤害及 12 点伤害，并治疗自己，治疗量相当于伤害的 50%。与其他圣槌共用冷却时间。'),
(800612, '成为安瑟的勇士，使近战自动攻击额外造成相当于伤害 100% 的神圣伤害，持续 25 秒。'),
(800614, '攻击敌人，造成 100% 武器伤害及 23 点伤害，并恢复 25 点法力值。与其他圣槌共用冷却时间。'),
(800617, '攻击敌人，造成 100% 武器伤害及 45 点伤害，并驱散 1 个有益魔法效果。与其他圣槌共用冷却时间。'),
(800622, '成为安瑟的眷者，使受到的伤害降低 50%，持续 8 秒。生命值低于 50% 时受到伤害，会立即恢复 10% 最大生命值，仅触发一次。'),
(800626, '使用双持武器攻击目标，造成武器伤害及 8 点物理伤害，并恢复法力值，数值相当于造成伤害的 5%。'),
(800637, '每0.5秒对目标发动一次攻击，持续3 秒，每次造成90%的武器伤害。'),
(800654, '从盾牌向前方敌人释放圣光，造成（23 + 10% 攻击强度 + 25% 法术强度）点圣焰伤害，伤害随格挡值提高。'),
(800669, '复活一名死亡的盟友，为其恢复70点生命值和135点法力值。无法在战斗中施放。'),
(800685, '向后跳跃最多10码。［拥有林地追踪者: \n\n你在落地前使用的下一个穿颅者将变为瞬发，并且你在空中每停留0.1秒，造成的伤害就提高10%，最多叠加10层。\n\n当碎颅者在拥有5层优势和10层天降者时使用，将重置后跳的冷却时间。］'),
(800699, '你的风暴升腾现在额外使自然伤害提高10%。'),
(800702, '当生命值高于75%时，所有直接物理伤害将提供一层地狱骑士。'),
(800703, '移动速度提高，全局冷却时间降低5%。物理伤害和暴击几率提高1%，可叠加5层。持续20 秒。'),
(800706, '将一名敌人转化为食尸鬼，使其恐惧40 秒（对玩家为［拥有腐化者: 9；否则： 8］秒）。仅对人型生物有效。伤害可能中断该效果。'),
(800710, '将你的斩断转化为硫磺重击。'),
(800722, '15 秒内的下一次圣光照耀变为瞬发且不消耗法力值。'),
(800732, '向敌人发射一枚原始飞弹，造成（25 + 22% 攻击强度 + 66% 法术强度）点元素伤害［拥有冰霜符印: ，并生成一个符印］。'),
(800736, '使你的法术和技能的资源消耗降低10%。'),
(800752, '释放一个符印现在会对目标8码内的所有敌人额外造成（115 + 6% 法术强度）点同系法术伤害。'),
(800756, '受到致命伤害会使守护符文的冷却时间缩短10%。'),
(800757, '你的魔网封锁现在会额外打断主目标附近的2名敌人。'),
(800758, '符印崩解对冻结目标的伤害提高100%。'),
(800764, '立即产生 10 点太阳能量，并恢复 10% 最大法力值。与其他太阳祈愿共用冷却时间。'),
(800766, '施放嚎叫法术现在会使附近队友造成的伤害提高5%，受到的伤害降低5%，持续10 秒。'),
(800772, '需要凡人之躯腐蚀敌人的心脏，使其在15 秒内持续流血，造成60点暗影伤害。\n\n每次造成伤害时产生3点怒气。\n\n通过此效果造成的周期性伤害可造成暴击。'),
(800774, '需要凡人之躯沸腾的血液爆发，对敌人造成（17 + 35% 暗影法术强度）点暗影伤害，并为每个被击中的敌人产生怒气。［拥有饥渴: \n\n获得1层饥渴效果。］'),
(800776, '谴责一名敌人，在12 秒内造成（200.8 + 77.3332% 暗影法术强度）点暗影伤害，并使其从你的下5个直接伤害法术中受到的伤害提高20%。'),
(800780, '你渴望鲜血，持续12 秒。在此期间你不会被打断或沉默，并且每2秒恢复5%最大生命值和15%缺失的怒气。'),
(800781, '需要凡人之躯缔结血契，治疗一个友方目标（77 + 35% 法术强度 + 25% 精神）点生命值，并对其施加血祭仪式，效果会弹射至最多10个附近盟友，每击中一个目标治疗效果递减。'),
(800782, '嘲讽10码范围内的附近敌人，强制他们攻击你，持续5 秒。'),
(800785, '需要凡人形态施放黑暗仪式，使你的急速提高20%，持续15 秒。\n\n激活时，攻击者会受到诅咒之血影响。每1秒只能触发一次。\n\n持续时间结束时，你的治疗量提高15%，并在15 秒内为你恢复（1040 + 200% 法术强度）点生命值。'),
(800790, '产生20点热量对一名敌人召唤烈焰，造成（22 + 57.1% 火焰法术强度）点火焰伤害。'),
(800791, '每跳产生10点热量灼烧一名敌人，在21 秒内造成175点火焰伤害。如果点燃被驱散，则对驱散者造成（111 + 150% 火焰法术强度）点火焰伤害。\n\n可在移动时施放。'),
(800796, '在目标位置召唤一只凤凰，每5秒为附近队友恢复（10% 治疗强度 + 85 × 等级系数）点生命值。\n\n你同时只能拥有1只凤凰。'),
(800797, '进入灵魂世界潜行，移动速度降低 20%。无法在战斗中使用。'),
(800806, '产生30点热量用治愈之焰治疗一名盟友，恢复（45 + 65% 法术强度 + 100% 精神）点生命值，额外效果受你的精神属性加成。'),
(800807, '在目标位置制造一个火焰之环，持续10 秒，每（172.85 + 31% 火焰法术强度）秒造成一次火焰伤害，并使范围内的所有敌人迷惑，持续6 秒。\n\n进入火焰之环同样会伤害并迷惑敌人。'),
(800808, '反制敌人的施法，使其在5 秒内无法施放该魔法学派的任何法术。'),
(800811, '当烈焰施法结束时，你向最多12个受你激活的烈焰法师周期性效果影响的敌人发射一枚烈焰箭。'),
(800816, '产生50点热量命令你的凤凰进入休眠状态，持续10 秒。\n\n休眠期间，凤凰会每2秒为附近盟友恢复（72.8% 治疗强度 + 1001 × 等级系数）点生命值。'),
(800818, '消耗1枚余烬以永恒之火温暖一名盟友，为其恢复（83 + 45% 法术强度 + 100% 精神）点生命值，治疗量额外受你的精神属性加成。'),
(800838, '释放一股冰霜吐息，对12码锥形范围内的敌人造成（42 + 20% 攻击强度）点冰霜伤害，并使其移动速度降低30%，持续5 秒。\n\n只能在清空你的酒杯后使用。'),
(800841, '变形为蜘蛛形态，允许使用需要该形态的技能，使你的移动速度提高 20%，并让你免疫变形效果。'),
(800843, '潜行于阴影中，进入潜行状态。持续直到取消。\n\n当潜行时，你的下一次毒蛇之牙［拥有寡妇之吻: 或寡妇之吻］无消耗，并造成55%的额外伤害，随等级提高。'),
(800845, '撕裂你的凡躯 5 秒，使你免疫所有有害法术效果，并立即恢复 30% 最大生命值与符文能量。被眩晕、恐惧或变形时仍可使用。'),
(800848, '向前疾冲一段长距离。\n\n可在10 秒内使用3次，之后触发冷却。\n\n可在潜行状态下使用。'),
(800852, '祝福一名友方目标，每 5 秒恢复 5 点法力值，技能消耗降低 5%，持续 30 分钟。每名目标同一时间只能受到同一位太阳祭司的一种祝祷影响。'),
(800856, '［拥有回响碎片: 扭曲法术\n］分解一个敌人，在21 秒内造成68.25点混沌伤害。该伤害会缓慢造成，并在持续时间内逐渐加速。［拥有回响碎片: \n\n每消耗一个回响碎片，伤害提高25%。］\n\n急速不会缩短持续时间，但会增加总伤害次数。'),
(800857, '加速身体的自然愈合过程，在15 秒内为目标恢复（179.28 + 343.62% 治疗强度）点生命值。［拥有加速愈合: \n\n使你对盟友造成的治疗提高6%。］'),
(800861, '你的毒液箭现在可在移动时施放，且施法速度提高30%，持续6 秒。'),
(800869, '向一名敌人喷吐毒液，造成（19 + 81.4% 自然法术强度）点自然伤害［拥有凋零菇注射: ，并使其受到的治疗效果降低 15%，持续 10 秒，可叠加 2 次］。'),
(800870, '将沙德拉的荣耀带给一名盟友，为其恢复（32 + 26.3078% 治疗强度）点生命值，并在 24 秒内每 3 秒额外恢复（5 + 13.1086% 治疗强度）点生命值。'),
(800871, '需要蜘蛛形态。消耗孵化印记。向一名敌人及其附近的敌人喷洒毒液，在15 秒内造成自然伤害。\n1枚印记：（87.5 + 93.75% 自然法术强度）点自然伤害。\n2枚印记：（112 + 120% 自然法术强度）点自然伤害。\n3枚印记：（143.5 + 153.75% 自然法术强度）点自然伤害。\n4枚印记：（182 + 195% 自然法术强度）点自然伤害。\n5枚印记：（245 + 262.5% 自然法术强度）点自然伤害。'),
(800878, '如果你处于蜘蛛形态，施放钻地现在会使你获得潜行。\n\n当潜行激活时，每1秒，你的钻地冷却时间减少1秒。'),
(800880, '［拥有寡妇之吻: 施加1层孵化印记\n］撕咬一名敌人，造成（24 + 40% 自然法术强度）点自然伤害。'),
(800882, '施加1层孵化印记。刺击一名敌人，造成（26 + 25% 暗影法术强度）点暗影伤害，并在15 秒内额外造成（20 + 50% 暗影法术强度）点伤害，最多可叠加3层。'),
(800887, '向身后所有敌人喷射蛛网，定身他们，持续4 秒，并造成（61 + 40% 自然法术强度）点自然伤害。'),
(800892, '硬化你的甲壳，使受到的伤害降低45%，效果在10 秒内快速衰减，并在每次移除一层时恢复1%的最大生命值。\n\n在此期间受到物理伤害会使其衰减速度加快。\n\n离开甲虫形态将取消此效果。'),
(800894, '使你的最大法力值、能量值和怒气值提高10%。'),
(800895, '立即获得5点怒气，随后每0获得2.5点怒气。在10 秒内，你的所有法术和技能资源消耗降低0%，且脱离战斗后怒气不会衰减。'),
(800899, '将不稳定的迷雾扩散到30码内最多8个盟友，每1秒为其治疗（9 + 15% 治疗强度），持续10 秒。\n\n1.689秒后，30码内最多8个盟友额外获得（97.52 + 23.1% 治疗强度）点治疗。'),
(800901, '用恢复性药膏包裹一名盟友，每3秒为其恢复（14 + 25.1685% 治疗强度）点生命值，持续21 秒。'),
(800902, '快速治疗一名盟友，在6 秒内恢复24点生命值。\n\n［拥有沙德拉之书: 5.999秒后，；否则： 效果结束时，］此效果将寻找附近生命值最低的另一名盟友，为其恢复（47 + 24.4572% 治疗强度）点生命值。'),
(800905, '每4秒驱散目标身上的1个中毒效果，持续12 秒。'),
(800910, '对目标位置最多5个敌人施加枯萎和孢子，并放置一个蘑菇，2秒后爆炸，对附近敌人造成（303 + 25% 自然法术强度）点自然伤害。'),
(800912, '变形为维齐尔形态，使你可以在移动时施放沙德拉的祷言，并使你的周期性治疗有20%的几率为盟友提供回能。\n\n使你的持续治疗效果可以暴击，并使你免疫变形术效果。'),
(800914, '从毒蛇领主的护符中汲取力量，使你的法术急速提高20%，法力值消耗降低50%，持续15 秒。'),
(800921, '需要潜行将自己嵌入一名敌方或友方玩家体内1 分钟，期间免疫所有伤害，但无法攻击或施法。\n\n持续时间结束时，或施放寄生虫：破土而出时，你将在其位置出现。如果目标是敌人，你对其施加寄生毒药。\n\n不能在战斗中使用。此能力在离开目标后进入冷却。'),
(800922, '化为终焉使者，持续 15 秒：挽歌的伤害提高 30%、射程提高 20 码，并使其生成 3 层收割之魂。在此期间，挽歌会治疗你相当于其造成伤害 75% 的生命值。'),
(800926, '以翡翠帷幕笼罩一名盟友，为其恢复（416 + 95% 治疗强度）点生命值，并使其获得护盾，吸收最多（36 + 95% 自然法术强度）点伤害。持续 20 秒。'),
(800943, '当生命值低于35%时，你的自动攻击、先祖打击和投掷武器现在会赋予血之诞生效果。每2秒只能触发一次。'),
(800946, '向敌人投掷剧毒，造成（35 + 130% 自然法术强度）点自然伤害，并治疗其附近最多［拥有生命修复者: 10；否则： 5］名盟友（46.89 + 42% 治疗强度）点生命值。'),
(800995, '打断目标的施法，使其在2.5 秒内无法施放该法术学派的所有法术。'),
(800997, '近战物理伤害现在会提供一层恶魔之血。'),
(800999, '拥抱你内心的恶魔，使受到的治疗效果提高1%［拥有恶魔皮肤: ，护甲提高1%］，最多叠加10层。'),
(801002, '发出恐怖的嚎叫，释放你［拥有邪恶搭档: 和你的大恶魔的］ 主动瘟疫对附近敌人触发强力效果。'),
(801005, '向一名敌人投掷炸弹，造成（36 + 30% 远程攻击强度 + 50% 火焰法术强度）点火焰伤害，并使其护甲降低5%，持续15 秒，最多叠加4层。'),
(801006, '熔岩之雨灼烧区域内的敌人，在9 秒内造成225点火焰伤害。'),
(801016, '产生2层恶魔之火对一名敌人造成55%的武器伤害外加3点火焰伤害。'),
(801042, '吞噬目标尸体，产生20点怒气，然后在5 秒内每1秒为你和你的召唤物恢复4%最大生命值。\n\n尸体被剥皮后无法再次剥皮。\n\n无法在战斗中使用。仅能对类人生物、野兽或恶魔使用。'),
(801053, '散发瘟疫，使12码内所有敌人的施法速度降低10%。［拥有释放瘟疫: \n\n释放：打断10码内所有敌人的施法，并使其无法施放该系法术，持续2 秒。］'),
(801054, '散发瘟疫，使你的暴击伤害提高10%。［拥有释放瘟疫: \n\n释放：对10码内的敌人造成（62 + 75% 攻击强度）点暗影烈焰伤害，并吸收其（104 + 40% 攻击强度 + 25% 力量）点治疗效果，持续10 秒。］'),
(801059, '灼烧前方最多6个敌人，造成（14 + 15% 攻击强度 + 45% 火焰法术强度）点火焰伤害。\n\n每消耗一层恶魔之火可造成额外伤害。\n\n［学会无尽地狱火时：地狱火打击会引爆附近受此效果影响的敌人，造成额外火焰伤害。］'),
(801061, '创建一个恶魔印记，保护你20码内的队伍成员，使其偏转在3 秒内对他们施放的下一个有害法术。'),
(801063, '拥抱你的凡人之躯，每3秒恢复（5% 攻击强度 + 200 × 等级系数 + 10% 耐力）点生命值，随耐力和防御等级提高。\n\n每消耗一层冥火，持续3秒。\n\n客户端校对：原文的额外减伤说明缺少天赋条件，且把持续时间字段引用为百分比；该附加效果待游戏内核对。'),
(801065, '成功的格挡、招架和闪避现在有30%的几率使你激怒，使你的伤害提高10%，持续10 秒。'),
(801067, '将一名恶魔囚禁30 秒（对玩家为6秒），将其放逐，使其无法行动，并对所有法术和攻击免疫。\n\n每次只能影响1个敌人。'),
(801069, '使你的物理伤害和暴击伤害提高10%。\n\n同时只能激活1个箭袋。\n\n与其他箭袋共享冷却时间。'),
(801074, '需要凡人形态用血肉剥离的幻象淹没最多5个附近敌人的心智，使其恐惧40 秒（对玩家为8秒），同时吸取他们的生命精华，每3秒吸取（8 + 15% 法术强度）点生命值。\n\n造成的伤害可能会中断该效果。'),
(801076, '进入独特的诅咒形态，持续15 秒，不会禁用凡人形态技能［拥有猩红恐怖: ，获得相当于你的精神值0%的法术伤害加成］。\n\n激活时，直接法术伤害会触发吸血盛宴，对敌人造成20%额外暗影伤害，并为你恢复相当于造成伤害50%的生命值。\n\n处于诅咒形态时，你被视为恶魔。'),
(801086, '在15 秒内，你触发的下10次武器铭刻将额外造成（20% 攻击强度 + 348 × 等级系数 + 30% 法术强度）点元素伤害。'),
(801087, '点燃你的刀刃并攻击一名敌人，造成140%的武器伤害外加19点火焰伤害。'),
(801094, '与大地协调，使你的护甲提高75点，自然抗性提高5点。'),
(801096, '将奥术能量导入你的武器，从 20 码范围内的敌人身上汲取力量。在半径范围内，每有一个敌人，你的伤害就会额外造成 10% 的奥术伤害，最多提高100%，持续 15 秒。\n\n激活时，近战攻击和技能会为你提供驾驭魔网。'),
(801103, '在你面对的方向上召唤一道符文路径，持续10 秒，使盟友的移动速度提高70%。\n\n离开符文路径后，该效果可短暂持续一段时间。'),
(801104, '在你面前以冰霜之怒横扫，对最多3个附近的敌人造成（13 + 33% 攻击强度）点冰霜伤害，并在21 秒内每3秒额外造成（13 + 33% 攻击强度）点伤害。\n\n被初始打击命中的敌人将被冻结在原地，持续3 秒。'),
(801106, '与火焰协调，使你的火焰抗性提高5点，暴击伤害提高15%。'),
(801107, '与水元素共鸣，每5秒恢复10点法力值，并使你的法术和技能的法力消耗降低5%［拥有魔石之泉: ，同时通过魔石之泉恢复的法力值提高2.5%］。［拥有冰霜符印: \n\n激活时，原初轰击施放后恢复你最大法力值的5%。］'),
(801121, '受到物理伤害或格挡物理攻击现在会恢复2点能量。'),
(801123, '近战和远程攻击有40%的几率使敌人的移动速度降低20%，持续10 秒，可叠加2层，并施加散落星辰。\n\n与其他架势技能共享冷却时间。'),
(801125, '毁灭一名敌人，造成130%的武器伤害外加（100% 智力）点奥术伤害，并恢复15%的已损失法力值。'),
(801126, '吸取 30% 最大法力值用天界魔法包裹自身，使受到的伤害降低 25%，持续 10 秒。\n\n与其他庇护法术共享冷却时间。'),
(801127, '吸取20%最大法力值施加1层散落星辰攻击一名敌人，造成40%武器伤害外加（3 + 4.2% 最大法力值 + 30% 奥术法术强度）点奥术伤害，伤害量额外基于你的最大法力值提高。'),
(801128, '近战和远程自动攻击有10%的几率额外攻击3次，造成100%的伤害（奥术伤害）并施加散落星辰。\n\n与其他架势共享冷却时间。\n\n此伤害无法暴击。'),
(801132, '消耗散落的星辰向敌人释放月光之枪，造成（9 + 21% 攻击强度 + 35% 奥术法术强度）点法术火焰伤害［拥有月光枪兵: ，并使其着火了，在0 秒内每3秒受到（6 + 5% 攻击强度 + 10% 奥术法术强度）点伤害］。'),
(801134, '将目标盟友转移出物理位面，使其获得强化潜行效果，持续10 秒。\n\n受到伤害不会取消该效果。'),
(801135, '召唤星辰之力，从你身上向外发射艾露恩的星界之光，使被击中的敌人昏迷5 秒，并施加一个散落星辰。'),
(801143, '使用散落星辰造成伤害时，现在有15%的几率重置星界之刃的冷却时间，并使你的下一次星界之刃不消耗资源。'),
(801145, '40级被动造成伤害的暴击现在会使守望者之刃的冷却时间缩短1秒。\n\n此外，获得法力值不再产生威胁值。'),
(801146, '女猎手刃豹的冷却时间减少 60 秒。'),
(801148, '格挡等级、招架等级和格挡值根据你当前的法力值提高。'),
(801153, '在你附近召唤一个上古之神触须，持续30 秒。\n\n它会寻找一个敌人，每1.5秒造成（3% 攻击强度 + 65 × 等级系数 + 8% 暗影法术强度）点暗影伤害，伤害受法术强度和攻击强度加成。\n\n当你的狂乱值高于60点时，该法术的法力值消耗被移除。\n\n你同时只能激活一个上古之神触须。'),
(801155, '用月光环绕自身，使10 秒内受到的伤害有30%转化为法力值。'),
(801157, '移除你或一名盟友邪邪教徒身上的疯狂负面效果，将目标的狂乱重置为0。'),
(801165, '3层充能，35秒充能时间向一名盟友冲锋，为你和该盟友恢复（102 + 80.5% 攻击强度 + 85% 神圣法术强度）点生命值。'),
(801179, '对一名敌人释放你激活的符印效果，造成（82 + 100% 法术强度）点元素伤害。'),
(801181, '劈裂前方最多5个附近的敌人，造成55%武器伤害的奥术伤害。\n\n每击中一个敌人恢复2%最大法力值。'),
(801191, '发射一枚在3个敌人之间弹射的射击，对每个敌人造成远程武器伤害外加6点伤害。\n\n每击中一个敌人获得1层优势。'),
(801202, '当生命值高于 80% 或低于 20% 时，你受到的魔法伤害降低 20%。'),
(801204, '使你的敏捷、智力和命中几率提高3%。'),
(801205, '在目标位置放置一个圣光法阵，持续4 秒，使敌人移动速度降低50%。\n\n每2秒，法阵范围内的敌人进入宁静状态，陷入沉睡，持续40 秒（对玩家为8秒）。'),
(801219, '举起盾牌并发动猛攻，对前方敌人造成75%武器伤害外加19.8点伤害，每0.5秒消耗10点能量。持续5 秒。\n\n激活时，你获得100%格挡几率提高，并且在引导期间可以进行格挡、躲闪和招架。\n\n在强攻激活期间，你无法使用其他技能。'),
(801226, '月相的叠加层数增加4层。'),
(801231, '化身星界形态，持续15 秒，使你的暴击几率提高10%。\n\n激活时，暴击现在会使所有治疗法术的剩余冷却时间缩短10%，并对你的目标及其5码范围内的最多4个敌人施加散落星辰效果。'),
(801234, '当你施放恩赐时，你也会以50%的效果对你的宠物施放相同的恩赐。'),
(801235, '连续 3 次直接暴击现在会触发末日雕塑者。'),
(801242, '当装备单手武器时，你的物理暴击会使你及任何激活的宠物进入激怒状态，持续8 秒，使你下2次攻击的急速提高10%，并使它们下2次攻击的急速提高80%。'),
(801270, '用青铜龙军团赐予你的魔法修复一名盟友，为其治疗（44.82 + 49.8% 法术强度），并为你提供时光之沙。'),
(801271, '在目标位置为所有友方和敌方恢复时间连续体，移除敌方的所有有益魔法效果和友方的所有有害魔法效果。\n\n此驱散效果足够强大，能够移除通常无法驱散的魔法效果。'),
(801277, '用时间分形爆破前方锥形区域内的敌人，并使其略微后退。\n\n2秒后，击退效果会额外重复1次。'),
(801281, '在目标位置放置一颗重力炸弹。6 秒后，炸弹爆炸，对10码范围内的所有敌人造成（973 + 30% 远程攻击强度 + 120% 法术强度）点多彩伤害。\n\n在爆炸即将发生前，15码范围内的所有敌人会被传送至初始目标位置。［拥有黑暗之星: \n\n在延迟期间，初始目标从你处受到的伤害提高0%。］'),
(801291, '撕裂时间之布，在 6 秒内造成 30 点多彩伤害。\\r\n\\r\n急速不会缩短持续时间，但会增加总伤害次数。'),
(801292, '向一名敌人投掷一枚混沌碎片，造成（270 + 200% 法术强度）点多彩伤害，无视免疫和抗性。\n\n使用异常尖刺造成伤害会使此能力的施法时间降低10%，持续30 秒，可叠加10层。'),
(801303, '逆转盟友的伤口，为其治疗（46.812 + 89.64% 治疗强度）。［拥有救世主: \n\n延长加速恢复的持续时间2秒。］'),
(801304, '加速一位盟友，使其移动速度和急速提高20%［拥有现实瓦解者: ，并使其在造成伤害时有25%的几率额外造成一次相当于30%伤害的打击］。持续12 秒。［拥有比科效应: \n\n激活时，维度分歧、回溯和时间守卫的冷却时间每2秒减少10%。］'),
(801312, '产生1层邪能之怒向一名敌人释放强大的邪能火球，造成（火焰法术强度高于暗影法术强度时：（21 + 50% 火焰法术强度）；否则：（21 + 50% 暗影法术强度））点火焰伤害。［拥有邪能学徒: \n\n心魔：对目标释放一次邪能打击，在6 秒内造成0点混沌伤害，可叠加3层。］\n\n可在移动时使用。'),
(801325, '以收割、恐惧之潮与灵魂突刺造成伤害现在为你叠加 1 层痛苦铠甲，持续 15 秒，最多叠加 8 层。再次施加不会刷新效果。痛苦铠甲层数自然消失时，你会恢复 2% 最大生命值，并使强化形态的冷却时间每层缩短 0.5 秒。'),
(801328, '生成 2 个灵魂碎片。以双武器劈砍敌人，每次造成 70% 武器伤害（若装备匕首则为 130%）的暗霜伤害，并生成符文能量。'),
(801335, '使死亡之风的持续时间延长 4 秒；身处其中时，群鸦收割的伤害额外提高 15%。'),
(801343, '召唤一只永久的暗影猎犬伙伴协助你战斗。\n\n你的暗影猎犬获得你所受治疗量的25%。'),
(801345, '使你能够潜行移动。潜行时移动速度降低20%，持续永久。\n\n无法在战斗中使用。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (801384, 801387, 801389, 801434, 801435, 801438, 801441, 801443, 801445, 801446, 801448, 801450, 801455, 801457, 801461, 801463, 801465, 801466, 801468, 801478, 801480, 801481, 801482, 801483, 801511, 801523, 801524, 801530, 801539, 801549, 801563, 801576, 801607, 801624, 801639, 801660, 801661, 801662, 801663, 801664, 801669, 801670, 801674, 801678, 801689, 801690, 801693, 801696, 801706, 801707, 801709, 801716, 801718, 801722, 801724, 801733, 801739, 801744, 801753, 801755, 801758, 801759, 801760, 801761, 801767, 801768, 801774, 801778, 801782, 801790, 801791, 801792, 801793, 801794, 801795, 801796, 801799, 801801, 801802, 801809, 801821, 801827, 801838, 801839, 801841, 801844, 801847, 801851, 801855, 801859, 801868, 801869, 801892, 801895, 801899, 801901, 801903, 801904, 801905, 801911, 801925, 801938, 801945, 801951, 801952, 801955, 801957, 801958, 801959, 801960, 801961, 801962, 801963, 801968, 801972, 801975, 801976, 801978, 801987, 801989, 801990, 801996, 802004, 802006, 802011, 802013, 802019, 802020, 802024, 802036, 802039, 802042, 802043, 802044, 802047, 802048, 802049, 802052, 802058, 802060, 802065, 802068, 802075, 802076, 802087, 802092, 802100, 802107, 802108, 802117, 802119, 802120, 802121, 802132, 802138, 802139, 802140, 802161, 802164, 802167, 802168, 802169, 802170, 802173, 802175, 802180, 802202, 802203, 802204, 802207, 802208, 802215, 802216, 802219, 802229, 802262, 802268, 802269, 802272, 802276, 802277, 802278, 802279, 802280, 802281, 802284, 802286, 802290, 802295, 802296, 802297, 802299, 802300, 802310, 802313, 802315, 802335, 802342, 802344, 802345);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(801384, '激活你的机甲，每秒消耗5点废料，使造成的伤害提高10%，护甲提高114，移动速度提高10%［拥有烈焰锻造泰坦: ，并使受到的所有伤害降低0%］。\n\n如果在激活状态下废料耗尽，你将被弹出机甲。\n\n激活时，你的废料射击将转化为加特林机枪。'),
(801387, '向一名敌人发射巨大的火球，同时伤害附近的敌人，造成（70 + 20% 远程攻击强度）点火焰伤害。\n\n可在移动时使用。\n\n与其他机甲技能共享冷却时间。'),
(801389, '向前冲刺并减缓你的下落速度。\n\n当你落地时，根据在空中停留的时间对附近敌人造成 50 点火焰伤害。\n\n与其他机甲技能共享冷却时间。'),
(801434, '你的本能被激发，立即恢复40点集中值，并使你的攻击强度提高相当于敏捷40%，持续15 秒。\n\n可在潜行时使用。'),
(801435, '击晕一名敌人，使其瘫痪4 秒，并移除其身上的流血和中毒效果。造成的伤害会中断此效果。［拥有欺凌: \n\n在效果持续期间，敌人从突击受到的伤害提高0%。］\n\n可在隐匿状态下使用。'),
(801438, '使野性打击和突击的暴击几率提高10%。'),
(801441, '阅读你的奉献圣契，使伤害性技能对目标额外造成24点神圣伤害，持续20 秒。\n\n同一时间只能激活1个圣契法术。'),
(801443, '以神圣狂热刺击一名敌人，造成80%武器伤害外加9点伤害，并获得一层誓言。\n\n誓言： 你的技能造成的伤害或治疗效果提高5%。'),
(801445, '横扫敌人，对目标及附近一个额外敌人造成60%武器伤害外加1点伤害，并获得一个誓言。\n\n誓言： 你的技能会额外击中1个附近目标。'),
(801446, '以热忱打击一名敌人，造成（40 + 28.5% 攻击强度 + 75% 法术强度）点物理伤害，触发狂热，并获得一层誓言。\n\n誓言：你的伤害性技能有20%的几率触发狂热。'),
(801448, '释放一个治疗性的破誓者，为一名盟友恢复（6 + 30% 法术强度 + 25% 耐力）点生命值，效果随耐力提高。\n\n消耗你的誓言，每消耗一层造成额外治疗。'),
(801450, '造成80%副手武器伤害，视为神圣伤害。'),
(801455, '解除一名盟友的世界束缚，使其在10 秒内免疫所有移动限制效果。\n\n施加神圣束缚，持续1 分钟。'),
(801457, '治疗盟友现在会将10%的伤害转移给你，并使你受到的伤害降低5%，持续10 秒，可叠加3层。\n\n 治疗自己不会触发此效果。'),
(801461, '阅读你的坚韧圣契，使你受到的物理伤害降低30%（对玩家时降低15%），持续20 秒［拥有顽强防御者: 并立即为你恢复0%最大生命］。\n同一时间只能激活1个圣契法术。'),
(801463, '阅读你的恩典圣契，使你受到的治疗效果提高20%，并让你的伤害技能为你和附近盟友恢复（30 + 10% 攻击强度 + 15% 法术强度）点生命值，持续20 秒。\n同一时间只能激活1个圣契法术。'),
(801465, '吟唱银手咒语，向目标投掷一把神圣之锤，使你冲向目标，若目标为友方，则移除你和目标身上的神圣束缚效果。\n\n抵达目标时，你对附近所有敌人造成（300 + 200% 攻击强度）点神圣伤害，并为附近友方恢复等量生命值。'),
(801466, '阅读你的热忱圣契，使你的近战急速提高20%，并使你的伤害技能缩短正义剧变的冷却时间2秒，持续20 秒。\n\n同时只能激活1个圣契法术。'),
(801468, '直接伤害技能的暴击现在产生4点集中值。'),
(801478, '为一名盟友祈祷，为其恢复（152 + 200% 攻击强度 + 100% 法术强度）点生命值。\n\n施加神圣束缚，持续1 分钟。'),
(801480, '使奉献圣契造成的伤害提高100%。\n\n此外，使你的圣契效果提高100%，并使它们的冷却时间缩短25%。'),
(801481, '为圣光带来荣耀，使你的攻击速度提高30%，持续5 秒。\n\n持续时间结束后，你将获得陨落效果。'),
(801482, '在5 秒内，你造成的所有伤害的50%会治疗你。持续时间结束后，你获得救赎。'),
(801483, '攻击速度提高30%，并且在5 秒内，你造成的所有伤害的50%会治疗你。'),
(801511, '你的符文剑现在有20%的几率，而跃迁匕首有100%的几率重置燃刃斩的冷却时间，并使你的下一次燃刃斩的伤害提高20%。'),
(801523, '与一名盟友分享克罗米的智慧，使其精神提高10点，持续30 分钟。\n\n每个时光法师只能激活一个智慧效果。'),
(801524, '用光链束缚敌人，阻止其骑乘、逃跑或使移动速度超过正常速度，持续 15 秒。'),
(801530, '在 20 码范围内将生命能量注入你的复生仆从，持续 10 秒，每 1 秒为其恢复最大生命值的 5% 外加（5.75 + 25% 法术强度）点生命值。'),
(801539, '使虚空打击的暴击伤害提高 25%。'),
(801549, '你的厚实颅骨使你免疫所有昏迷和恐惧效果，持续10 秒，激活期间受到直接伤害会获得血之诞生。\n\n可在昏迷时使用。'),
(801563, '复活一名死亡的玩家，恢复其70%的生命值和法力值。\n\n在接下来的20 秒内，目标受到的治疗效果提高50%，但受到伤害会中断该效果。无法在战斗中施放。'),
(801576, '以祖先的力量猛击敌人，造成（13 + 40% 攻击强度）点伤害。使用速度更慢的武器会造成更高的伤害。'),
(801607, '向敌人释放你的精魂，每个激活的精魂每0.25秒造成（15 + 7% 远程攻击强度 + 15% 暗影法术强度）点暗影伤害。\n\n每个精魂在命中时爆炸，对目标5码范围内的其他附近敌人造成（15% 远程攻击强度 + 130 × 等级系数 + 15% 暗影法术强度）点暗影伤害。'),
(801624, '在目标身后重新现身并伏击，造成 25 点 + 50% 攻击强度的暗影伤害，将其定身 2 秒，并生成 20 点符文能量。'),
(801639, '在 5 秒后对附近敌人造成（1290 + 17.5% 攻击强度 + 11% 火焰法术强度）点火焰伤害。'),
(801660, '将丛林蘑菇酿入你的大锅。\n\n大锅：每6秒治疗30码内最多［拥有丛林绽放: 5；否则： 8］名盟友（20% 治疗强度 + 91 × 等级系数）点生命值。\n\n投掷药水：每3秒治疗目标盟友10点生命值，持续18 秒。'),
(801661, '从你的大锅中装填一瓶药剂，并将其掷向一个友方目标，为其恢复（108 + 28% 治疗强度 + 10% 精神）点生命值。\n\n投掷药水的效果将根据你激活的材料而改变。'),
(801662, '将鱼油酿入你的大锅中。\n\n大锅：使40码范围内的盟友移动速度和游泳速度提高10%。\n\n药水：使目标盟友的移动速度提高20%，闪避几率提高5%，持续8 秒。'),
(801663, '将鱼骨投入你的大锅。\n大锅：使 40 码内的盟友受到的伤害降低 3%。\n药水：为目标盟友提供一个吸收护盾，可吸收（100 + 80% 治疗强度 + 35% 精神）点伤害，效果随精神属性提高。'),
(801664, '将血蓟投入你的大锅中。\n\n大锅：40码范围内的盟友受到的治疗效果提高8%。\n\n药水：使目标盟友在15 秒内汲取其造成的所有伤害的5%。每0.5秒只能触发一次。'),
(801669, '在目标位置降下暗影魔法，对所有敌人造成（57 + 10% 远程攻击强度 + 35% 暗影法术强度）点暗影伤害。\n\n用此法术杀死敌人将为你提供一个精魂。'),
(801670, '配制一瓶药水并将其掷向一个盟友目标，恢复（84 + 84% 法术强度）点生命值［拥有洛阿的祝福: ，并使其获得一个持续20 秒的随机效果］.［拥有洛阿的祝福: \n\n］\n\n使用洛阿之酿治疗一名不同目标时，也会为你上一个洛阿之酿的目标恢复相当于治疗量50%的生命值。'),
(801674, '向一名敌人发射一支巫毒箭矢，造成 85% 远程武器伤害外加（25 + 20% 远程攻击强度 + 25% 自然法术强度）点自然伤害，并为你恢复造成伤害的 40% 点生命值。'),
(801678, '在你附近放置一个停滞守卫。\n\n2秒后，结界会爆发出闪电，击晕附近的敌人，持续4 秒，并造成（17 + 25% 自然法术强度）点自然伤害。\n\n同一时间只能激活1个守卫。'),
(801689, '向一名盟友投掷你的奥术酿造，使其法术强度和法术精神提高30点，持续10 秒。\n\n法术强度随施法者等级提高。'),
(801690, '使材料的持续时间延长20%，并使受丛林蘑菇影响的盟友在接下来的3次攻击技能或法术造成的伤害中，获得5%的治疗效果，持续15 秒。'),
(801693, '诅咒一个敌人，造成（5 + 10% 远程攻击强度 + 8% 暗影法术强度）点暗影伤害，并在24 秒内额外造成88点暗影伤害。\n\n此效果造成的周期性伤害可造成暴击。'),
(801696, '向一名盟友释放灵魂，为其恢复（109 + 45% 法术强度）点生命值，并对5码范围内最多5个敌人造成相当于4%治疗量的伤害。'),
(801706, '使动能护盾、扰乱！和排斥装置的冷却时间缩短20%。'),
(801707, '向盟友发射一枚治疗兴奋剂，为其恢复（38 + 70% 治疗强度）点生命值。'),
(801709, '向一名盟友发送纳米机器人，每4秒对附近敌人造成（15 + 17.1% 法术强度）点伤害，持续1 分钟。你产生的所有威胁值将转移至该目标。\n\n纳米机器人群每次只能发送给1个目标，且无法被驱散。'),
(801716, '让邦桑迪之灵附身于你20 秒［拥有力量的代价: ，使你造成的暗影伤害提高0%］。\n\n造成周期性伤害时，会向敌人释放一个被禁锢的巫毒之灵，爆炸造成（162 × 等级系数 + 25% 暗影法术强度）点暗影伤害。'),
(801718, '放置一个爆破地雷，持续1 分钟。\n\n当地雷被摧毁或使用远程引爆时，最多8个附近的敌人被炸飞，敌人受到少量火焰伤害。'),
(801722, '向一名敌人释放一枚冰霜腐化碎片，造成（15 + 86.9894% 冰霜法术强度）点冰霜伤害，使其移动速度降低35%，持续3 秒，并产生符文能量。'),
(801724, '向一名敌人发射冰霜锁链，每1秒造成（351.25 + 35% 冰霜法术强度）点冰霜伤害，持续3 秒。\n\n每次造成伤害时产生3点符文能量。'),
(801733, '每第3个命令法术现在会将目标冻结在原地，持续5 秒。造成的伤害可能提前结束此效果。'),
(801739, '冰封敌人的心脏，打断其当前施法。\n\n成功打断法术还会使其移动速度和急速降低80%，持续3 秒。'),
(801744, '标记目标位置，发动一次空中打击。7 秒后，对爆炸范围内的最多12个敌人造成1238点火焰伤害。\n\n此技能总是造成暴击。'),
(801753, '向一名敌人发起决斗挑战，持续10 秒，使其受到的治疗效果降低20%，并吸收其接下来受到的（1244 + 100% 攻击强度）点治疗。'),
(801755, '需要激怒用双持武器猛击一名敌人，造成149%的武器伤害外加8点额外伤害。'),
(801758, '激怒效果进入激怒状态，立即产生25点能量，并在10 秒内每2秒额外产生20点能量。'),
(801759, '需要激怒状态使你的急速和暴击几率提高20%，但受到的伤害提高30%，持续10 秒。\n\n物理暴击会使此效果延长1秒，最多延长至［拥有嗜血: 20；否则： 10］秒。'),
(801760, '释放一连串无情的冰川碎片，每0.25秒造成（26 + 59.71% 法术强度）点冰霜伤害，持续1 秒。\n\n在持续时间结束时，你将目标冰封在冰块中，使其冻结4 秒。'),
(801761, '激怒效果进入激怒状态，使你的物理伤害提高10%，持续8 秒。'),
(801767, '使你的战团的冷却时间减少30秒，并使先祖咆哮的冷却时间减少5秒。'),
(801768, '激怒效果激怒持续15 秒，获得40%最大生命值提升。效果结束后，生命值将随之失去。'),
(801774, '敲响战鼓，使你的自动攻击触发战争之声，并使你的急速提高15%，持续15 秒。\n\n此外，在你10码范围内的盟友在造成任何伤害时，有5%的几率触发战争之声。\n\n与投身战局不兼容。'),
(801778, '下一个直接技能或法术造成的伤害中，有15%会转化为额外魔法伤害。'),
(801782, '你造成的物理伤害现在有25%的几率对目标触发一次额外的副手攻擊，造成冰霜傷害，并为你叠加一层满溢。'),
(801790, '复活一名盟友，使其拥有 70 点生命值和 135 点法力值。无法在战斗中使用。'),
(801791, '使一名死亡的玩家复活，拥有 70 点生命值和 135 点法力值。无法在战斗中施放。'),
(801792, '复活一名已死亡的盟友，恢复其70点生命值和135点法力值。\n\n可在战斗中使用。'),
(801793, '立即复活一名死亡的盟友，恢复400%的生命值和635%的法力值。\n\n此法术可在战斗中使用。'),
(801794, '复活一名已死亡的盟友，恢复其70点生命值和135点法力值。\n\n无法在战斗中施放。'),
(801795, '复活一名已死亡的盟友，恢复其70点生命值和135点法力值。目标获得200%的法力恢复速度提升，持续10 秒。\n\n无法在战斗中施放。'),
(801796, '复活一名已死亡的盟友，恢复其70点生命值和135点法力值。\n\n无法在战斗中施放。'),
(801799, '3层充能，15秒充能时间投下一个护盾信标，持续15 秒，信标会投射出10码半径的力场，使附近盟友的护甲值提高220。［拥有信标充能: \n\n过载：为10码范围内的盟友施加护盾，吸收（150% 治疗强度 + 815 × 等级系数 + 100% 耐力）点伤害，数值受盟友耐力加成。］\n\n与其他信标共享冷却时间'),
(801801, '3层充能，15秒充能时间投下一个恢复信标，持续15 秒，投射出一个力场，每3秒为区域内的团队和队伍成员恢复（125 × 等级系数 + 12% 法术强度）点生命值。［拥有信标充能: \n\n过载：为15码范围内的所有盟友恢复10%最大生命值外加（264 + 80% 治疗强度）点生命值。］\n\n与其他信标共享冷却时间'),
(801802, '在目标位置召唤一个雷霆宝珠，持续16 秒，触发球状电击并产生10点静电。'),
(801809, '向一名盟友发送纳米机器人，在 1 分钟内为其恢复 360 点生命值。\n\n纳米机器人重构每次只能发送给1个目标，且无法被驱散。'),
(801821, '当穿刺强化或以太增强激活时，你的远程急速提高10%。'),
(801827, '强化接下来的［拥有火箭弹幕: 10；否则： 6］次废铁射击或火箭发射器，在30 秒内对目标周围最多10个敌人造成额外火焰伤害，数值相当于造成伤害的100%。'),
(801838, '制造一股强风，击退附近所有敌人。'),
(801839, '消耗50点静电以狂风之重碾压敌人，造成（138 + 63.5% 自然法术强度）点自然伤害，并在1 秒后额外造成40%的伤害。'),
(801841, '使分叉闪电、召唤闪电和电刑造成的伤害额外提高30%，并允许电刑攻击3个额外敌人。'),
(801844, '生成20点静电电刑一名敌人，造成（25 + 45% 自然法术强度）点自然伤害。\n\n仅能对生命值低于35%的敌人使用。'),
(801847, '消耗所有静电召唤一道可怕的闪电光束轰击敌人，造成（128 + 120% 自然法术强度）点自然伤害，并使其昏迷 1 秒。\n\n伤害和施法时间根据静电等级提高。'),
(801851, '向一名敌人发射闪电，造成（77 + 49% 法术强度）点自然伤害，并弹射至多 4 个敌人。\n\n每击中一个敌人产生 5 点静电。'),
(801855, '你对受溺水影响的敌人的暴击几率提高 15%。'),
(801859, '在敌人目标头顶召唤一片雷云，持续15 秒，使其受到你的法术伤害提高20%。\n\n对受湍流之怒影响的敌人使用风暴云时，会在其脚下引发喷泉，造成（538.084 + 25% 冰霜法术强度）点冰霜伤害并将其轻微击飞。'),
(801868, '对最多3个敌人造成（16 + 4% 自然法术强度）点自然伤害，并使其从雷霆宝珠和能量之球受到的伤害提高［拥有导电: 1%］，持续8 秒，可叠加6层。'),
(801869, '施放召唤闪电或电刑现在会使托里姆之臂和闪电牢笼的冷却时间减少 1.5 秒。'),
(801892, '双刃斩或安尼赫兰打击的暴击现在会额外产生 1 点邪能之怒。'),
(801895, '消耗2层邪能之怒对一名敌人施加厄运，造成（火焰法术强度高于暗影法术强度时：（116 + 100% 火焰法术强度）；否则：（116 + 132% 暗影法术强度））点暗影烈焰伤害，穿透所有吸收效果。\n\n心魔：额外造成相当于伤害量30%的伤害，持续3 秒。'),
(801899, '近战技能伤害现在有15%的几率重置安尼赫兰打击的冷却时间，并使你在15 秒内的下一次安尼赫兰打击能量消耗降低50%。'),
(801901, '产生1层邪能之怒双持武器攻击，每次攻击造成100%武器伤害外加8点伤害。'),
(801903, '产生2层邪能之怒发动毁灭性攻击，用双武器对目标造成210%的武器伤害。\n\n该技能对生命值高于75%的敌人必定造成暴击。'),
(801904, '消耗 2 点邪怒用两把武器攻击一个敌人，造成武器伤害外加（26 + 14.5% 攻击强度）点伤害，并额外受到攻击强度加成。［拥有心魔: \n\n心魔：使心魔的持续时间延长 3 秒。］'),
(801905, '每个目标产生10点热量召唤火焰条纹轰击一名敌人及其15码范围内最多8个目标，造成（107 + 31.24% 火焰法术强度）点火焰伤害。'),
(801911, '朝你移动方向冲刺20码，对路径上的敌人造成（13.52 + 40% 火焰法术强度）点火焰伤害，并使施法者摆脱昏迷和束缚效果。'),
(801925, '诅咒一个敌人，持续8 秒，每2秒吸取100点法力值，并阻止法力值恢复。\n\n每个目标同时只能有一个厄运咒生效。'),
(801938, '重新激活你的疾病，刷新目标敌人身上的所有疾病并将其复制，保留其威力和持续时间。\n\n你可以在10秒内再次使用此技能，感染另一个目标，施加已复制的疾病。'),
(801945, '对一名敌人施加疾病，每2.5秒造成（32 + 25% 暗影法术强度）点瘟疫伤害，并在20 秒内降低目标受到的神圣治疗量40%。\n\n如果亡灵瘟疫被驱散，敌人将受到（88 + 125% 暗影法术强度）点瘟疫伤害并被眩晕5 秒。\n\n此效果造成的周期性伤害受你的法术急速加成。'),
(801951, '你的感官变得敏锐，立即获得5层优势，并在15 秒内无需进入潜行即可获得隐匿的效果。'),
(801952, '修复血肉与骨骼，为一名盟友恢复其最大生命值的50%，并施加满足效果。［拥有汇聚活力: \n\n强化：额外恢复你最大生命值25%的生命值，并降低100%的怒气消耗。］'),
(801955, '召唤血契，以生命换取强化反应，提高你的闪避几率，并使远程攻击命中你的几率降低50%［拥有血液渐冷: ，同时使你受到的治疗效果提高20%］，持续12 秒。\n\n激活时，你可以在施法时进行闪避或招架。'),
(801957, '嘲讽一名敌人攻击你，持续 3 秒。'),
(801958, '召唤 1 只暗影蝙蝠从暗影中现身，打击目标，造成（5.65 + 20% 攻击强度 + 40% 法术强度）点物理伤害，并为你恢复等量的生命值。'),
(801959, '20 码内的盟友受到暗影群落的保护，使他们在受到直接伤害时有 40% 的几率触发暗翼召唤。每3秒只能触发一次。\n\n如果此效果触发时盟友的生命值低于你，则对触发该效果的敌人产生大量威胁值。'),
(801960, '施放嚎叫法术现在对所有附近敌人造成（65 + 25% 敏捷 + 10% 攻击强度 + 25% 耐力）点暗影伤害，且触发暗翼召唤现在使所有嚎叫法术的冷却时间减少 1 秒。\n\n每秒只能触发一次。'),
(801961, '你的液化现在在使用时会清除所有负面效果。'),
(801962, '激活你永恒的意志，持续30 秒，使你进入狂野的狂暴状态，提高近战攻击速度、最大生命值和受到的治疗效果，提高50%。'),
(801963, '施放诅咒形态技能现在有 50% 的几率获得 1 枚鲜血碎片，持续 10 分钟，最多 8 枚。\\r\n\\r\n使用血箭造成伤害时，会发射 1 枚鲜血碎片，对你的目标造成（18 + 5% 攻击强度 + 10% 法术强度）点法术暗影伤害。'),
(801968, '50级被动使你的最大生命值提高10%，并且在变身为虚空巨兽形态时，你造成的伤害也会提高20%。'),
(801972, '发射一支附魔箭矢，造成（9 + 15% 智力 + 48% 远程攻击强度 + 33% 法术强度）点物理伤害，并恢复你最大法力值的10%再加上10点。\n\n受远程攻击强度、法术强度和智力加成。'),
(801975, '女猎手射击和唤星术现在额外施加一层散落星辰，并且你的远程攻击范围在20 秒内提高至50码。'),
(801976, '使你受到的有害魔法效果持续时间缩短25%。'),
(801978, '消耗散落星辰发射一支附魔箭矢，造成100%远程武器伤害，外加（64 + 9% 最大法力值）点奥术伤害，数值进一步受你的最大法力值加成。\n\n月蚀： 对目标施加灼烧，在6 秒内造成720点法术火焰伤害。受到你的星火术影响的敌人无法潜行。'),
(801987, '向艾露恩祈祷，治疗40码内最多12名盟友，治疗量为（77 + 27.5697% 治疗强度），并驱散他们身上的1个有害魔法效果。'),
(801989, '你对生命值低于20%的盟友造成的治疗效果提高30%。'),
(801990, '消耗20%最大法力值用艾露恩的恩惠包围一名盟友，为其治疗［拥有艾露恩之手消耗 %: （15% 最大法力值 + 300 × 等级系数 + 47.6% 法术强度）］，随最大法力值提高。\n\n可在移动时施放。'),
(801996, '每次命中叠加1层散落星辰粉碎最多8个敌人，造成（2 + 15% 攻击强度 + 30% 奥术法术强度）点奥术伤害，伤害受格挡值和最大法力值加成，并使其攻击速度降低20%，持续10 秒。\n\n消耗一层散落星辰可使星辰爆裂的剩余冷却时间减少2秒。'),
(802004, '用你的利刃打击一名敌人，对其造成武器伤害外加 25 点神圣伤害，并对 5 名附近敌人造成同样伤害。'),
(802006, '2层充能，25秒充能时间向一名敌人冲锋，使其移动速度降低70%，持续2 秒，并产生20点怒气。'),
(802011, '使强效药剂的持续时间增加5秒。'),
(802013, '嘲讽一名敌人攻击你，持续 3 秒。如果目标是恶魔或亡灵，则额外受到（1 + 35% 攻击强度）点暗影伤害。'),
(802019, '用灼热之刃攻击一名敌人，双持武器造成武器伤害外加20点火焰伤害。\n\n获得罪孽之火或将其持续时间延长3秒。'),
(802020, '用双持武器打击一名敌人，造成武器伤害外加（10 + 15% 暗影法术强度）点暗影伤害，穿透抗性。为你恢复造成伤害的 25% 点生命值。'),
(802024, '挥砍一名敌人，造成武器伤害加上（14 + 15% 攻击强度 + 15% 火焰法术强度）点神圣火焰伤害。［拥有罪孽之火: \n\n使你获得罪孽之火，并使其持续时间延长 3 秒，使你的自动攻击造成额外的火焰伤害。］'),
(802036, '瞄准头骨，造成（10 + 10% 攻击强度 + 25% 远程攻击强度）点物理伤害。\n每层优势都会提高伤害。'),
(802039, '使你的暴击几率提高15%，并降低你的集中值消耗25%。\n\n每层优势持续4秒。'),
(802042, '在你附近召唤一个尤格萨隆触须，持续30 秒。\n\n15码范围内的盟友受到的治疗效果提高6%，并降低50%的法术退条效果。\n\n你同时只能激活1个上古之神触须。'),
(802043, '现在闪避攻击会使你的暴击和躲闪几率提高2%，持续6 秒，最多可叠加5层。'),
(802044, '在你附近召唤一个亚煞极触须，持续30 秒。\n\n当被召唤时以及每当使用克苏恩之凝视时，它会猛击地面，对前方10码锥形范围内的所有敌人造成物理伤害，伤害随耐力提高。\n\n你同时只能激活1个上古之神触须。'),
(802047, '使暮光之锤和熵能猛击造成的武器伤害提高20%。'),
(802048, '使你的触手造成的伤害提高20%。'),
(802049, '召唤上古之神，持续15 秒，移除你的下3次惊骇愈合或恶意的施法时间，并使其必定造成暴击。'),
(802052, '在你面前建造一座蜘蛛炸弹工厂，持续20 秒。\n\n持续期间，炸弹投掷和火箭发射器将召唤3枚蜘蛛炸弹，它们会立即冲向你的目标并引爆，造成（33.5 + 18% 远程攻击强度 + 18% 法术强度）点火焰伤害。\n\n使用废料射击会将蜘蛛炸弹重新导向至你的新目标。'),
(802058, '在10 秒内，你的邪能火球将变为免费施放、瞬发，并最多击中4个目标。\n\n在此期间，你的坠落速度降低，且你的邪能火球造成的伤害会使你造成的伤害提高4%，持续15 秒，可叠加4层。'),
(802060, '消耗2层邪能之怒对一名敌人造成（火焰法术强度高于暗影法术强度时：（21 + 19% 攻击强度 + 60% 火焰法术强度）；否则：（21 + 19% 攻击强度 + 60% 暗影法术强度））点暗影烈焰伤害，并产生20点能量。［拥有心魔: \n\n心魔：该法术会额外免费施放一次。］'),
(802065, '诅咒一个敌人，持续10 秒，使其移动速度降低50%［拥有衰败诅咒: ，并使其受到周期性治疗效果降低30%］。\n\n同一目标身上只能同时存在1个厄运咒。'),
(802068, '周期性火焰伤害现在有 10% 的几率获得一层烈焰施法，如果造成暴击则获得两层。'),
(802075, '产生6点邪能之怒浸入玛诺洛斯的血液中，使你的能量恢复速度提高100%［拥有邪能迷雾: ，并让你无视所有敌人的护甲］，持续20 秒。'),
(802076, '你的湮灭现在影响 1 次额外攻击，且你造成的物理伤害提高 3%。'),
(802087, '向一名敌人发射一道暗影魔法箭矢，造成（191 + 100% 法术强度 + 30% 精神）点暗影伤害。\n\n如果目标受到恶意妖咒影响，还会使其受到的治疗效果降低 20%，持续 8 秒。'),
(802092, '暗影傀儡造成的伤害现在使你的伤害和暴击几率提高1%，持续20 秒，最多可叠加10层。\n\n额外触发不会刷新持续时间。'),
(802100, '用暗影巫毒面纱包裹一个目标，使你对其造成的伤害提高15%，持续15 秒。\n\n如果你与目标距离在40码以内，则每1.5秒对其造成（194.7 + 4.5% 攻击强度 + 10% 暗影法术强度）点暗影伤害。'),
(802107, '产生30点热量对一名敌人释放凶猛的龙颚，造成（144 + 100% 火焰法术强度）点无法被抵抗的火焰伤害。'),
(802108, '20级被动技能你的法术伤害提高，数值相当于你的智力和精神的15%。\n\n此外，心魔现在使你的法术伤害和暴击等级额外提高，数值相当于你的精神的20%。'),
(802117, '释放你的巨龙化身，使你的法术伤害提高相当于智力30%的数值，并使你的法术暴击伤害提高50%。\n\n激活时，对敌人造成直接伤害会使其受到巨龙之怒效果影响。'),
(802119, '召唤所有守护巨龙，立即产生 5 点余烬。'),
(802120, '为一名盟友注入玛里苟斯的精华，每1秒恢复其4%的最大法力值，持续6 秒。\n\n若对自己使用，该效果翻倍。'),
(802121, '从你的亡灵仆从身上吸取生命，牺牲其40%的生命值，为你提供一个相当于所偷取生命值一半的吸收护盾，持续20 秒。\n\n可在昏迷时使用。'),
(802132, '使一名敌人感染疾病，每3秒造成（151 + 22% 法术强度）点瘟疫伤害，持续18 秒。\n\n敌人身上的每个死灵法师疾病都会使伤害提高4%。'),
(802138, '为自己施加一面黑暗护盾，吸收（3255 + 41% 攻击强度 + 700% 耐力）点伤害，然后凝视你的小队成员，使他们在12 秒内受到的伤害中有25%转移给你。\n\n将你的生命值降低至20%以下的伤害会打破此效果。\n\n可在昏迷时使用。'),
(802139, '用你的罪孽之火为灯笼充能并使其闪耀，造成（291 + 15% 攻击强度）点火焰伤害，使附近所有敌人昏迷5 秒，并打断非玩家角色的施法3 秒。'),
(802140, '审判一名敌人，对其及附近敌人造成（361 + 40% 攻击强度 + 100% 火焰法术强度）点火焰伤害。\n\n获得罪孽之火或使其持续时间延长 3 秒。'),
(802161, '向前瞬移 25 码并移除定身效果，在原地留下传送门，持续 15 秒。盟友可与传送门互动，向前瞬移相同距离；每名盟友的使用冷却时间为 90 秒。'),
(802164, '消耗余烬现在有25%的几率对所有受到巨龙之怒影响的敌人触发炽燃。'),
(802167, '移除你周围20码范围内所有队伍和团队成员身上的所有移动限制效果，并使他们免疫昏迷、减速和定身效果，持续4 秒。'),
(802168, '你的下一次诺兹多姆的回响或奈萨里奥之焰必定造成暴击，并触发时光化身，额外施放一次造成 45% 伤害的效果。持续 15 秒。\n\n以此方式造成的伤害最多可额外触发3次。'),
(802169, '增加烈焰步的射程10码。'),
(802170, '你的火雨和熔岩碎片现在会使敌人身上的炽燃持续时间延长3秒，并使其被法术命中的几率提高3%，持续10 秒。'),
(802173, '释放你的怒火，对目标造成（9 + 30% 火焰法术强度）点火焰伤害，穿透所有抗性和吸收效果。'),
(802175, '复活5码范围内最多5个已死亡的盟友，恢复其70点生命值和135点法力值。\n\n无法在战斗中施放。'),
(802180, '对生命值高于75%的敌人，提高邪能火球和毁灭的暴击几率20%。'),
(802202, '轰击一名敌人，造成（30 + 5% 攻击强度 + 55% 法术强度）点元素伤害［拥有冰霜符印: ，并生成一个符印］。'),
(802203, '激活时，你的治疗效果提高10%，并且你的法术和技能不会未命中。\n\n此外，消耗散落星辰现在会治疗目标周围最多5名盟友，治疗量为（31.85 + 14.9749% 治疗强度）。\n\n与其他架势共享冷却时间。'),
(802204, '释放一个雕文会使你的释放雕文的伤害提高 5%，持续 15 秒，最多叠加 3层。'),
(802207, '提高近战、远程和法术急速3%。'),
(802208, '受到的治疗效果提高3%。'),
(802215, '暴击几率提高3%。'),
(802216, '受到的物理伤害降低3%。'),
(802219, '魔精光束产生的有效治疗现在会使投掷药水和溅射药水的冷却时间缩短1秒。\n\n施放洛阿之酿现在会使魔精光束的冷却时间缩短2秒。'),
(802229, '进入静止状态，持续6 秒，立即恢复15%的最大法力值，并在每0.5秒恢复5%的最大法力值。\n\n激活时，你受到的伤害降低50%，但受到任何直接伤害都可能中断此效果。'),
(802262, '你的毒蛇守卫的攻击现在有20%的几率发射巫毒之火，对最多3名附近敌人造成（火焰法术强度高于自然法术强度时：（12.5% 远程攻击强度 + 73 × 等级系数 + 12% 火焰法术强度）；否则：（12.5% 远程攻击强度 + 73 × 等级系数 + 12% 自然法术强度））点火焰伤害。'),
(802268, '召唤毒蛇守卫或精魂现在会使你的下一次精魂飞刃或精魂之蚀的伤害提高6%，持续10 秒，可叠加5层。'),
(802269, '向一名敌人射出一发带有绳索的箭矢，造成（6 + 25% 攻击强度）点物理伤害并将其拉向你。'),
(802272, '你可以激活此技能，持续10 秒，使你的陷阱能够投掷到30码外。'),
(802276, '饮用一瓶吸血鬼药剂，使你造成的物理伤害的40%转化为治疗［拥有亡灵使者: ，并使你的躲闪几率提高0%］，持续10 秒。\n\n同时只能激活1瓶药剂。'),
(802277, '饮用一瓶炽热药剂，使你的火焰伤害提高30%，暴击伤害提高20%，持续10 秒。\n\n同时只能激活1瓶药剂。'),
(802278, '饮用一瓶暗影药剂，移除你身上的所有诅咒效果，并在10 秒内使受到的所有魔法伤害降低60%。\n\n同时只能激活1瓶药剂。'),
(802279, '饮用苦味药剂，使所有技能的法力消耗降低40%，持续10 秒。\n\n同时只能激活1瓶药剂。'),
(802280, '打击一名敌人，造成100%武器伤害外加26点伤害，伤害随你的招架等级提高，并为你恢复造成伤害的100%生命值。'),
(802281, '变身为目标亡灵或恶魔敌人的形态。持续永久，或直到你上马、造成或受到伤害。\n\n激活时，你对所有敌对生物呈现中立状态。仅可在开放世界中使用。'),
(802284, '用盾牌猛击一名敌人，造成（12 + 38.5% 攻击强度）点物理伤害，伤害随你的格挡值提高，并使目标的护甲降低4%，持续20 秒，可叠加5次。'),
(802286, '刺击一名敌人，造成145%的武器伤害，并根据你的武器附加额外效果。\n\n剑：触发3次额外自动攻击。\n\n斧：必定造成暴击，伤害提高25%。\n\n锤：无视目标50%的护甲。\n\n长柄武器：额外刺击目标及其身后的敌人一次。'),
(802290, '降低［拥有节奏: 征服者之歌；否则： 粉碎］和［拥有节奏: 屠龙者之歌；否则： 横扫千军］的能量消耗5点。'),
(802295, '你的近战自动攻击现在有20%的几率额外攻击2次。'),
(802296, '你的勇气战旗的移动速度降低效果提高15%。'),
(802297, '装备剑时，你的近战急速提高10%。'),
(802299, '允许你使用长柄武器，并可在装备盾牌时使用它们。\n\n当装备长柄武器时，你的近战技能获得2码的额外攻击距离。'),
(802300, '冲撞现在对定身敌人使用时，会使你的战斗冲锋冷却时间减少10秒。'),
(802310, '需要凡人之躯\\r\n\\r\n治疗一个盟友的伤口，为其恢复（24 + 20% 攻击强度 + 58% 法术强度 + 25% 精神）点生命值。［拥有汇聚活力: \\r\n\\r\n增效: 变为瞬发，并为自己恢复相当于治疗量 50% 的生命值。］'),
(802313, '血棘术从一名盟友身上长出，持续30 分钟，当被击中时对攻击者造成（6 + 3.5% 暗影法术强度）点暗影伤害。\n\n每半秒只能触发一次。'),
(802315, '你的塔达拉姆的折磨现在每跳额外产生3点怒气，并提高对目标的法术暴击几率3%，持续15 秒。'),
(802335, '每 0.2 秒向目标发射 1 枚岩浆晶洞，持续 0.2 秒，造成（火焰法术强度高于自然法术强度时：（225 + 20% 火焰法术强度）；否则：（225 + 20% 自然法术强度））点火焰风暴伤害。\n\n每层大地塑形使持续时间延长 0.2 秒。'),
(802342, '制造一场地狱风暴，对最多8名附近敌人造成（120 + 8% 攻击强度 + 25% 火焰法术强度）点火焰伤害。\n\n随后余烬每1秒爆发一次，持续2 秒，造成（59 + 5% 攻击强度 + 5% 火焰法术强度）点火焰伤害。\n\n每消耗一层恶魔之火，持续时间延长100%。'),
(802344, '散发瘟疫，降低附近敌人25%的移动速度和10%的攻击速度。［拥有释放瘟疫: \n\n释放：降低10码范围内敌人50%的移动速度，持续8 秒。］'),
(802345, '散发瘟疫，每消耗一点恶魔之火为你恢复［拥有瘟疫先驱: 1.5%；否则： 1%］的最大生命值。［拥有释放瘟疫: \n\n释放：从附近敌人身上吸取（17.25 + 16% 攻击强度 + 20% 法术强度）点生命值，并恢复5%的最大生命值。］');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (802354, 802487, 802494, 802575, 802576, 802581, 802595, 802602, 802603, 802604, 802605, 802610, 802615, 802619, 802629, 802630, 802631, 802669, 802678, 802680, 802682, 802684, 802707, 802710, 802714, 802719, 802727, 802728, 802756, 802780, 802782, 802790, 802792, 802793, 802797, 802826, 802839, 802870, 802888, 802935, 802963, 802986, 802988, 802990, 803013, 803018, 803030, 803035, 803037, 803074, 803082, 803085, 803104, 803108, 803113, 803114, 803115, 803126, 803128, 803129, 803130, 803134, 803157, 803158, 803159, 803163, 803177, 803183, 803185, 803193, 803195, 803196, 803197, 803198, 803199, 803210, 803212, 803219, 803225, 803236, 803237, 803283, 803291, 803325, 803333, 803334, 803339, 803340, 803343, 803347, 803392, 803405, 803417, 803436, 803437, 803452, 803463, 803478, 803489, 803491, 803511, 803525, 803546, 803552, 803563, 803564, 803565, 803570, 803571, 803573, 803638, 803645, 803649, 803651, 803657, 803658, 803665, 803667, 803671, 803678, 803679, 803681, 803683, 803700, 803719, 803730, 803731, 803736, 803737, 803738, 803741, 803748, 803766, 803772, 803797, 803798, 803814, 803817, 803819, 803851, 803871, 803872, 803889, 803903, 803904, 803905, 803950, 803956, 803963, 803973, 803974, 803980, 803981, 803990, 803992, 803995, 803997, 803998, 803999, 804002, 804004, 804013, 804014, 804017, 804018, 804019, 804020, 804024, 804026, 804027, 804032, 804033, 804035, 804036, 804038, 804040, 804046, 804047, 804049, 804051, 804052, 804053, 804056, 804057, 804058, 804060, 804061, 804068, 804094, 804124, 804136, 804137, 804138, 804139, 804141, 804152, 804154, 804168, 804169, 804178);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(802354, '消耗20点静电\n2层充能，10秒充能时间在目标位置生成一个8码的上升气流，持续20 秒。\n\n对范围内的敌人造成持续（260 + 68.3% 自然法术强度）点自然伤害。\n\n使范围内友方单位的移动速度提高25%。'),
(802487, '投掷药水现在对目标施加不稳定混合物，持续20 秒。\n\n对目标使用洛阿之酿或瓶中精魂将触发目标周围的魔精爆炸，为20码范围内的附近盟友恢复（9 + 40% 治疗强度）点生命值。'),
(802494, '原初奔袭和巨石冲刺的冷却时间缩短20%。'),
(802575, '恢复理智，使你的狂乱值降低20点，并恢复你缺失法力值的20%。\n\n可在施法或引导时使用。'),
(802576, '你的吸血鬼之牙伤害提高25%'),
(802581, '猛击地面，对附近敌人造成65%武器伤害外加2点伤害，并使其受到的所有治疗效果降低50%，持续10 秒。\n\n每消耗一层恶魔之火，造成的伤害提高。'),
(802595, '双头飞龙之咬造成的伤害现在会使你的宠物的伤害和暴击几率提高2%，持续10 秒，可叠加2层。'),
(802602, '将你的强效小鬼转化为末日守卫，持续20 秒。\n\n在转化状态下，你的末日守卫造成的伤害提高50%，并且其自动攻击会点燃目标，在6 秒内额外造成相当于伤害值10%的火焰伤害，可叠加6层。'),
(802603, '小鬼造成的伤害有20%的几率使敌人的近战和远程攻击速度降低20%，持续6 秒。'),
(802604, '小鬼造成的伤害有20%的几率为你恢复（1 + 10% 攻击强度）点生命值。'),
(802605, '小鬼造成的伤害有20%的几率使敌人的魔法伤害降低5%，持续5 秒。'),
(802610, '你的夺颅者在拥有6层恶魔之火时使用，现在会使末日的冷却时间减少5秒。\n\n此外，当末日激活时，你的末日守卫现在会复制你的夺颅者，造成降低的伤害。'),
(802615, '地狱火打击现在会为你叠加一层克索诺斯狂怒，使你在10 秒内的下一次夺颅者的暴击几率每层提高10%，最多叠加3层。\n\n此外，当拥有6层夺颅者时使用恶魔之火会赋予你地狱咆哮，使你在10 秒内的下一次地狱火打击必定造成暴击。'),
(802619, '地狱之喉在效果结束时引发一场地狱火爆炸，对5码内的所有附近敌人造成额外火焰伤害，数值相当于持续期间周期性伤害的50%。'),
(802629, '对附近所有敌人造成（144 + 37% 攻击强度）点物理伤害。\n\n使你的格挡几率提高 10%，每次格挡都会使加固的冷却时间缩短 2 秒。持续5次格挡或 10 秒。\n\n随重击的修正效果而提升。'),
(802630, '与空气共鸣，移动速度提高20%，并有20%几率抵抗移动限制效果'),
(802631, '在目标位置铭刻一个半径为5码的符文，在0.999秒后激活，使范围内的所有敌人沉默，持续6 秒'),
(802669, '魔网封锁的持续时间增加 0.5 秒。'),
(802678, '在6 秒内灼烧一名敌人，造成（54 + 30% 法术强度）点暗影烈焰伤害，最多叠加3层。'),
(802680, '消耗散落星辰现在有15%几率将星界打击转化为月刃，持续8 秒。'),
(802682, '发射一枚附魔箭矢，造成100%远程武器伤害外加（50 + 40% 奥术法术强度）点奥术伤害，并在3 秒内每0.5秒额外造成（50 + 7.5% 奥术法术强度）点奥术伤害，同时施加一个散落星辰效果。\n\n受星火射击的修正效果影响。\n\n可在移动时使用。'),
(802684, '向一名盟友快速发射治疗刺激针，为其恢复（116 + 38.5% 治疗强度）点生命值'),
(802707, '使你对此目标造成的伤害和暴击几率提高1%，最多可叠加5层。\n\n受影响期间，敌人无法潜行或隐身。'),
(802710, '从你的大锅中装填一瓶喷溅药水，并将其投掷到指定位置，为最多8名盟友恢复（54 + 22.4494% 治疗强度 + 8% 精神）点生命值。\n\n以此方式使用的材料所产生的材料效果会降低。'),
(802714, '你的精魂飞刃现在会在其持续时间结束时额外造成（25% 远程攻击强度 + 315 × 等级系数 + 40% 暗影法术强度）点暗影伤害。'),
(802719, '召唤邦桑迪之灵，持续8 秒。在15码范围内时，你免疫所有有害法术和效果，但造成的伤害和治疗效果降低50%。\n\n当盟友处于15码范围内时，其受到的伤害降低20%。\n\n无法在从强大巫毒中获益后的2 分钟内使用。'),
(802727, '引导攻击一名敌人，并连锁至附近敌人，在4 秒内造成（80 + 176% 暗影法术强度）点暗影伤害，每击中一个敌人伤害递减。'),
(802728, '使你的触手的暴击几率和暴击伤害提高10%。'),
(802756, '你的直接伤害现在为你恢复造成伤害的10%生命值。'),
(802780, '每第3次组合施放奈萨里奥之焰或诺兹多姆的回响时，获得大地化身，持续15 秒。'),
(802782, '以高贵的坚韧咆哮，产生20点怒气，并使所有小队和团队成员的最大生命值提高10%，持续12 秒。［拥有大地母亲之咆哮: \n\n此外，你为所有受影响的盟友恢复相当于其缺失生命值20%的生命值。］'),
(802790, '与目标玩家交换位置。\n\n如果目标是敌人，你偷取其80%的移动速度，持续3 秒。'),
(802792, '尝试击碎敌人的下巴，打断其施法，并使其在4 秒内无法施放该系法术。［拥有击倒专家: \n\n成功打断目标后，你的急速提高30%，持续4 秒，并返还此技能一半的消耗。］'),
(802793, '猛踏地面，释放出一道20码的土石波，将路径上的所有敌人击退到两侧，并造成（火焰法术强度高于自然法术强度时：（684 + 100% 火焰法术强度）；否则：（684 + 100% 自然法术强度））点火焰伤害，穿透吸收效果。\n\n你在6 秒内的下一个法术变为瞬发。'),
(802797, '召唤艾露恩的一名监视者降临指定区域，持续15 秒，揭示潜行和隐形的敌人。'),
(802826, '在你脚下砸碎一瓶圣水补剂，驱逐周围所有亡灵和恶魔敌人10 秒，并使你对亡灵和恶魔造成的伤害提高30%，持续10 秒。\n\n同时只能激活1瓶药剂。'),
(802839, '饮用一瓶生存药剂，驱散所有中毒和疾病效果，并在9 秒内每3秒移除1层中毒和疾病效果。\n［拥有生存工具包: \n此外，每次生效时恢复你最大生命值的10%。］'),
(802870, '跃入空中，免疫群体控制效果，然后以惊人的速度砸向你的敌人。\n\n落地时，对冲击区域内的敌人造成400%武器伤害，并在6 秒内额外造成（611.25 + 77.25% 攻击强度）点伤害，无视护甲并将其击飞至空中。'),
(802888, '精神冲锋和原始突袭现在会召唤2个生命之灵，立即对最近的盟友施放一次较弱的精神冲锋，为其恢复（64 + 20% 攻击强度 + 20% 自然法术强度）点生命值，并对附近敌人造成（71 + 20% 攻击强度 + 20% 自然法术强度）点自然伤害。'),
(802935, '造成的物理伤害提高 6%，自动攻击有 10% 几率恢复 3% 最大法力值。'),
(802963, '使炸弹投掷和火罐无人机的暴击几率提高10%。'),
(802986, '你的亡灵仆从造成的伤害现在有10%的几率对自己施放瘟疫大军，持续5 秒，并散发僵尸瘟疫，对其目标造成（79 × 等级系数 + 10% 法术强度）点瘟疫伤害。'),
(802988, '使巫妖寒霜的施法时间缩短15%，并使你在受到伤害时因施法被打退的效果降低50%。'),
(802990, '使你的疾病持续时间提高25%。'),
(803013, '武器铭刻：火焰现在对冻结的敌人造成25%的额外伤害。'),
(803018, '以冰霜之怒打击一个敌人，造成（921 + 150% 攻击强度）点冰霜伤害，并燃烧目标（25 + 35% 攻击强度）点法力值。\n\n对冻结目标造成的伤害必定暴击。'),
(803030, '延迟 1 秒后，你承受 660 点 + 36% 攻击强度的伤害，使你狂暴，15 秒内造成的伤害提高 20%。'),
(803035, '进入强大的灵气形态，使造成的伤害有20%的几率诅咒地面，持续12 秒，每3秒对范围内的敌人造成（11.175 + 7.5% 攻击强度 + 13.5% 法术强度）点暗影伤害。\n\n你同时只能激活1种灵气。'),
(803037, '进入黑暗的灵气形态，使造成的伤害有20%几率召唤触手附着于你的背部，攻击附近的一名敌人造成8 秒点伤害。\n\n你同时只能激活1个灵气。'),
(803074, '当弹片地雷爆炸时，你会在目标脚下生成2个黏性炸弹。'),
(803082, '进入疯狂灵气状态，使你的伤害有 30% 几率对目标造成（18.5 + 18% 法术强度）点暗影伤害，并使其施法速度降低 30%，持续 6 秒。\n\n你同时只能激活一种灵气。'),
(803085, '使你的法术和技能的能量消耗降低10%。'),
(803104, '产生2点优势在1 秒内对一名敌人发动4次快速打击，每次造成110%武器伤害。\n\n如果目标正在流血，每次打击额外造成（602.25 + 25% 攻击强度）点物理伤害。\n\n如果目标中毒，每次打击将造成自然伤害而非物理伤害。'),
(803108, '攻击一个低生命值的敌人，造成100%武器伤害（装备匕首时为175%），外加额外的（8 + 100% 攻击强度）点物理伤害。如果目标正在流血，则伤害提高50%。\n每层优势使伤害提高。\n仅能对生命值低于20%的敌人使用。'),
(803113, '使你的副手武器伤害提高25%。\n\n手持长柄武器时，你的流血效果伤害提高25%。'),
(803114, '侧翼攻击和生锈匕首造成的伤害现在会使目标在8 秒内从你的优势终结技中受到的伤害提高25%。'),
(803115, '夺取敌人的近战武器，使其缴械4 秒。\n\n如果你被缴械，你也会将武器归还给自己。'),
(803126, '近战暴击现在有50%的几率重置律法之锤的冷却时间。\n\n施放［拥有王者之锤: 王者之锤；否则： 勇气战旗］现在会使你的攻击强度提高10%，持续15 秒。'),
(803128, '使你的招架和躲闪几率提高4%，并使你的锁甲和板甲物品提供的护甲值提高20%。'),
(803129, '猛击一名敌人及其身后的敌人（直线），造成（23 + 37% 攻击强度）点高威胁物理伤害，随防御等级提高。'),
(803130, '使你的移动速度提高15%［拥有步兵天职: ，受到的伤害降低10%，］并使移动限制效果对你的持续时间缩短25%。'),
(803134, '你的粉碎和冲撞现在有10%几率重置举盾的冷却时间。'),
(803157, '释放一名破誓者，对一名敌人造成（10 + 45% 攻击强度 + 60% 神圣法术强度）点神圣伤害［拥有武术训练: ，并额外造成150%点武器伤害］。\n\n消耗你的誓言，每消耗一层造成额外伤害。'),
(803158, '近战攻击现在恢复1点能量，暴击时额外恢复2点能量。'),
(803159, '使圣契的冷却时间缩短15秒，并且破誓者现在会治疗目标周围的盟友，治疗量为（20 + 35% 法术强度）。'),
(803163, '你造成的物理伤害现在有25%的几率使你的信仰之刃和定罪的跳动频率提高10%，可叠加5次。'),
(803177, '为一名盟友注射蜘蛛信息素，使其敏捷提高6点，持续30 分钟。'),
(803183, '变形为甲虫形态，允许使用需要该形态的技能，并使你的护甲加成提高100%，最大生命值提高相当于你的智力和敏捷的500%。\n\n激活时，你免疫变形术效果，受到的伤害降低10%，产生的威胁值提高140%，此外由自然伤害产生的威胁值额外提高200%。'),
(803185, '用魔法锁链锁定一个敌人，使其昏迷并拖拽跟随你移动，持续5 秒。\n\n每1秒，敌人将受到16点物理伤害。\n\n无法被昏迷或定身的敌人无法被拖拽。'),
(803193, '用前腿刺穿敌人，造成（32 + 15% 攻击强度 + 35% 自然法术强度）点自然伤害。［拥有剧毒驱散: \n\n消耗毒刺毒素的2秒持续时间，对附近敌人造成20点自然伤害。］'),
(803195, '向一名敌人及其附近所有敌人喷洒毒液，造成（30 + 10% 攻击强度 + 11% 自然法术强度）点自然伤害，并使其攻击速度降低20%，持续15 秒。'),
(803196, '清除暴露血肉的所有层数，将一根倒钩毒刺掷入敌人体内，持续0 秒，每清除一层额外延长1秒。对同一目标再次施放会拔出毒刺，将目标拉向你并造成自然伤害；毒刺留在目标体内越久，伤害越高。'),
(803197, '清除暴露血肉层数，使你在5 秒内受到的伤害降低20%，每层额外延长1秒。'),
(803198, '用利爪猛击一个敌人及其周围最多3个敌人，造成25点自然伤害，伤害随耐力提高。\n\n产生20点怒气。'),
(803199, '将身体猛砸向地面，对8码内的敌人造成（32 + 14.0625% 攻击强度 + 20% 自然法术强度）点自然伤害。'),
(803210, '受到的伤害降低5%，但受到的伤害有10%几率击碎你的外骨骼，移除该伤害减免效果。\n\n当你的外骨骼被击碎时，你将在12 秒内恢复最大生命值的8%，持续时间结束后你的外骨骼会重新生成。'),
(803212, '变形为海蛇形态，游泳速度提高75%，并使毒蛇使者能够在水下呼吸。'),
(803219, '你的希望圣约现在每个都会使受到的伤害额外降低5%。'),
(803225, '在持续时间内，累积你对目标造成伤害的 ［拥有极寒元素: 30%；否则： 20%］。\n\n持续时间结束后，将其作为冰霜伤害施加给目标。'),
(803236, '使你的暮光盾牌投掷造成的伤害提高100%，但不再弹射。'),
(803237, '40%的承受伤害现在会被延迟，并在8秒内对你造成。'),
(803283, '使你的灵气触发几率提高5%，法力值消耗降低50%。'),
(803291, '使冰霜之握的移动速度降低效果持续时间延长4秒，并使你的命中几率提高4%。'),
(803325, '诅咒一个野兽，使其恐惧并提高其移动速度25%，持续40 秒（对玩家为8秒）。\n\n每个目标同时只能拥有1个厄运咒。'),
(803333, '2层充能，15秒充能时间向一名敌人投掷流星索，造成（348 + 40% 攻击强度）点神圣伤害，并使其移动速度降低60%，持续8 秒。'),
(803334, '用地狱烈焰焚烧一名敌人，每层消耗的恶魔之火使其护甲降低 4%［拥有地狱猛击: ，并且从你的克索诺斯之刃和克索诺斯之焰受到的伤害提高 10%］，持续 24 秒。'),
(803339, '进入邪恶的灵气形态，使造成的伤害有20%的几率令你的急速提高20%，持续6 秒。\n\n你同时只能激活1种灵气。'),
(803340, '你的急速提高20%，持续6 秒。'),
(803343, '散发光环，使附近盟友的坐骑移动速度提高20%。\n\n每个玩家同时只能激活1个契约。'),
(803347, '当你造成暴击时，你的宠物恢复10点集中值。\n\n当你的宠物造成暴击时，你恢复2%的最大法力值，并使目标受到的物理伤害提高4%，持续10 秒。'),
(803392, '造成（55 + 10% 攻击强度 + 15% 暗影法术强度）点暗影伤害，并使目标从后续血肿效果中受到的伤害提高3%，可叠加10层。根据造成的伤害产生怒气值。'),
(803405, '制造一只机械熊陪伴地精工程师，直到被解散。'),
(803417, '提高你的暴击几率10%，但受到的伤害提高10%。'),
(803436, '建造一个发条助手来陪伴修补匠，直到被解散。'),
(803437, '建造一个铁锈猎犬来陪伴修补匠，直到被解散。'),
(803452, '使炽燃的持续时间延长20%，并使其能从你的法术急速中获益。'),
(803463, '使你的洛阿之酿和破咒的消耗降低10%。'),
(803478, '你的憎恨壁垒现在还会随你的最大生命值提高。\n\n施放破甲会使你在接下来4秒内施放两次恶魔爆炸。'),
(803489, '技能的直接伤害或治疗产生 2 点太阳能量，并额外造成相当于原数值 25% 的伤害或治疗。履行誓言：伤害或治疗翻倍。同一时间只能激活一种誓言。'),
(803491, '技能的直接伤害或治疗产生 1 点太阳能量，并跳转至附近 2 个额外目标，每次跳转效果递减。履行誓言：目标数量翻倍。同一时间只能激活一种誓言。'),
(803511, '使你与小队和团队成员的所有法术和攻击命中几率提高1%。\n不与同类效果叠加。'),
(803525, '在你面前放置一窝蛛卵，持续5 分钟。踩到蛛卵的敌人会受到（871 × 等级系数 + 150% 自然法术强度）点自然伤害并被定身，持续30 秒（对玩家为6秒），随后受到小蜘蛛的攻击。造成的伤害可能中断此效果。\n\n你最多同时拥有6个孵化陷阱。\n\n可在潜行状态下使用。无法在战斗中使用。'),
(803546, '灼烧你周围的地面，标记该区域持续5 秒，并吸引附近所有敌人。\n\n区域内的敌人移动速度降低80%，且受到的昏迷和定身效果持续时间增加50%。\n\n4.999秒后，你对附近敌人造成（2214 + 300% 火焰法术强度）点火焰伤害，无视吸收效果、抗性和免疫。\n\n引导期间，你免疫群体控制效果，但无法移动，且一旦开始便无法取消该效果。'),
(803552, '向一名盟友发送纳米机器人，每5秒恢复13点法力值，持续1 分钟。\n\n纳米机器人充能器每次只能发送给1个目标，且无法被驱散。'),
(803563, '使周围空气变得浓稠，降低敌人20%的移动速度，并减少其20%的施法速度。\n同一时间只能激活1个气压法术。'),
(803564, '强化你周围的空气，使敌人身上的移动限制、恐惧和惊骇效果的持续时间提高20%。\n\n同一时间只能激活1个压力法术。'),
(803565, '使周围空气失稳，提高敌人被法术命中的几率3%，并使你在受到伤害时额外产生静电。\n同一时间只能激活1个压力法术。'),
(803570, '向前冲锋并打击路径上的敌人，造成（37 + 14.0625% 攻击强度 + 50% 自然法术强度）点自然伤害。\n\n造成的伤害产生额外威胁值。'),
(803571, '移除盾牌挑衅的能量消耗。'),
(803573, '女猎手射击和唤星术会额外施加一层散落星辰，并且你的远程攻击范围增加至50码。'),
(803638, '当敌人对你施加诅咒时，你受到的魔法伤害降低10%，持续8 秒。\n每激活一个诅咒，伤害降低效果提高5%，持续时间延长2秒。'),
(803645, '40级被动技能使你的法术穿透提高20点，数值随等级提升。\n\n此外，在心魔激活期间，受到伤害性攻击时施法推迟时间降低50%。'),
(803649, '以奥的力量祝福一名盟友，每5秒恢复10点法力值。'),
(803651, '提高友方目标的护甲值105点，并使所有主属性提高4点，持续30 分钟。\n\n不与其它同类效果叠加。'),
(803657, '提高附近所有小队和团队成员护甲值285点，所有主属性提高12点，持续30 分钟。\n\n与其他同类效果不叠加。'),
(803658, '为一名盟友注入法力模块，每5秒恢复10点法力值，持续30 分钟。\n每个工匠只能激活一个模块。'),
(803665, '为附近的小队和团队成员安装法力模块，每5秒恢复33点法力值，持续30 分钟。\n\n每个工匠只能激活一个模块。'),
(803667, '以瑞文戴尔的狡诈标记一名盟友，使其耐力提高32点，冰霜抗性提高25点，持续30 分钟。'),
(803671, '以泽里克印记强化一名盟友，使其资源消耗降低5%，奥术抗性提高60点，持续30 分钟。'),
(803678, '诅咒一个敌人，持续8 秒，使其下一次施法会沉默自己5秒。\n同一目标只能同时拥有1个厄运咒效果。'),
(803679, '在地面放置一枚奥术符文，驱散范围内盟友身上的3个有害魔法效果，并净化敌人身上的3个有益魔法效果。'),
(803681, '切入盟友的命脉，吸取其所有诅咒效果。你可以在10 秒内再次激活此技能，将这些诅咒效果施加给一名敌人。'),
(803683, '在你周围放置3面战斗之鼓，持续1 分钟。\n\n距离战鼓12码范围内的盟友的暴击几率、急速、造成伤害和治疗效果提高10%，并且他们造成伤害时会触发战争之声，持续接下来5次伤害或30 秒。'),
(803700, '为你的大锅注入香料：和平花。\n\n使40码范围内盟友受到的定身、昏迷和减速效果持续时间降低25%。'),
(803719, '每 2 秒产生 2 点太阳能量；技能的直接伤害或治疗恢复 5% 缺失法力值及 13.5 点法力值。履行誓言：所有法术和技能的法力消耗减半；学会终末誓言后还会使冷却时间缩短 0%。同一时间只能激活一种誓言。'),
(803730, '以瑞文戴尔的诡计标记附近的队伍和团队成员，使其耐力提高54点，冰霜抗性提高60点，持续30 分钟。'),
(803731, '以泽里克印记强化附近的队伍和团队成员，使其资源消耗降低5%，奥术抗性提高60点，持续30 分钟。'),
(803736, '用符文灌注的武器攻击一名敌人及其附近所有敌人，造成150%武器伤害外加115点元素伤害，每次弹射造成的伤害递减。\n\n此技能造成的伤害不会弹射到受到控制效果的敌人。'),
(803737, '猛踏你周围8码范围内的地面并释放蒸汽，对附近的敌人造成（25% 攻击强度 + 128 × 等级系数）点冰霜火焰伤害。'),
(803738, '你现在可以使用双手锤，并且可以装备双手锤和盾牌。\n\n你的重击和律法之锤现在会随耐力获得伤害加成，并且你的耐力提高15%。'),
(803741, '将最多5个附近的敌人转化为食尸鬼，使其恐惧40 秒（［拥有腐化者: 9；否则： 8］）。仅影响人型生物。\n当符文能量高于50点时，该法术变为瞬发。'),
(803748, '与奥术协调，使你的奥术抗性提高5点，有害魔法和诅咒效果对你的持续时间缩短20%。'),
(803766, '制造一个1 骸骨圣匣，恢复你缺失生命值的30%。\n盟友每分钟只能使用一次骸骨圣匣。与同类效果共享冷却时间。'),
(803772, '制造一个1冰封圣物，恢复你缺失法力的30%。\n盟友每分钟只能使用一次冰封圣物。'),
(803797, '每施放第3个命令法术，你的下一个巫妖寒霜在10 秒内必定造成暴击。'),
(803798, '允许你在每只手中 wield 一把双手斧、双手锤或剑。'),
(803814, '你做好准备以支配敌人，使你的能量消耗降低 50%，并且击杀提供经验值或荣誉的敌人会使你获得血之诞生。 持续 30 秒。'),
(803817, '近战自动攻击现在有10%的几率重置碾压的冷却时间。'),
(803819, '产生20点热量以火焰为一名盟友疗伤，为其恢复（116 + 35% 法术强度 + 40% 精神）点生命值，数值额外受你的精神加成。'),
(803851, '产生1点优势撕裂一名敌人，使其流血不止，在12 秒内受到（140 + 32.022% 攻击强度）点物理伤害。'),
(803871, '提高本能的效果25%。'),
(803872, '对一名敌人释放毁灭性的破誓者，在30 秒内造成（260 + 100% 攻击强度 + 200% 法术强度）点神圣伤害。该技能可造成暴击。\n\n消耗你的誓言，每层消耗的誓言造成额外伤害。'),
(803889, '使你的近战急速、移动速度和坐骑移动速度提高10%，持续10 秒。\n每消耗一层恶魔之火，持续时间和效果提高20%。\n可在骑乘时使用。'),
(803903, '激活时，玛诺洛斯之血现在还会使你无视所有敌方护甲。'),
(803904, '吞噬邪能，使你的下一次直接伤害必定造成暴击，但会消耗你最大生命值的5%。持续5次攻击或12 秒。'),
(803905, '减少湮灭的冷却时间15秒，以及撕裂的冷却时间4秒。'),
(803950, '产生1枚余烬投掷一块熔岩，猛击敌人造成（26 + 95% 法术强度）点物理伤害。'),
(803956, '每 1.5 秒，你散发出战争之音，对 8 码内的所有敌人造成（71 + 12.7449% 攻击强度）点物理伤害，持续 15 秒。\n\n效果结束时，眩晕 8 码内的所有敌人，持续 4 秒。\n\n与投身战斗不兼容。'),
(803963, '立即解除一名盟友的昏迷、恐惧或变形效果，并使其在5 秒内免疫此类效果。\n\n驱散盟友身上的2个有害魔法效果。\n\n可在昏迷、恐惧或变形状态下使用。'),
(803973, '你的近战攻击和技能现在会为最多3名附近盟友恢复相当于伤害值20%的生命值，并对最多3名附近敌人造成等量伤害。'),
(803974, '2层充能，8秒充能时间猛踏地面，对8码范围内的敌人造成武器伤害外加（13 + 10% 攻击强度 + 20% 自然法术强度）点自然伤害，并使其近战和远程急速降低20%，持续10 秒。'),
(803980, '大地母亲将你标记为她的选民，使所有其他非伤害性法术和技能的冷却时间降低5%，每1.5秒重复一次，持续15 秒。\n\n立即恢复你5%的缺失生命值、法力和怒气，每3秒重复一次。'),
(803981, '制造钟乳石攻击你的敌人3次，在1 秒内造成（84 + 18% 攻击强度 + 60% 法术强度）点物理伤害。产生［拥有大地塑形: 2层大地塑形，并产生］ 20点怒气。\n\n与其他地震法术共享冷却时间。'),
(803990, '2 层充能，60 秒冷却。以幽影姿态移动，移动速度提高 50%，持续 5 秒，可叠加 2 次。移除所有移动限制效果。潜行状态下可使用。'),
(803992, '生成 1 层收割之魂。向 12 码锥形范围内的敌人释放一道灵魂之潮，造成 80% 武器伤害外加 5 点冰霜伤害。'),
(803995, '使你的伤害与暴击几率提高 15%；需要灵魂灌注的法术在 15 秒内有 50% 几率不再消耗该效果。'),
(803997, '2 层充能，40 秒冷却。以幽魂之力灌注你的武器，持续 15 秒，使近战攻击额外造成 25% 伤害，类型为冰霜伤害。'),
(803998, '使收割、挽歌与迷失者遗物匣的伤害提高 10%。'),
(803999, '获得灵魂灌注后，护甲提高 585 点，持续 6 秒。'),
(804002, '向目标投掷一块附魔之石，造成（8.5% 攻击强度 + 173 × 等级系数 + 34.9% 法术强度）点物理伤害，并产生5点怒气值。'),
(804004, '大幅提高逐死者生成的符文能量。'),
(804013, '每当一个地狱火小鬼死亡时，你的献祭之环冷却时间缩短2秒，内爆冷却时间缩短1秒。'),
(804014, '你的恶魔之血现在可以额外叠加5层，每层使黑盾的吸收量提高1%。'),
(804017, '消耗 40 点静电冲击一个敌人，触发传导，并造成（冰霜法术强度高于自然法术强度时：（123 + 100% 冰霜法术强度）；否则：（123 + 150% 自然法术强度））点冰霜伤害，受你的急速等级加成。'),
(804018, '召唤风之力强化一名友方玩家，每5秒恢复10点法力值，持续30 分钟。\n\n不与风暴之唤叠加。'),
(804019, '召唤一个空气元素协助你战斗，每当它造成伤害时，会获得一层振奋。'),
(804020, '［拥有召唤闪电: 产生20点静电\n］对一名敌人造成（奥术法术强度高于自然法术强度时：（17 + 55% 奥术法术强度）；否则：（17 + 55% 自然法术强度））点自然伤害，并在1 秒内额外造成相当于初始伤害20%的伤害。'),
(804024, '对恶魔或亡灵作战时，造成的伤害提高5%。\n\n此外，法术或技能造成的直接伤害现在有10%的几率额外造成（151 × 等级系数）点神圣伤害。'),
(804026, '由觅心弩箭、暗影射击和诅咒造成的伤害提高 15%，对不死生物、恶魔或受到暗影陷阱影响的敌人造成伤害时效果加倍。'),
(804027, '向一个敌人投掷蛇麻草，造成（27 + 30% 远程攻击强度）点物理伤害并将其击退。'),
(804032, '太阳祈愿的冷却时间缩短 10 秒。'),
(804033, '造成的伤害提高20%，法术急速提高15%，每2秒恢复50点生命值。'),
(804035, '消耗20点静电借助疾风之力，使你的伤害提高10%，并为所有友方玩家提供5%的急速加成，持续15 秒。\n\n不与类似效果叠加。'),
(804036, '3层充能，10秒充能时间产生20点静电用一股强风冲击一名敌人及其附近最多2名敌人，造成（62 + 42% 自然法术强度）点自然伤害。'),
(804038, '使你的云爆和乘风的冷却时间缩短20%。'),
(804040, '当风暴斗篷激活时，你的护甲提高相当于智力500%的数值。'),
(804046, '20级被动技能使你的格挡值提高耐力值的25%，并使你的命中等级提高耐力值的5%。'),
(804047, '施放叙事曲有20%的几率移除下一次冲撞的消耗，并使其暴击几率提高10%。'),
(804049, '移除一名盟友身上的所有中毒、疾病和诅咒效果，并在3 秒内使其免疫此类效果。'),
(804051, '放置一个巫术神像，持续 30 秒，每 2.5 秒为 20 码内的小队成员驱散一次恐惧、睡眠和魅惑效果。'),
(804052, '立即揭示你周围30码半径内的所有潜行和隐形敌人。'),
(804053, '等级 40 被动：踏入冥行现在会让你获得帷幕彼端，移动速度提高 30%，并允许你行走于水面。'),
(804056, '释放一道疯狂共鸣波，打断周围所有敌人正在施放的法术，并使其无法施放该系法术，持续3 秒。'),
(804057, '安抚一名敌人，使其近战与远程武器被缴械，持续 6 秒。若目标为亡灵或恶魔，还会使其无法攻击和移动，持续 6 秒。无法影响免疫沉默效果的敌人。'),
(804058, '成为安瑟的勇士，使你能在移动中施放所有法术，持续 10 秒。'),
(804060, '需要冻结目标铭刻一道永冻符文并将其释放在一名敌人身上，使其昏迷40 秒（对玩家为8秒）。受到伤害将中断此效果。\n\n受影响的敌人被视为冻结。\n\n在符文帷幕状态下使用此技能，其冷却时间将减少80%。'),
(804061, '使用飓风造成伤害现在也会使目标造成的魔法伤害降低15%，持续8 秒，并且每次攻击会从你身上驱散1个有害魔法效果。'),
(804068, '标记一个敌人，使所有攻击者对该目标的攻击强度提高150点，你的暴击几率提高3%，每1秒提高3%，持续8 秒。\n\n持续期间，该敌人无法潜行。'),
(804094, '当武器铭刻：空气激活时，你的飓风每次攻击的伤害提高30%。'),
(804124, '使你的攻击强度提高，相当于耐力值的20%，并使你的耐力提高，相当于力量值的10%，持续15 秒。'),
(804136, '向一名敌人投掷远程武器，造成125%远程武器伤害外加13点物理伤害。\n\n可在移动时使用。'),
(804137, '向一名敌人投掷轻矛，造成140%远程武器伤害外加21点伤害，并恢复你最大能量值的30%。\n\n与其他长矛共享冷却时间。'),
(804138, '需要激怒\n3层充能，8秒充能时间向敌人投掷两把斧头，每把造成（16 + 40% 远程攻击强度）点物理伤害，并使其护甲降低4%，持续20 秒，最多可叠加5层。'),
(804139, '向敌人腿部投掷远程武器，造成100%远程武器伤害外加2点伤害，并使其移动速度降低50%，持续10 秒。\n\n与其他长矛共享冷却时间。'),
(804141, '你的远程技能有 20% 的几率释放狂暴者投掷，造成 75% 远程武器伤害。持续 15 秒。\n\n激活时，每次使用远程攻击技能都会使其触发几率提高 2%。'),
(804152, '碾压你面前的敌人，造成130%武器伤害外加16点暗影伤害，并吸取40点狂乱。'),
(804154, '允许打开上锁的箱子和门。'),
(804168, '束缚一个等级最高为43的敌方恶魔，强迫它为你效力，持续5 分钟（对玩家为8秒）。\n\n在效果持续期间，其承受的所有伤害的20%会转移给你。'),
(804169, '诅咒一个敌人，持续15 秒，在15 秒内造成（1575 + 100% 攻击强度）点暗影烈焰伤害。\n\n你的下一次盾刺猛击在12 秒内将赋予你黑盾，吸收（508 + 200% 耐力）点伤害，持续30 秒。'),
(804178, '你的技能暴击现在会使目标受到的流血伤害提高30%，持续15 秒。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (804179, 804183, 804185, 804187, 804190, 804191, 804192, 804193, 804194, 804197, 804199, 804201, 804203, 804207, 804216, 804219, 804220, 804223, 804224, 804226, 804228, 804230, 804231, 804232, 804249, 804250, 804251, 804253, 804254, 804257, 804269, 804275, 804278, 804286, 804300, 804301, 804311, 804316, 804337, 804339, 804340, 804342, 804345, 804353, 804354, 804360, 804369, 804371, 804378, 804381, 804383, 804384, 804385, 804386, 804404, 804412, 804414, 804418, 804432, 804433, 804435, 804436, 804438, 804441, 804444, 804451, 804452, 804456, 804461, 804462, 804478, 804488, 804490, 804491, 804492, 804495, 804503, 804505, 804531, 804550, 804557, 804561, 804571, 804580, 804584, 804591, 804592, 804599, 804602, 804604, 804605, 804609, 804610, 804611, 804613, 804617, 804620, 804625, 804628, 804629, 804630, 804632, 804633, 804652, 804661, 804662, 804664, 804667, 804669, 804670, 804671, 804673, 804674, 804681, 804683, 804684, 804685, 804686, 804687, 804690, 804691, 804702, 804703, 804704, 804705, 804707, 804711, 804712, 804715, 804716, 804723, 804724, 804725, 804726, 804728, 804729, 804730, 804731, 804733, 804735, 804737, 804739, 804745, 804746, 804748, 804749, 804750, 804751, 804753, 804758, 804763, 804764, 804765, 804768, 804773, 804774, 804777, 804781, 804785, 804786, 804787, 804788, 804802, 804805, 804807, 804811, 804822, 804823, 804826, 804827, 804828, 804830, 804833, 804834, 804849, 804851, 804858, 804859, 804868, 804879, 804883, 804891, 804892, 804897, 804906, 804912, 804914, 804924, 804927, 804928, 804929, 804930, 804932, 804939, 804940, 804947, 804961, 804962, 804963, 804964);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(804179, '向敌人发射暗影射击，造成100%远程武器伤害外加4点伤害，并产生怒气。［拥有疾弩手: \n\n可在移动时使用。］'),
(804183, '你的暗影射击和暗影射击会生成爆破火药层数，最多叠加5层，持续20 秒。\n\n巫术猎手和暗鸦群会消耗这些层数以造成更高的伤害。\n\n额外施加不会刷新持续时间。'),
(804185, '在夜晚时，你的敏捷提高4%。\n\n在白天时，你的急速提高3%。'),
(804187, '使你的远程急速提高10%。'),
(804190, '使快速拔枪的冷却时间缩短4秒。'),
(804191, '向一名敌人发射暗影射击，造成100%远程武器伤害外加5点暗影伤害［拥有神射手: ，并恢复3%最大法力值］。［拥有暗影狂怒: \n\n用暗影猎犬激怒你的暗影狂怒，持续15 秒，可叠加1层。］［拥有利爪盛宴: \n\n获得爆破火药，持续20 秒。］'),
(804192, '自动攻击有50%的几率额外造成（15% 攻击强度 + 57 × 等级系数）点暗影伤害。持续15 秒。'),
(804193, '快速射击，造成175%远程武器伤害外加（16 + 20% 远程攻击强度）点物理伤害。\n仅在使用技能造成暴击后可用。'),
(804194, '强化你的暗影猎犬，持续20 秒，使其伤害和急速提高30%，并允许它们无视护甲。'),
(804197, '2层充能，6秒充能时间撕碎所有附近的敌人，造成（28 + 11% 攻击强度）点暗影伤害，产生怒气并感染他们的伤口，使其流血，在4 秒内受到（24 + 16% 攻击强度）点暗影伤害。'),
(804199, '你的活化之血现在会额外生成一个融合体。'),
(804201, '使你的最大生命值提高，并使你的法术和技能消耗降低10%。'),
(804203, '进入嗜血状态，每秒消耗怒气，使你在30 秒内获得100%的伤害治疗量。每秒只能触发一次。\n\n如果怒气耗尽，该效果将提前结束。'),
(804207, '发出一声邪恶的嚎叫，使你的最大生命值提高30%，持续15 秒。'),
(804216, '消耗邪能之怒进行恶魔变形，释放你内心的恶魔，使你的伤害提高 10%［拥有埃辛诺斯的壁垒: , 受到的伤害降低 5%］,［拥有格罗玛什的妄举: 使近战攻击速度提高 15%,］ 并使心魔效果生效。\n\n每消耗一层邪能之怒，持续 5 秒。'),
(804219, '毁灭现在有25%几率不消耗邪能之怒。'),
(804220, '嘲讽一个敌方目标，使其攻击你，持续3 秒。\n\n心魔：对敌人造成（50% 攻击强度）点暗影烈焰伤害。'),
(804223, '在诅咒形态下，你对生命值低于 35% 的目标造成的伤害提高 15%。\\r\\n\\r\\n对生命值低于 35% 的敌人造成直接伤害时，现在会吸取相当于伤害值 10% 的生命值。'),
(804224, '在 15 秒内持续治疗目标，总治疗量为 25 点。'),
(804226, '在你附近放置一个迅捷神像，持续10 秒。\n\n30码范围内的盟友移动速度提高25%，并且抵抗移动限制效果的几率提高25%。'),
(804228, '祝福一名盟友，使其意志坚定，在10 秒内免疫恐惧、魅惑和惊骇效果。\n\n可在恐惧状态下使用。\n\n施加神圣束缚，持续1 分钟。'),
(804230, '在15 秒内，你每3秒产生1点余烬，并且你的烬火之心每次施法产生的热量翻倍。'),
(804231, '复活一名已死亡的盟友，恢复其400点生命值和635点法力值，也可在死亡状态下对自己使用。\n\n可在战斗中使用。'),
(804232, '在你周围铭刻反魔法符文，移除所有有害魔法效果，并使有害魔法效果在6 秒内对你施放时没有持续时间。'),
(804249, '强化受赐福影响的盟友，使其向前方释放神圣能量，对 10 码锥形范围内的敌人造成（32 + 150% 治疗强度）点神圣伤害，并产生额外威胁值。只能对受你的赐福影响的盟友使用。'),
(804250, '救赎受赐福影响的盟友，持续 20 秒，使其急速提高 25%，伤害提高 10%。若盟友生命值低于 35%，剩余时间内，其直接伤害还会治疗自身，治疗量相当于伤害的 10%。只能对受你的赐福影响的盟友使用。'),
(804251, '治疗受太阳指引影响的盟友（64.04 + 85% 法术强度）点生命值，随后每 0.5 秒额外恢复（3.2 + 12% 法术强度）点生命值，持续 6 秒。只能对受太阳指引影响的盟友使用。'),
(804253, '保护受赐福影响的盟友，使其免疫所有伤害，持续 6 秒。只能对受你的赐福影响的盟友使用。'),
(804254, '守护受赐福影响的盟友，偏斜其在 1 分钟内受到的下一个有害法术。只能对受你的赐福影响的盟友使用。'),
(804257, '所有小队和团队成员的法术急速提高 3%，你额外提高 3%。不与同类效果叠加。'),
(804269, '近战攻击强度提高，数值相当于智力的 125%；圣光之槌额外治疗你，治疗量相当于其伤害的 50%。'),
(804275, '引导6 秒，每0.5秒产生5点狂乱并恢复5%的最大法力值［拥有虚空饥渴: ，；否则： ，但受到的伤害提高20%。］'),
(804278, '提高你的电击、召唤闪电和托里姆之臂的伤害，提高20%。'),
(804286, '20级被动使你的法术伤害按力量和智力总值的25%提高，并使你的命中等级按智力值的10%提高。'),
(804300, '产生热量现在有25%几率获得烈焰施法。'),
(804301, '使你的法术急速提高5%［拥有火焰血管: ，并使精神提高3%］，持续15 秒。最多可叠加5层。\n\n额外施加不会刷新持续时间。'),
(804311, '对可提供经验或荣誉的目标造成致命一击时，获得灵魂收割者效果，持续 10 秒。'),
(804316, '你的符文剑和元素迸发的伤害提高3%，最多可叠加10层。\n\n额外施加不会刷新该效果。'),
(804337, '在激怒状态下，野蛮人技能的公共冷却时间减少30%。'),
(804339, '等级 20 被动：攻击强度提高 25%，法术命中等级提高，数值相当于力量的 5%。'),
(804340, '20级被动每个地狱火小鬼现在使你的伤害降低 1%，并使你的力量提高 3%。'),
(804342, '20级被动技能使你的法术伤害提高，相当于智力值的25%，并使你的命中等级提高，相当于智力值的3%。'),
(804345, '你是个恶魔。\n\n受到伤害时有 25% 的几率产生 3 点怒气，并获得恶魔之血，持续 1 分钟。'),
(804353, '产生2层恶魔之火用你的尖刺盾牌刺穿目标，造成（23 + 35% 攻击强度）点高威胁火焰伤害，伤害随你的格挡值提高［拥有克索诺斯壁垒: ，并对其施加撕裂血肉效果］。'),
(804354, '使盾刺猛击的怒气消耗降低 5 点，并使其伤害提高 25%。'),
(804360, '允许你使用生命之力召唤亡灵仆从。\n\n被召唤的仆从会根据其生命之力，从你的智力和法术强度中获得攻击强度和法术强度。\n\n它们还会继承你的一部分抗性、护甲、命中几率、暴击几率、急速，并从你的命中几率中获得专精。'),
(804369, '你的克苏恩之凝视［拥有腐化低语: 或湮灭光束］ 造成 3% 的额外伤害，最多叠加 5 层。'),
(804371, '变身为亡灵怪物，持续 20 秒，使你的最大耐力提高 40%，并使你和你召唤的亡灵仆从散发有害的疾病之云。\n\n在变身状态下，你对恐惧、睡眠、魅惑和疾病效果免疫。'),
(804378, '可被法术消耗以造成额外的奥术伤害。［拥有魔法印记: 并使你造成的奥术伤害提高 2%。］ 持续 30 秒，最多叠加 4 层。'),
(804381, '用星幕覆盖你的盾牌，持续 8 秒，使你的格挡几率和格挡值提高 100%。'),
(804383, '格挡攻击或造成自动攻击后，获得一层先锋，持续 1 分钟，最多叠加 10 层。'),
(804384, '受到的魔法伤害降低 2%。每当被法术击中时，失去一层此效果。'),
(804385, '延长庇护法术的持续时间3秒。'),
(804386, '嘲讽一个敌人，使其攻击你，持续3 秒。\n\n如果目标是玩家，则使其无法停止移动，持续3 秒。'),
(804404, '40级被动技能远程直接伤害现在有8%的几率使你获得投掷弩箭。\n\n每5秒只能触发一次。'),
(804412, '试图使一名敌人陷入疯狂，嘲讽目标，持续3 秒。'),
(804414, '尝试斩首一名受伤的敌人，造成 220% 点武器伤害，外加 27 点伤害。在支付基础消耗后，斩首消耗剩余能量的一半，最多额外消耗 55 点能量。对抗怪物时，每额外消耗1点能量，其伤害提高1%。\n\n仅能对生命值低于35%的敌人使用。'),
(804418, '瓦解一名敌人，在1 秒内造成（25 + 50% 法术强度）点多彩伤害。'),
(804432, '用武器柄击打一名敌人，打断其施法，并阻止该系法术被施放，持续3 秒。'),
(804433, '从敌人脚下召唤一根巨大的石笋，攻击该敌人及最多［拥有大地猛击: 6；否则： 4］名附近敌人，造成（113 + 12.675% 攻击强度 + 126.75% 自然法术强度）点物理伤害。\n\n每命中一个目标产生4点怒气。［拥有大地塑形: \n\n产生1层大地塑形。］\n\n与其他地震法术共享冷却时间。'),
(804435, '连续体法术强化魔杖攻击，使其在3秒内影响最多2个额外附近的敌人，每层回响碎片增加5秒。\n\n受影响的攻击每击中一个额外敌人，造成的伤害降低。\n\n同一时间只能激活1个连续体法术。'),
(804436, '连续体法术工艺师的魔杖和逆转伤口可在移动中施放，持续5 秒。\n\n每层回响碎片使持续时间延长5秒。\n\n同时只能激活1个连续体法术。'),
(804438, '连续体法术强化你的魔杖攻击，在3秒内额外造成50%远程武器伤害加上（2 + 12% 远程攻击强度 + 25% 法术强度）点奥术伤害，并且每拥有一个回响碎片延长5秒。\n\n同一时间只能激活1个连续体法术。'),
(804441, '为一名盟友施加一道魔法护卫，持续 2 分钟，使接下来 3 次直接伤害（若每次伤害超过其总生命值的 20%，或将其生命值降至 35% 以下）降低 50%。'),
(804444, '当受到暴击伤害时，你受到的伤害降低 3%，受到的治疗效果提高 5%，持续 3 秒，最多叠加 3 层。'),
(804451, '你的时光倒转现在会额外移除1个有害效果。'),
(804452, '当碎裂回响法术激活时，你的连续体造成 20% 的额外伤害。'),
(804456, '激怒附近所有盟友，使其急速提高30%，持续20 秒。\n\n受到此法术影响后，盟友在5 分钟内无法从类似效果中获益。'),
(804461, '将敌人变成婴儿，使其无法行动，持续40 秒（对玩家为8秒），造成伤害将中断此效果。\n\n移除目标身上的有害魔法效果，且每次只能影响1个目标。\n\n仅对人形生物和野兽生效。'),
(804462, '你的时间暂停！不再因受到伤害而中断，但伤害减免效果降低75%。'),
(804478, '将你的瓦解转化为工艺师的魔杖。'),
(804488, '使纪元的施法时间降低20%，持续10 秒，可叠加5层。消耗第5层时，所有层数被移除。'),
(804490, '逆转时间，驱散一名盟友身上最近的一个有害效果，或一名敌人身上最近的一个有益效果。\n\n后续使用会使此技能的法力消耗提高 50%，持续 5 秒。'),
(804491, '强化当前时间线，立即为所有小队和团队成员恢复（99.6 + 39.84% 法术强度）点生命值，并使其身上的加速恢复持续时间延长 5 秒。每次施放加速恢复最多可被延长 15 秒。'),
(804492, '为自己创造一个记录当前位置、生命值和法力值的永恒分身，消耗10 秒。\n\n你可以施放倒转，将位置、生命值和法力值重置为记录的状态。'),
(804495, '切换到你的队伍没有死亡的时间线，将所有队员复活，恢复583生命值和833法力值。\n\n可在死亡时施放，但无法在战斗中使用。'),
(804503, '扭曲法术从你的法杖向敌人发射一道扭曲回响，造成90%远程武器伤害加上（奥术法术强度高于神圣法术强度时：（4 + 30% 奥术法术强度）；否则：（4 + 30% 神圣法术强度））点奥术伤害。\n\n每消耗一层回响碎片，伤害提高40%。'),
(804505, '你的周期性伤害和治疗效果使强化时间线的冷却时间缩短1秒。'),
(804531, '使你的符文法术的冷却时间缩短25%。'),
(804550, '对一名敌人造成（67 + 10% 攻击强度 + 41% 奥术法术强度）点奥术伤害，并释放你激活的符印效果。'),
(804557, '提高元素迸发的法术强度加成，提高25%。'),
(804561, '30级被动当符文纹饰：火焰激活时，你的符印崩解的暴击伤害提高30%。\n\n当符文纹饰：流水激活时，你的符印崩解的消耗降低50%。'),
(804571, '使用神殿守护者冲向一名盟友时，有40%的几率刷新一层充能。'),
(804580, '20级被动技能使你的法术伤害提高，数值相当于精神属性的30%和智力属性的10%，并使法术命中等级提高，数值相当于精神属性的6%。'),
(804584, '允许你履行誓言。接下来 1 分钟内的 10 次伤害或治疗技能会触发当前誓言的履行效果，每秒最多触发一次。期间无法产生太阳能量。'),
(804591, '在20 秒持续期间，你的［拥有风暴召唤 or 风暴君主: ；否则： 召唤闪电］［拥有风暴召唤: 气爆］［拥有风暴君主: 湍流之怒］会额外击中3个附近敌人，你的移动速度提高25%，并且每1秒获得5点静电。\n\n激活时，造成伤害的暴击会额外造成基于法术强度的法术风暴伤害，并赋予狂怒风暴。'),
(804592, '重置电刑的冷却时间，并使你的下一次使用无视目标生命值百分比。'),
(804599, '直接暴击现在使你的急速提高10%，持续5 秒。'),
(804602, '每 5 秒你处于诅咒形态中，将使你的鲜血涌动冷却时间减少 5 秒。'),
(804604, '你的血月冲击每次命中现在额外产生 3 点怒气。'),
(804605, '使你受到的魔法伤害降低10%。'),
(804609, '你的古尔丹之颅的效果提高50%，但冷却时间延长30秒。'),
(804610, '对减速敌人造成的埃辛诺斯的猛攻、安尼赫兰打击和双刃斩的伤害提高15%。'),
(804611, '你的护甲穿透提高10%，武器技能提高4点。'),
(804613, '当生命值全满时，你对下一个诅咒或魔法效果的抵抗几率提高100%。此效果每10秒只能触发一次。'),
(804617, '你对目标施加的每个周期性效果都会使耀焰箭的伤害提高3%。'),
(804620, '造成的伤害与治疗现在有 8% 的几率收集一个精魂。\n\n此外，每个激活的精魂现在使你的灵魂之力提高 2%。'),
(804625, '激活黎明时获得灼烧印记。'),
(804628, '审判日激活期间，每 0.5 秒叠加一层，最多 10 层。持续时间结束或审判结束时，对敌人造成（30% 攻击强度 + 477 × 等级系数 + 50% 神圣法术强度）点神圣伤害，伤害随层数提高。'),
(804629, '辉耀圣焰造成伤害有 15% 几率使你获得荣耀之矛。'),
(804630, '施放圣光迸发后，10 秒内的下一次黎明灼击会击中目标两次，并向目标发射太阳烈焰。'),
(804632, '霍鲁萨斯冲击造成伤害后，对目标周围 5 码内最多 5 名敌人发射太阳烈焰。'),
(804633, '你抵抗驱散效果的几率提高20%。'),
(804652, '饮用你的附魔月井药水，立即移除所有群体控制效果，并在3 秒内免疫这些效果。\n\n可在昏迷、恐惧或变形状态下使用。'),
(804661, '使30码范围内的盟友获得5%声望获取加成，并降低你受到的伤害3%。'),
(804662, '魔法解锁宝箱和其他上锁的物品。'),
(804664, '向一名盟友洒下精灵之尘，［拥有仙灵之临: 提高其潜行侦测能力，］并使其受到的所有自然和奥术伤害降低3%，持续15 分钟。'),
(804667, '使你的小队成员声望获取提高5%，持续60 分钟。'),
(804669, '从敌方目标的口袋中偷取物品。'),
(804670, '凝聚一道深渊护盾，使你在10 秒内或承受5次攻击时受到的伤害降低50%。在此期间，每次受到攻击都会使该效果降低10%。\n\n可在昏迷时使用。'),
(804671, '使你的力量与护甲穿透提高 5%。'),
(804673, '制造一个毁灭机器人，你可以透过它进行观察并直接控制。\n\n该机器人能够爆炸，对附近的敌人造成大量火焰伤害，并使其迷失方向，持续3 秒。'),
(804674, '召唤一个探知之球，持续1 分钟，你可以直接控制并透过它进行观察。'),
(804681, '活化一个骷髅铁匠，可以为盟友修理装备，持续1 分钟。'),
(804683, '在你的位置创建一个铁匠铺和一个铁砧，持续2 分钟。'),
(804684, '放置一个巫毒大锅，持续15 秒，使大锅附近盟友受到的治疗效果提高20%。\n\n15码范围内的盟友每1.5秒恢复（300 + 60% 治疗强度）点生命值，持续15 秒。'),
(804685, '向敌人投掷一枚血箭，造成（17 + 20% 攻击强度 + 45% 暗影法术强度）点暗影伤害，并为你恢复等量的生命值。［拥有汇聚活力: \n\n强化：对命中的首个目标造成100%的额外伤害。］'),
(804686, '鲜血碎片造成的伤害现在使静脉爆裂和劫掠斩的冷却时间减少 1.5 秒。'),
(804687, '使你受到的所有中毒效果持续时间缩短 10%，并使你受到的所有周期性魔法伤害降低 5%。'),
(804690, '为15码范围内的队伍和团队成员装备一个降落伞，持续1 分钟，自动展开并减缓其坠落速度。'),
(804691, '使40码范围内的所有小队和团队成员骑乘移动速度提高50%，持续10 秒。\n\n可在骑乘时使用。不与类似效果叠加。'),
(804702, '命令你的坐骑践踏，对附近敌人造成（86 + 55% 攻击强度）点火焰打击伤害。\n\n每层地狱火之路使伤害提高 25%。'),
(804703, '骑上你的克索诺斯战马，移动速度提高20%。\n\n若你在3秒内未造成或受到伤害，则生成地狱火之路，最多可叠加2层。该效果在30级时提升至3层，40级时提升至5层。\n\n可在战斗中使用，且移动时可施放。'),
(804704, '你的战马向前冲锋25码，对路径上的敌人造成（18 + 100% 攻击强度 + 25.5% 法术强度）点火焰伤害。\n\n每层地狱火之路使你获得25%的伤害加成。'),
(804705, '40码范围内的盟友受到的治疗效果提高6%。不与同类效果叠加。\n\n此外，你受到的魔法伤害降低10%。'),
(804707, '在你的位置召唤一个紧凑型便携式锯木机。\n\n该物体可作为锯木机工艺台使用。\n\n便携式锯木机将在2 分钟后消失。'),
(804711, '2层充能，60秒充能时间凝聚一面黑暗守卫，使你的伤害降低50%，持续10 秒或承受5次攻击。持续期间，每受到一次攻击，效果值降低10%。\n\n昏迷时可以使用。\n\n受到作用于深渊护盾的修正效果影响。'),
(804712, '凝聚一支强力的魔法箭矢并射出，对目标造成（10 + 20% 远程攻击强度）点自然伤害，每层优势效果会提升该伤害。\n\n在地面制造一个附魔闪光，使附近的敌人每2秒受到（20% 远程攻击强度 + 224 × 等级系数）点自然伤害，每层优势效果会使持续时间延长2秒。'),
(804715, '在目标区域召唤战鹰，使区域内最多［拥有空中突袭: 10；否则： 8］个敌人减速60%，持续5 秒。\n\n每个受影响的敌人会召唤一只猎鹰，持续12 秒。'),
(804716, '造成（7 + 18.2183% 法术强度）点奥术伤害，并为每个散落星辰恢复8%的最大法力值。'),
(804723, '召唤一名小队或团队成员至你的位置。'),
(804724, '你呼唤风将一名友善的小队或团队成员带到你的位置。'),
(804725, '向一名敌人射出致残射击，降低其移动速度50%，并将其打下坐骑，使其在5 秒内无法再次上马。'),
(804726, '消耗饥渴层数从一名敌人身上窃取（36 + 34% 法术强度）点生命值。\n\n每层饥渴使伤害提高 10%。\n\n清除贪噬无厌和饥渴层数。'),
(804728, '你牢牢握住武器，使你的力量提高 25，并使缴械效果的持续时间缩短 30%。'),
(804729, '教你先祖之唤。'),
(804730, '你被战矛印记标记，使小队和团队成员的攻击强度提高10%。不与类似效果叠加。\n\n此外，战矛的冷却时间缩短2秒。'),
(804731, '散发强大的光环，使100码范围内的队伍和团队成员近战与远程急速提高10%。\n\n不与类似效果叠加。'),
(804733, '你的治疗效果现在会对目标施加月水，可叠加5层。'),
(804735, '造成伤害将消耗一层效果来治疗你。'),
(804737, '在目标位置放置族长图腾，图腾将持续15 秒。\n\n图腾散发光环，持续15 秒，使100码范围内的盟友在造成直接伤害时额外造成相当于（35% 攻击强度）的冰霜伤害，并获得50%荣誉值提升。\n\n施加精疲力竭效果，使你在1 分钟内无法从类似效果中获益。'),
(804739, '在目标位置创造一片受月井之水祝福的区域，持续15 秒。\n\n所有站在井内的友方玩家受到的治疗效果提高25%，法力值恢复速度提高100%。［拥有月之轮回: \n\n满月：立即生效。\n\n新月：触发30秒冷却时间缩短。］'),
(804745, '你的碾压现在会对敌人施加受伤，持续1 分钟，并且现在必定对受到头槌影响的敌人造成暴击。'),
(804746, '旋进造成伤害时，现在会移除你身上的1个移动减速效果，并返还2点能量。'),
(804748, '在地上放置一个酒桶，持续30 秒，盟友可使用它恢复生命值和法力值。\n\n饮酒时进入战斗或移动将中断效果。'),
(804749, '移除致残标枪的最小射程，并使其持续时间延长 30%。'),
(804750, '降低野蛮旋风的冷却时间2秒，并对生命值低于35%的敌人提高100%伤害。'),
(804751, '接受圣光的祝圣，召唤围绕自身的圣锤，每 3 秒对附近敌人造成（5.8 + 12% 攻击强度 + 22% 神圣法术强度）点圣焰伤害，持续 12 秒。'),
(804753, '将施法者传送至塔纳利斯的时光之穴。'),
(804758, '恶魔学识使你能够追踪同类，在小地图上显示附近所有恶魔的位置。\n\n激活时，你对恶魔的攻击有 10% 几率造成一次背叛者之击，造成（25 + 25% 攻击强度 + 50% 法术强度）点物理伤害，并使目标昏迷 2 秒。'),
(804763, '召唤5桶淡雷麦酒，为风暴使者和其盟友提供饮品。\n\n召唤物品在登出超过15分钟后消失。'),
(804764, '散发光环，使附近盟友的火抗提高0.66点，抵抗诅咒和魔法效果的几率提高15%。'),
(804765, '当你击杀一个提供经验值或荣誉值的敌人后，你可以使用此技能吞食其血肉，在10 秒内恢复30%的生命值。\n\n无法在战斗中使用。'),
(804768, '你的先祖战斗攻击现在会为你的受敬先祖恢复5%最大生命值，并使其发动一次先祖旋风攻击。'),
(804773, '从世界上的任何位置召唤一名友好的队伍或团队成员到你身边。'),
(804774, '召唤一个恐惧战马传送门，持续1 分钟。\n\n盟友可以与传送门互动，骑乘一匹恐惧战马。'),
(804777, '在目标位置召唤一块仪式石。你和你的盟友可以与仪式石互动，开始将他们的生命能量引导其中。\n\n当10名盟友引导时，仪式之石将被摧毁，召唤出一个敌对的无面毁灭者进入世界，持续2 分钟。'),
(804781, '缴纳1银币的什一税，学习一项特殊的新技能，为你的整个队伍提供强化。\n\n东部王国：北郡修道院、丧钟镇、光明大教堂、血色修道院、斯坦恩布莱德、光明希望礼拜堂、墓地之厅。|n|n卡利姆多：月神殿、埃瑟尔·雷索、灵魂之谷、幻象之池。［拥有重置贡品: 。|n|n外域：礼拜堂庭院、沙塔斯城、特尔哈曼神庙、奥金顿、卡拉波废墟、奥舒冈。］'),
(804785, '使克索诺斯战马的坐骑速度提高75%，持续5 秒。\n\n激活时，你不会失去地狱火之路的层数。\n\n无法在战斗中使用。'),
(804786, '散发天启瘟疫，使附近敌人从你处受到的火焰伤害提高10%。［拥有释放瘟疫: \n\n释放：对10码半径内的附近敌人造成（150 × 等级系数 + 24% 火焰法术强度）点火焰伤害，并每1秒额外造成（69 × 等级系数 + 7.25% 火焰法术强度）点火焰伤害，持续8 秒。］'),
(804787, '坐骑速度提高20%。\n\n当你受到伤害时，开始失去动力，在2 秒延迟后移除所有层数。'),
(804788, '你的战马向前冲刺30码。距离随地狱火之路层数提升。\n\n无法在战斗中使用。'),
(804802, '强化你的意志力并提升反应速度，使你的招架和躲闪几率提高30%，持续8 秒。'),
(804805, '立即获得10层汇聚活力，每5秒触发一次，持续15 秒。'),
(804807, '降低需要诅咒形态的技能消耗，并使血祭仪式的治疗效果提高25%。'),
(804811, '激怒持续10 秒，使接下来6次血牙撕咬的公共冷却时间和消耗降低50%，并触发暗翼召唤。'),
(804822, '躲闪或招架攻击后，有10%的几率使你的接下来10次双刃斩伤害提高30%，并产生1点邪能之怒。'),
(804823, '嘲讽附近敌人，持续4 秒，并在30 秒内忽略受到的50%伤害，最多不超过你最大生命值的100%。\n\n效果结束时，你释放一道邪能爆破，根据效果激活期间受到伤害的次数，从附近敌人身上吸取生命值。'),
(804826, '为自身充能，获得100点静电，并使下一次施法的法术急速提高30%，持续10 秒。'),
(804827, '20级被动技能使你的法术暴击伤害提高150%。'),
(804828, '你的电刑现在有25%的几率再次触发。'),
(804830, '消耗40点静电命令你的空气元素，使其在8 秒内的下一次伤害击中一名敌人，造成（2683 + 100% 奥术法术强度）点自然伤害，并使附近所有盟友的移动速度提高30%，持续15 秒。'),
(804833, '为自己包裹一层不稳定的能量屏障，持续15 秒，使所有针对你的攻击有50%的几率只造成一半伤害，并产生10点静电。\n\n风暴斗篷有60%的几率抵抗驱散效果。'),
(804834, '召唤一位受敬先祖协助你战斗，直至解散，其属性随你的敏捷和攻击强度提升。\n\n每当你使用野蛮旋风或旋进时，你的受敬先祖会模仿该技能。'),
(804849, '等级 30 被动\\r\n\\r\n现在造成暗影伤害会获得 1 枚鲜血碎片，如果造成暴击则额外获得 1 枚，持续 10 分钟，最多 8 枚。\\r\n\\r\n使用静脉爆裂造成伤害时，现在会消耗所有层数的鲜血碎片，每层对你的目标造成（18 + 5% 攻击强度 + 10% 法术强度）点法术暗影伤害。'),
(804851, '脱离诅咒形态后，你获得70%移动速度和法术急速，持续5 秒。'),
(804858, '周期性伤害和治疗现在会使目标在脚下留下一滩血迹。\n\n处于诅咒形态的盟友穿过血迹时将获得血之轨迹，持续6 秒。。'),
(804859, '移动速度不会低于80%。移动速度提高20%。造成的伤害提高5%。'),
(804868, '允许你在小地图上追踪元素生物和龙类。'),
(804879, '向25码内的所有小队和团队成员散发光环，持续15 秒，使其造成的伤害提高10%。\n\n当此效果作用于地狱火小鬼时，其火焰伤害提高150%，总生命值提高50%。'),
(804883, '产生2层恶魔之火召唤1 地狱火小鬼［拥有小鬼帮主: s］协助你战斗，持续12 秒，并产生20点怒气。\n\n地狱火小鬼产生的威胁值将转移给你。'),
(804891, '每次受到伤害时，获得该伤害值5%的攻击强度，持续1 分钟。'),
(804892, '施放推进现在重置举盾的冷却时间。'),
(804897, '你的神圣之力现在对受到信仰之刃影响的敌人使用时，将触发 30 秒的冷却缩减。'),
(804906, '谴责一名敌人，在21 秒内造成（77 + 35% 攻击强度 + 70% 法术强度）点神圣伤害，可叠加3层，并获得一个誓言。\n\n誓言： 使你的暴击几率提高3%。'),
(804912, '当你的自动攻击造成暴击或招架一次攻击时，你的招架几率提高3%，持续5 秒，可叠加5层。'),
(804914, '嘲讽一名敌人，使其攻击你，持续3 秒。'),
(804924, '暴击伤害提高5%。'),
(804927, '40级被动施放破誓者技能现在使圣契的冷却时间缩短 4秒。\n\n你的神圣法术伤害提高，相当于敏捷的35%。'),
(804928, '降低你的圣约的能量消耗50%。'),
(804929, '以白银热诚粉碎敌人，造成215%武器伤害外加（20 + 47.25% 攻击强度 + 135% 神圣法术强度）点伤害，为你恢复等同于造成伤害的生命值，并释放天灾克星，造成（25% 攻击强度 + 262 × 等级系数 + 25% 神圣法术强度）点神圣伤害。'),
(804930, '当法杖守卫的吸收护盾被打破时，对附近敌人造成（167.4 + 20% 攻击强度 + 50% 神圣法术强度）点高威胁神圣伤害。'),
(804932, '50级被动造成伤害的技能现在会为你提供不破信条，持续15 秒，最多可叠加3层。\n\n当你使用一个造成伤害的破誓者或神圣狂怒时，现在会消耗这些层数，并对你的目标进行等同于层数的自动攻击次数。'),
(804939, '减少隐匿和击倒的冷却时间4秒。'),
(804940, '产生2点优势从背后包抄敌人，出其不意地造成150%武器伤害（若装备匕首则为300%）外加10点物理伤害。'),
(804947, '释放瘟疫的冷却时间减少 15 秒。'),
(804961, '需要蜘蛛形态。消耗孵化印记。向一名敌人注入暗影毒液，造成暗影伤害并使其受到的治疗效果降低50%，持续8 秒。\n1枚印记：（55 + 56.25% 暗影法术强度）暗影伤害。\n2枚印记：（70.4 + 72% 暗影法术强度）暗影伤害。\n3枚印记：（90.2 + 92.25% 暗影法术强度）暗影伤害。\n4枚印记：（114.4 + 117% 暗影法术强度）暗影伤害。\n5枚印记：（154 + 157.5% 暗影法术强度）暗影伤害。'),
(804962, '移动速度提高60%，持续10 秒。\n\n离开蜘蛛形态会取消此效果。\n\n可在潜行状态下使用。'),
(804963, '拥抱沙德拉的生命之血，使你受到的伤害和施法退条降低20%，并使你受到的所有伤害都会施放回春毒素。持续10 秒。'),
(804964, '激怒12 秒，使你触发毒素的几率提高50%，能量恢复速度提高100%，造成的伤害提高20%，持续12 秒。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (804968, 804969, 804970, 804975, 804977, 804978, 804979, 804980, 804982, 804983, 804984, 804986, 804987, 804989, 804993, 805027, 805029, 805032, 805035, 805038, 805040, 805044, 805048, 805049, 805074, 805093, 805094, 805095, 805096, 805097, 805102, 805103, 805104, 805105, 805107, 805110, 805114, 805115, 805116, 805117, 805121, 805126, 805140, 805150, 805155, 805181, 805184, 805185, 805186, 805188, 805192, 805194, 805195, 805196, 805197, 805198, 805203, 805204, 805205, 805235, 805236, 805238, 805239, 805240, 805243, 805244, 805245, 805246, 805248, 805249, 805255, 805256, 805258, 805265, 805267, 805288, 805301, 805303, 805305, 805306, 805308, 805314, 805335, 805336, 805346, 805347, 805351, 805356, 805365, 805369, 805372, 805378, 805390, 805409, 805415, 805417, 805420, 805421, 805422, 805423, 805424, 805427, 805428, 805429, 805433, 805437, 805439, 805442, 805443, 805445, 805448, 805462, 805468, 805476, 805477, 805483, 805496, 805500, 805503, 805505, 805508, 805510, 805511, 805512, 805519, 805524, 805533, 805546, 805550, 805552, 805555, 805563, 805568, 805572, 805581, 805583, 805587, 805591, 805592, 805607, 805628, 805629, 805643, 805647, 805649, 805669, 805671, 805674, 805675, 805677, 805678, 805679, 805693, 805695, 805696, 805697, 805703, 805706, 805708, 805716, 805718, 805719, 805724, 805726, 805727, 805731, 805738, 805743, 805750, 805751, 805754, 805756, 805758, 805767, 805770, 805773, 805775, 805776, 805777, 805778, 805780, 805793, 805794, 805796, 805801, 805804, 805808, 805810, 805811, 805812, 805813, 805815, 805816, 805821, 805828, 805832, 805835, 805844, 805847, 805851);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(804968, '虫群在你体内涌动，为你备战，立即产生 100 点怒气或能量。\n\n可在潜行状态下使用。'),
(804969, '提高孵化印记的效果10%，并使你的命中几率提高5%。'),
(804970, '从阴影中现身，恐吓附近所有敌人，持续3.5 秒。'),
(804975, '提高你的暗影伤害和暗影法术的暴击几率3%。'),
(804977, '需要蜘蛛形态。消耗孵化印记。向一名敌人注入毒液，使其从内部腐烂，在24 秒内造成瘟疫伤害。\n 1个印记：（240 + 220% 法术强度）点瘟疫伤害。\n 2个印记：（307.2 + 281.6% 法术强度）点瘟疫伤害。\n 3个印记：（393.6 + 360.8% 法术强度）点瘟疫伤害。\n 4个印记：（499.2 + 457.6% 法术强度）点瘟疫伤害。\n 5个印记：（672 + 616% 法术强度）点瘟疫伤害。\n造成的伤害无视抗性。'),
(804978, '将你周围的区域指定为你的巢穴，持续8 秒。\n\n敌人无法将目标锁定在巢穴内部或外部，且其移动速度降低60%。'),
(804979, '使敌人的命中几率降低3%，并使其受到你的自然伤害提高5%，持续8 秒。\n\n驱散此效果会使驱散者的资源消耗提高100%，持续5 秒。'),
(804980, '变形为织者形态，使受到伤害性攻击时的施法退条降低 70%，并使你的持续伤害有 15% 的几率恢复 5% 的基础法力值。\n\n使你的持续效果受益于法术急速，并让你免疫变形术效果。'),
(804982, '用恶毒毒药枯萎敌人的生命，在18 秒内造成138点自然伤害。'),
(804983, '向一名敌人注入寄生孢子，造成（20 + 17.5% 自然法术强度）点暗影伤害，并在21 秒内额外造成210点伤害。\n\n10秒后，在目标脚下掉落一个蘑菇，2秒后爆炸，对附近敌人造成（303 × 等级系数 + 25% 自然法术强度）点自然伤害。'),
(804984, '对生命值高于50%的敌人，提高你的毒药效果伤害25%。'),
(804986, '真菌在敌人全身生长，造成（153 + 65% 自然法术强度）点自然伤害，并施加一个护盾，吸收接下来对其造成的（100 + 200% 法术强度）点治疗效果，持续8 秒。\n\n目标身上每层真菌增生会使伤害提高20%。'),
(804987, '暗影和自然伤害现在有35%几率使你对目标造成的周期性伤害提高2%，持续30 秒，可叠加10层。'),
(804989, '真菌突袭者现在在目标下方生成 3 个蘑菇。'),
(804993, '移除甲壳冲锋的怒气消耗，并使其射程提高5码。'),
(805027, '牺牲你的亡灵，将其生命之力返还给你，每摧毁一个亡灵仆从恢复（49 + 30% 法术强度）点生命值。'),
(805029, '激怒你的亡灵仆从15 秒，使其急速提高30%，移动速度提高50%。'),
(805032, '召唤一只骨灵协助你战斗，持续15 秒。\n\n激活期间，它会定期释放骨风暴，每0.5秒对最多5个附近敌人造成（30 + 40% 法术强度）点物理伤害，持续5 秒。'),
(805035, '造成的周期性伤害现在使敌人的移动速度降低30%。'),
(805038, '在你的位置召唤一个仪式圈，持续1 分钟。在激活期间，你可以施放仪式归还来返回该位置。'),
(805040, '召唤3个骷髅弓箭手协助你战斗，持续15 秒。'),
(805044, '唤醒一名墓穴之王协助你战斗，持续15 秒。\n\n激活时，你所有亡灵仆从的攻击额外造成相当于伤害值10%的瘟疫伤害。'),
(805048, '召唤一个瘟疫之父为你作战，持续15 秒。\n\n该仆从造成的伤害会释放僵尸瘟疫，对附近敌人造成（79 + 10% 法术强度）点瘟疫伤害，并使其攻击强度降低19点。'),
(805049, '召唤一名墓缚勇士，将施法者承受的所有伤害的50%转移至自身，持续20 秒。\n\n与其他冠军法术共享［拥有骸骨博弈: 2分钟；否则： 3分钟］冷却时间。'),
(805074, '从天空召唤一只地狱火深渊魔砸向目标3 秒码区域，造成（1500 + 100% 攻击强度 + 100% 法术强度）点火焰伤害。\n\n深渊魔将停留15 秒协助你战斗，并发出光环使40码范围内的小队和团队成员受到的伤害降低5%。\n\n每激活一只地狱火小鬼，消耗的怒气减少15点。'),
(805093, '提高甲壳冲锋的暴击几率20%，暴击伤害10%。'),
(805094, '清除暴露血肉层数，使附近敌人中毒5 秒，每清除一层额外持续1秒，每1秒造成（15 + 5% 攻击强度 + 10% 自然法术强度）点自然伤害。'),
(805095, '产生10点怒气，并使你受到的物理伤害提高3%，持续20 秒，可叠加10层。'),
(805096, '向一名敌人注入无效毒素，打断其施法，并阻止其施放该系法术，持续3 秒。'),
(805097, '嘲讽一个敌方目标攻击你，持续3 秒。如果目标可被嘲讽且当前未攻击你，则触发你当前的毒液。'),
(805102, '粉碎你的外骨骼，立即施加15层暴露血肉，并使你的移动速度提高30%，持续8 秒。'),
(805103, '30级被动技能清除暴露血肉层数时，若处于甲虫形态，将根据清除的层数恢复生命值。'),
(805104, '强化蜘蛛形态，使其变为毒蛇领主，使部分蜘蛛形态技能增加1秒施法时间，并提升10码射程。\n\n攻击距离超过10码的敌人时，伤害提高30%，并且来自敌人的法术退条效果降低50%。\n\n提升凋零毒素的伤害50%，并使其产生一片瘴气。'),
(805105, '将自然能量汇聚于自身，变身为知识古树，持续20 秒。\n\n激活时，你的属性提高20%，附近队友的消耗降低30%。\n\n变身期间，你的移动速度降低30%。'),
(805107, '将目标包裹在大地母亲的爱中，为其恢复（501 + 100% 攻击强度 + 100% 治疗强度）点生命值。\n\n若对友方使用，其承受的30%伤害将转移至你身上，持续6 秒。'),
(805110, '所有直接伤害现在有5%的几率对目标附近所有敌人释放黑暗祷言，持续9 秒。'),
(805114, '将黑暗帝国的噩梦传播给最多5个附近的敌人，使其恐惧5 秒，并打断非玩家施法，持续3 秒。'),
(805115, '将帝国之刃、虚空打击和暮光之锤的范围提高25码，并使其法力消耗降低50%，持续15 秒。'),
(805116, '猛击一名敌人，造成195%武器伤害外加14点暗影伤害，无视吸收效果，并消耗40点狂乱。［拥有恩佐斯之手: 刷新一层帝国之刃。］'),
(805117, '你的虚空之影现在还会使你的暴击伤害提高10%。'),
(805121, '40级被动使你的暗影法术伤害提高，相当于力量值的50%，并使你的法术命中几率提高，相当于力量值的5%。'),
(805126, '你的深渊护盾现在可以额外叠加3层。'),
(805140, '强化你的蜘蛛形态，使你的伤害提高10%，并允许你的蛛魔钉刺额外叠加1层。'),
(805150, '挥击前方最多8个敌人，造成126%武器伤害外加17点伤害，并在10 秒内使其攻击强度降低25点。'),
(805155, '施放横扫千军现在会使你的下一次横扫千军击中的敌人数量增加1个，并使其能量消耗降低10%，持续6 秒，可叠加3层。'),
(805181, '达到 3 层收割之魂时，你受到的物理伤害降低 10%，并在 10 秒内每 2 秒恢复 1% 最大生命值。该效果生效期间不会重复触发。此外，死亡之风造成的治疗效果翻倍。'),
(805184, '从灵魂收割中汲取的生命值额外提高 50%。'),
(805185, '拥抱你邪恶的念头，立即生成 3 层收割之魂。'),
(805186, '使用需要灵魂灌注的技能时，有 50% 几率恢复 5% 缺失生命值。'),
(805188, '使灵魂突刺汲取的生命值额外提高 20%。'),
(805192, '使幽魂疾步的射程提高 5 码，并额外生成 5 点符文能量。'),
(805194, '受到幽魂武器影响的能力，每额外命中一个目标，伤害提高 25%。'),
(805195, '对生命值低于 20% 的敌人发动的攻击额外造成 140 点 + 18% 攻击强度的暗影伤害。'),
(805196, '逐死者造成的伤害现在会施加灵魂腐化。'),
(805197, '在目标位置创造一片墓地，使其中的敌人移动速度降低 40%，并周期性从地面召唤亡灵，对附近敌人造成（199 + 33% 法术强度）点瘟疫伤害并产生一具尸体。持续 20 秒。'),
(805198, '群鸦杀戮造成的伤害会施加毁灭，持续 10 秒。学会震颤之镰后，由震颤之镰施加此效果。'),
(805203, '使作用于你的缴械与瘫痪效果的持续时间缩短 20%。'),
(805204, '使末日撕裂的暴击几率提高 5%。'),
(805205, '末日撕裂与群鸦收割造成的伤害现在会附加一层流血，每 2 秒造成 56 点 + 8.5% 攻击强度的物理伤害，持续 10 秒，可叠加 5 次。再次施加不会刷新持续时间。'),
(805235, '在目标位置释放邪能，使敌人陷入恐惧，并使其移动速度降低80%，持续8 秒。\n\n造成的伤害可能会中断此效果。'),
(805236, '当心魔激活时，你的近战急速提高15%，并且自动攻击的暴击现在会为你恢复相当于造成伤害50%的生命值。\n\n此外，切割的暴击伤害提高5%，根据引导时间每次攻击最多可提升至60%。'),
(805238, '使你的蘑菇伤害提高 50%，并教你学会菌丝之环。'),
(805239, '使你进入激怒状态，立即获得6点邪能之怒，并使你的近战伤害为你吸取生命，造成相当于伤害值50%的混沌伤害，持续15 秒。'),
(805240, '将你的炽热目光投向一名敌人及其附近所有敌人，恐吓他们并使其燃烧，造成（220 + 35% 攻击强度）点暗影烈焰伤害。\n\n以此方式伤害敌人将为你恢复（146 + 50% 攻击强度）点生命值，并产生 1 点邪能之怒。\n\n仅能对生命值低于 35% 的敌人使用。'),
(805243, '激怒［拥有监工之军: 所有；否则： 最多8个］ 20码范围内的盟友，使其受到的伤害降低15%，急速提高10%，持续10 秒。'),
(805244, '提高［拥有邪能突进: 邪能突进；否则： 混沌冲刺］的射程3码［拥有邪能突进: ，并使其暴击几率提高10%］。'),
(805245, '当恶魔意志或憎恨壁垒激活时，所有受到或避免的伤害现在有20%的几率产生1点邪能之怒。'),
(805246, '20级被动技能使你的攻击强度提高，相当于耐力值的30%，并使你的命中等级提高，相当于敏捷值的6%。'),
(805248, '消耗敌人相当于你耐力200%的法力值。\n\n造成等同于所吸取法力值的伤害。'),
(805249, '躲闪攻击现在产生3点能量。'),
(805255, '使燃烧憎恨的冷却时间减少60秒。'),
(805256, '使你的最大生命值提高10%，并使你的副手武器伤害提高30%。'),
(805258, '生成 3 层收割之魂。进行一次斩击，造成 150% 武器伤害外加 36 点 + 62.5% 法术强度 + 18% 攻击强度的暗影伤害，无视抗性、吸收与无敌效果。'),
(805265, '盾牌提供的护甲提高 50%。'),
(805267, '受到的法术伤害降低 5%，生命值高于 80% 时额外降低 5%。'),
(805288, '消耗20点静电释放电能，恢复你最大法力值的15%，并对周围小范围内的敌人造成（18 + 25% 自然法术强度）点自然伤害。'),
(805301, '化身神圣形态，治疗提高 10%，产生的威胁值降低 50%。法力值不低于 30% 时，每次治疗额外牺牲法力，并治疗受你的赐福影响的盟友。此额外治疗可以暴击，也可触发救赎者等效果。'),
(805303, '提高紧急治疗的暴击几率15%，并允许医疗包的周期性治疗效果造成暴击。'),
(805305, '使一名盟友的身体带电，使其急速提高20%，并且其造成的伤害会为附近盟友恢复相当于伤害值15%的生命值。持续15 秒，或20次攻击。'),
(805306, '电击！的暴击现在会对目标8码范围内最多12个盟友施加再生毒气，每2秒恢复射击值15%的生命值，持续10 秒。'),
(805308, '建造一个电池充电站，供30 秒使用，盟友可与其互动一次，恢复15%的最大生命值和法力值，以及50%的最大怒气、能量、集中值和符文能量。\n\n对40码范围内的队伍和团队副本成员施加电量耗尽效果。'),
(805314, '提高追踪强化的层数5层，持续时间延长7秒，并且对拥有10层效果的敌人使用炸弹投掷造成的伤害会向其位置发射火箭弹幕。'),
(805335, '在20 秒内化身为岩石与大地构成的生物，使你的急速提高20%，护甲提高50%，并允许你在移动时施放伤害性法术。'),
(805336, '你的大地涌动现在总是会对受到你的地震震颤影响的目标造成暴击。'),
(805346, '使用双手武器造成的直接技能伤害现在会减少你的药水剩余冷却时间1秒，并赋予巫术效果。'),
(805347, '使魔法抗性提高10%，近战急速提高10%，持续8 秒，可叠加3层。'),
(805351, '用你的扳手猛击一名敌人，造成110%武器伤害外加14点伤害。\n\n对机械类敌人必定造成暴击。'),
(805356, '近战和远程自动攻击现在有 35% 的几率吸取目标相当于伤害值 25% 的法力值，并施加散落星辰，但在激活期间你的伤害降低 25%。\n\n与其他架势共享冷却时间。'),
(805365, '施展一次高阶华彩，对附近敌人造成（83 + 100% 攻击强度）点火焰伤害，每4秒重复一次，并使你的罪孽之火最多额外击中3个敌人，持续20 秒。\n\n使你获得罪孽之火，并使其持续时间延长10秒。'),
(805369, '汲取死灵能量，立即恢复 30 点符文能量。'),
(805372, '用激光轰击一名敌人，造成100%远程武器伤害外加18点火焰伤害，并强制你的宠物向该敌人冲锋，造成24点物理伤害。\n\n与其他机甲技能共享冷却时间。'),
(805378, '你的凤凰之卵的跳动频率提高 2 秒。'),
(805390, '移动速度提高5%。\n\n达到6层时，能量恢复速度提高100%，持续8 秒。\n\n额外施加不会刷新持续时间。'),
(805409, '释放旋转的破誓者，每1秒对附近敌人造成100%武器伤害，外加（7 + 30% 法术强度）点伤害，伤害受法术强度加成，［拥有银色骑士: 并使受到的伤害降低20%］，持续3 秒。\n\n消耗你的誓言，每消耗一层造成额外伤害。'),
(805415, '你的伤害性暴击现在会使你造成的神圣伤害提高2%，持续20 秒，可叠加5层。每1秒只能触发一次。\n\n达到5层时，你将获得高阶将军。'),
(805417, '发出拯救之光，使附近小队和团队成员在15 秒内受到的治疗效果提高40%。\n\n持续期间，队友产生的仇恨值将转移给你。'),
(805420, '神圣挥击和清算造成的伤害现在使施法速度降低10%，持续10 秒，可叠加2层。'),
(805421, '释放强大的破誓者，对每个击中的敌人造成（36 + 17.5% 攻击强度 + 50% 耐力）点神圣伤害，并恢复 15 点能量。\n\n消耗你的誓言，每消耗一层造成额外伤害。'),
(805422, '获得一个相当于你最大生命值100%的护盾，持续30 秒，重置光之屏障和宁静之环的冷却时间，并为每个技能赋予额外效果。'),
(805423, '阅读你的热忱圣契，使你获得相当于敏捷值30%的法术强度和相当于智力值30%的攻击强度，持续20 秒。\n\n同一时间只能激活一种圣契法术。'),
(805424, '减少寒冰弹幕的引导和施法时间25%。'),
(805427, '施放邪恶狂热现在召唤一个腐烂冰霜巨人在持续时间内协助你战斗。'),
(805428, '召唤一条冰霜巨龙，飞在死灵法师身后，每2秒对附近敌人喷吐，持续30 秒，造成（1500 + 14.8824% 智力 + 14.8824% 冰霜法术强度）点冰霜伤害。'),
(805429, '你的智力提高5%，你的亡灵仆从造成的冰霜伤害提高10%。'),
(805433, '为你提供一个相当于你最大法力值的护盾，持续10 秒。\n\n可在昏迷时使用。'),
(805437, '施放守望者之刃现在使你获得粉碎之刃。'),
(805439, '使你的暴击几率提高15%［拥有迅捷命令: ，移动速度提高0%］，持续10 秒。\n\n激活时，你的伤害性暴击有40%的几率触发守望者之刃。'),
(805442, '为40码范围内的队伍和团队成员灌注翠绿之力，使其攻击或法术强度提高95点，持续20 秒。\n\n不与同类效果叠加。'),
(805443, '使你与小队和团队成员的所有法术和攻击命中几率提高1%。\n\n不与类似效果叠加。'),
(805445, '野性之爪造成的伤害现在会降低敌人4%的护甲，持续20 秒，最多可叠加5层。'),
(805448, '引燃造成的治疗效果现在使你对该目标的治疗效果提高5%，持续20 秒，可叠加2层。'),
(805462, '在你周围制造一道治疗水波，为最多8名盟友恢复（67 + 28% 攻击强度 + 60% 治疗强度）点生命值，并对25码范围内的敌人造成（47 + 28% 攻击强度 + 30% 治疗强度）点自然伤害。\n\n与其他地震法术共享冷却时间。'),
(805468, '爆炸或奈萨里奥之焰的暴击现在使炽燃的持续时间延长 0.5 秒。'),
(805476, '从敌人脚下升起熔岩尖刺，将其定身，每3秒造成4点火焰伤害，持续12 秒（对玩家持续8秒）。\n\n造成的伤害可能会中断该效果。每次只能影响1个敌人。'),
(805477, '产生 50 点热量在你周围召唤一道岩浆与火焰构成的护盾，吸收（625 + 300% 法术强度）点伤害。持续 10 秒。\n\n激活期间，你对驱散机制的抵抗提高 70%。'),
(805483, '提高熔岩碎片的暴击几率和暴击伤害10%。'),
(805496, '每个目标产生 20 点热量在敌人脚下制造一根熔岩柱，造成（36 + 31.24% 火焰法术强度）点火焰伤害。\n\n对主目标附近的敌人额外造成（92 + 34.364% 火焰法术强度）点火焰伤害。'),
(805500, '消耗1个余烬灼烧一名敌人，每3秒造成（33 + 29.375% 法术强度）点火焰伤害，并使其受到的治疗效果降低40%，持续15 秒。'),
(805503, '提高月神之矛的伤害20%。'),
(805505, '格挡或招架攻击现在使你造成的伤害提高10%，持续6 秒。'),
(805508, '以星界狂热发起攻击，造成 150% 武器伤害，并根据你当前激活的守护之相触发一个独特效果。'),
(805510, '你的月神之矛造成的伤害提高25%。'),
(805511, '对敌人造成的治疗效果降低40%，持续8 秒。'),
(805512, '恢复30%的最大法力值。'),
(805519, '自动攻击现在会电击最多10个附近敌人，造成（157 + 35% 攻击强度）点风暴打击伤害，且被击中的敌人受到你的召唤物伤害提高20%。'),
(805524, '30级被动你的散落星辰现在可以额外叠加 2 次，且消耗散落星辰的效果提高 50%。'),
(805533, '你的敏捷以及招架和闪避几率提高2%。'),
(805546, '使一名敌人陷入沉睡，持续30 秒（对玩家为6秒）。造成伤害会提前结束该效果。\n\n在沉睡期间，你每3秒从目标身上吸取12点法力值。'),
(805550, '消耗散落星辰用你的星界之刃横扫一名敌人及其附近所有敌人，造成（39 + 30% 攻击强度 + 35% 法术强度）点奥术伤害。\n\n每消耗一颗散落星辰，此法术的冷却时间减少3秒。'),
(805552, '你的精神提高10%。'),
(805555, '2层充能，8秒充能时间产生1层恶魔之火快速刺穿一名敌人，造成100%武器伤害外加15点伤害。'),
(805563, '吸取 25% 最大法力值精准地打击一名敌人，造成（106 + 100% 攻击强度 + 10% 最大法力值 + 100% 法术强度）点奥术伤害，伤害还会根据你的最大法力值进一步提高。\n\n使你对该敌人造成的伤害提高 15%，持续 5 秒。'),
(805568, '复活一名已死亡的盟友，恢复其400点生命值和635点法力值。\n\n可在战斗中使用。不能在竞技场中使用。'),
(805572, '产生10点狂乱值释放一道异界能量光束，对一名敌人及其附近所有敌人造成（126 + 65% 暗影法术强度）点暗影伤害。\n\n当狂乱高于60点时，伤害提高20%。'),
(805581, '履行誓言时，霍鲁萨斯冲击的冷却时间缩短 2 秒。'),
(805583, '对周围 8 码内的敌人造成（20 + 27.4099% 法术强度）点神圣伤害并使其昏迷，持续 5 秒。'),
(805587, '50级被动技能死亡之翼的遗产现在也会使你的下一次毁灭者之喉或天火坠落的伤害提高50%。'),
(805591, '30级被动技能周期性伤害现在有20%的几率对目标施加一层血疮，持续8 秒，最多可叠加5层。'),
(805592, '你的下一次鲜血爆裂和血月冲击对目标造成的伤害提高10%，持续8 秒，可叠加5层。'),
(805607, '等级20 被动使邪异愈合的治疗效果提高50%，并使克苏恩凝视的治疗效果提高100%。\n\n此外，你的攻击现在不会未命中，且不会被招架或躲闪。'),
(805628, '圣槌和霍鲁萨斯冲击的效果提高 20%，法力消耗降低 20%。'),
(805629, '以太阳之力每 1 秒猛击敌人，造成（28 + 15.9426% 攻击强度）点神圣伤害并使其昏迷 1 秒，持续 4 秒。只能在黎明激活期间使用，可在移动中使用。'),
(805643, '躲避攻击会获得一层移山者效果，持续10 秒，可叠加5层。\n\n野性之爪会消耗移山者层数，每层使怒气消耗降低10%，造成的伤害提高5%。'),
(805647, '荣耀处决有 20% 几率额外攻击一次。'),
(805649, '你的命令法术现在有40%的几率返还部分符文能量消耗。'),
(805669, '拥抱你内心的恶魔，立即生成 6 层恶魔之火和 50 点怒气。'),
(805671, '产生 2 点恶魔之火灼烧一个敌人，造成（63 + 33% 攻击强度 + 33.6188% 火焰法术强度）点火焰伤害［拥有恶魔面容: , 使其移动速度降低 30%，持续 8 秒］。'),
(805674, '施放活化或命令法术现在使你的急速提高1%，持续10 秒，最多叠加5层。'),
(805675, '你的疫病蔓延现在会施加腐臭崇拜者，持续10 秒，使你复制20%的周期性伤害作为直接伤害。'),
(805677, '牺牲你15码内的地狱火小鬼，为你恢复最大生命值的15%，并额外恢复每个地狱火小鬼最大生命值25%的生命值。\n\n以这种方式牺牲的地狱火小鬼会留下尸体。'),
(805678, '为你的召唤物注入恶魔坚毅，使其总生命值提高15%，受到的伤害降低10%。'),
(805679, '消耗所有恶魔之血层数，创造一个恶魔护盾，吸收508点伤害，每层恶魔之血使吸收量提高20%，持续30 秒。'),
(805693, '在拥有6层夺颅者时施放恶魔之火，使你在15 秒内的下一次地狱之喉的每跳速度提高25%，且消耗的怒气降低50%。'),
(805695, '使刺穿、地狱火打击和［拥有硫磺重击: 硫磺重击；否则： 斩断］的伤害提高10%。'),
(805696, '进入地狱火形态，使你的火焰伤害提高20%，火焰暴击几率提高15%，持续15 秒。'),
(805697, '你对燃烧目标的暴击伤害提高20%。'),
(805703, '使追踪烈焰获得 30% 的几率在造成伤害时额外生成 1 层恶魔之火。\n\n每层激活的恶魔之火会使触发几率提高 5%。'),
(805706, '当你消耗至少4层恶魔之火时，现在会刷新目标身上的释放天启的持续时间。'),
(805708, '你的群鸦杀戮变为震颤之镰，符文能量消耗更高，但伤害更高且能生成灵魂碎片。'),
(805716, '召唤一名幽魂守卫与你并肩作战 20 秒，并为 20 码内最多 8 名盟友附加吸收护盾，吸收 199 点 + 150% 耐力对应的伤害。'),
(805718, '呼唤典狱长，获得一层护盾，在 10 秒内吸收相当于你最大生命值 30% 的伤害。该效果期间你被视为亡灵，免疫恐惧、睡眠与魅惑效果。'),
(805719, '每次收割收割之魂时以鬼魅之力爆发，6 秒内对附近敌人造成 47 点 + 10.5% 耐力 + 15% 攻击强度的法术暗影伤害。'),
(805724, '施放奥术秘法现在使你的移动速度提高25%，持续5 秒。'),
(805726, '冰霜烙印的射程提高10码。'),
(805727, '在元素迸发激活期间使用原初轰击或火焰符印现在会赋予你奥术符印。\n\n 雕文可通过符印崩解或奥术秘法来释放。'),
(805731, '激活衰弱毒素，持续120 分钟，使你的施法有30%的几率向目标及其周围的敌人注入致残毒液，使其移动速度降低40%，持续8 秒。\n\n你最多可以同时激活2种不同的毒液。'),
(805738, '武装自己以对抗邪恶，重置所有陷阱和歼灭的冷却时间，并在此效果期间使你的陷阱不触发冷却。持续 8 秒。'),
(805743, '武器铭刻：大地造成的伤害现在有5%的几率施放狂野蒸汽。每3秒只能触发一次。'),
(805750, '你的武器铭刻：空气现在会击中目标附近的 2 个额外敌人。'),
(805751, '旋转，在5 秒内无法停止移动，向附近敌人射击，造成50%远程武器伤害加上（暗影法术强度高于神圣法术强度时：（16 + 10% 远程攻击强度 + 20% 暗影法术强度）；否则：（16 + 10% 远程攻击强度 + 20% 神圣法术强度））点暗影伤害。\n\n激活时可闪避和招架。'),
(805754, '蓄力一发强力箭矢，对敌人造成200%远程武器伤害外加（40 + 50% 远程攻击强度 + 30% 暗影法术强度）点伤害，并使其受到的治疗效果降低30%，持续10 秒。\n\n根据造成的伤害产生怒气。'),
(805756, '投掷一枚烟雾弹，使敌人无法瞄准烟雾内部或外部的目标，持续8 秒。\n\n烟雾区域内的所有盟友移动速度提高40%，所有敌人的移动速度降低60%。'),
(805758, '50级被动技能你的折磨者现在可以造成暴击。'),
(805767, '暮光狂暴现在会在激活时使你受到的伤害降低20%。'),
(805770, '进入强力潜行模式，持续3 秒，免疫所有有害魔法效果。\n\n在受到魔法暴击后10 秒内可使用。可在昏迷或恐惧状态下使用。'),
(805773, '施放暗影斩杀或猎巫现在会为你叠加一层赏金猎人，持续8 秒，可通过施放觅心弩箭消耗，额外造成（302 + 30% 远程攻击强度 + 45% 法术强度）点物理伤害，可叠加2层。'),
(805775, '激活肾上腺毒素，持续120 分钟，使你的施法有25%的几率提高6%急速，持续6 秒，可叠加3层。\n\n你最多同时激活2种不同的毒素。'),
(805776, '激活枯萎毒素，持续120 分钟，使你的有害法术和技能有30%的几率使敌人中毒，在6 秒内造成（822 × 等级系数 + 108% 法术强度）点暗影伤害。\n\n你最多可以同时激活2种不同的毒液。'),
(805777, '激活抑法毒素，持续120 分钟，使你的施法有30%的几率降低敌人30%的施法速度，持续8 秒。\n\n你最多可以同时激活2种不同的毒液。'),
(805778, '激活虚弱毒素，持续120 分钟，使你的法术有35%的几率造成（18.85 + 12.5% 法术强度）点暗影伤害，并降低敌人18.6点攻击力，持续8 秒。\n\n你最多同时激活2种不同的毒素。'),
(805780, '强化你的先祖之魂的近战攻击，使其额外造成基于攻击强度的冰霜伤害。持续20 秒或10次攻击。\n\n此技能消耗满溢层数，并根据消耗的层数缩短冷却时间。'),
(805793, '当释放瘟疫激活时，它现在保护你的移动速度不会被降低到正常速度的90%以下。'),
(805794, '向一名敌人投掷强大的元素飞弹，每0.3秒造成（250.495 + 44% 法术强度）点元素伤害，持续1 秒。每枚飞弹都会为你提供一层符印。\n\n受原初轰击的修正效果影响。'),
(805796, '为你的双拳注入力量，持续15 秒，使自动攻击有几率获得大地之拳，持续10 秒，使近战急速提高3%，并提高触发武器铭刻：大地的几率10%，可叠加5层。'),
(805801, '无法受到虚空护盾的影响。持续15 秒。'),
(805804, '激怒效果使你附近的小队和团队成员激怒，持续 3 秒，使他们的生命值恢复提高 100%，并每 1.5 秒恢复其最大生命值的 2%。\n\n近战自动攻击会使此效果的持续时间延长 2 秒，最多延长至 15 秒。\n\n此技能会清空你的酒杯，消耗所有满溢层数，并根据消耗的层数以缩短的冷却时间触发。'),
(805808, '对一名敌人造成（25 + 15% 攻击强度）点物理伤害，并对最多 5 个附近敌人额外造成（17 + 25% 攻击强度）点冰霜伤害。［拥有满溢: \n\n此技能会清空你的酒杯，消耗满溢层数，并根据消耗的层数触发缩短的冷却时间。］'),
(805810, '指定一名盟友作为你的酒友，持续30 分钟，使其受到的所有伤害降低5%，并使其受到的所有伤害的10%转移至你身上。\n\n你同时只能指定1名盟友。'),
(805811, '酒桶猛击造成的伤害现在会使敌人的施法速度降低30%，持续15 秒。'),
(805812, '施放北地吐息现在使你获得10%的近战攻击速度，使用双手武器时额外获得20%，持续8 秒。'),
(805813, '你有一个神奇的酒杯，它会随时间逐渐填满，每2秒为你提供1层满溢。\n\n你的部分其他技能会清空你的酒杯，以缩短冷却时间触发效果。'),
(805815, '向一名敌人投掷一个额外的酒杯，造成 107 点冰霜伤害，并使其昏迷 4 秒。\n\n被击晕的敌人被视为冻结。'),
(805816, '使生命值降至 35% 以下的伤害，以及生命值低于 35% 时受到的伤害，降低 25%。'),
(805821, '当生命值低于或等于35%时受到伤害，现在使你获得20%的额外治疗效果，并降低10%的所受伤害。'),
(805828, '50级被动艾露恩的恩泽贯穿你的每一次攻击。\n\n你获得相当于你的力量 20% 的智力，且你的武器伤害提高，数值相当于你的法术强度。'),
(805832, '向一名敌人投掷重斧，使其在12 秒内流血，造成90点伤害。\n\n每6秒，目标会进入开膛破肚状态，额外流血（71 + 40% 远程攻击强度）点伤害。'),
(805835, '你的灵魂法术的射程提高10码。'),
(805844, '你的无尽之握现在会使你对目标造成的伤害提高15%。'),
(805847, '对一名敌人施放魔法束缚，该效果会弹射至附近敌人，使其定身4 秒。［拥有永恒: \n\n定身期间，目标受到的伤害提高0%。］'),
(805851, '瓦解的暴击几率提高5%。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (805854, 805864, 805867, 805884, 805888, 805893, 805895, 805900, 805919, 805927, 805931, 805933, 805997, 805998, 806021, 806024, 806039, 806049, 806058, 806060, 806068, 806086, 806099, 806100, 806103, 806104, 806109, 806111, 806116, 806121, 806123, 806124, 806125, 806134, 806140, 806142, 806143, 806146, 806148, 806149, 806153, 806154, 806155, 806157, 806159, 806162, 806165, 806167, 806175, 806177, 806182, 806185, 806188, 806191, 806195, 806203, 806204, 806206, 806209, 806210, 806212, 806216, 806222, 806223, 806224, 806228, 806229, 806235, 806240, 806250, 806264, 806266, 806269, 806273, 806274, 806283, 806285, 806286, 806288, 806289, 806290, 806291, 806292, 806293, 806296, 806299, 806300, 806301, 806302, 806307, 806310, 806312, 806315, 806321, 806324, 806328, 806335, 806337, 806338, 806342, 806346, 806353, 806354, 806359, 806360, 806368, 806374, 806382, 806384, 806397, 806400, 806407, 806409, 806410, 806411, 806412, 806414, 806415, 806421, 806423, 806424, 806428, 806449, 806458, 806469, 806477, 806479, 806516, 806521, 806522, 806525, 806533, 806536, 806543, 806549, 806552, 806559, 806563, 806583, 806588, 806602, 806603, 806611, 806627, 806629, 806631, 806698, 806699, 806704, 806708, 806711, 806718, 806727, 806728, 806736, 806737, 806738, 806747, 806753, 806757, 806758, 806762, 806768, 806779, 806795, 806797, 806944, 806957, 806962, 806965, 806973, 806978, 806980, 806984, 806993, 806996, 807004, 807023, 807035, 807036, 807037, 807038, 807040, 807042, 807047, 807050, 807059, 807061, 807070, 807077, 807098, 807105, 807126, 807128, 807144, 807146, 807159, 807160, 807172, 807175);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(805854, '熔解现实的跳动频率提高25%。'),
(805864, '使致残标枪和倒刺标枪的持续时间延长 5 秒。'),
(805867, '将一名队友送入翡翠梦境，持续15 秒，使其免疫伤害，但无法攻击或施法。\n\n在效果持续期间，目标快速恢复生命值和法力值，且其他玩家或生物无法看见目标。\n\n无法对自己使用。'),
(805884, '在15 秒内，你的智力和精神翻倍，并且你造成的所有周期性暴击治疗会恢复5%的缺失法力值。'),
(805888, '使你与小队和团队成员的所有法术和攻击的命中几率提高1%。\n\n不与类似效果叠加。'),
(805893, '每当你粉碎穿刺标枪时，受影响的目标会在3 秒内流血，造成相当于伤害值100%的流血伤害。'),
(805895, '移动速度降低40%，持续8 秒。'),
(805900, '减少毒液箭的施法时间 0.3 秒。'),
(805919, '嘲讽目标攻击你。如果目标可被嘲讽且当前未攻击你，它们会被石化，使下一次攻击速度降低50%。'),
(805927, '延长血之诞生的持续时间，持续2秒。'),
(805931, '3层充能，20秒充能时间再生你的甲壳，使受到的物理伤害降低4%，每1秒恢复1%最大生命值，每跳消耗10点怒气以保持激活，可叠加3层。'),
(805933, '对生命值低于35%的敌人造成伤害时，毒性强化的冷却时间减少2秒。\n\n此外，你的寡妇制造者对生命值低于35%的敌人造成的伤害提高20%。'),
(805997, '长矛的暴击现在使敌人流血，在6 秒内造成（16.5% 远程攻击强度 + 633 × 等级系数）点伤害。'),
(805998, '萨格隆惩戒造成的伤害现在会将你的残废术扩散到2个附近的敌人。'),
(806021, '施放黎明灼击或太阳耀斑有 40% 几率使你获得灼烧印记，持续 10 秒。'),
(806024, '辉耀圣焰造成伤害后，使目标受到你造成的神圣与火焰伤害提高 1%，持续 8 秒，可叠加 8 层。'),
(806039, '每3秒造成（0.5% 攻击强度 + 136 × 等级系数 + 12% 暗影法术强度）点暗影伤害，并降低攻击速度20%。'),
(806049, '猩红浪潮造成的伤害现在会为你提供至高权柄。'),
(806058, '正义旋击造成伤害时，有 8% 几率重置自身冷却时间。'),
(806060, '用辉耀光球轰击目标，每个光球造成（31 + 20.6923% 法术强度）点圣焰伤害。每 1 秒重复一次，持续 4 秒。'),
(806068, '使移动速度提高4%，急速提高3%，持续8 秒，可叠加5层。'),
(806086, '周期性伤害现在有5%的几率召唤2个腐臭者，它们会跑向敌人并在5秒后爆炸，造成（202 + 33.5% 法术强度）点瘟疫伤害。'),
(806099, '反制敌人的法术施放，使其在4 秒内无法施放该系任何法术。\n\n成功打断敌人施法可为你恢复最大生命值的5%。'),
(806100, '凝聚元素魔法，在你脚下制造一片8码宽的云雾屏障，持续8 秒。\n\n敌人无法将目标锁定在雾之内或之外。'),
(806103, '你的魔法伤害提高3%，法术命中几率提高2%。'),
(806104, '你的下3次邪能火球的施法时间降低30%，持续8 秒。'),
(806109, '吞噬邪能，在8 秒内免疫所有物理攻击和法术，但在此期间你无法攻击、移动或施放法术。\n\n持续时间结束时，你在5 秒内的下一次［拥有邪能突进: 邪能突进；否则： 混沌冲刺］将额外冲刺20码。'),
(806111, '萨格隆惩击造成暴击时，现在会使目标在5 秒内流血，额外造成相当于伤害50%的伤害。'),
(806116, '日落期间，你造成的神圣伤害会触发双生圣焰；日出期间，你造成的火焰伤害会触发太阳威能。同一时间只能有其中一种光环。'),
(806121, '审判附近所有敌人，使其瘫痪 30 秒（对玩家为 8 秒）。伤害会打破此效果。受影响的敌人受到你的下一次伤害提高 50%。'),
(806123, '15 秒内，盟友受到的治疗提高 20%，且造成直接伤害时会施放圣光照耀，每 3 秒最多触发一次。'),
(806124, '消耗40点静电在40码范围内用魔法迷雾笼罩队伍和团队成员，使其攻击强度或法术强度提高95点，持续15 秒。\n\n不与同类效果叠加。'),
(806125, '尝试抽干敌人的生命力，汲取 22 点 + 31.03% 攻击强度的生命值，打断施法，并在 3 秒内阻止同一法术系别的任何法术再次施放。'),
(806134, '使战旗的射程提高10码，并使你的荣耀效果提高20%。'),
(806140, '你的战歌的伤害提高15%。'),
(806142, '站在你的勇气战旗范围内时，你的盟友受到的物理伤害降低10%。'),
(806143, '将你的身体包裹在琥珀中，免疫所有物理攻击和法术，持续8 秒，每2秒为你恢复（300 + 50% 法术强度）点生命值，但使你无法移动或行动。\n\n可在昏迷、恐惧或变形状态下使用。'),
(806146, '以鬼魅之意发出尖啸，使周围所有敌人沉默 4 秒，并在效果结束时对其造成 90 点 + 25% 攻击强度的暗霜伤害。'),
(806148, '将伊瑟拉的目光投向一名敌人，使其陷入沉睡，持续40 秒（对玩家为8秒）。\n\n直接伤害可能打断此效果。'),
(806149, '你的暗影伤害提高5%，对生命值低于35%的敌人效果翻倍。'),
(806153, '以神圣之力扑向一名敌人，使其昏迷6 秒，造成（20 + 55% 攻击强度 + 100% 法术强度）点神圣伤害，并打断非玩家角色的施法，持续3 秒。'),
(806154, '钻入地下8 秒，免疫所有物理攻击和法术，但在此期间无法移动或行动。\n\n钻地状态下，你可以在30码范围内选择一个新的位置钻出地面。'),
(806155, '吸取30%最大法力值在10 秒内，受到直接魔法伤害将使攻击者沉默1 秒，并对其造成（57 × 等级系数 + 18% 奥术法术强度）点奥术伤害。\n\n与其他庇护法术共享冷却时间。'),
(806157, '向一条直线上的所有敌人发射冰霜射线，冻结他们，持续40 秒（对玩家为8秒）。造成的伤害可能提前结束此效果。'),
(806159, '向安瑟祈愿，持续 8 秒。期间圣光照耀变为瞬发且必定暴击，但法力消耗提高 100%。与其他太阳祈愿共用冷却时间。'),
(806162, '你的纪元造成的治疗效果现在会使时间经纬的治疗效果提高10%，持续10 秒，可叠加10层。\n\n每层效果使你在施放时间经纬时有2%的几率重置其自身的冷却时间。'),
(806165, '你将自身锁定于完美瞬间，移除并免疫放逐、沉默和打断效果，持续10 秒。'),
(806167, '你的精神提高8%。'),
(806175, '举起盾牌向一名敌人冲锋，对穿过的敌人造成（50% 攻击强度）点暗影伤害，并产生额外威胁值。'),
(806177, '发出一声黑暗的嚎叫激励你的盟友，使所有盟友免疫移动限制效果，持续 6 秒。'),
(806182, '将一名盟友笼罩在黑暗中，暂时降低其所有威胁值，持续8 秒。\n\n在效果持续期间，目标的潜行侦测能力大幅提高。'),
(806185, '撼动大地，对前方锥形范围内的最多12个敌人造成（892 + 17% 攻击强度 + 65% 法术强度 + 125% 耐力）点物理伤害，并将他们拉向你，每2秒重复一次，持续4 秒。\n\n每次将敌人拉向你时，你获得2%的伤害减免，持续3 秒，可叠加5层。'),
(806188, '20级被动技能黎明之刃造成的伤害现在额外造成相当于该伤害100%的火焰伤害，持续10 秒。'),
(806191, '你的近战攻击速度提高10%，持续10 秒。'),
(806195, '每当你招架或躲闪一次攻击，你的攻击速度提高 5%，招架几率提高 2%，持续 15 秒，可叠加 2 次。'),
(806203, '连续体法术每2.5秒生成1个回响碎片，持续5 秒，每消耗1个回响碎片额外增加5秒。\n\n同一时间只能激活1个连续体法术。'),
(806204, '30级被动技能施放时光不谐现在会释放水晶炮，在1 秒内对敌人快速发射2次较弱的小型魔杖攻击，伤害随精神属性提高。'),
(806206, '40级被动施放时光魔杖现在会使你的连续体法术持续时间延长 3 秒。\n\n连续体法术无法被延长至超过其最大持续时间。'),
(806209, '时光不谐造成的伤害现在会对敌人施加永恒之线。'),
(806210, '对生命值低于35%的敌人，静脉爆裂、血牙撕咬和利爪扫击的伤害提高25%。'),
(806212, '延长你的激活的诅咒形态持续时间3秒，并每0.5秒打击附近的敌人，持续3 秒，每次打击造成（20 + 12% 攻击强度）点物理伤害。［拥有凝血: \n\n当此效果结束时，你面前的敌人受到（600 + 60% 攻击强度）点物理伤害。］'),
(806216, '时光魔杖和碎裂回响现在有25%的几率触发水晶炮，在1 秒内对敌人快速发射2次较弱的小型魔杖自动攻击，效果随精神属性提高。\n\n当悖论炮激活时，触发此效果的几率提高10%。'),
(806222, '产生20点狂乱快速攻击一名敌人，造成125%的武器伤害外加48点暗影伤害，并驱散其身上的1个有益魔法效果。\n\n仅能对生命值低于35%的敌人使用。'),
(806223, '摧毁敌人身上的任何伤害吸收效果和伤害免疫效果。'),
(806224, '在友方目标身上制造持续8 秒的动能磁盾，使其受到的伤害降低40%，并免疫昏迷效果。\n\n可在昏迷时使用。'),
(806228, '尝试违抗死亡，根据你当前损失的生命值，使所有受到的伤害降低30%至80%，持续15 秒。'),
(806229, '向你的祖先致敬并获得他们的祝福，使所有小队和团队成员的反射20%受到的伤害，持续20 秒。'),
(806235, '邪能之怒终结技的直接暴击现在会延长心魔的持续时间，延长1秒，并使被击中的敌人受到法术攻击的几率提高3%，持续12 秒。'),
(806240, '移除一名盟友的诅咒，驱散其身上的 1 个诅咒效果［拥有希里克的祝福: ；否则： ］。'),
(806250, '为自己施加黑暗恩赐，持续15 秒，使你的下一次暮光之锤额外造成80%的暗影伤害。\n\n创造一个裂隙，吸收踏入其中的敌人受到的（210 + 150% 攻击强度）点治疗量，并在其内部期间使其受到的治疗效果降低50%，持续10 秒。'),
(806264, '等级 50 被动使你的攻击强度提高相当于法术暴击等级 2.5 倍的数值。'),
(806266, '你的邪异之眼现在额外影响1次施法。'),
(806269, '使你下一次对目标施放的逆转伤口的治疗效果提高10%，持续20 秒。\n\n在持续时间内，每1秒他们获得一层该效果，最多叠加5层。'),
(806273, '破誓者现在使你获得一层愈合结界，持续 15 秒，可叠加 3 次。'),
(806274, '你的鲜血帷幕现在会作用于目标的小队成员。'),
(806283, '当你的缩小诅咒被驱散时，现在会对驱散者施加痛苦。'),
(806285, '诅咒一个敌人，持续20 秒，使其体型缩小，攻击力降低21，法术强度降低10。［拥有潜伏诅咒: \n\n如果该效果被驱散，则对驱散者施加痛苦。］\n\n同一时间目标身上只能存在1个厄运咒。'),
(806286, '巫毒之火的触发几率提高 10%。'),
(806288, '快速向敌人射出一支巫毒箭矢，造成 100% 远程武器伤害外加 15 点自然伤害，并收集一个精魂。\n\n可在移动时使用。'),
(806289, '投掷幽灵战刃，击中路径上的敌人，造成（66 + 50% 远程攻击强度 + 50% 暗影法术强度）点暗影伤害，并使其暗影抗性降低（1 + 100% 角色等级）点，持续 5 秒。［拥有弑神者: \n\n持续时间结束时，对目标及其 8 码范围内的所有敌人造成（315 + 35% 远程攻击强度 + 75% 暗影法术强度）点暗影伤害。］\n\n可在移动时使用。施法时间随你的敏捷属性提高而缩短。'),
(806290, '使纪元的治疗效果降低 25%，使其暴击几率提高 25%，并且纪元现在会在 3 秒内额外恢复相当于治疗量 75% 的生命值。\n\n与其他纪元技能共享冷却时间。此技能造成的治疗无法暴击。'),
(806291, '使纪元的施法时间降低 25%，法力消耗降低 25%，并且纪元会使目标身上的加速恢复传导至附近另一名盟友。\n\n与其他纪元技能共享冷却时间。'),
(806292, '使纪元的施法时间提高 25%，治疗效果提高 25%，并且纪元现在会施加一个伤害吸收护盾，护盾值相当于治疗量的 50%，持续 8 秒。\n\n与其他纪元技能共享冷却时间。'),
(806293, '使纪元的法力消耗降低 25%，暴击几率提高 25%，并且纪元现在会对附近一名敌人造成相当于其治疗量 100% 的伤害。\n\n与其他纪元技能共享冷却时间。'),
(806296, '最多引导5 秒。引导结束时，若引导时间至少1.5秒，则40码范围内的盟友将根据引导时长获得治疗。\n\n引导期间，你免疫昏迷效果。'),
(806299, '改变时间结构，为一名盟友恢复（376.488 + 84.66% 治疗强度）.点生命值。\n\n在8 秒内使用的下一次永世类技能将无冷却和消耗触发。'),
(806300, '你的精神提高8%。'),
(806301, '50级被动你的时光涟漪通道会根据当前激活的永劫产生独特效果：'),
(806302, '激活永世法术现在使你造成的伤害和治疗效果提高 4%，持续 20 秒，可叠加 3 次。'),
(806307, '标记一个敌人，持续4 秒。每1秒，其附近的敌人受到（冰霜法术强度高于自然法术强度时：（11 + 42% 冰霜法术强度）；否则：（11 + 42% 自然法术强度））点自然伤害。\n\n持续时间结束时，其附近的敌人受到（冰霜法术强度高于自然法术强度时：（42 + 64% 冰霜法术强度）；否则：（42 + 64% 自然法术强度））点自然伤害，并被定身，持续4 秒。'),
(806310, '需要凡人之躯化作一滩血池，使你对法术和攻击免疫，但无法攻击或施法，移动速度降低30%，持续6 秒。［拥有吸血之池: \n\n当液化结束时，从附近敌人身上吸取（102.4 + 100% 法术强度）点生命值，并使其恐惧0 秒。］\n\n可在昏迷、恐惧或迷惑状态下使用。'),
(806312, '对受到你的瓦解影响的敌人使用时光撕裂，现在会使敌人爆发出一阵沙尘漩涡，每1秒对8码范围内的最多8个敌人造成（142.5 + 12% 法术强度）点多彩伤害，持续6 秒。'),
(806315, '强化现实，持续 10 秒，使所受伤害的 50% 被储存，并在持续时间结束时转化为治疗。'),
(806321, '暴击现在会施加一层墓穴瘟疫。'),
(806324, '降低命令法术的法力消耗15%，并使其使目标受到的法术伤害提高10%，持续15 秒。'),
(806328, '对敌人施放命令法术现在会施加墓穴瘟疫。'),
(806335, '熔化目标的现实，在 36 秒内造成 1629 点多彩伤害。\\r\\n\\r\\n激活期间，对目标造成的周期性伤害会以 20% 的值复制给其附近的所有敌人。\\r\\n\\r\\n急速不会缩短持续时间，但会增加总伤害次数。'),
(806337, '周期性伤害现在有 5% 的几率使你的急速提高 25%，持续 5 秒。'),
(806338, '施放纪元现在会为你提供无尽之沙。'),
(806342, '向目标射出一支附着魔法藤蔓的箭矢，造成（78 + 33% 远程攻击强度）点自然伤害，并使其定身 40 秒（对玩家为8秒）。造成的伤害可能中断该效果。\n\n每层优势效果可额外击中 1 个附近目标。'),
(806346, '沉默目标5 秒，并在持续时间内每1秒造成（9 + 60% 暗影法术强度）点暗影伤害。'),
(806353, '当生命值低于35%时，下一次受到的直接伤害将消耗这些层数，为你恢复（395 + 25% 耐力）点生命值。\n\n治疗效果受你的耐力和招架等级影响。'),
(806354, '你的下一个光之屏障在30 秒内移除守誓者的醉拳减益效果。'),
(806359, '产生1点优势散发光环，持续30 秒，使小队和团队成员在施放法术或技能时有30%的几率治疗自己，治疗量为（2 + 12.95% 攻击强度）。\n\n激活时，你每1秒产生3点专注值。\n\n所有游侠号角法术共享冷却时间。'),
(806360, '产生1点优势散发一道持续30 秒的光环，使小队和团队成员获得5%急速提升。不与同类效果叠加。\n\n激活时，每1秒产生3点集中值。\n\n所有游侠号角法术共享冷却时间。'),
(806368, '射出一支魔法箭矢，造成（38 + 35% 远程攻击强度）点物理伤害，并使激活的号角法术的冷却时间减少2秒。\n\n每层优势会使伤害和冷却时间缩减效果提高。'),
(806374, '造成冰霜伤害现在有60%的几率使目标从电刑受到的伤害提高15%，持续10 秒，最多可叠加4层。'),
(806382, '引导饱足现在每1秒为30码范围内的所有盟友恢复（70.5 + 20% 治疗强度）点生命值，持续10 秒。'),
(806384, '通过深渊契约转化为治疗的伤害提高10%。'),
(806397, '使溺水的叠加值提高20%。'),
(806400, '消耗 50 点静电将目标区域内的敌人包裹于水中，造成（冰霜法术强度高于自然法术强度时：（118 + 30% 冰霜法术强度）；否则：（118 + 30% 自然法术强度））点冰霜伤害，触发传导，并使其攻击强度降低 24，持续 10 秒。'),
(806407, '尝试溺毙一名敌人，使其受到的治疗效果降低20%，持续8 秒。效果结束时，从深渊释放一只生物，造成（冰霜法术强度高于自然法术强度时：（92 + 100% 冰霜法术强度）；否则：（92 + 100% 自然法术强度））点冰霜伤害。\n\n每次你获得一层导电效果时，都会使目标受到此效果的伤害提高，最多可叠加8层。'),
(806409, '施放湍流之怒或洪水现在会使你获得一层动能。'),
(806410, '暴击几率提高2%，可叠加3层，持续12 秒。\n\n额外施加不会刷新持续时间。'),
(806411, '引导风暴之流时，你的［拥有风暴君主: 盐水；否则： 电击］现在会以1%的效果额外击中75个目标。'),
(806412, '造成暴击伤害现在会减少你所有技能的冷却时间，减少0.5秒。'),
(806414, '使［拥有风暴君主: 盐水；否则： 电击］的伤害提高15%。'),
(806415, '在你所在位置生长出一片荆棘丛，持续12 秒。\n\n区域内的盟友免疫抓取和击退效果。\n\n区域内的敌人无法跳跃、冲刺或冲锋。'),
(806421, '生命值低于35%时被敌人击中，立即重置你的吸血鬼之牙的冷却时间，并赋予你悲惨效果。\n\n每分钟只能触发一次。'),
(806423, '减少你的突刺冷却时间，减少10秒。'),
(806424, '造成的直接伤害现在有10%的几率使你的下一次鲜血愈合在10 秒内变为瞬发。'),
(806428, '施放灌注或吸血鬼之吻现在使所有盟友受到的治疗效果提高6%，持续10 秒。'),
(806449, '所有有效治疗现在使你对盟友造成的周期性治疗效果提高1%，持续30 秒，最多可叠加8层。'),
(806458, '对处于燃烧状态的目标造成的火焰伤害提高 10%。'),
(806469, '使蛙化术的冷却时间缩短60秒，但施法时间增加0.5秒。'),
(806477, '以一道光束贯穿目标及其附近的敌人，造成（111 + 103.734% 火焰法术强度）点火焰伤害。无视免疫效果，每命中一名敌人，后续伤害递减。'),
(806479, '立即治疗自己，恢复 25% 最大生命值及（100 + 100% 法术强度）点生命值。昏迷时也可使用。'),
(806516, '伤害技能现在会获得天界精锐，持续12 秒，最多叠加6层。'),
(806521, '召唤神祇之怒降临于受伤的敌人，造成（356 + 20% 攻击强度 + 100% 神圣法术强度）点神圣伤害，为你恢复等量的生命值，并将你的誓言锁链持续时间延长 3 秒。\n\n仅能对生命值低于35%的敌人使用。'),
(806522, '施放白银之刃或猩红之锤现在将确保你的下一次天灾克星造成的2次伤害必定造成暴击。\n\n提高天灾克星的暴击伤害 25%。'),
(806525, '50级被动你的惩戒和猩红之锤现在额外造成150%武器伤害。'),
(806533, '使你的暴击几率和急速提高3%。'),
(806536, '近战攻击的暴击现在会召唤1个生命之灵，立即对附近一名盟友施放次级灵魂冲锋，为其恢复（64 + 20% 攻击强度 + 20% 自然法术强度）点生命值，并对附近敌人造成（71 + 20% 攻击强度 + 20% 自然法术强度）点自然伤害。'),
(806543, '你的符文纹饰爆发15 秒，使符文剑最多额外攻击5个敌人。\n\n在此期间，你的符文纹饰效果提高100%。'),
(806549, '使你和你宠物激怒18 秒，造成的伤害提高20%，攻击速度和移动速度提高30%。'),
(806552, '标记一个敌人，持续15 秒，使你的宠物技能对该目标造成的伤害会叠加一层献上他们的白骨。\n\n达到5层时，你的宠物会消耗此增益效果，对目标造成（310 + 50% 攻击强度）点伤害，无视护甲。'),
(806559, '你的物理暴击现在会使你宠物的下一次攻击施加流血效果，每2秒造成（92.7 + 15% 攻击强度）点物理伤害，持续6 秒。'),
(806563, '你的精神提高 8%，命中几率提高 2%。'),
(806583, '30级被动现在你对流血效果免疫，且你的晶石弹幕、晶核和Seismic技能伤害将额外受到你的招架等级加成。'),
(806588, '亡灵仆从造成的伤害提高5%。'),
(806602, '在15 秒内的下一次腐牙、凋零毒液或融面者持续时间缩短1%，跳速提高2%，最多叠加10次。'),
(806603, '30级被动技能周期性伤害现在有40%的几率，暴击有100%的几率，获得一层酸牙。'),
(806611, '跃向目标位置并猛砸地面，对最多10名附近敌人造成（29 + 30% 火焰法术强度）点火焰伤害。'),
(806627, '你的暴击现在会为你提供一个护盾，吸收（17 + 15% 攻击强度 + 60% 法术强度）点伤害。\n每10秒只能触发一次。'),
(806629, '30级被动技能你的远程伤害现在有20%的几率刷新一层简易炸药。'),
(806631, '你的机甲现在使你的护甲额外提高 50%。'),
(806698, '使原初轰击的冷却时间缩短4秒，并且现在会刷新3层符文剑。'),
(806699, '近战攻击有 20% 几率重置荣耀处决的冷却时间。'),
(806704, '使你的火焰、冰霜和自然法术的暴击几率提高3%，精准等级提高4点。'),
(806708, '急速提高5%。'),
(806711, '符文烙印造成的伤害现在有 33% 的几率将你的原初轰击转化为一个随机的独特元素版本。'),
(806718, '使你身上的有害魔法和诅咒效果持续时间缩短20%。'),
(806727, '将一名小队或团队成员位移并拉向你，同时驱散他们身上的定身和诱捕效果。'),
(806728, '你在15 秒内的下一次逆转伤口施法时间缩短20%，最多叠加5层。'),
(806736, '直接治疗暴击有 50% 的几率在目标周围创造一个地狱烈焰。每 5 秒只能触发一次。'),
(806737, '施放燃刃斩现在会使原初之怒的冷却时间缩短10秒，巅峰的冷却时间缩短5秒。'),
(806738, '你的守望者之刃现在会使触发守望者之相的几率提高10%，持续8 秒。'),
(806747, '对你的咆哮篝火或凤凰使用余烬之触时，会使其爆发烈焰，为30码内的12名盟友恢复（232 + 100% 精神）点生命值，治疗量额外受精神加成。\n\n其他友方烈焰法师也可以为你的咆哮篝火和凤凰助燃。'),
(806753, '使你受到的有害魔法效果持续时间缩短30%。'),
(806757, '使你的宠物超频20 秒，造成的伤害提高20%，并且其攻击有几率对目标敌人触发硬接线重拳。\n\n此外，你的宠物每5秒会触发一次超载猛击。'),
(806758, '远程技能伤害现在有10%的几率立即制造2个机械守护者，它们将陪伴你12 秒，并有50%的几率触发硬接线重拳，持续12 秒。\n\n施放润滑机器或全面升级！会立即制造2个机械守护者。'),
(806762, '空中打击现在会创造一个坠毁地点，每 2 秒造成（203.1 + 100% 攻击强度 + 11% 自然法术强度）点火焰伤害，持续 12 秒。'),
(806768, '你的虚空之影现在额外叠加1层。'),
(806779, '当你的凤凰死亡时，现在会治疗 30 码范围内所有盟友，治疗量相当于其最大生命值。'),
(806795, '使你受到的所有火焰、自然、冰霜和奥术伤害降低8%。'),
(806797, '提高敏捷铭刻的效果20%。'),
(806944, '你的瓦拉纳的复仇现在会在2 秒内额外造成其初始伤害50%的伤害，并为你恢复相当于该伤害50%的生命值。'),
(806957, '持续伤害现在产生 5 点集中值。\n\n此外，你的伏击的范围提高 10 码。'),
(806962, '使你的小鬼造成的火焰伤害提高 10%，并每 5 秒恢复其 155 点法力值。'),
(806965, '以烈焰打击灼烧一名敌人，造成（24 + 10% 攻击强度 + 18% 法术强度）点暗影烈焰伤害，并在 12 秒内额外造成（96 + 56% 攻击强度 + 57.2% 法术强度）点伤害。\n\n每消耗一层恶魔之火，伤害提高 20%。'),
(806973, '当你装备匕首时，对生命值低于35%的敌人造成的直接暴击有几率使你可以使用隐匿状态才能使用的技能，持续5 秒。'),
(806978, '在30 秒内，每第二次用穿颅者或突击造成暴击，就会将15 秒内的下一次突击转变为偷袭。'),
(806980, '对敌人施加神圣怒火，造成（508 + 25% 攻击强度 + 55% 法术强度）点高威胁神圣伤害，并使其受到的法术伤害提高 10%，持续 15 秒。'),
(806984, '激活巅峰后，对你的目标造成（33% 攻击强度 + 900 × 等级系数）点元素伤害，并使你的符文烙印和武器铭刻造成的伤害提高30%，持续8 秒。'),
(806993, '提高武器铭刻：火焰造成的伤害20%。'),
(806996, '当符文纹饰：大地激活时，你现在每20秒会周期性获得花岗岩护盾。'),
(807004, '你在30 秒内施放的下一个宁静之环变为瞬发。'),
(807023, '当你装备长柄武器时，你的野性打击有15%的几率额外攻击3次。'),
(807035, '对一名敌人投下猩红战锤，造成190%武器伤害外加42点神圣伤害，使圣殿骑士的攻击忽略目标10%的护甲，并使每次自动攻击有几率治疗圣殿骑士，治疗量为最大生命值的2%，持续30 秒。'),
(807036, '每30秒，你的下一个技能必定造成暴击。'),
(807037, '向敌人投掷巫毒能量，造成（22 + 62.5% 自然法术强度）点自然伤害。'),
(807038, '每层使你的急速提高1%。达到20层时，你将化身为强大的灵体，使恶咒之怒和厄运巫咒的伤害提高30%，并使其必定造成15 秒的暴击。\n\n此外，每个灵魂木偶都会爆炸，造成（582 + 50% 暗影法术强度）点暗影伤害，并击晕5码范围内的敌人，持续4 秒。'),
(807040, '遁入黑暗，进入强化潜行模式，清除所有有害效果，并使移动速度提高50%，持续20 秒。［拥有巫毒渴望: \n\n每0.5秒获得一层巫毒渴望效果。］'),
(807042, '用咒火冲击一名敌人，造成（火焰法术强度高于自然法术强度时：（60 + 55% 火焰法术强度）；否则：（60 + 50% 精神 + 55% 自然法术强度））点火焰伤害，伤害受你的精神加成［拥有巫毒精魂: ，并扯断你的傀儡师的丝线，立即释放其伤害］。'),
(807047, '使碾压的施法时间缩短1秒，并使其对怪物造成的伤害提高 15%。'),
(807050, '酿造 5 鱼汤，为巫医及其盟友提供食物。\n\n酿造物品若登出超过15分钟将会消失。'),
(807059, '下一次辉耀圣焰不消耗法力，生效频率提高 50%，持续时间缩短 50%。'),
(807061, '15 秒内的下一次圣光迸发额外攻击一次，造成 8% 的伤害，可叠加 10 层。'),
(807070, '调制5 恶臭鸡尾酒，为巫医及其盟友提供饮品。\n\n召唤物品在登出超过15分钟后消失。'),
(807077, '15 秒内的下一次霍鲁萨斯冲击额外攻击一次，造成 8% 的伤害，可叠加 10 层。'),
(807098, '传送回你的天灾传送器所在位置，并移除你身上的所有移动减速效果。'),
(807105, '生成25点静电浇灭一名敌人，造成（冰霜法术强度高于自然法术强度时：（99 + 57.1% 冰霜法术强度）；否则：（99 + 87.1% 自然法术强度））点冰霜伤害，伤害随你的暴击等级提高。\n\n受电击类效果加成。'),
(807126, '消耗一个余烬现在恢复2%的最大法力值。'),
(807128, '当深渊先驱激活时，你将变身为无面巨兽，使你的暴击治疗和暴击几率提高20%，但持续时间减少5秒。\n\n此外，激活期间你将免疫恐惧、惊骇和变形效果。'),
(807144, '煽动烈焰造成的伤害现在会使斩断和主宰的冷却时间缩短4秒。'),
(807146, '炽燃和点燃的暴击几率提高5%，其周期性伤害频率提高20%，持续时间缩短25%。\n\n周期性暴击会施加萨弗浓烟。'),
(807159, '使玛里苟斯的精华的持续时间延长3秒。'),
(807160, '你的星界之刃现在有30%的几率重置其冷却时间并返还其最大法力值消耗。'),
(807172, '使符文剑和符文烙印的伤害提高 20%。'),
(807175, '造成（52.9 + 26% 法术强度）点圣焰伤害，并使目标的未命中几率提高 3%，持续 10 秒。');

DELETE FROM `coa_client_spell_description` WHERE `ID` IN (807183, 807195, 807196, 807197, 807204, 807206, 807213, 807224, 807233, 807237, 807243, 807247, 807292, 807296, 807297, 807299, 807307, 807309, 807314, 807319, 807336, 807343, 807345, 807346, 807357, 807364, 807376, 807388, 807397, 807400, 807404, 807415, 807419, 807430, 807431, 807432, 807435, 807438, 807450, 807459, 807460, 807461, 807462, 807466, 807467, 807480, 807482, 807487, 807488, 807489, 807490, 807491, 807493, 807494, 807496, 807498, 807499, 807500, 807504, 807505, 807507, 807509, 807510, 807512, 807523, 807531, 807544, 807558, 807560, 807566, 807569, 807578, 807587, 807588, 807589, 807600, 807601, 807610, 807626, 807635, 807653, 807654, 807657, 807659, 807668, 807669, 807671, 807682, 807686, 807690, 807691, 807700, 807723, 807725, 807727, 807729, 807730, 807731, 807733, 807734, 807741, 807743, 807748, 807749, 807754, 807758, 807759, 807774, 807788, 807796, 807811, 807813, 807814, 807816, 807820, 807822, 807823, 807828, 807834, 807842, 807846, 807849, 807855, 807861, 807863, 807874, 807877, 807908, 807918, 807937, 807942, 807944, 807960, 807963, 807964, 807966, 808008, 808009, 808036, 808060, 808082, 809935, 809936, 809937, 809938, 850021, 926591, 954534, 1108459, 1119751, 1119754, 1119881, 1119901, 1200006, 1200011, 1200012, 1257670, 1397742);
INSERT INTO `coa_client_spell_description` (`ID`, `Description`) VALUES
(807183, '移除碾压的施法时间，但其伤害降低 15%，且不再使敌人昏迷。'),
(807195, '向敌人投掷一个魔法网陷阱，使其定身40 秒（对玩家为8秒）。造成伤害可能提前结束效果。'),
(807196, '提高湍流之怒和风暴之流的伤害15%。'),
(807197, '迷惑一个敌人，使其晕眩4 秒。\n\n造成伤害将中断此效果。'),
(807204, '提高霜寒斩的暴击几率10%，并使其周期性伤害可以造成暴击。'),
(807206, '侧翼攻击、闷棍和野性打击的集中值消耗降低10%。'),
(807213, '使你下一次恶咒箭的伤害提高10%，最多叠加10层。持续8 秒。'),
(807224, '闪光箭、爆炸或奈萨里奥之焰会引爆硫磺烟雾，造成萨弗隆爆裂，对目标造成263点火焰伤害，并使其身上的炽燃持续时间延长1秒。'),
(807233, '每30秒，你的下一个风暴预警或湍流之怒变为瞬发。'),
(807237, '产生1点优势向一名敌人投掷一枚涂毒飞镖，在24 秒内造成88点自然伤害，并使其沉默2.5 秒。\n\n此周期性伤害受你的远程急速影响：ext@'),
(807243, '凋零毒素现在在其持续时间结束时额外造成（72.5% 暗影法术强度）点暗影伤害。'),
(807247, '2次充能，60秒充能时间短暂跃上你的克索诺斯战马，使你的移动速度提高70%，持续3 秒。\n\n可在室内使用，但以此方式骑乘战马时无法使用骑乘战斗技能。'),
(807292, '提高鲜血愈合和血箭的暴击几率10%。'),
(807296, '40级被动技能每激活一个厄运巫咒，使你的法术暴击伤害提高100%，并使精魂的暴击几率提高5%。'),
(807297, '40级被动技能施放冲撞和粉碎现在会根据你的格挡等级提高攻击强度，持续6 秒。'),
(807299, '10 秒内的下一次黎明灼击变为瞬发，伤害提高 25%。'),
(807307, '近战技能伤害现在使30码内所有盟友身上的心智撕裂持续时间缩短1秒。'),
(807309, '施放纠正错误现在会赋予2层无尽之沙。'),
(807314, '使用静电终结技造成的直接暴击现在会返还10点静电。'),
(807319, '使龙跃造成的伤害提高 50%，且其造成的伤害将使其冷却时间缩短 1 秒。'),
(807336, '施放血肉之钩或锁链鞭挞现在会嘲讽目标，持续2 秒，并使你受到的物理伤害降低5%，持续10 秒。'),
(807343, '霍鲁萨斯冲击造成伤害后，使你获得赦罪之光，持续 10 秒。'),
(807345, '使消耗生命值的法术和活化之血的消耗降低 30%。'),
(807346, '提高你的格挡值 10%。'),
(807357, '你的动脉突袭引导速度提高10%，持续10 秒，最多叠加5层，且每次攻击现在使塔达拉姆的折磨的持续时间延长2秒。'),
(807364, '对1.5 秒快速射出6发箭矢，每发造成100%远程武器伤害外加46.8点物理伤害，并产生3点怒气值和2%最大法力值。\n\n可在移动时使用。'),
(807376, '当符文纹饰：空气激活时，每5秒使符文法术的剩余冷却时间缩短5%。'),
(807388, '在机甲中时，施放黏性炸弹会使你在5 秒内下一次加特林机枪的引导时间缩短30%。'),
(807397, '侵蚀你自己灵魂的精要，生成 50 点符文能量。潜行状态下可使用。'),
(807400, '在主目标下方制造一座火山，喷发造成（292 + 11% 法术强度）点火焰伤害，每1.5秒重复一次，持续6 秒。\n\n火山造成的伤害产生1点热量，并回复2%的已损失法力值。'),
(807404, '净化之焰的每跳现在额外产生5点热量。'),
(807415, '你造成的物理伤害现在会让你获得猩红渴望，持续 20 秒，可叠加 5 层。'),
(807419, '使死亡追猎者、灵魂割裂与灵魂石诱引的冷却时间缩短 50%。'),
(807430, '延长古尔丹之颅的持续时间5秒。'),
(807431, '施放消耗邪能之怒的技能现在使你的能量恢复速度提高5%，持续10 秒，最多可叠加4层。'),
(807432, '在敌人脚下形成泥浆和碎片，使其下马，并在10 秒内降低其移动速度50%。［拥有大地塑形: \n\n产生1点大地塑形。］\n\n与其他地震法术共享冷却时间。'),
(807435, '技能的直接伤害或有效治疗产生 1 点太阳能量，并每 3 秒产生相当于原伤害或治疗 5% 的灼烧效果，持续 18 秒。每次触发增加此效果的伤害，再次施加不会刷新持续时间。履行誓言：对受此誓言影响的目标，你造成的技能直接伤害或治疗提高 10%。同一时间只能激活一种誓言。'),
(807438, '生成邪能之怒现在延长心魔的持续时间0.5秒。'),
(807450, '恶意妖咒造成的伤害现在有30%的几率在你的敌人位置召唤一个毒蛇守卫，持续10 秒，协助你战斗。\n\n每3秒只能触发一次。'),
(807459, '爆裂种子造成的伤害现在使敌人的命中几率降低15%，持续10 秒。'),
(807460, '散发一道光环，持续10 秒，使小队和团队成员获得400点护甲值。\n\n不与类似效果叠加。'),
(807461, '混沌灾祸造成的伤害现在会在敌人周围散发邪能能量，对最多8个附近敌人造成相当于伤害值50%的伤害。'),
(807462, '使你在施法时保持30%的法力恢复速度，并使你的暴击几率提高2%。'),
(807466, '用地震波治疗盟友现在会额外造成相当于治疗量20%的额外治疗，每3秒触发一次，持续9秒。'),
(807467, '散发一道持续15 秒的光环，使盟友在造成直接伤害时额外造成相当于（35% 攻击强度）的冰霜风暴伤害。\n\n施加力竭效果，阻止你在1 分钟内从类似效果中获益。'),
(807480, '向一名敌人及其附近最多2名敌人投掷邪火能量，造成（火焰法术强度高于自然法术强度时：（306 + 75% 火焰法术强度）；否则：（306 + 75% 自然法术强度））点火焰伤害并使其受到诅咒，持续9 秒。诅咒每3秒造成（火焰法术强度高于自然法术强度时：（239 + 10% 火焰法术强度）；否则：（239 + 10% 自然法术强度））点火焰伤害。\n\n在目标脚下召唤一个毒蛇守卫，持续10 秒。其强度受恶咒之怒的加成。\n\n此效果造成的周期性伤害可造成暴击。'),
(807482, '快速连续投掷远程武器3次，每次造成50%远程武器伤害外加25点物理伤害。\n\n获得血之诞生。伤害加成效果与投掷武器相同。'),
(807487, '等级50 被动当你激活诅咒形态时，如果目标在20码范围内，你将向其冲锋。若目标为敌人，则将其定身2 秒。\n\n效果结束时，你的诅咒形态可被重新激活，使你爆发血魔法能量，从附近敌人身上吸取（364 + 12.5% 攻击强度 + 33% 暗影法术强度）点生命值，并向后传送。'),
(807488, '使用动脉突袭造成伤害时，现在会发射 1 枚鲜血碎片，对你的目标造成（18 + 15% 攻击强度 + 35% 法术强度）点法术暗影伤害。'),
(807489, '你的血箭现在额外吸取50%的生命值，但消耗增加5点怒气。'),
(807490, '每层汇聚活力现在使你的精神提高3%。'),
(807491, '使你的近战急速提高5%，移动速度和坐骑移动速度提高20%。'),
(807493, '使精准射击对生命值高于80%的敌人造成的暴击几率提高50%。'),
(807494, '30级被动技能提高你的最大生命之力1点，并提升你的亡灵仆从的耐力10%。'),
(807496, '你的武器铭刻获得强化：\n\n寒冰： 寒冰铭刻和冰封动能对受到你的火焰烙印影响的目标获得30%的暴击几率加成。\n\n火焰： 当风之铭刻激活时，火焰铭刻的触发几率提高30%。\n\n风： 对受到你的冰封动能影响的目标，复制伤害提高至60%。\n\n大地： 当风之铭刻激活时，大地铭刻对首个命中目标造成10%额外伤害，且每额外命中一个目标再提高10%。'),
(807498, '使修复射击的治疗效果提高15%。'),
(807499, '20级被动技能当处于你的机甲中时，你的召唤物造成的伤害现在有20%的几率为你提供5 废料和2%的最大法力值。'),
(807500, '施放简易炸药现在会重置你的机甲技能的冷却时间。'),
(807504, '40级被动技能使你释放符印的法术强度加成提高10%。\n\n此外，使用元素迸发造成伤害时，会使目标受到的法术伤害提高10%，持续12 秒。'),
(807505, '使元素迸发和符印崩解的施法时间缩短0.5秒，并使你的命中几率提高3%。'),
(807507, '副手武器伤害提高 31%，缴械效果的持续时间缩短 15%。'),
(807509, '30级被动使你的周期性效果可以造成暴击，并且你的法术暴击等级提高，相当于智力值的15%。'),
(807510, '40级被动使你的法术穿透提高30点，数值随等级提升。'),
(807512, '30级被动技能你的克苏恩凝视现在产生10点狂乱。'),
(807523, '太阳烈焰造成伤害后，为 40 码内盟友恢复 2% 缺失生命值及缺失能量、集中值、符文能量与怒气。每 0.5 秒最多触发一次。'),
(807531, '使用作战药剂增幅的有效治疗现在减少医疗包的冷却时间3秒。'),
(807544, '使血月冲击、塔达拉姆的折磨和血箭的法术强度加成提高20%。'),
(807558, '用地震法术攻击敌人现在额外造成（8% 攻击强度）点冰霜伤害，并使所有抗性降低18.8542点，同时使其受到的法术伤害提高2%，持续10 秒。'),
(807560, '激怒附近所有盟友，使其急速提高30%，持续20 秒。\n\n受到该法术影响后，盟友在5 分钟内无法从类似效果中获益。'),
(807566, '施放灌注或吸血鬼之吻现在额外产生2层汇聚活力。'),
(807569, '当混沌化身激活时，所有造成的伤害现在有10%的几率使你陷入时间循环3 秒，在此期间你只能施放多彩碎片。\n\n激活时，你免费施放多彩碎片，每1秒重复一次。'),
(807578, '使混沌化身的持续时间延长3秒，并且在激活期间你的熔解现实没有冷却时间。'),
(807587, '将你的克索诺斯之焰转化为地狱火风箱。'),
(807588, '你的时光魔杖现在有40%的几率重置自身的冷却时间。'),
(807589, '50级被动使你的暴击伤害提高25%。'),
(807600, '每第3次毒牙变为寡妇之吻，造成额外伤害并为你提供额外急速。'),
(807601, '使腐牙的伤害频率提高20%，并使其周期性伤害可以造成爆击。'),
(807610, '使毒性强化的冷却时间缩短60秒。'),
(807626, '使击倒和致残射击的持续时间延长1秒。'),
(807635, '当你进入机甲时，现在返还20%的基础法力值，在机甲内每20秒触发一次。'),
(807653, '激怒5 秒，使其暴击几率提高10%。'),
(807654, '等级 40 被动：暴击等级和精准等级提高，数值相当于智力的 12%。'),
(807657, '使溺水的冷却时间缩短15秒。'),
(807659, '40级被动招架攻击现在恢复 15 点能量，并对攻击者造成 65% 武器伤害。每 1 秒只能触发一次。\n\n此外，消耗散落星辰的效果提高 50%。'),
(807668, '提高毒性飞镖和蹂躏的伤害和持续时间25%。'),
(807669, '使你的地狱火小鬼对生命值高于80%的敌人造成的火焰伤害提高30%。'),
(807671, '追踪烈焰对受天启瘟疫影响的敌人造成的伤害提高20%。\n每激活一个恶魔之火，造成的伤害额外提高10%。'),
(807682, '给一名敌人施加烙印，持续12 秒。\n\n若其在烙印状态下生命值低于10%，则立即对其造成（85 + 100% 攻击强度 + 100% 法术强度）点暗影伤害，并施加诅咒，使你对目标的法术暴击几率提高10%，持续12 秒。\n\n对亡灵和恶魔造成的伤害提高100%。\n\n你同一时间只能对一名敌人施加烙印。'),
(807686, '当你对除自己以外的盟友使用玛里苟斯的精华时，立即恢复你缺失法力值的25%。'),
(807690, '在无尽之握效果结束时，向受影响的敌人发射一枚异常尖刺，使其造成的伤害降低10%，持续4 秒。'),
(807691, '你的时间暂停！现在每跳恢复的法力值减少2%，但施放时会立即额外恢复相当于你最大法力值15%的法力值。'),
(807700, '50级被动你的法术穿透提高50点，随等级提高。\n\n此外，你造成的周期性伤害现在有几率召唤一只次级僵尸，持续10 秒。'),
(807723, '建造一个噪音盒，持续15 秒，定期对附近敌人发出刺耳噪音，中断施法并阻止该系法术被施放，持续3 秒。'),
(807725, '你被暮光魔法包裹，产生的威胁值提高180%，对暗影法术和技能效果翻倍。'),
(807727, '以邪能魔法强化自身，使你产生的威胁值提高210%，但对怪物造成的伤害降低10%。\n\n醉拳：将承受自怪物的25%物理伤害转化为延迟伤害，在5秒内分摊。'),
(807729, '挺身对抗邪恶，使你产生的威胁值提高 135%，并且神圣法术和技能产生的威胁值额外提高 45%。'),
(807730, '你内心的恶魔由内而外散发力量，使你产生的威胁值提高 180%，并且火焰法术和技能产生的威胁值额外提高 50%。'),
(807731, '你的存在令敌人畏惧，产生的威胁值提高120%，对奥术法术和技能效果翻倍。'),
(807733, '你进入戒备状态以抵御邪恶，使你产生的威胁值提高210%。\n\n醉拳：将承受自怪物的25%物理伤害转化为延迟伤害，在5秒内分摊。'),
(807734, '瑟拉赞恩眷顾你，产生的威胁值提高150%。'),
(807741, '传送到目标位置，沉默周围所有敌人，持续4 秒。'),
(807743, '冲击敌人的灵魂，使其沉默4 秒，并打断非玩家施法，持续4 秒。'),
(807748, '50级被动作战药剂增幅造成的有效治疗现在会为目标施加一个护盾，吸收相当于治疗量50%的伤害，最多不超过其最大生命值的10%。'),
(807749, '自动攻击产生 1 点太阳能量，伤害提高 10%。履行誓言：近战技能造成伤害时，触发每把武器各一次自动攻击。同一时间只能激活一种誓言。'),
(807754, '你的时光不谐现在会额外击中3个敌人。'),
(807758, '移动速度降低50%。无法造成爆击。持续10 秒。'),
(807759, '引诱一个敌人，吸引其注意力3 秒，并迫使玩家移动。不会打破潜行。'),
(807774, '在夜晚、室内或地下城中，你造成的所有伤害和治疗效果提高5%。'),
(807788, '在激活诅咒形态后的前5秒内，你的血牙撕咬必定造成暴击。'),
(807796, '强迫目标接受死亡的现实，移除其所有无敌或免疫效果，并诅咒目标，持续5 秒。\n若持续时间结束时目标生命值低于20%，则其受到（800 + 200% 法术强度）点暗影冰霜伤害。'),
(807811, '召唤一个缚法勇士，它会偏转对你施放的法术，将其引导至自身，持续20 秒。\n\n与其他冠军法术共享［拥有骸骨博弈: 2分钟；否则： 3分钟］冷却时间。'),
(807813, '召唤一名冰缚勇士，使你免疫沉默和打断效果，并在施法时减少因受到伤害性攻击而造成的施法推迟，持续20 秒。\n\n与其他冠军法术共享［拥有骸骨博弈: 2分钟；否则： 3分钟］冷却时间。'),
(807814, '向圣光祈求，在10 秒内恢复100点能量，并每秒降低你的威胁值。'),
(807816, '从目标身上吸取10%最大法力值。'),
(807820, '产生1点优势向一名敌人的眼睛撒沙，使其命中几率降低100%并昏迷4 秒。\n\n在战斗中，使用撒尘土后你仍保持潜行状态2秒。'),
(807822, '用冰霜魔法轰击一名敌人，将其冻结在原地，持续40 秒（对玩家为8秒）。每次只能影响1个敌人。\n\n不会打破潜行。造成的伤害可能会中断该效果。'),
(807823, '在目标位置制造一阵狂风，搅动10码范围内的气流，干扰所有敌人，使其移动速度提高20%，持续2 秒。\n不会打破潜行状态。'),
(807828, '定期用火焰焚烧你脚下的地面，持续10 秒。\n穿过火焰的敌人会从潜行或隐形状态中暴露，并被标记1 分钟，使你可以在小地图上追踪他们，即使他们处于潜行或隐形状态也能看见。\n不会打破潜行。'),
(807834, '与冰霜协调，使你的冰霜抗性提高5点，并且对你进行的近战和远程攻击会使攻击者的移动速度和攻击速度降低20%，持续8 秒。'),
(807842, '在目标位置放置一个符文，在1秒后爆发极寒魔法，对范围内的敌人造成（46.9864 + 30% 法术强度）点冰霜伤害，并将其冻结在原地，持续40 秒（对玩家为8秒）。\n造成的伤害可能会打断该效果。'),
(807846, '控制一个最高等级为（100% 角色等级）的机械敌人，强迫其为你效力最多5 分钟（对玩家为8秒）。\n\n该机械单位的近战和远程攻击速度大幅提升，但会随时间短路，每3秒对其造成最大生命值2%的自然伤害。'),
(807849, '在你面前召唤一个雷霆酒桶，持续3 分钟。你的小队或团队中的玩家可以与之互动，获得5杯雷霆麦酒。'),
(807855, '你的蛙化术现在变为瞬发。'),
(807861, '直接暴击现在使你的无羁之怒持续时间延长0.5秒。该效果每秒只能触发一次。\n\n击杀使你的无羁之怒持续时间延长0.5秒。'),
(807863, '你的猎首者之矛现在恢复 15% 的最大能量，并且当你击中 20 码以外的敌人时，造成的伤害提高 100%。'),
(807874, '辉耀连锁的施法时间缩短 15%。'),
(807877, '施放饱足现在会刷新所有 30 码内盟友身上的黑血持续时间。\n\n黑暗灌注在第三次灌注后额外弹跳一次，扩散至附近生命值最低的三名小队或团队成员。'),
(807908, '制造一锅活力巫毒锅。团队成员可以与锅互动，获得一个强效恢复巫毒。锅持续3 分钟或25次使用。'),
(807918, '召唤1只次级暗影猎犬协助你战斗，持续20 秒。'),
(807937, '你的骷髅法师现在仅消耗1点生命之力。'),
(807942, '汲取堕落邪能，将能量转化为生命值。每2点能量恢复你最大生命值的1%。'),
(807944, '以净化烈焰笼罩一名盟友，持续 5 秒，每 1.001 秒为其 10 码范围内的最多 3 名小队和团队成员恢复（130 + 8% 法术强度）点生命值。\n\n［拥有火焰权杖: 每 5 秒，；否则： 在持续时间结束时，］为小队和团队成员恢复 383 点生命值。'),
(807960, '使你的暴击和命中几率提高3%。'),
(807963, '辉耀连锁的治疗提高 15%，法力消耗降低 15%。'),
(807964, '安瑟的祝福的冷却时间缩短 60 秒，圣光誓言的效果翻倍。'),
(807966, '降低所有建造技能的法力消耗，数值相当于25%。'),
(808008, '为你的宠物恢复15%的最大法力值，并使你的召唤物造成的伤害和治疗效果提高，提高数值相当于你治疗法术强度的10%，持续6 秒秒，可叠加3层。'),
(808009, '你的作战药剂增幅现在额外恢复相当于治疗量10%的生命值。'),
(808036, '向目标释放异界之力，对敌人造成（340 + 46.41% 暗影法术强度）点暗影伤害，或为盟友恢复（375 + 41.6018% 治疗强度）点生命值，并消耗 20 点狂乱。'),
(808060, '以奥的祝福祝福所有小队和团队成员，每5秒恢复33点法力值。'),
(808082, '将一个友方目标包裹在毒液之茧中，持续 15 秒，储存你对目标造成有效治疗的 10%。当茧成熟时，接下来对目标造成的 12 次直接攻击都会为其恢复储存的治疗量。'),
(809935, '创造一道梦境之路，通往菲拉斯的梦境之枝，使小队和团队成员可以传送至那里。持续 1 分钟。'),
(809936, '创造一道梦境之路，通往灰谷的枝影，使小队和团队成员可以传送至那里。持续 1 分钟。'),
(809937, '创造一道梦境之路，通往暮色森林的枝影，使小队和团队成员可以传送至那里。持续 1 分钟。'),
(809938, '创造一道梦境之路，通往辛特兰的枝影，使小队和团队成员可以传送至那里。持续 1 分钟。'),
(850021, '向一名敌人冲锋，造成（25 + 30% 攻击强度）点物理伤害。\n\n只能在造成击杀或施加血之诞生后的 6 秒内使用。'),
(926591, '飞斧回旋现在可让你额外击中 1 名敌人。'),
(954534, '奴役目标敌对元素生物，最多持续40 秒（对玩家为8秒），迫使其为你而战。同时只能奴役一个目标。'),
(1108459, '对目标小队成员施放的法术被放大，使其受到的法术伤害提高最多30点，受到的治疗法术效果提高最多32点。持续10 分钟。'),
(1119751, '40码范围内的所有小队或团队成员在受到伤害时，施法或引导时间减少35%。\n同时只能激活1个升腾法术。'),
(1119754, '对任何攻击队伍或团队成员的敌人造成 15 点火焰伤害。\n\n同一时间只能激活一个升腾法术。'),
(1119881, '为40码范围内的所有小队和团队成员提供30点额外的暗影抗性。不与类似效果叠加。'),
(1119901, '40码范围内的所有小队或团队成员获得30点额外的火焰抗性。\n同一时间只能激活1个升腾法术。'),
(1200006, '放置一个彩色沙漏，将盟友的时间线与你的融合，使你和另一名盟友能将队伍和团队成员召唤到当前位置。'),
(1200011, '放置一个来自上古之神的召唤方尖碑，使你和另一名盟友能将队伍和团队成员召唤到当前位置。'),
(1200012, '牺牲自身90%的生命值，在地面上刻下一个巨大的血符文。一旦盟友进入其中，他们可以帮助将队伍和团队成员召唤到当前位置。'),
(1257670, '每5秒恢复5%的最大法力值，持续15 秒。'),
(1397742, '召唤2个你的分身，向附近的敌人冲锋，并在20 秒内协助你战斗。\n\n在距离你15码范围内时，每个分身使你受到的所有伤害降低10%。\n\n施加神圣束缚，持续1 分钟。');
